/** @deprecated 用 DEFAULT_OPERATORS / 运行时 operators 状态 */
const MANAGERS = DEFAULT_OPERATORS;

/** 运行时运营商名册（供剖面/质量查找；主组件写入） */
let OPERATOR_LIVE: Operator[] = DEFAULT_OPERATORS;

/**
 * 把 DEFAULT 里缺的运营商（尤其 WuWei）合并进 live 名册；
 * 已有同 id 保留用户改动，仅补缺项；补进的默认项强制 enabled。
 */
function mergeOperatorsWithDefaults(live: Operator[]): Operator[] {
  const base = live.length > 0 ? live : [];
  const byId = new Map(base.map((o) => [o.id, o]));
  let changed = false;
  for (const d of DEFAULT_OPERATORS) {
    if (!byId.has(d.id)) {
      byId.set(d.id, { ...d, enabled: true });
      changed = true;
    }
  }
  if (!changed && base.length > 0) return base;
  // 保持 DEFAULT 顺序在前，其后跟用户自建
  const out: Operator[] = [];
  const seen = new Set<string>();
  for (const d of DEFAULT_OPERATORS) {
    const hit = byId.get(d.id);
    if (hit) {
      out.push(hit);
      seen.add(d.id);
    }
  }
  for (const o of base) {
    if (!seen.has(o.id)) {
      out.push(o);
      seen.add(o.id);
    }
  }
  return out.length > 0 ? out : DEFAULT_OPERATORS;
}

function relatedFlagOf(
  rp: Partial<Record<string, RelatedFlag>> | undefined,
  id: ManagerId,
): RelatedFlag {
  return rp?.[id] ?? "unknown";
}

function newOperatorId(nameZh: string, existing: Operator[]): string {
  const base =
    nameZh
      .trim()
      .toLowerCase()
      .replace(/\s+/g, "-")
      .replace(/[^a-z0-9\-]/g, "") || "op";
  let id = base === "op" ? `op-${Date.now().toString(36)}` : base;
  let n = 2;
  while (existing.some((o) => o.id === id)) {
    id = `${base}-${n++}`;
  }
  return id;
}

