/**
 * 资产 SKU（得物式货架）：四轮车辆、两轮、或充电站。
 * 购入价/指导价/皮费/寿命/保险维保固定在 SKU；数量与量折由管理员在 SKU 库配置。
 * 价位字段 *Mxn 存「价位币种」面值（见 priceCcy；缺省 MXN）。
 */
type SkuKind = "vehicle" | "two_wheel" | "station";
/** 价位本地币：入引擎时折为投资本位 USD（IDR→USD / MXN→USD），不经 IDR↔MXN */
type PriceCcy = "MXN" | "IDR";

/** 引擎账面口径：墨西哥本地账保持 MXN；非 MXN 价位入账后为 USD */
type EngineBookCcy = "MXN" | "USD";

/** 印尼盾默认汇率（1 USD = N IDR）；经营假设可改 */
const DEFAULT_USD_IDR = 16_250;
const DEFAULT_USD_HKD = 7.8;
type AssetSku = {
  id: string;
  kind: SkuKind;
  nameZh: string;
  brand: string;
  model: string;
  tagline: string;
  /** 计量单位：台 / 辆 / 座 */
  unitLabel: string;
  /**
   * 购入价（价位币种面值，见 priceCcy）。若 pricesIncludeVat=true，则为列载含税现金价；
   * 否则为未税录入，展示/现金流按 vat 加税。
   */
  purchasePriceMxn: number;
  /** 指导价（同价位币种）；税口径同 purchasePriceMxn */
  guidePriceMxn: number;
  /** 价位币种；缺省 MXN。IDR 价位入引擎折 USD，不经 MXN */
  priceCcy?: PriceCcy;
  /**
   * 可配置展业国家/地区（可多选）。资产配置时只能选此集合内国家。
   * 运营剖面 / FX 假设跟所选国家走，不跟 SKU 名称国别前缀。
   */
  marketCountriesZh?: string[];
  /** @deprecated 用 marketCountriesZh；normalize 时并入数组 */
  marketCountryZh?: string;
  /**
   * true：购入/指导/皮费已按含税现金列载（对齐 YOHO DAE 案例表）；
   * false/缺省：未税录入，购物车另加 IVA。
   */
  pricesIncludeVat?: boolean;
  softCosts: SoftCostLine[];
  /** 会计寿命期末残值率（0–1，可配） */
  residualRate: number;
  /** 物理寿命期末残值率（0–1，可配） */
  physResidualRate: number;
  /** 维保寿命期末残值率（0–1，可配） */
  maintResidualRate: number;
  /** 会计寿命（年）；默认见 DEFAULT_LIFE_YEARS */
  acctYears: number;
  /** 物理寿命（年） */
  physYears: number;
  /** 维保寿命（年）；默认 5 */
  maintYears: number;
  insuranceYrMxn: number;
  maintPolicyZh: string;
  maintMxn: number;
  softMxn: number;
  wearYrMxn: number;
  kwhPer100: number;
  /** 管理员：起订量 / 步长 / 上限 / 默认加购量 */
  minOrderQty: number;
  qtyStep: number;
  maxOrderQty: number;
  defaultQty: number;
  /** 量折阶梯：数量达到 minQty 时适用 discountRate（取最高档） */
  volumeTiers: VolumeTier[];
  /** 商详规格（点击 SKU 可见） */
  productSpecs: ProductSpecRow[];
  /** 四大件：电池/电机/电控/车身 · 品牌+供应商（场站为设备/变压器/柴发） */
  majorComponents?: MajorComponent[];
  /** 配置档（续航/电池版本等） */
  configVariants?: SkuConfigVariant[];
  defaultConfigId?: string;
  /** 供应商→工厂追溯链 */
  supplyChain: SupplyChainNode[];
  /** 中国市场：残值公允曲线 / 保有量 / 口碑（海外市暂无则空） */
  marketIntel?: MarketIntel;
  /** 仅场站 */
  stationSpec?: StationSpec;
  stationBom?: StationBomLine[];
  specFill?: SpecFillRow[];
  /** 场站经营常量（跟本 SKU；大中小不同） */
  stationOps?: StationOpsConstants;
};

/** 单座场站经营常量：吞吐/电价/租金等，绑定资产而非全局前提 */
type StationOpsConstants = {
  powerKwPerGun: number;
  externalUtil: number;
  internalUtil: number;
  externalPriceMxn: number;
  internalPriceMxn: number;
  elecCostMxn: number;
  lossFactor: number;
  rentMonthMxn: number;
  opexMonthMxn: number;
  /**
   * 场地租约寿命（年）。剩余经营 NPV / 路径最长经营月数取 min(租约, 物理寿命)。
   * 租约到期且无续约假设时，持有期末剩余经营 NPV=0（仅押金等可收回项）。默认 5。
   */
  leaseYears?: number;
  /** @deprecated 遗留共享爬坡；优先用 external/internal/ancillary 分项 */
  rampYears?: number;
  /** @deprecated 遗留共享首年负荷；优先用分项 */
  rampStartLoad: number;
  /** 对外充电：达产爬坡年数（缺省跟 rampYears / 0.5） */
  externalRampYears?: number;
  /** 对外充电：首年负荷（相对稳态；缺省跟 rampStartLoad） */
  externalRampStartLoad?: number;
  /** 对内充电：达产爬坡年数 */
  internalRampYears?: number;
  /** 对内充电：首年负荷 */
  internalRampStartLoad?: number;
  /** 衍生收入：达产爬坡年数（缺省 0.5） */
  ancillaryRampYears?: number;
  /** 衍生收入：首年负荷（缺省 0；Excel 对表时改用延迟阶跃） */
  ancillaryRampStartLoad?: number;
  /**
   * 对外充电收入平台抽佣占比（小桔等）。Excel≈10%；只乘对外收入。
   */
  xiaojufenPct: number;
  /**
   * 对内充电收入平台抽佣占比。默认 0（Excel 对内不抽佣）；可配置。
   */
  xiaojufenInternalPct?: number;
  /** 支付通道费占比；默认仅乘对外收入（Excel≈2%） */
  payFeePct: number;
  /** 对内支付通道费占比；默认 0 */
  payFeeInternalPct?: number;
  /**
   * 车队押金（关联·非收入）：车队向场站 SPV 缴纳的保证金合计。
   * 投产首月现金流入、持有期末退还；不计 P&L/稳态收入。对齐 YOHO IC 关联交易列载。
   */
  fleetDepositMxn: number;
  /** 车位租金收入（Excel《充电桩》约 16,240/月）· 计入经营收入 */
  parkingRentMxn: number;
  /** 衍生收入（Excel 约 50,000/月；主要为场站食品/配件零售示意）· 计入经营收入 */
  ancillaryMxn: number;
  /**
   * Excel《充电桩》初始投资占位（默认中型 8,761,000，含税/配套差额）。
   * 路径权益出资用未税硬成本（对齐表内桩+装修+押金）；账面现金按 invest−硬成本留存，供表内计息。
   */
  investMxn?: number;
  /** 存款年利率；Excel 利息=年利率×因子×上期末账面现金（按月、不÷12） */
  cashInterestAnn?: number;
  /** Excel 利息因子（表内 C26=0.8） */
  cashInterestFactor?: number;
  /** 是否启用 Excel 同口径（未税出资 + 账面计息 + 运维包已含维保；默认 true） */
  excelCashInterest?: boolean;
  /**
   * 衍生收入起算延迟（月）：仅 Excel 同口径时用阶跃（满 N 月后满额）。
   * 非对表时优先用 ancillaryRampYears / ancillaryRampStartLoad。
   */
  ancillaryDelayMonths?: number;
};

/** 场站某收入流在经营月第 m 月的负荷系数（1=满负荷） */
function stationIncomeRampFactor(args: {
  opsMonth1Based: number;
  rampYears: number;
  rampStartLoad: number;
  /** true → 恒为 1（Excel 对表充电） */
  forceFull?: boolean;
}): number {
  if (args.forceFull || args.opsMonth1Based >= 900) return 1;
  const rampY = Math.max(0, args.rampYears);
  if (rampY <= 1e-9) return 1;
  const ramp0 = Math.max(0, Math.min(1, args.rampStartLoad));
  const rampMo = Math.max(1, Math.round(rampY * 12) || 1);
  return Math.min(
    1,
    ramp0 +
      (1 - ramp0) *
        Math.min(1, (args.opsMonth1Based - 1) / Math.max(1, rampMo - 1)),
  );
}

function stationExternalRampYears(ops: StationOpsConstants): number {
  return ops.externalRampYears != null
    ? ops.externalRampYears
    : ops.rampYears != null
      ? ops.rampYears
      : 0.5;
}
function stationExternalRampStart(ops: StationOpsConstants): number {
  return ops.externalRampStartLoad != null
    ? ops.externalRampStartLoad
    : ops.rampStartLoad ?? 0.5;
}
function stationInternalRampYears(ops: StationOpsConstants): number {
  return ops.internalRampYears != null
    ? ops.internalRampYears
    : ops.rampYears != null
      ? ops.rampYears
      : 0.5;
}
function stationInternalRampStart(ops: StationOpsConstants): number {
  return ops.internalRampStartLoad != null
    ? ops.internalRampStartLoad
    : ops.rampStartLoad ?? 0.5;
}
function stationAncillaryRampYears(ops: StationOpsConstants): number {
  return ops.ancillaryRampYears != null ? ops.ancillaryRampYears : 0.5;
}
function stationAncillaryRampStart(ops: StationOpsConstants): number {
  return ops.ancillaryRampStartLoad != null
    ? ops.ancillaryRampStartLoad
    : 0;
}

/** 二手残值曲线点：车龄年 → 相对新车成交价残值率% */
type ResidualCurvePoint = { year: number; ratePct: number };

type ReputationDim = { nameZh: string; score: number };

/** 好评/差评摘录（可点信源） */
