/** 规格行挂靠的信源 id（优先 sourceIds；兼容旧「信源」行用 · 拼 id） */
function resolveSpecSourceIds(row: ProductSpecRow): string[] {
  if (row.sourceIds && row.sourceIds.length > 0) return row.sourceIds;
  if (row.id !== "source") return [];
  return row.valueZh
    .split(/[·,，;\s]+/)
    .map((x) => x.trim())
    .filter((x) => Boolean(x) && Boolean(getSource(x)));
}

/**
 * 商详产品规格两列清单专用字号：比全局 TYPE 再小一档（仅本表，勿改 TYPE）。
 * 标签 ≈ 原 label 再缩；取值贴近原 caption；脚注再低半档。
 */
const SPEC_SHEET = {
  label: {
    fontSize: "clamp(0.68rem, 0.66rem + 0.08vw, 0.74rem)",
    lineHeight: 1.35,
  },
  value: {
    fontSize: "clamp(0.76rem, 0.74rem + 0.1vw, 0.84rem)",
    lineHeight: 1.4,
  },
  footnote: {
    fontSize: "clamp(0.68rem, 0.66rem + 0.08vw, 0.74rem)",
    lineHeight: 1.35,
  },
} as const;

/** 紧凑规格清单：标签左固定宽 + 取值折行 + 状态 Pill（避免三列表格状态竖排） */
function SpecSheetList(props: {
  rows: ProductSpecRow[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  renderCites: (ids: string[]) => any;
  borderColor: string;
  /** 某规格行下方附加说明（如运营补能提示） */
  footnotesById?: Record<string, string>;
}) {
  const { rows, renderCites, borderColor, footnotesById } = props;
  return (
    <Stack
      gap={0}
      style={{
        borderTop: `1px solid ${borderColor}`,
      }}
    >
      {rows.map((r) => {
        const citeIds = resolveSpecSourceIds(r);
        const isSourceOnly =
          r.id === "source" || (!r.valueZh && citeIds.length > 0);
        const footnote = footnotesById?.[r.id];
        return (
          <Row
            key={r.id}
            gap={10}
            align="start"
            style={{
              padding: "5px 0",
              borderBottom: `1px solid ${borderColor}`,
            }}
          >
            <Text
              tone="secondary"
              style={mergeStyle(TYPE.label, {
                ...SPEC_SHEET.label,
                width: "min(96px, 28%)",
                flexShrink: 0,
                paddingTop: 1,
                overflowWrap: "break-word",
              })}
            >
              {r.labelZh}
            </Text>
            <Stack gap={2} style={{ flex: 1, minWidth: 0 }}>
              {!isSourceOnly && (
                <Text
                  style={mergeStyle(TYPE.body, {
                    ...SPEC_SHEET.value,
                    wordBreak: "break-word",
                  })}
                >
                  {r.valueZh || "—"}
                </Text>
              )}
              {citeIds.length > 0 && (
                <Row
                  gap={4}
                  align="center"
                  wrap
                  style={SPEC_SHEET.footnote}
                >
                  {renderCites(citeIds)}
                </Row>
              )}
              {footnote ? (
                <Text
                  tone="tertiary"
                  style={mergeStyle(TYPE.caption, {
                    ...SPEC_SHEET.footnote,
                    marginTop: 1,
                  })}
                >
                  {footnote}
                </Text>
              ) : null}
            </Stack>
          </Row>
        );
      })}
    </Stack>
  );
}

