/** 中型站对齐 YOHO 首站经营假设；大/小按 opsScale 缩放租金与运维包 */
function stationOpsForTier(tier: StationTierDef): StationOpsConstants {
  const guns = Math.max(1, tier.fast + tier.slow);
  const scale = tier.opsScale;
  const parking = Math.max(1, tier.parking || guns);
  return {
    powerKwPerGun: tier.totalPowerKw / guns,
    externalUtil: 0.1,
    internalUtil: 0.2,
    externalPriceMxn: 8,
    internalPriceMxn: 7,
    elecCostMxn: 3,
    lossFactor: 1.08,
    rentMonthMxn: Math.round(81_200 * scale),
    opexMonthMxn: Math.round(160_000 * scale),
    leaseYears: 5,
    rampYears: 0.5,
    rampStartLoad: 0.5,
    externalRampYears: 0.5,
    externalRampStartLoad: 0.5,
    internalRampYears: 0.5,
    internalRampStartLoad: 0.5,
    ancillaryRampYears: 0.5,
    ancillaryRampStartLoad: 0,
    xiaojufenPct: 0.1,
    xiaojufenInternalPct: 0,
    payFeePct: 0.02,
    payFeeInternalPct: 0,
    /** 示意：约 6,000 MXN/车位·台（关联车队向场站缴存；可改） */
    fleetDepositMxn: Math.round(6_000 * parking),
    parkingRentMxn: Math.round(16_240 * scale),
    ancillaryMxn: Math.round(50_000 * scale),
    investMxn: Math.round(8_761_000 * scale),
    cashInterestAnn: 0.04,
    cashInterestFactor: 0.8,
    excelCashInterest: true,
    ancillaryDelayMonths: 6,
  };
}

function defaultStationOpsConstants(sku?: AssetSku): StationOpsConstants {
  const spec = sku?.stationSpec;
  const guns = Math.max(
    1,
    (spec?.fastGuns || 0) + (spec?.slowGuns || 0) || 10,
  );
  const power =
    spec?.totalPowerKw != null ? spec.totalPowerKw / guns : 42.86;
  const parking = Math.max(1, spec?.parkingSpaces || guns);
  return {
    powerKwPerGun: power,
    externalUtil: 0.1,
    internalUtil: 0.2,
    externalPriceMxn: 8,
    internalPriceMxn: 7,
    elecCostMxn: 3,
    lossFactor: 1.08,
    rentMonthMxn: 81_200,
    opexMonthMxn: 160_000,
    leaseYears: 5,
    rampYears: 0.5,
    rampStartLoad: 0.5,
    externalRampYears: 0.5,
    externalRampStartLoad: 0.5,
    internalRampYears: 0.5,
    internalRampStartLoad: 0.5,
    ancillaryRampYears: 0.5,
    ancillaryRampStartLoad: 0,
    xiaojufenPct: 0.1,
    xiaojufenInternalPct: 0,
    payFeePct: 0.02,
    payFeeInternalPct: 0,
    fleetDepositMxn: Math.round(6_000 * parking),
    parkingRentMxn: 16_240,
    ancillaryMxn: 50_000,
    investMxn: 8_761_000,
    cashInterestAnn: 0.04,
    cashInterestFactor: 0.8,
    excelCashInterest: true,
    ancillaryDelayMonths: 6,
  };
}

function resolveStationOps(sku: AssetSku): StationOpsConstants {
  const base = defaultStationOpsConstants(sku);
  const over = sku.stationOps || {};
  return {
    ...base,
    ...over,
    fleetDepositMxn: Math.max(
      0,
      over.fleetDepositMxn != null ? over.fleetDepositMxn : base.fleetDepositMxn,
    ),
    parkingRentMxn: Math.max(
      0,
      over.parkingRentMxn != null ? over.parkingRentMxn : base.parkingRentMxn,
    ),
    ancillaryMxn: Math.max(
      0,
      over.ancillaryMxn != null ? over.ancillaryMxn : base.ancillaryMxn,
    ),
    ancillaryDelayMonths: Math.max(
      0,
      Math.round(
        over.ancillaryDelayMonths != null
          ? over.ancillaryDelayMonths
          : base.ancillaryDelayMonths ?? 6,
      ),
    ),
    leaseYears: Math.max(
      1,
      Math.round(
        over.leaseYears != null ? over.leaseYears : base.leaseYears ?? 5,
      ),
    ),
    xiaojufenPct: Math.max(
      0,
      Math.min(
        0.5,
        over.xiaojufenPct != null ? over.xiaojufenPct : base.xiaojufenPct,
      ),
    ),
    xiaojufenInternalPct: Math.max(
      0,
      Math.min(
        0.5,
        over.xiaojufenInternalPct != null
          ? over.xiaojufenInternalPct
          : base.xiaojufenInternalPct ?? 0,
      ),
    ),
    payFeePct: Math.max(
      0,
      Math.min(
        0.2,
        over.payFeePct != null ? over.payFeePct : base.payFeePct,
      ),
    ),
    payFeeInternalPct: Math.max(
      0,
      Math.min(
        0.2,
        over.payFeeInternalPct != null
          ? over.payFeeInternalPct
          : base.payFeeInternalPct ?? 0,
      ),
    ),
    externalRampYears: stationExternalRampYears({ ...base, ...over }),
    externalRampStartLoad: stationExternalRampStart({ ...base, ...over }),
    internalRampYears: stationInternalRampYears({ ...base, ...over }),
    internalRampStartLoad: stationInternalRampStart({ ...base, ...over }),
    ancillaryRampYears: stationAncillaryRampYears({ ...base, ...over }),
    ancillaryRampStartLoad: stationAncillaryRampStart({ ...base, ...over }),
  };
}

/** 场站单位月路径：期初购置 + 经营月（含爬坡）
 * 可变成本（电费/佣金）随负荷 ramp 同比；租金/运维/保养为固定。
 * 「稳态」瀑布须用满负荷（见 stationSteadyMonthEconomics），勿把首年负荷当成稳态。
 * 可选 spvTiers：与车辆同套优先/夹层，期初按权益出资、经营月扣本息。
 * 车队押金：投产首月流入、持有期末退还（非收入）。
 */
function buildStationMonthBars(args: {
  unitLandedMxn: number;
  guns: number;
  ops: StationOpsConstants;
  maintMxn: number;
  months: number;
  spvTiers?: WaterfallTier[];
  /** 场地押金：经营末月收回（默认 0；调用方传入 softCost deposit） */
  siteDepositReturnMxn?: number;
  /**
   * 还款时钟偏移（与同单车辆空窗对齐）：financeMonth = offset + 经营月。
   * 缺省 0（场站独立路径无空窗时从第1月起息）。
   */
  financeMonthOffset?: number;
}): {
  label: string;
  opsInMxn: number;
  /** 融资保证金退还；与 opsIn 分列 */
  depositReturnMxn?: number;
  /** 当月优先+夹层本息（用于反推 CFADS） */
  debtServiceMxn?: number;
  /** 扣本息前经营净 */
  cfadsMxn?: number;
  outflowMxn: number;
  netMxn: number;
}[] {
  const { unitLandedMxn, guns, ops, maintMxn, months } = args;
  const siteDepReturn = Math.max(0, args.siteDepositReturnMxn || 0);
  const fleetDep = Math.max(0, ops.fleetDepositMxn || 0);
  const parkingRentMo = Math.max(0, ops.parkingRentMxn || 0);
  const ancillaryMo = Math.max(0, ops.ancillaryMxn || 0);
  const ancDelay = Math.max(0, Math.round(ops.ancillaryDelayMonths ?? 6));
  const gunKwhFullMo = (ops.powerKwPerGun || 40) * 24 * 30;
  const stExt =
    gunKwhFullMo * ops.externalUtil * ops.externalPriceMxn;
  const stInt =
    gunKwhFullMo * ops.internalUtil * ops.internalPriceMxn;
  /**
   * Excel《充电桩》运维包 16 万已含安保/办公；表无另列「维保」。
   * Excel 同口径开启时不再叠加 SKU.maintMxn，避免双重扣减。
   */
  const useExcelAlign = ops.excelCashInterest !== false;
  const maintUse = useExcelAlign ? 0 : maintMxn;
  const fixedMo = ops.rentMonthMxn + ops.opexMonthMxn + maintUse;
  const tiers = args.spvTiers || [];
  const stack = capitalStackPcts(tiers);
  const debtLayers = DEBT_TIER_ORDER.map((id) => {
    const tier = tiers.find((t) => t.id === id && t.enabled && t.investor);
    if (!tier?.investor) return null;
    const inv = normalizeInvestorPi(tier.investor);
    const depositOne = investorDepositMxn(inv, unitLandedMxn);
    const prinOne = unitLandedMxn * Math.max(0, Math.min(1, inv.principalPct));
    const settlementMo =
      depositOne > 0 ? investorDepositReturnFinanceMonth(inv, prinOne) : 0;
    return { id, inv, depositOne, prinOne, settlementMo };
  }).filter(
    (
      x,
    ): x is {
      id: DebtTierId;
      inv: InvestorPiDetail;
      depositOne: number;
      prinOne: number;
      settlementMo: number;
    } => !!x,
  );
  const depositSum = debtLayers.reduce((s, d) => s + d.depositOne, 0);
  const hasDebt = stack.debtSum > 1e-9;
  const finOff = Math.max(0, Math.round(args.financeMonthOffset || 0));
  const investBook = Math.max(
    unitLandedMxn,
    ops.investMxn != null && Number.isFinite(ops.investMxn)
      ? ops.investMxn
      : unitLandedMxn,
  );
  /** 无债：路径出资=硬成本落地；Excel 初始投资差额留在账面现金上计息 */
  const equityBuy = hasDebt
    ? unitLandedMxn * Math.max(0, stack.equityPct) + depositSum
    : unitLandedMxn;
  const buyLabel = hasDebt
    ? depositSum > 0
      ? "期初权益出资+保证金"
      : `期初权益出资（${ratePctShown(stack.equityPct, 0)}%落地）`
    : investBook > unitLandedMxn + 1
      ? "期初购置（硬成本；投资差额留存计息）"
      : "期初购置";
  const bars: {
    label: string;
    opsInMxn: number;
    depositReturnMxn?: number;
    debtServiceMxn?: number;
    cfadsMxn?: number;
    outflowMxn: number;
    netMxn: number;
  }[] = [
    {
      label: buyLabel,
      opsInMxn: 0,
      outflowMxn: equityBuy,
      netMxn: -equityBuy,
      debtServiceMxn: 0,
      cfadsMxn: 0,
    },
  ];
  const n = Math.max(1, Math.round(months) || 60);
  /** Excel 对表：充电外/内按满负荷；衍生用延迟阶跃。非对表：分项爬坡 */
  const useExcelInt = useExcelAlign && !hasDebt;
  const intAnn = Math.max(0, ops.cashInterestAnn ?? 0.04);
  const intFac = Math.max(0, ops.cashInterestFactor ?? 0.8);
  /** 账面现金：Excel 初始投资 − 已投硬成本；之后随经营净额与利息滚动 */
  let bookCash = useExcelInt ? Math.max(0, investBook - unitLandedMxn) : 0;
  const debtPayAt = (financeMonth: number) =>
    debtLayers.reduce((s, d) => {
      if (!(d.prinOne > 0)) return s;
      return s + investorMonthPayMxn(d.inv, d.prinOne, financeMonth);
    }, 0);
  const depositReturnAt = (financeMonth: number) =>
    debtLayers.reduce(
      (s, d) =>
        s +
        (d.settlementMo > 0 && financeMonth === finOff + d.settlementMo
          ? d.depositOne
          : 0),
      0,
    );
  const extRampY = stationExternalRampYears(ops);
  const extRamp0 = stationExternalRampStart(ops);
  const intRampY = stationInternalRampYears(ops);
  const intRamp0 = stationInternalRampStart(ops);
  const ancRampY = stationAncillaryRampYears(ops);
  const ancRamp0 = stationAncillaryRampStart(ops);
  for (let m = 1; m <= n; m++) {
    const rampExt = stationIncomeRampFactor({
      opsMonth1Based: m,
      rampYears: extRampY,
      rampStartLoad: extRamp0,
      forceFull: useExcelAlign,
    });
    const rampInt = stationIncomeRampFactor({
      opsMonth1Based: m,
      rampYears: intRampY,
      rampStartLoad: intRamp0,
      forceFull: useExcelAlign,
    });
    const ancIn = useExcelAlign
      ? m > ancDelay
        ? ancillaryMo
        : 0
      : ancillaryMo *
        stationIncomeRampFactor({
          opsMonth1Based: m,
          rampYears: ancRampY,
          rampStartLoad: ancRamp0,
        });
    const chargeIn = guns * (stExt * rampExt + stInt * rampInt);
    const inflow = chargeIn + parkingRentMo + ancIn;
    /** 电费/佣金随对应吞吐爬坡；场租+运维包固定；车位租金满月 */
    const stElecExt =
      gunKwhFullMo * ops.externalUtil * ops.lossFactor * ops.elecCostMxn;
    const stElecInt =
      gunKwhFullMo * ops.internalUtil * ops.lossFactor * ops.elecCostMxn;
    const stFeeExt =
      stExt * (ops.xiaojufenPct || 0) + stExt * (ops.payFeePct || 0);
    const stFeeInt =
      stInt * (ops.xiaojufenInternalPct || 0) +
      stInt * (ops.payFeeInternalPct || 0);
    const opsOut =
      guns *
        ((stElecExt + stFeeExt) * rampExt + (stElecInt + stFeeInt) * rampInt) +
      fixedMo;
    const debtMo = debtPayAt(finOff + m);
    const depReturn = depositReturnAt(finOff + m);
    const siteDep = m === n ? siteDepReturn : 0;
    const fleetDepIn = m === 1 ? fleetDep : 0;
    const fleetDepOut = m === n ? fleetDep : 0;
    /** Excel：利息=年利率×因子×上期末账面（按月、不÷12） */
    const interestIn =
      useExcelInt && Math.abs(bookCash) > 0.01
        ? intAnn * intFac * bookCash
        : 0;
    const outflow = opsOut + debtMo + fleetDepOut;
    const opsInCore =
      inflow + siteDep + fleetDepIn + Math.max(0, interestIn);
    const interestOut = interestIn < -0.01 ? -interestIn : 0;
    const outflowTot = outflow + interestOut;
    const netMo = opsInCore + depReturn - outflowTot;
    bookCash += netMo;
    const tagParts: string[] = [];
    if (fleetDepIn > 0) tagParts.push("车队押金收取");
    if (Math.abs(interestIn) > 0.01) tagParts.push("账面计息");
    if (depReturn > 0) tagParts.push("融资保证金退还");
    if (siteDep > 0) tagParts.push("场地押金收回");
    if (fleetDepOut > 0) tagParts.push("车队押金退还");
    bars.push({
      label:
        tagParts.length > 0
          ? `经营第${m}月·${tagParts.join("·")}`
          : `经营第${m}月`,
      opsInMxn: opsInCore,
      depositReturnMxn: depReturn,
      debtServiceMxn: debtMo,
      /** 杠杆净 + 本息 − 融资保证金退还 ≈ 扣本息前；仍含押金/计息进 opsIn（包层 stIn 另取纯经营） */
      cfadsMxn: netMo - depReturn + debtMo,
      outflowMxn: outflowTot,
      netMxn: netMo,
    });
  }
  return bars;
}

/** 场站满负荷稳态月经济（瀑布「稳态」口径；≠ 首年负荷） */
function stationSteadyMonthEconomics(args: {
  guns: number;
  ops: StationOpsConstants;
  maintMxn: number;
}): { revMo: number; varMo: number; fixedMo: number; netMo: number } {
  const p = stationMonthPartsAt({
    guns: args.guns,
    ops: args.ops,
    maintMxn: args.maintMxn,
    opsMonth1Based: 999, // 稳态：衍生已起算、满负荷
    debtPiMo: 0,
    debtMezzMo: 0,
  });
  return {
    revMo: p.revMo,
    varMo: p.varMo,
    fixedMo: p.fixedMo,
    netMo: p.grossMo,
  };
}

/** 场站单月经营分项（对齐车辆瀑布科目形：收入合计 + 成本 slice + 权益） */
type StationMonthParts = {
  chargeExtMo: number;
  chargeIntMo: number;
  parkingMo: number;
  ancillaryMo: number;
  elecMo: number;
  platformMo: number;
  payFeeMo: number;
  rentMo: number;
  opexPackMo: number;
  maintMo: number;
  debtPiMo: number;
  debtMezzMo: number;
  revMo: number;
  varMo: number;
  fixedMo: number;
  grossMo: number;
  financeMo: number;
  equityMo: number;
  /** 对外负荷系数（兼容旧读数） */
  ramp: number;
  rampExt: number;
  rampInt: number;
  rampAnc: number;
};

function stationMonthPartsAt(args: {
  guns: number;
  ops: StationOpsConstants;
  maintMxn: number;
  opsMonth1Based: number;
  debtPiMo?: number;
  debtMezzMo?: number;
}): StationMonthParts {
  const { guns, ops, maintMxn, opsMonth1Based } = args;
  const gunKwhFullMo = (ops.powerKwPerGun || 40) * 24 * 30;
  const stExtGun =
    gunKwhFullMo * ops.externalUtil * ops.externalPriceMxn;
  const stIntGun =
    gunKwhFullMo * ops.internalUtil * ops.internalPriceMxn;
  const stElecExtGun =
    gunKwhFullMo * ops.externalUtil * ops.lossFactor * ops.elecCostMxn;
  const stElecIntGun =
    gunKwhFullMo * ops.internalUtil * ops.lossFactor * ops.elecCostMxn;
  const platformExtGun = stExtGun * (ops.xiaojufenPct || 0);
  const platformIntGun = stIntGun * (ops.xiaojufenInternalPct || 0);
  const payFeeExtGun = stExtGun * (ops.payFeePct || 0);
  const payFeeIntGun = stIntGun * (ops.payFeeInternalPct || 0);
  const useExcelAlign = ops.excelCashInterest !== false;
  const rampExt = stationIncomeRampFactor({
    opsMonth1Based,
    rampYears: stationExternalRampYears(ops),
    rampStartLoad: stationExternalRampStart(ops),
    forceFull: useExcelAlign,
  });
  const rampInt = stationIncomeRampFactor({
    opsMonth1Based,
    rampYears: stationInternalRampYears(ops),
    rampStartLoad: stationInternalRampStart(ops),
    forceFull: useExcelAlign,
  });
  const ancDelay = Math.max(0, Math.round(ops.ancillaryDelayMonths ?? 6));
  const rampAnc = useExcelAlign
    ? opsMonth1Based >= 900 || opsMonth1Based > ancDelay
      ? 1
      : 0
    : stationIncomeRampFactor({
        opsMonth1Based,
        rampYears: stationAncillaryRampYears(ops),
        rampStartLoad: stationAncillaryRampStart(ops),
      });
  const g = Math.max(0, guns);
  const ancIn = Math.max(0, ops.ancillaryMxn || 0) * rampAnc;
  const parkingMo = g > 0 ? Math.max(0, ops.parkingRentMxn || 0) : 0;
  const chargeExtMo = g * stExtGun * rampExt;
  const chargeIntMo = g * stIntGun * rampInt;
  const elecMo = g * (stElecExtGun * rampExt + stElecIntGun * rampInt);
  const platformMo =
    g * (platformExtGun * rampExt + platformIntGun * rampInt);
  const payFeeMo = g * (payFeeExtGun * rampExt + payFeeIntGun * rampInt);
  const rentMo = g > 0 ? ops.rentMonthMxn : 0;
  const opexPackMo = g > 0 ? ops.opexMonthMxn : 0;
  const maintUse =
    g > 0 && !useExcelAlign ? Math.max(0, maintMxn) : 0;
  const revMo = chargeExtMo + chargeIntMo + parkingMo + ancIn;
  const varMo = elecMo + platformMo + payFeeMo;
  const fixedMo = rentMo + opexPackMo + maintUse;
  const grossMo = revMo - varMo - fixedMo;
  const debtPiMo = Math.max(0, args.debtPiMo || 0);
  const debtMezzMo = Math.max(0, args.debtMezzMo || 0);
  const financeMo = debtPiMo + debtMezzMo;
  return {
    chargeExtMo,
    chargeIntMo,
    parkingMo,
    ancillaryMo: ancIn,
    elecMo,
    platformMo,
    payFeeMo,
    rentMo,
    opexPackMo,
    maintMo: maintUse,
    debtPiMo,
    debtMezzMo,
    revMo,
    varMo,
    fixedMo,
    grossMo,
    financeMo,
    equityMo: grossMo - financeMo,
    ramp: rampExt,
    rampExt,
    rampInt,
    rampAnc,
  };
}

/** 场站稳态/月桥段：对齐车辆「收入 → 成本 delta → 权益」形 */
function buildStationBridgeSteps(
  parts: StationMonthParts,
  opts?: { ivaCashMo?: number },
): WfBridgeStep[] {
  const ivaCash = Math.max(0, opts?.ivaCashMo || 0);
  const steps: WfBridgeStep[] = [];
  if (parts.revMo > 0.01) {
    steps.push({
      id: "passenger",
      label: "场站经营收入",
      kind: "total",
      mxn: parts.revMo,
      module: "income",
    });
  }
  const deltas: { id: string; label: string; mxn: number; module: WfModule }[] =
    [
      {
        id: "platform",
        label: "平台佣金",
        mxn: parts.platformMo,
        module: "platform",
      },
      { id: "pay_fee", label: "通道费", mxn: parts.payFeeMo, module: "platform" },
      { id: "charge", label: "充电", mxn: parts.elecMo, module: "energy" },
      {
        id: "fix_site_rent",
        label: "场租",
        mxn: parts.rentMo,
        module: "fixed",
      },
      {
        id: "fix_opex",
        label: "运维",
        mxn: parts.opexPackMo,
        module: "fixed",
      },
      {
        id: "fix_maint",
        label: "保养",
        mxn: parts.maintMo,
        module: "fixed",
      },
      {
        id: "iva_output",
        label: "IVA付现",
        mxn: ivaCash,
        module: "tax",
      },
      {
        id: "investor_pi",
        label: "优先",
        mxn: parts.debtPiMo,
        module: "finance",
      },
      {
        id: "investor_mezz",
        label: "夹层",
        mxn: parts.debtMezzMo,
        module: "finance",
      },
    ];
  for (const d of deltas) {
    if (d.mxn <= 0.01) continue;
    steps.push({
      id: d.id,
      label: d.label,
      kind: "delta",
      mxn: -d.mxn,
      module: d.module,
    });
  }
  steps.push({
    id: "equity_residual",
    label: "权益",
    kind: "total",
    mxn: parts.equityMo - ivaCash,
    module: "equity",
  });
  return steps;
}

function stationPartsToWfBucket(parts: StationMonthParts): Record<string, number> {
  const b: Record<string, number> = {
    _passenger: parts.revMo,
  };
  if (parts.platformMo > 0.01) b.platform = parts.platformMo;
  if (parts.payFeeMo > 0.01) b.pay_fee = parts.payFeeMo;
  if (parts.elecMo > 0.01) b.charge = parts.elecMo;
  if (parts.rentMo > 0.01) b.fix_site_rent = parts.rentMo;
  if (parts.opexPackMo > 0.01) b.fix_opex = parts.opexPackMo;
  if (parts.maintMo > 0.01) b.fix_maint = parts.maintMo;
  if (parts.debtPiMo > 0.01) b.investor_pi = parts.debtPiMo;
  if (parts.debtMezzMo > 0.01) b.investor_mezz = parts.debtMezzMo;
  if (Math.abs(parts.equityMo) > 0.01) {
    b.equity_residual = Math.max(0, parts.equityMo);
  }
  return b;
}

/** 场站月度销项/经营进项（对齐车辆 day.tax；工资类不进进项） */
function stationMonthIvaTax(args: {
  parts: StationMonthParts;
  vat: number;
  cfg: AssetCashflowConfig;
}): { outputMo: number; inputMo: number; netMo: number } {
  const vatRate = Math.max(0, args.vat);
  if (!(vatRate > 0)) return { outputMo: 0, inputMo: 0, netMo: 0 };
  const revInc = cfOpsRevIncludesVat(args.cfg);
  const outputMo =
    args.parts.revMo > 0.01
      ? vatOnAmountMxn(args.parts.revMo, vatRate, revInc)
      : 0;
  const deductible =
    args.parts.elecMo +
    args.parts.platformMo +
    args.parts.payFeeMo +
    args.parts.rentMo +
    args.parts.opexPackMo +
    args.parts.maintMo;
  const inputMo =
    deductible > 0.01 ? vatOnAmountMxn(deductible, vatRate, true) : 0;
  return { outputMo, inputMo, netMo: outputMo - inputMo };
}

/**
 * 把 IVA 写入堆叠桶：完整申报=购置进项贷方滚动后付现；
 * 未税+拆销项=当月销项−经营进项示意扣池。
 */
function applyStationIvaToWfBucket(
  bucket: Record<string, number>,
  parts: StationMonthParts,
  cfg: AssetCashflowConfig,
  vat: number,
  creditRef: { mxn: number },
): number {
  const tax = stationMonthIvaTax({ parts, vat, cfg });
  if (!(vat > 0)) return 0;
  if (cfVatNetInCashflow(cfg)) {
    const settled = settleEntityIvaMonth({
      outputMxn: tax.outputMo,
      opsInputMxn: tax.inputMo,
      creditMxn: creditRef.mxn,
    });
    creditRef.mxn = settled.creditAfterMxn;
    if (settled.cashOutMxn > 0.01) {
      bucket.iva_output = settled.cashOutMxn;
      bucket.equity_residual = Math.max(
        0,
        (bucket.equity_residual || 0) - settled.cashOutMxn,
      );
      return settled.cashOutMxn;
    }
    return 0;
  }
  if (cfOpsVatEnabled(cfg) && !cfOpsRevIncludesVat(cfg)) {
    const cash = Math.max(0, tax.netMo);
    if (cash > 0.01) {
      bucket.iva_output = cash;
      bucket.equity_residual = Math.max(
        0,
        (bucket.equity_residual || 0) - cash,
      );
      return cash;
    }
  }
  return 0;
}

function buildStationDebtPayAtMonth(args: {
  unitLandedMxn: number;
  spvTiers: WaterfallTier[];
  financeMonth: number;
}): { pi: number; mezz: number } {
  const tiers = args.spvTiers || [];
  let pi = 0;
  let mezz = 0;
  for (const id of DEBT_TIER_ORDER) {
    const tier = tiers.find((t) => t.id === id && t.enabled && t.investor);
    if (!tier?.investor) continue;
    const inv = normalizeInvestorPi(tier.investor);
    const prinOne =
      args.unitLandedMxn * Math.max(0, Math.min(1, inv.principalPct));
    if (!(prinOne > 0)) continue;
    const pay = investorMonthPayMxn(inv, prinOne, args.financeMonth);
    if (id === "investor_pi") pi += pay;
    else if (id === "investor_mezz") mezz += pay;
  }
  return { pi, mezz };
}

type StationWfBuildArgs = {
  guns: number;
  ops: StationOpsConstants;
  maintMxn: number;
  unitLandedMxn: number;
  spvTiers: WaterfallTier[];
  holdMonths: number;
  vat: number;
  cfg: AssetCashflowConfig;
  sku: AssetSku;
  configId?: string;
};

function buildStationYearlyWfTotals(args: StationWfBuildArgs): YearlyWfRow[] {
  const n = Math.max(1, Math.min(120, Math.round(args.holdMonths) || 60));
  const yearCount = Math.max(1, Math.ceil(n / 12));
  const buckets: Record<number, Record<string, number>> = {};
  for (let y = 1; y <= yearCount; y++) buckets[y] = {};
  const creditRef = {
    mxn:
      cfVatNetInCashflow(args.cfg) && args.vat > 0
        ? unitPurchaseIvaCreditMxn(args.sku, args.vat, args.configId)
        : 0,
  };
  for (let m = 1; m <= n; m++) {
    const debt = buildStationDebtPayAtMonth({
      unitLandedMxn: args.unitLandedMxn,
      spvTiers: args.spvTiers,
      financeMonth: m,
    });
    const parts = stationMonthPartsAt({
      guns: args.guns,
      ops: args.ops,
      maintMxn: args.maintMxn,
      opsMonth1Based: m,
      debtPiMo: debt.pi,
      debtMezzMo: debt.mezz,
    });
    const y = Math.ceil(m / 12);
    const b = buckets[y]!;
    const add = stationPartsToWfBucket(parts);
    applyStationIvaToWfBucket(add, parts, args.cfg, args.vat, creditRef);
    for (const [k, v] of Object.entries(add)) {
      b[k] = (b[k] || 0) + v;
    }
  }
  return Array.from({ length: yearCount }, (_, i) => {
    const yearId = i + 1;
    const by = buckets[yearId] || {};
    return {
      yearId,
      label: `Y${yearId}`,
      bySliceId: by,
      incomeMxn: by._passenger || 0,
      equityMxn: by.equity_residual || 0,
    };
  });
}

function buildStationMonthlyWfRows(
  args: StationWfBuildArgs,
  filter?: { yearId?: number },
): YearlyWfRow[] {
  const n = Math.max(1, Math.min(120, Math.round(args.holdMonths) || 60));
  const rows: YearlyWfRow[] = [];
  const creditRef = {
    mxn:
      cfVatNetInCashflow(args.cfg) && args.vat > 0
        ? unitPurchaseIvaCreditMxn(args.sku, args.vat, args.configId)
        : 0,
  };
  for (let m = 1; m <= n; m++) {
    const yearId = Math.ceil(m / 12);
    const debt = buildStationDebtPayAtMonth({
      unitLandedMxn: args.unitLandedMxn,
      spvTiers: args.spvTiers,
      financeMonth: m,
    });
    const parts = stationMonthPartsAt({
      guns: args.guns,
      ops: args.ops,
      maintMxn: args.maintMxn,
      opsMonth1Based: m,
      debtPiMo: debt.pi,
      debtMezzMo: debt.mezz,
    });
    const by = stationPartsToWfBucket(parts);
    applyStationIvaToWfBucket(by, parts, args.cfg, args.vat, creditRef);
    if (filter?.yearId != null && yearId !== filter.yearId) continue;
    const moInYear = ((m - 1) % 12) + 1;
    rows.push({
      yearId,
      label: filter?.yearId != null ? `M${moInYear}` : `M${m}`,
      bySliceId: by,
      incomeMxn: by._passenger || 0,
      equityMxn: by.equity_residual || 0,
    });
  }
  return rows;
}

/** 场地押金（软成本 deposit）——到期/退租可收回，不按残值率折旧 */
function stationSiteDepositMxn(sku: AssetSku): number {
  return Math.max(
    0,
    (sku.softCosts || []).find((s) => s.id === "deposit")?.amountMxn || 0,
  );
}

/**
 * 单月经营净额（无债、无押金退还）——与 buildStationMonthBars 经营段同口径。
 * opsMonth1Based：投运第几月（用于爬坡）。
 */
function stationOpsMonthNetMxn(args: {
  guns: number;
  ops: StationOpsConstants;
  maintMxn: number;
  opsMonth1Based: number;
}): number {
  return stationMonthPartsAt({
    guns: args.guns,
    ops: args.ops,
    maintMxn: args.maintMxn,
    opsMonth1Based: args.opsMonth1Based,
    debtPiMo: 0,
    debtMezzMo: 0,
  }).grossMo;
}

/**
 * 场站转让估值 = 剩余经营现金流 NPV + 可收回场地押金。
 * 转让时点：已投运 holdMonths 月末；买方付的是此后至「租约与物理寿命孰短」的未杠杆经营 CF 折现。
 * 租约到期（无续约）时剩余经营月数可为 0，转让价≈押金。
 */
function stationOpsEndMonths(ops: StationOpsConstants, physMonths: number): number {
  const leaseMo = Math.max(
    1,
    Math.round((ops.leaseYears != null ? ops.leaseYears : 5) * 12),
  );
  const phys = Math.max(1, Math.round(physMonths) || 1);
  return Math.min(phys, leaseMo);
}

function stationTransferValuationMxn(args: {
  sku: AssetSku;
  guns: number;
  ops: StationOpsConstants;
  maintMxn: number;
  holdMonths: number;
  physMonths: number;
  discountAnn: number;
}): {
  npvRemainingOps: number;
  siteDeposit: number;
  transferTotal: number;
  remainingOpsMonths: number;
  opsEndMonths: number;
  leaseMonths: number;
} {
  const hold = Math.max(0, Math.round(args.holdMonths) || 0);
  const leaseMonths = Math.max(
    1,
    Math.round((args.ops.leaseYears != null ? args.ops.leaseYears : 5) * 12),
  );
  const opsEnd = stationOpsEndMonths(args.ops, args.physMonths);
  const remaining: number[] = [];
  for (let m = hold + 1; m <= opsEnd; m++) {
    remaining.push(
      stationOpsMonthNetMxn({
        guns: args.guns,
        ops: args.ops,
        maintMxn: args.maintMxn,
        opsMonth1Based: m,
      }),
    );
  }
  const npvRemainingOps = npvAnnualOnMonths(remaining, args.discountAnn);
  const siteDeposit = stationSiteDepositMxn(args.sku);
  return {
    npvRemainingOps,
    siteDeposit,
    transferTotal: npvRemainingOps + siteDeposit,
    remainingOpsMonths: remaining.length,
    opsEndMonths: opsEnd,
    leaseMonths,
  };
}

