const DEFAULT_STATION_SKUS: AssetSku[] =
  STATION_TIER_DEFS.map(buildStationSku);

/** 旧场站 id → 中型站（兼容购物车/订单持久化） */
const STATION_ID_ALIASES: Record<string, string> = {
  "station-dc-gun": "station-medium",
  "station-demo-01": "station-medium",
};

function resolveSkuId(id: string): string {
  return STATION_ID_ALIASES[id] || id;
}

/** 寿命默认：会计 5 / 物理车辆 12·场站 8 / 维保 5；上限默认 15（可调） */
const DEFAULT_LIFE_YEARS = {
  acct: 5,
  physVehicle: 12,
  physStation: 8,
  maint: 5,
  cap: 15,
  capMin: 5,
  capMax: 30,
} as const;

/** 各寿命期末残值率默认（0–1）；可在资产估值页调节 */
const DEFAULT_END_RESIDUAL = {
  acct: 0.1,
  phys: 0,
  maint: 0,
} as const;

/** 四类寿命对照（问号浮层 · pre-wrap 表格） */
const LIFE_YEARS_HINT_TABLE_ZH = `四类「寿命」对照（折旧年限=会计寿命，同一字段 acctYears）：

| 名称 | 字段 | 管什么 | 驱动什么 | 与谁不同 |
| 市场寿命 | holdYears | 持有/处置展望、路径月数 | IRR/NPV/回本、期末处置价；路径长度=年×12 | ≠ 会计折旧年数 |
| 会计寿命/折旧年限 | acctYears | 地域折旧制度、账面直线终点 | 账面残值/折旧对照；LTO/RTO 未手改时路径月数 | = 折旧年限；≠ 市场/物理 |
| 物理寿命 | physYears | 可运营年限、成交曲线跨度 | 运营现金流；NPV/VTL 残值取 min(物理,维保,市场) | ≠ 市场处置年数 |
| 维保寿命 | maintYears | 主机厂质保/维保政策 | 维保期末残值对照；债未退出时参与 VTL 孰低 | 可短于物理；≠ 账面折旧 |

场站另有「租约寿命」leaseYears（默认 5）：剩余经营 NPV 与路径最长月数取 min(租约, 物理)；租约到期无续约 → 剩余经营 NPV=0（仅押金等）。`;

function lifeYearsFieldTip(short: string): string {
  return `${short}\n\n${LIFE_YEARS_HINT_TABLE_ZH}`;
}

