/** 显著差于对照的阈值：盈利≥5%、出险相对≥20%、保值≥3% */
const OPS_GAP_THRESH = {
  earnPct: 0.05,
  claimRel: 0.2,
  residualPct: 0.03,
};

function operatorQualityOf(id: ManagerId): OperatorOpsQuality {
  const live = OPERATOR_LIVE.find((o) => o.id === id);
  const baked =
    OPERATOR_OPS_QUALITY.find((q) => q.manager === id) ||
    OPERATOR_OPS_QUALITY[0]!;
  if (!live) return { ...baked, manager: id };
  return {
    manager: id,
    earnIndex: live.earnIndex ?? baked.earnIndex,
    claimPer100Yr: live.claimPer100Yr ?? baked.claimPer100Yr,
    residualMul: live.residualMul ?? baked.residualMul,
    insuranceMul: live.insuranceMul ?? baked.insuranceMul,
    noteZh:
      live.qualityNoteZh ||
      live.hint ||
      (id === baked.manager ? baked.noteZh : `${live.nameZh}·自定义档案`),
  };
}

function operatorDecisionScore(q: OperatorOpsQuality): number {
  return q.earnIndex * 100 - q.claimPer100Yr * 0.8 + (q.residualMul - 1) * 80;
}

/** a 是否显著差于 b（同资产决策） */
function isOpsSignificantlyWorse(
  a: OperatorOpsQuality,
  b: OperatorOpsQuality,
): boolean {
  const earnWorse =
    b.earnIndex / Math.max(a.earnIndex, 0.01) - 1 >= OPS_GAP_THRESH.earnPct;
  const claimWorse =
    (a.claimPer100Yr - b.claimPer100Yr) / Math.max(b.claimPer100Yr, 1) >=
    OPS_GAP_THRESH.claimRel;
  const resWorse =
    b.residualMul / Math.max(a.residualMul, 0.01) - 1 >=
    OPS_GAP_THRESH.residualPct;
  return earnWorse || claimWorse || resWorse;
}

function bestOperatorByQuality(
  ids: ManagerId[],
): { id: ManagerId; q: OperatorOpsQuality } | null {
  const uniq = [...new Set(ids.filter(Boolean))];
  if (!uniq.length) return null;
  let best = uniq[0]!;
  let bestQ = operatorQualityOf(best);
  let bestS = operatorDecisionScore(bestQ);
  for (const id of uniq.slice(1)) {
    const q = operatorQualityOf(id);
    const s = operatorDecisionScore(q);
    if (s > bestS) {
      best = id;
      bestQ = q;
      bestS = s;
    }
  }
  return { id: best, q: bestQ };
}

/**
 * 资产基础现金流：时点支出柱 + 乘客付费→平台/支付手续费→运营SPV→SPV内瀑布。
 * 投放情境 = 国家 × 业态 × 模式。
 */
type CfLayer = "platform" | "spv";

/** 司机工资预留周期 */
type WageReserveCycle = "day" | "week" | "month";

/** 充电成本录入/预付周期（瀑布仍折成日扣） */
type ChargePayCycle = "day" | "week" | "month" | "year";

/** 优先本息还本付息规则 */
type DebtServiceRule =
  | "interest_only"
  | "equal_principal"
  | "equal_payment"
  | "convert_equity";

type InvestorDepositMode = "months" | "principal_pct";

type InvestorPiDetail = {
  /** 本金占单车落地成本比例（LTV） */
  principalPct: number;
  /** 年化利率 */
  annualRate: number;
  /** 期限（月） */
  tenureMonths: number;
  /** @deprecated 兼容旧持久化；见 interestOnlyMonths */
  graceMonths: number;
  /** @deprecated 兼容旧持久化；true=免本期只还息 */
  interestDuringGrace: boolean;
  /** 只还息月数（期内不还本，按 opening balance × 月利率付息） */
  interestOnlyMonths: number;
  /** 只还息期位置：front=期初前置，back=期末后置（末月含气球还本） */
  interestOnlyTiming: "front" | "back";
  rule: DebtServiceRule;
  /**
   * 期末剩余转股：发放本金比例 0–1（可与等额本息/等额本金/只还息叠加）。
   * 期内月供按「发放本金×(1−本比例)」摊还；本比例作期末气球（期内只计息、到期转股不现金清偿）。
   * rule=convert_equity 为旧口径（整期只还息后转股），新录入用 rule+本字段。
   */
  convertRemainingPct?: number;
  /** 转股定价 PB 倍数（×权益账面净资产） */
  convertPbMultiple?: number;
  /** 转股后按权益层同权参与 residual（对齐权益收益率路径） */
  convertAlignEquityYield?: boolean;
  /**
   * 保证金口径：
   * - months：稳态月供 × depositMonths（月本息）
   * - principal_pct：该档本金 × depositPrincipalPct（占优先/夹层投资金额）
   * 期初锁定、本息结清当月退还；金额为 0 则不设。
   */
  depositMode?: InvestorDepositMode;
  /** 保证金（月本息）：稳态月供×月数；depositMode=months 时生效 */
  depositMonths: number;
  /** 保证金占该档本金比例 0–1；depositMode=principal_pct 时生效 */
  depositPrincipalPct?: number;
};

/** 计划层债档订立（对齐融资假设 InvestorPiDetail 字段子集） */
type PlanDebtTierOverride = {
  enabled?: boolean;
  principalPct?: number;
  annualRate?: number;
  tenureMonths?: number;
  interestOnlyMonths?: number;
  interestOnlyTiming?: "front" | "back";
  rule?: DebtServiceRule;
  depositMode?: InvestorDepositMode;
  /** 保证金：几个月本息（months 口径） */
  depositMonths?: number;
  /** 保证金占该档本金比例 0–1（principal_pct 口径） */
  depositPrincipalPct?: number;
  /** 期末剩余转股比例 0–1；0=关 */
  convertRemainingPct?: number;
  convertPbMultiple?: number;
  convertAlignEquityYield?: boolean;
};

/** 计划订立默认：对齐案例优先 LTC90% / 13.5% / 3+36 · 等额本息 */
const PLAN_SENIOR_DEBT_DEFAULT: PlanDebtTierOverride = {
  enabled: true,
  principalPct: 0.9,
  annualRate: 0.135,
  tenureMonths: 39,
  interestOnlyMonths: 3,
  interestOnlyTiming: "front",
  rule: "equal_payment",
  depositMode: "months",
  depositMonths: 0,
  depositPrincipalPct: 0,
  convertRemainingPct: 0,
  convertPbMultiple: 1,
  convertAlignEquityYield: true,
};

const PLAN_MEZZ_DEBT_DEFAULT: PlanDebtTierOverride = {
  enabled: true,
  principalPct: 0.1,
  annualRate: 0.18,
  tenureMonths: 39,
  interestOnlyMonths: 0,
  interestOnlyTiming: "front",
  rule: "equal_payment",
  depositMode: "months",
  depositMonths: 0,
  depositPrincipalPct: 0,
  convertRemainingPct: 0,
  convertPbMultiple: 1,
  convertAlignEquityYield: true,
};

function planDebtRuleShown(ov: PlanDebtTierOverride): DebtServiceRule {
  if (ov.rule === "convert_equity") return "interest_only";
  if (
    ov.rule === "equal_payment" ||
    ov.rule === "equal_principal" ||
    ov.rule === "interest_only"
  ) {
    return ov.rule;
  }
  return "equal_payment";
}

function planDebtHasEndConvert(ov: PlanDebtTierOverride): boolean {
  return (ov.convertRemainingPct ?? 0) > 1e-9;
}

/** 计划层单档融资条款编辑（字段对齐「融资假设」） */
function PlanDebtTierFields(props: {
  titleZh: string;
  value: PlanDebtTierOverride;
  onPatch: (patch: Partial<PlanDebtTierOverride>) => void;
}) {
  const inv = { ...props.value };
  const tenure = Math.max(1, Math.round(inv.tenureMonths ?? 39));
  const io = Math.max(
    0,
    Math.min(tenure - 1, Math.round(inv.interestOnlyMonths ?? 0)),
  );
  return (
    <Stack gap={6}>
      <Text size="small" weight="semibold">
        {props.titleZh}
      </Text>
      <Grid columns={GRID_TIER_FIELDS} gap={4}>
        <NumField
          compact
          label="本金比例 %"
          value={ratePctShown(inv.principalPct ?? 0, 2)}
          onChange={(n) =>
            props.onPatch({
              principalPct: Math.max(0, Math.min(1, n / 100)),
            })
          }
          hint="占落地成本"
        />
        <NumField
          compact
          label="年化利率 %"
          value={ratePctShown(inv.annualRate ?? 0)}
          onChange={(n) => props.onPatch({ annualRate: ratePctToAnnual(n) })}
        />
        <NumField
          compact
          label="期限月"
          value={tenure}
          onChange={(n) => {
            const t = Math.max(1, Math.min(120, Math.round(n)));
            props.onPatch({
              tenureMonths: t,
              interestOnlyMonths: Math.min(io, Math.max(0, t - 1)),
            });
          }}
        />
        {investorDepositModeOf(inv) === "principal_pct" ? (
          <NumField
            compact
            label="保证金（占本金%）"
            value={ratePctShown(inv.depositPrincipalPct ?? 0, 2)}
            onChange={(n) =>
              props.onPatch({
                depositMode: "principal_pct",
                depositPrincipalPct: Math.max(0, Math.min(1, n / 100)),
              })
            }
            hint="占该档本金"
          />
        ) : (
          <NumField
            compact
            label="保证金（月本息）"
            value={inv.depositMonths ?? 0}
            onChange={(n) =>
              props.onPatch({
                depositMode: "months",
                depositMonths: Math.max(0, Math.min(24, Math.round(n))),
              })
            }
          />
        )}
      </Grid>
      <Row gap={4} wrap align="center">
        <Text size="small" tone="secondary">
          保证金口径
        </Text>
        {(
          [
            { id: "months" as const, label: "月本息" },
            { id: "principal_pct" as const, label: "占本金%" },
          ] as const
        ).map((o) => (
          <Pill
            key={o.id}
            size="sm"
            active={investorDepositModeOf(inv) === o.id}
            onClick={() => props.onPatch({ depositMode: o.id })}
          >
            {o.label}
          </Pill>
        ))}
      </Row>
      <Grid columns={GRID_TIER_FIELDS} gap={4}>
        <NumField
          compact
          label="只还息月"
          value={io}
          onChange={(n) =>
            props.onPatch({
              interestOnlyMonths: Math.max(
                0,
                Math.min(tenure - 1, Math.round(n)),
              ),
            })
          }
          hint={
            io > 0
              ? inv.interestOnlyTiming === "back"
                ? "期末后置"
                : "期初前置"
              : "0=无"
          }
        />
      </Grid>
      <Row gap={4} wrap align="center">
        <Text size="small" tone="secondary">
          只还息位置
        </Text>
        {IO_TIMING_OPTS.map((o) => (
          <Pill
            key={o.id}
            size="sm"
            active={(inv.interestOnlyTiming ?? "front") === o.id}
            onClick={() => props.onPatch({ interestOnlyTiming: o.id })}
          >
            {o.label}
          </Pill>
        ))}
      </Row>
      <Row gap={4} wrap align="center">
        <Text size="small" tone="secondary">
          还款
        </Text>
        {DEBT_RULE_OPTS.map((o) => (
          <Pill
            key={o.id}
            size="sm"
            active={planDebtRuleShown(inv) === o.id}
            onClick={() => props.onPatch({ rule: o.id })}
          >
            {o.label}
          </Pill>
        ))}
      </Row>
      <Row gap={6} align="center">
        <Toggle
          checked={planDebtHasEndConvert(inv)}
          onChange={(v) => {
            if (v) {
              props.onPatch({
                ...(inv.rule === "convert_equity"
                  ? { rule: "interest_only" as const }
                  : {}),
                convertRemainingPct:
                  (inv.convertRemainingPct ?? 0) > 0
                    ? inv.convertRemainingPct
                    : 0.1,
                convertPbMultiple: inv.convertPbMultiple ?? 1,
                convertAlignEquityYield: inv.convertAlignEquityYield !== false,
              });
            } else {
              props.onPatch({ convertRemainingPct: 0 });
            }
          }}
        />
        <Text size="small">期末剩余转股</Text>
      </Row>
      {planDebtHasEndConvert(inv) ? (
        <Grid columns={GRID_TIER_FIELDS} gap={4}>
          <NumField
            compact
            label="剩余转股 %"
            value={ratePctShown(inv.convertRemainingPct ?? 0, 0)}
            onChange={(n) =>
              props.onPatch({
                convertRemainingPct: Math.max(0, Math.min(100, n)) / 100,
              })
            }
            hint="到期月剩余本金"
          />
          <NumField
            compact
            label="PB 倍数"
            value={inv.convertPbMultiple ?? 1}
            onChange={(n) =>
              props.onPatch({
                convertPbMultiple: Math.max(0.01, Math.min(10, n)),
              })
            }
          />
        </Grid>
      ) : null}
    </Stack>
  );
}

type DriverWageDetail = {
  cycle: WageReserveCycle;
  /** 按所选周期录入的预留额（MXN） */
  amountMxn: number;
  /** from_card：跟资产卡司机月薪×班次×利用率；manual：手改 */
  source: "from_card" | "manual";
  /** 预留覆盖率 1=全额 */
  coverPct: number;
  /**
   * 合作分成·司机占比（占通道/平台后当时剩余池）。
   * 仅 `driver_wage.enabled=false` 时生效；默认 0=不另扣（只关全职底薪）。
   */
  coopSharePct?: number;
};

/** 必要经营支出·仅可变成本项（固定项走年养护） */
type VarOpexItem = {
  id: string;
  nameZh: string;
  enabled: boolean;
  kind: "pct_pool" | "fixed_day";
  pct: number;
  fixedDayMxn: number;
};

type VarOpexDetail = {
  items: VarOpexItem[];
};

type WaterfallTier = {
  id: string;
  nameZh: string;
  layer: CfLayer;
  /** 占「当前剩余池」比例（瀑布顺位扣除；无明细配置时用） */
  pctOfRemaining: number;
  /** 按日固定 MXN（无明细配置时用；与 pct 二选一优先 fixed） */
  fixedDayMxn: number;
  enabled: boolean;
  noteZh: string;
  investor?: InvestorPiDetail;
  wage?: DriverWageDetail;
  varOpex?: VarOpexDetail;
};

type AssetCashflowConfig = {
  /** 本 SKU 绑定的经营模式（一 SKU 一模型） */
  boundMode: OpMode;
  /** 线上支付手续费：占乘客支付；YOHO DAE 案例表里程收入已是车队口径，默认 0 */
  paymentFeePct: number;
  /**
   * 网约车平台佣金占乘客支付比例。
   * YOHO《DAE-200》IPH = 平台返佣/抽佣后的车队净应收；里程收入按净 IPH 计。
   * DAE 默认 platformTakePct=25%：反推抽佣前 IPH 与乘客支付瀑布，不重复扣车队实收。
   */
  platformTakePct: number;
  /** 运营SPV内瀑布（顺序即优先级） */
  spvTiers: WaterfallTier[];
  /** 每年固定养护（摊到月）= 启用分项合计；引擎读此字段 */
  annualMaintMxn: number;
  /** 可变成本总开关：关则路径不计通道/抽成/充电/易损/司机/过路日额（占池酌量仍走固定卡） */
  varCostEnabled: boolean;
  /** 固定成本总开关：关则路径不计年养护 */
  fixedCostEnabled: boolean;
  /** from_card：跟资产卡/情景；manual：手改分项 */
  fixedCostSource: "from_card" | "manual";
  /** 保险（年） */
  fixInsuranceYrMxn: number;
  fixInsuranceOn: boolean;
  /** 保养（月） */
  fixMaintMoMxn: number;
  fixMaintOn: boolean;
  /** 软件/GPS（月） */
  fixSoftMoMxn: number;
  fixSoftOn: boolean;
  /** 车位（月）；LTO/RTO 默认 0 */
  fixParkingMoMxn: number;
  fixParkingOn: boolean;
  /**
   * 易损件：MXN / 万公里（胎+刹+悬）。
   * 月额 = 月里程/10000 × 本单价；与「计划保养」不同。
   */
  fixWearPer10kKmMxn: number;
  fixWearOn: boolean;
  /** @deprecated 仅兼容旧持久化；引擎优先用 fixWearPer10kKmMxn */
  fixWearYrMxn?: number;
  /** 折日后的日均充电成本（引擎用；由周期预付额推导） */
  chargeDayMxn: number;
  /** 充电录入/预付周期 */
  chargeCycle: ChargePayCycle;
  /** 所选周期的预付/预提金额 MXN */
  chargeAmountMxn: number;
  /** from_card：跟电耗×电价；manual：手改 */
  chargeSource: "from_card" | "manual";
  /** 易损月期望：轮胎/刹车/悬挂等年耗÷12（由 fixWear* 推导；路径可加轻微月波动） */
  randomMaintMonthMxn: number;
  horizonMonths: number;
  /**
   * 经营收入是否含税（对齐 YOHO / Excel 现金列载）。
   * true：IPH/租金等为含税流入，路径现金不再扣销项（与表内里程收入同列）；false：未税基数。
   */
  opsRevIncludesVat: boolean;
  /**
   * 日瀑布是否展示/扣销项 IVA。
   * 含税口径（默认）下不扣经营池，仅未税基数且开启时才从池内扣销项税。
   */
  opsVatEnabled: boolean;
  /**
   * 月度 IVA 完整申报示意进路径：销项−经营进项，并用购车进项贷方余额滚动冲抵（可跨年）。
   * 默认开；假设本路径/本资产包 = 单一纳税实体、无其他业务。
   */
  vatNetInCashflow: boolean;
  /** 所得税层（示意）：本息后、权益前；默认关 */
  incomeTaxEnabled: boolean;
  /** 所得税示意税率（墨西哥 ISR 常见 30% 量级，非申报口径） */
  incomeTaxRate: number;
  /** 与《DAE-200台含IRR》1.1假设对齐版本；变更则重置默认常量 */
  assumptionsVer?: string;
};

/** 单位现金流默认假设版本（改案例表常量时递增，强制覆盖旧持久化） */
const CF_ASSUMPTIONS_VER = "arcfox-dae-iva-filing-20260902";

/** DAE 专车默认滴滴平台抽佣（占乘客支付）；底表 IPH 210 为抽佣后车队净入 */
const DAE_DEFAULT_PLATFORM_TAKE_PCT = 0.25;

const DEBT_RULE_OPTS: { id: DebtServiceRule; label: string }[] = [
  { id: "equal_payment", label: "等额本息" },
  { id: "equal_principal", label: "等额本金" },
  { id: "interest_only", label: "期内只还息" },
];

const IO_TIMING_OPTS: { id: "front" | "back"; label: string }[] = [
  { id: "front", label: "期初前置" },
  { id: "back", label: "期末后置" },
];

const WAGE_CYCLE_OPTS: { id: WageReserveCycle; label: string }[] = [
  { id: "month", label: "按月" },
  { id: "week", label: "按周" },
  { id: "day", label: "按日" },
];

const CHARGE_CYCLE_OPTS: { id: ChargePayCycle; label: string }[] = [
  { id: "day", label: "按日" },
  { id: "week", label: "按周预付" },
  { id: "month", label: "按月预付" },
  { id: "year", label: "按年预付" },
];

/** 日充电 → 周期预付额 */
function chargeAmountFromDay(
  dayMxn: number,
  cycle: ChargePayCycle,
  daysWeek = 6,
): number {
  const d = Math.max(0, dayMxn);
  const dw = Math.max(1, daysWeek || 6);
  const daysMo = opsDaysPerMonth(dw);
  if (cycle === "week") return Math.round(d * dw * 100) / 100;
  if (cycle === "month") return Math.round(d * daysMo * 100) / 100;
  if (cycle === "year") return Math.round(d * daysMo * 12 * 100) / 100;
  return Math.round(d * 100) / 100;
}

/** 周期预付额 → 日充电（瀑布扣款） */
function chargeDayFromAmount(
  amountMxn: number,
  cycle: ChargePayCycle,
  daysWeek = 6,
): number {
  const a = Math.max(0, amountMxn);
  const dw = Math.max(1, daysWeek || 6);
  const daysMo = opsDaysPerMonth(dw);
  if (cycle === "week") return a / dw;
  if (cycle === "month") return a / daysMo;
  if (cycle === "year") return a / (daysMo * 12);
  return a;
}

function chargeCycleLabelZh(cycle: ChargePayCycle): string {
  if (cycle === "week") return "周预付";
  if (cycle === "month") return "月预付";
  if (cycle === "year") return "年预付";
  return "日";
}

/** 固定成本分项 → 年合计（关总开关或关分项则不计） */
function annualMaintFromFixedLines(cfg: {
  fixedCostEnabled?: boolean;
  fixInsuranceOn?: boolean;
  fixInsuranceYrMxn?: number;
  fixMaintOn?: boolean;
  fixMaintMoMxn?: number;
  fixSoftOn?: boolean;
  fixSoftMoMxn?: number;
  fixParkingOn?: boolean;
  fixParkingMoMxn?: number;
}): number {
  if (cfg.fixedCostEnabled === false) return 0;
  let y = 0;
  if (cfg.fixInsuranceOn !== false) y += Math.max(0, cfg.fixInsuranceYrMxn || 0);
  if (cfg.fixMaintOn !== false) y += Math.max(0, cfg.fixMaintMoMxn || 0) * 12;
  if (cfg.fixSoftOn !== false) y += Math.max(0, cfg.fixSoftMoMxn || 0) * 12;
  if (cfg.fixParkingOn !== false)
    y += Math.max(0, cfg.fixParkingMoMxn || 0) * 12;
  return Math.round(y * 100) / 100;
}

/** 易损单价默认：年耗 ÷（年里程/万km） */
function defaultWearPer10kKmMxn(card: VehicleCard, wearYrMxn: number): number {
  const wearYr = Math.max(0, wearYrMxn);
  const kmDay = card.mode === "DAE" ? daeKmDay(card) : 80;
  const kmYr = kmDay * opsDaysPerMonth(card.daysWeek || 6) * 12;
  if (kmYr < 100) return 0;
  return Math.round((wearYr / (kmYr / 10000)) * 10) / 10;
}

/** 易损月额：元/万km × 月里程 */
function wearMonthFromFixed(
  cfg: {
    fixWearOn?: boolean;
    fixWearPer10kKmMxn?: number;
    fixWearYrMxn?: number;
  },
  card?: VehicleCard,
): number {
  if (cfg.fixWearOn === false) return 0;
  if (card) {
    const per10k = Math.max(0, cfg.fixWearPer10kKmMxn || 0);
    if (per10k > 0) {
      const kmDay = card.mode === "DAE" ? daeKmDay(card) : 80;
      const kmMo = kmDay * opsDaysPerMonth(card.daysWeek || 6);
      return Math.round((kmMo / 10000) * per10k * 100) / 100;
    }
  }
  /** 旧口径回落：年耗÷12 */
  return Math.round((Math.max(0, cfg.fixWearYrMxn || 0) / 12) * 100) / 100;
}

