/** 额度天花板闭合：优先÷LTC vs 实算总投（§0 额度匹配） */
function yohoFacilityCeilingClosure(r: typeof YOHO_REPORT_V242 = YOHO_REPORT_V242) {
  const ceilingUsd = r.creditFacilityUsd / Math.max(r.pkgLtc, 1e-9);
  const vehicleUsd = r.creditUnitsActual * r.unitOnBoardUsd;
  const actualTotalUsd = vehicleUsd + r.stationCapexUsd;
  const seniorUsd = actualTotalUsd * r.pkgLtc;
  const juniorUsd = actualTotalUsd - seniorUsd;
  const slackUsd = ceilingUsd - actualTotalUsd;
  const fillPct = Math.min(1.2, actualTotalUsd / Math.max(ceilingUsd, 1e-9));
  return {
    ceilingUsd,
    vehicleUsd,
    actualTotalUsd,
    seniorUsd,
    juniorUsd,
    slackUsd,
    fillPct,
    withinCeiling: slackUsd >= -1,
  };
}

