type DrawdownEnvelopeBatch = {
  seq: number;
  ym: string;
  labelZh: string;
  units: number;
  withStation: boolean;
  contentZh: string;
};

type DrawdownEnvelope = {
  id: string;
  labelZh: string;
  reportVer: string;
  facilityUsd: number;
  maxUnits: number;
  maxStations: number;
  ltc: number;
  batches: DrawdownEnvelopeBatch[];
};

const YOHO_DRAWDOWN_ENVELOPE: DrawdownEnvelope = {
  id: "yoho-credit-65p1-v238",
  labelZh: "案例授信包放款包络（表4-0）",
  reportVer: YOHO_REPORT_V242.reportVer,
  facilityUsd: YOHO_REPORT_V242.creditFacilityUsd,
  maxUnits: YOHO_REPORT_V242.creditUnitsActual,
  maxStations: 1,
  ltc: YOHO_REPORT_V242.pkgLtc,
  batches: YOHO_REPORT_V242.creditDeployBatches.map((b, i) => ({
    seq: i + 1,
    ym: b.ym,
    labelZh: b.labelZh,
    units: b.units,
    withStation: !!b.withStation,
    contentZh: b.withStation
      ? "车辆采购上牌/车机投产 + 首座场站电容接入与工程建设"
      : "车辆采购与投产前置（上牌、GPS/车机、保险等）",
  })),
};

function drawdownEnvelopeTotals(env: DrawdownEnvelope) {
  const units = env.batches.reduce((s, b) => s + b.units, 0);
  const stations = env.batches.filter((b) => b.withStation).length;
  return {
    units,
    stations,
    withinUnits: units <= env.maxUnits,
    withinStations: stations <= env.maxStations,
  };
}

