/** 投后监控矩阵（Ⅰ–Ⅳ · DSCR∥VTL） */
function PostInvestWatchDashboard(props: { compact?: boolean }) {
  const r = YOHO_REPORT_V242.vtlRefP90;
  const [tierFocus, setTierFocus] = useCanvasState<PostInvestTierId | "all">(
    "postInvestTierFocus",
    "all",
  );
  const [planOverride] = useCanvasState<PlanOverride>("planOverrideV1", {});
  const [dscrRefModeRaw] = useCanvasState<PkgDscrRefLineMode>(
    "pkgDscrRefLineMode",
    "plan_target",
  );
  const dscrRefMode = normalizePkgDscrRefMode(dscrRefModeRaw);
  const dscrRamp: YohoPkgRampMode = planOverride.yohoPkgRampMode ?? "base24";
  const dscrCurve = planOverrideToYohoPkgRampCurve(planOverride);
  const [vtlFxBufferPctWatch] = useCanvasState<number>("vtlFxBufferPct", 0.1);
  const dscrFxBuf =
    planOverride.fxBufferPct != null
      ? Math.max(0, Math.min(0.5, planOverride.fxBufferPct))
      : Math.max(0, Math.min(0.5, vtlFxBufferPctWatch));
  const dscrRows = buildCalendarAlignedPackageMonths({
    planId: "yoho-credit-65p1-v238",
    rampMode: dscrRamp,
    rampCurve: dscrCurve,
    planDebt: {
      seniorDebt: planOverride.seniorDebt,
      mezzDebt: planOverride.mezzDebt,
    },
    scenario: "base",
  });
  const dscrSeriesWatch = buildPkgDscrSeries(
    dscrRows,
    dscrRamp,
    dscrCurve,
    dscrFxBuf,
  );
  const dscrThWatch = resolvePkgDscrThresholds(
    dscrSeriesWatch,
    dscrRefMode,
    dscrSeriesWatch,
  );
  const pkgSeniorWatch = resolveYohoPkgDebtFromPlan({
    seniorDebt: planOverride.seniorDebt,
    mezzDebt: planOverride.mezzDebt,
  }).senior;
  const vtlFormulaWatch = vtlSeniorCoverageRefPcts(
    pkgSeniorWatch.principalPct,
  );
  const rules =
    tierFocus === "all"
      ? POST_INVEST_WATCH_RULES
      : POST_INVEST_WATCH_RULES.filter((x) => x.tier === tierFocus);
  return (
    <Stack gap={props.compact ? 6 : 8}>
      <Row gap={6} align="center" wrap>
        <Text size="small" weight="medium">
          投后监控 · Ⅰ–Ⅳ
        </Text>
        <Pill size="sm" tone="info" active>
          经营目标三线
        </Pill>
        <Pill size="sm" tone="info">
          跟台账路径
        </Pill>
        <Pill
          size="sm"
          active={tierFocus === "all"}
          onClick={() => setTierFocus("all")}
        >
          全部
        </Pill>
        {POST_INVEST_TIER_META.map((t) => (
          <Pill
            key={t.id}
            size="sm"
            active={tierFocus === t.id}
            onClick={() => setTierFocus(t.id)}
          >
            {t.labelZh}
          </Pill>
        ))}
      </Row>
      <Callout tone="info" title="读法">
        Ⅰ异常通常领先于Ⅱ；Ⅱ-5 DSCR 与 Ⅲ-1 VTL
        并列触发。基准线=中性计划经营目标（达产稳态），不是报告写死输入；报告数字仅参考样例。Ⅳ爬坡窗内低于目标属计划达产过程；达产后相对目标的偏离才是计划—实际差距。
      </Callout>
      <Grid columns={GRID_STATS} gap={8}>
        <Stat
          label="VTL 经营目标"
          value={
            vtlFormulaWatch
              ? `${vtlFormulaWatch.baseline}%`
              : `${r.observe}%`
          }
          tone="info"
        />
        <Stat
          label="VTL 补仓"
          value={
            vtlFormulaWatch
              ? `${vtlFormulaWatch.marginCall}%`
              : `${r.margin}%`
          }
          tone="warning"
        />
        <Stat
          label="VTL 平仓"
          value={
            vtlFormulaWatch
              ? `${vtlFormulaWatch.liquidation}%`
              : `${r.liquidate}%`
          }
          tone="danger"
        />
        <Stat
          label={
            dscrRefMode === "plan_target"
              ? "DSCR 目标/补仓/平仓"
              : "DSCR 样例观察/补仓/平仓"
          }
          value={`${dscrThWatch.observe.toFixed(2)}/${dscrThWatch.margin.toFixed(2)}/${dscrThWatch.liquidate.toFixed(2)}×`}
        />
      </Grid>
      {POST_INVEST_TIER_META.filter(
        (t) => tierFocus === "all" || tierFocus === t.id,
      ).map((t) => (
        <Stack key={t.id} gap={4}>
          <Text size="small" weight="medium">
            {`${t.labelZh} · ${t.roleZh}`}
          </Text>
          <Table
            headers={["编号", "指标", "基准", "黄/观察", "橙/补仓", "平仓"]}
            columnAlign={["left", "left", "left", "left", "left", "left"]}
            rows={rules
              .filter((row) => row.tier === t.id)
              .map((row) => [
                row.code,
                row.metricZh,
                row.baselineZh,
                row.yellowZh,
                row.orangeZh,
                row.liquidateZh || "—",
              ])}
            striped
          />
        </Stack>
      ))}
      <PackageDscrStrip
        rows={dscrRows}
        rampMode={dscrRamp}
        rampCurve={dscrCurve}
        fxBufferPct={dscrFxBuf}
        compact={props.compact}
      />
      <Text size="small" tone="tertiary">
        GPS/完单/流失待 Fleet 联调后自动比对；上表为细则契约。DSCR
        序列来自授信包月路径（计划层爬坡/起点负荷）；分子扣 FX buffer。
      </Text>
    </Stack>
  );
}

