/** DealTerms + 提款 Checklist（可勾销） */
function YohoDealTermsAndChecklistPanel() {
  const [checked, setChecked] = useCanvasState<Record<string, boolean>>(
    "yohoDrawdownChecklistV242",
    {},
  );
  const [termsAck, setTermsAck] = useCanvasState<Record<string, boolean>>(
    "yohoDealTermsAckV242",
    {},
  );
  const done = YOHO_DRAWDOWN_CHECKLIST.filter((c) => checked[c.id]).length;
  const total = YOHO_DRAWDOWN_CHECKLIST.length;
  const termsDone = YOHO_DEAL_TERMS.filter((t) => termsAck[t.id]).length;
  return (
    <Stack gap={10}>
      <Stack gap={6}>
        <Row gap={6} align="center" wrap>
          <Text size="small" weight="medium">
            合作条款（DealTerms）
          </Text>
          <Pill size="sm" tone={termsDone === YOHO_DEAL_TERMS.length ? "success" : "neutral"}>
            已确认 {termsDone}/{YOHO_DEAL_TERMS.length}
          </Pill>
        </Row>
        {YOHO_DEAL_TERMS.map((t) => (
          <Row key={t.id} gap={8} align="start">
            <Toggle
              checked={!!termsAck[t.id]}
              onChange={(v) =>
                setTermsAck((prev) => ({ ...prev, [t.id]: v }))
              }
            />
            <Stack gap={2} style={{ flex: 1, minWidth: 0 }}>
              <Text size="small" weight="medium">
                {t.titleZh}
              </Text>
              <Text size="small" tone="tertiary">
                {t.bodyZh}
              </Text>
            </Stack>
          </Row>
        ))}
      </Stack>
      <Divider />
      <Stack gap={6}>
        <Row gap={6} align="center" wrap>
          <Text size="small" weight="medium">
            放款前闭合清单
          </Text>
          <Pill
            size="sm"
            tone={done === total ? "success" : done > 0 ? "info" : "neutral"}
          >
            {done}/{total}
          </Pill>
          <Stat
            label="可放款？"
            value={done === total ? "条件满足（勾销完）" : "尚不可放款"}
            tone={done === total ? "success" : "warning"}
          />
        </Row>
        <Table
          headers={["", "分组", "事项"]}
          columnAlign={["left", "left", "left"]}
          rows={YOHO_DRAWDOWN_CHECKLIST.map((c) => [
            checked[c.id] ? "✓" : "○",
            c.groupZh,
            c.itemZh,
          ])}
          striped
        />
        <Row gap={6} wrap>
          {YOHO_DRAWDOWN_CHECKLIST.map((c) => (
            <Pill
              key={c.id}
              size="sm"
              active={!!checked[c.id]}
              onClick={() =>
                setChecked((prev) => ({
                  ...prev,
                  [c.id]: !prev[c.id],
                }))
              }
            >
              {checked[c.id] ? "✓ " : ""}
              {c.id}
            </Pill>
          ))}
        </Row>
        <Text size="small" tone="tertiary">
          点选上方短码勾销；闭合后请在提款备忘录附文号。非正式法律意见。
        </Text>
      </Stack>
    </Stack>
  );
}

/** 本笔授信 65+1 · 同一次额度提用（「计划」Tab 汇总为一笔） */
const YOHO_CREDIT_DRAWDOWN_PLAN_ID = "yoho-credit-65p1-v238";
/** 附录/对照用全称；主 UI 角标勿直接贴（见 displayCreditPlanScopeZh） */
const YOHO_CREDIT_DRAWDOWN_PLAN_LABEL = `案例授信包（${YOHO_REPORT_V242.reportVer}）`;
/** 节奏轨 / 左右同屏范围角标：通用名，不露案例报告版本号 */
function displayCreditPlanScopeZh(
  planId?: string | null,
  labelZh?: string | null,
): string {
  if (planId === YOHO_CREDIT_DRAWDOWN_PLAN_ID) return "当前授信包";
  const s = String(labelZh || "").trim();
  if (!s || /^案例授信包/.test(s) || /V2\.\d+/.test(s)) return "当前授信包";
  return s;
}

function inferCreditDrawdownSeq(orderId: string): number | undefined {
  const m = String(orderId || "").match(/^po-yoho-credit-(\d{4}-\d{2})$/);
  if (!m) return undefined;
  const idx = YOHO_REPORT_V242.creditDeployBatches.findIndex(
    (b) => b.ym === m[1],
  );
  return idx >= 0 ? idx + 1 : undefined;
}

