/** 包层 DSCR 三线方法常数（平仓底 + 垫头切分份额）。
 * 经营目标（基准）来自中性计划达产稳态 DSCR，不是报告写死输入。
 * 下列 observe/margin/steadyAnchor 仅用于标定「垫头怎么切」的方法份额；
 * 报告附录数字是参考样例，可对照不可当作计划输入项。 */
const PKG_DSCR_THRESHOLDS = {
  /** 方法样例·观察（相对 1× 垫头切分用） */
  observe: 1.25,
  margin: 1.1,
  liquidate: 1.0,
  consecutiveMonths: 2,
  /** 锁口径爬坡窗：达产前正式触发豁免（计划爬坡期内允许低于目标） */
  rampExemptMonthsLock: 15,
  /** KPI/三月达产情景：豁免窗缩短 */
  rampExemptMonthsKpi: 3,
  /** 方法样例·达产中性锚点（仅用于份额标定，非计划输入） */
  steadyAnchor: 1.52,
  /**
   * 出图从有在营+优先本息起画（含只还息/爬坡高倍数）。
   * readableMax 仅在「本息峰值月之后 + 本息已萎缩」时用于债末虚高断线。
   */
  readableMax: 5,
} as const;

/**
 * 三线切分：顶线/补仓按「经营目标相对平仓 1× 的垫头」切分。
 * 份额取自样例在 1.52× 时复现 1.25/1.10；经营目标随中性计划稳态变，三线跟着变。
 */
const PKG_DSCR_HEADROOM_SHARES = {
  observe:
    (PKG_DSCR_THRESHOLDS.observe - PKG_DSCR_THRESHOLDS.liquidate) /
    (PKG_DSCR_THRESHOLDS.steadyAnchor - PKG_DSCR_THRESHOLDS.liquidate),
  margin:
    (PKG_DSCR_THRESHOLDS.margin - PKG_DSCR_THRESHOLDS.liquidate) /
    (PKG_DSCR_THRESHOLDS.steadyAnchor - PKG_DSCR_THRESHOLDS.liquidate),
  liquidate: PKG_DSCR_THRESHOLDS.liquidate,
} as const;

/**
 * plan_target：中性计划达产稳态 = 经营目标（唯一参考线来源）
 * 旧持久化键 path/report/report_sample 一律归一为 plan_target
 */
type PkgDscrRefLineMode = "plan_target" | "report_sample" | "path" | "report";

function normalizePkgDscrRefMode(
  _mode?: PkgDscrRefLineMode | string | null,
): "plan_target" {
  return "plan_target";
}

type PkgDscrThresholdSet = {
  /** 经营目标基准 */
  baseline: number;
  observe: number;
  margin: number;
  liquidate: number;
  source: "plan_target";
};

function pkgDscrSteadyFromSeries(series: PkgDscrPt[]): number | null {
  const formal = series.filter(
    (p) => p.formalTrigger && p.dscr != null && Number.isFinite(p.dscr),
  );
  if (!formal.length) return null;
  const maxCfads = Math.max(...formal.map((p) => p.cfads));
  const hit =
    formal.find((p) => p.cfads >= maxCfads * 0.98 - 1e-6) ||
    formal[formal.length - 1]!;
  return hit.dscr != null && Number.isFinite(hit.dscr) ? hit.dscr : null;
}

/**
 * 中性计划达产稳态 → 经营目标基准，三线按垫头切分。
 * @param targetSeries 经营目标序列；缺省则用 series（当前路径）
 */
function resolvePkgDscrThresholds(
  series: PkgDscrPt[],
  _mode: PkgDscrRefLineMode = "plan_target",
  targetSeries?: PkgDscrPt[] | null,
): PkgDscrThresholdSet {
  const target = targetSeries?.length ? targetSeries : series;
  const steady = pkgDscrSteadyFromSeries(target);
  const baseline =
    steady != null && Number.isFinite(steady) && steady > 1e-9
      ? steady
      : PKG_DSCR_THRESHOLDS.steadyAnchor;
  const liquidate = PKG_DSCR_HEADROOM_SHARES.liquidate;
  const head = Math.max(0, baseline - liquidate);
  let observe = liquidate + head * PKG_DSCR_HEADROOM_SHARES.observe;
  let margin = liquidate + head * PKG_DSCR_HEADROOM_SHARES.margin;
  if (margin > observe) margin = observe;
  if (observe < liquidate) observe = liquidate;
  if (margin < liquidate) margin = liquidate;
  return { baseline, observe, margin, liquidate, source: "plan_target" };
}

/** 权益剩余用途分拆（V2.45：扩产留存 / 可动用；不进 IRR 分子） */
const EQUITY_USE_SPLIT = {
  expansionPct: 0.9,
  distributablePct: 0.1,
} as const;

function splitEquityResidualUsd(equityUsd: number) {
  const e = Number.isFinite(equityUsd) ? equityUsd : 0;
  return {
    expansionUsd: e * EQUITY_USE_SPLIT.expansionPct,
    distributableUsd: e * EQUITY_USE_SPLIT.distributablePct,
  };
}

type PkgDscrPt = {
  month: number;
  cfads: number;
  pi: number;
  dscr: number | null;
  equity: number;
  inRampExempt: boolean;
  formalTrigger: boolean;
};

function pkgDscrExemptMonths(
  rampMode: YohoPkgRampMode,
  curveOverride?: Partial<YohoPkgRampCurve> | null,
): number {
  if (
    curveOverride?.rampMonths != null &&
    Number.isFinite(curveOverride.rampMonths)
  ) {
    const m = Math.max(0, Math.round(curveOverride.rampMonths));
    /** 锁口径历史上豁免≤15（非满24）；自定义短爬坡跟达产月 */
    return Math.min(m, PKG_DSCR_THRESHOLDS.rampExemptMonthsLock);
  }
  return rampMode === "fast3"
    ? PKG_DSCR_THRESHOLDS.rampExemptMonthsKpi
    : PKG_DSCR_THRESHOLDS.rampExemptMonthsLock;
}

/** FX buffer → DSCR 分子折减系数；(1−buffer)，与组合 NPV / VTL 同键 */
function fxBufferDscrFactor(fxBufferPct?: number | null): number {
  return 1 - Math.max(0, Math.min(0.5, fxBufferPct ?? 0));
}

/**
 * 包层 DSCR 序列。
 * @param fxBufferPct 与计划 FX buffer 同键：DSCR = CFADS×(1−buffer) / 优先本息；传 0=不扣 FX
 * @param vatMode as_is=现行经营净；ex_vat=不算增值税（见 pkgCfadsForDscr）
 *
 * 出图规则（稳定口径）：
 * 1) 有在营 + 有优先本息（含只还息 / 摊还，含他批空窗叠上的息）→ 画点
 * 2) 无在营 / 无本息 → null（断线；纯空窗付息不出点，避免 0÷息）
 * 3) 仅「本息峰值月之后」且本息已萎缩、倍数仍 > readableMax → null（债末虚高）
 *    只还息/爬坡期高倍数在峰值前照常画，避免蓝线中段断线
 * 4) 爬坡豁免只影响 formalTrigger（预警），不影响出线
 */
type PkgDscrVatMode = "as_is" | "ex_vat";
/** with_fx=扣计划 FX buffer；ex_fx=分子不扣 FX（对照用） */
type PkgDscrFxMode = "with_fx" | "ex_fx";

/** 有效 FX buffer：剔 FX 时按 0 计 */
function pkgDscrEffectiveFxBuf(
  fxBufferPct: number | null | undefined,
  fxMode: PkgDscrFxMode = "with_fx",
): number {
  if (fxMode === "ex_fx") return 0;
  return Math.max(0, Math.min(0.5, fxBufferPct ?? 0));
}

/**
 * DSCR 分子用的经营净。
 *
 * 路径层（完整申报）：车辆月条 outflow 已含 IVA 轧差付现；场站付现写入 iva 并同步扣 CFADS。
 * 因此包层 `cfads` 对 IVA **只计 1 次**；`iva` 列为同额对照，不再二次改写 CFADS。
 *
 * - as_is（含IVA）：分子 = CFADS（已含 IVA）
 * - ex_vat（剔IVA）：分子 = CFADS + IVA（加回已扣付现，IVA 计 0 次）
 */
function pkgCfadsForDscr(
  r: Pick<YohoPkgMonthRow, "cfads" | "iva">,
  mode: PkgDscrVatMode = "as_is",
  _vatRate = 0.16,
): number {
  const cfads = Number.isFinite(r.cfads) ? r.cfads : 0;
  if (mode !== "ex_vat") return cfads;
  const iva = Number.isFinite(r.iva) ? Math.max(0, r.iva) : 0;
  if (iva > 1) return cfads + iva;
  return cfads;
}

/** 口径标签后缀：·剔税 / ·剔FX / ·剔税·剔FX */
function pkgDscrCaliberSuffix(
  vatMode: PkgDscrVatMode,
  fxMode: PkgDscrFxMode,
): string {
  let s = "";
  if (vatMode === "ex_vat") s += "·剔IVA";
  if (fxMode === "ex_fx") s += "·剔FX";
  return s;
}

function buildPkgDscrSeries(
  rows: YohoPkgMonthRow[],
  rampMode: YohoPkgRampMode = "base24",
  curveOverride?: Partial<YohoPkgRampCurve> | null,
  fxBufferPct?: number | null,
  vatMode: PkgDscrVatMode = "as_is",
  vatRate = 0.16,
): PkgDscrPt[] {
  const exemptN = pkgDscrExemptMonths(rampMode, curveOverride);
  const fxFac = fxBufferDscrFactor(fxBufferPct);
  const hi = PKG_DSCR_THRESHOLDS.readableMax;
  let peakPi = 0;
  let peakPiMonth = 0;
  for (const r of rows) {
    if (r.pi > peakPi) {
      peakPi = r.pi;
      peakPiMonth = r.month;
    }
  }
  const tailPi = peakPi > 0 ? peakPi * 0.35 : 0;
  return rows.map((r) => {
    const cfadsAdj = pkgCfadsForDscr(r, vatMode, vatRate);
    const cfadsFx = Number.isFinite(cfadsAdj) ? cfadsAdj * fxFac : cfadsAdj;
    let dscr: number | null =
      r.nUnits > 0 &&
      r.pi > 1e-9 &&
      Number.isFinite(cfadsFx)
        ? cfadsFx / r.pi
        : null;
    if (
      dscr != null &&
      dscr > hi &&
      peakPiMonth > 0 &&
      r.month > peakPiMonth &&
      tailPi > 0 &&
      r.pi < tailPi
    ) {
      dscr = null;
    }
    const inRampExempt = r.month <= exemptN;
    return {
      month: r.month,
      /** 达产锚点用调整后经营净（与 DSCR 分子同口径） */
      cfads: cfadsAdj,
      pi: r.pi,
      dscr,
      equity: r.equity,
      inRampExempt,
      formalTrigger: !inRampExempt,
    };
  });
}

function countTrailingBelow(
  series: PkgDscrPt[],
  threshold: number,
): { months: number; fromMo: number | null } {
  let n = 0;
  let fromMo: number | null = null;
  for (let i = series.length - 1; i >= 0; i--) {
    const p = series[i]!;
    if (!p.formalTrigger || p.dscr == null) break;
    if (p.dscr < threshold) {
      n += 1;
      fromMo = p.month;
    } else break;
  }
  return { months: n, fromMo };
}

function summarizePkgDscr(
  series: PkgDscrPt[],
  thresholds?: PkgDscrThresholdSet,
) {
  const formal = series.filter((p) => p.formalTrigger && p.dscr != null);
  const maxCfads = formal.length
    ? Math.max(...formal.map((p) => p.cfads))
    : 0;
  const steady =
    formal.find((p) => p.cfads >= maxCfads * 0.98 - 1e-6) ||
    formal[formal.length - 1] ||
    null;
  const minPt = formal.reduce<PkgDscrPt | null>((best, p) => {
    if (p.dscr == null) return best;
    if (!best || (best.dscr != null && p.dscr < best.dscr)) return p;
    return best;
  }, null);
  const t = thresholds ?? resolvePkgDscrThresholds(series, "plan_target");
  const belowObs = countTrailingBelow(series, t.observe);
  const belowMar = countTrailingBelow(series, t.margin);
  const belowLiq = countTrailingBelow(series, t.liquidate);
  const hit = (c: { months: number }) =>
    c.months >= PKG_DSCR_THRESHOLDS.consecutiveMonths;
  let alertZh = "正常";
  let alertTone: "success" | "info" | "warning" | "danger" = "success";
  if (hit(belowLiq)) {
    alertZh = `平仓联动 · 连续${belowLiq.months}月<${t.liquidate.toFixed(2)}×`;
    alertTone = "danger";
  } else if (hit(belowMar)) {
    alertZh = `补仓 · 连续${belowMar.months}月<${t.margin.toFixed(2)}×`;
    alertTone = "warning";
  } else if (hit(belowObs)) {
    const topZh = t.source === "plan_target" ? "经营目标" : "样例观察";
    alertZh = `${topZh} · 连续${belowObs.months}月<${t.observe.toFixed(2)}×`;
    alertTone = "info";
  } else if (
    series.some((p) => p.inRampExempt && p.dscr != null && p.dscr < 1)
  ) {
    alertZh = "爬坡窗内低于目标（计划内达产过程·豁免正式触发）";
    alertTone = "info";
  }
  return {
    steadyDscr: steady?.dscr ?? null,
    minDscr: minPt?.dscr ?? null,
    minMonth: minPt?.month ?? null,
    thresholds: t,
    alertZh,
    alertTone,
    belowObs,
    belowMar,
    belowLiq,
  };
}

/** 口径卡片（附录B 范式：场景/公式/分情况/缺省） */
function CaliberCard(props: {
  titleZh: string;
  sceneZh: string;
  formulaZh: string;
  casesZh: string;
  defaultsZh: string;
  compact?: boolean;
}) {
  return (
    <Stack gap={props.compact ? 3 : 4}>
      <Text size="small" weight="medium">
        {props.titleZh}
      </Text>
      <Text size="small" tone="secondary">
        【场景】{props.sceneZh}
      </Text>
      <Text size="small">【公式】{props.formulaZh}</Text>
      <Text size="small" tone="tertiary">
        【分情况】{props.casesZh}
      </Text>
      <Text size="small" tone="tertiary">
        【缺省/阈值】{props.defaultsZh}
      </Text>
    </Stack>
  );
}

function PackageDscrStrip(props: {
  rows: YohoPkgMonthRow[];
  /** 中性计划路径：经营目标三线锚点；缺省则用 rows */
  targetRows?: YohoPkgMonthRow[] | null;
  rampMode: YohoPkgRampMode;
  rampCurve?: Partial<YohoPkgRampCurve> | null;
  /** 与计划 FX buffer 同键；缺省读 planOverride / VTL */
  fxBufferPct?: number | null;
  /** 增值税一般税率；剔税折算用 */
  vatRate?: number | null;
  compact?: boolean;
}) {
  const [refModeRaw, setRefMode] = useCanvasState<PkgDscrRefLineMode>(
    "pkgDscrRefLineMode",
    "plan_target",
  );
  const [vatMode, setVatMode] = useCanvasState<PkgDscrVatMode>(
    "pkgDscrVatModeV1",
    "as_is",
  );
  const [fxMode, setFxMode] = useCanvasState<PkgDscrFxMode>(
    "pkgDscrFxModeV1",
    "with_fx",
  );
  const [planOverride] = useCanvasState<PlanOverride>("planOverrideV1", {});
  const [vtlFxBufferPct] = useCanvasState<number>("vtlFxBufferPct", 0.1);
  const refMode = normalizePkgDscrRefMode(refModeRaw);
  const vatRate = Math.max(
    0,
    Math.min(0.5, props.vatRate != null ? props.vatRate : 0.16),
  );
  const fxBufPlan =
    props.fxBufferPct != null && Number.isFinite(props.fxBufferPct)
      ? Math.max(0, Math.min(0.5, props.fxBufferPct))
      : planOverride.fxBufferPct != null
        ? Math.max(0, Math.min(0.5, planOverride.fxBufferPct))
        : Math.max(0, Math.min(0.5, vtlFxBufferPct));
  const fxBuf = pkgDscrEffectiveFxBuf(fxBufPlan, fxMode);
  const series = buildPkgDscrSeries(
    props.rows,
    props.rampMode,
    props.rampCurve,
    fxBuf,
    vatMode,
    vatRate,
  );
  const targetSeries =
    props.targetRows && props.targetRows.length > 0
      ? buildPkgDscrSeries(
          props.targetRows,
          props.rampMode,
          props.rampCurve,
          fxBuf,
          vatMode,
          vatRate,
        )
      : series;
  const thresholds = resolvePkgDscrThresholds(series, refMode, targetSeries);
  const sum = summarizePkgDscr(series, thresholds);
  const exemptN = pkgDscrExemptMonths(props.rampMode, props.rampCurve);
  const fmt = (x: number | null) =>
    x == null || !Number.isFinite(x) ? "—" : `${x.toFixed(2)}×`;
  const lockTrack = props.rampMode === "base24";
  const fxPctZh = `${Math.round(fxBufPlan * 1000) / 10}%`;
  const caliberSfx = pkgDscrCaliberSuffix(vatMode, fxMode);
  return (
    <Stack gap={props.compact ? 4 : 6}>
      <Row gap={6} align="center" wrap>
        <Text size="small" weight="medium">
          包层 DSCR
        </Text>
        <HelpQ
          id="pkg-dscr-caliber"
          label="包层 DSCR 口径"
          tip={[
            fxMode === "ex_fx"
              ? `经营目标=${fmt(thresholds.baseline)}（中性达产稳态）；本视图剔 FX；垫头=目标−1×，平仓=1×。计划层 FX 仍为 ${fxPctZh}。`
              : `经营目标=${fmt(thresholds.baseline)}（中性达产稳态）；DSCR=CFADS×(1−FX ${fxPctZh})/优先；垫头=目标−1×，目标线/补仓按垫头份额切分，平仓=1×。`,
            vatMode === "ex_vat"
              ? "剔 IVA：路径 CFADS 已含 IVA（计1次）；分子=CFADS+IVA 加回后计0次。里程仍为剔税+返佣后净额，不在此÷(1+税率)。"
              : "含 IVA：分子=CFADS（完整申报下 IVA 轧差付现已进路径，计1次）。里程=剔税+返佣后车队净。",
            fxMode === "ex_fx"
              ? "剔 FX：分子不乘 (1−buffer)；堆叠柱本身从不乘 FX。"
              : `含 FX：分子×(1−${fxPctZh})；堆叠柱仍为未乘 FX 的科目金额，仅 DSCR 线含缓冲。`,
            `爬坡豁免 M1–M${exemptN}；正式窗内连续≥${PKG_DSCR_THRESHOLDS.consecutiveMonths}月跌破目标/补仓/平仓才触发。`,
            "路径含爬坡与情景；爬坡窗内低于目标属计划达产过程，达产后偏离=计划—实际差距。",
          ].join("\n")}
        />
        <Pill size="sm" tone={lockTrack ? "info" : "warning"}>
          {lockTrack ? "达产爬坡·豁免窗" : "投后KPI·短豁免"}
        </Pill>
        <Pill
          size="sm"
          active={vatMode === "as_is"}
          onClick={() => setVatMode("as_is")}
          title="现行 CFADS：已含 IVA（申报轧差现金）"
        >
          含IVA
        </Pill>
        <Pill
          size="sm"
          active={vatMode === "ex_vat"}
          onClick={() => setVatMode("ex_vat")}
          title="加回路径已扣的 IVA，看未含 IVA 时的 DSCR"
        >
          剔IVA
        </Pill>
        <Pill
          size="sm"
          active={fxMode === "with_fx"}
          onClick={() => setFxMode("with_fx")}
          title={`含 FX buffer：分子×(1−${fxPctZh})`}
        >
          含FX
        </Pill>
        <Pill
          size="sm"
          active={fxMode === "ex_fx"}
          onClick={() => setFxMode("ex_fx")}
          title="剔 FX buffer：分子不乘 (1−buffer)"
        >
          剔FX
        </Pill>
        <Pill size="sm" active>
          经营目标
        </Pill>
      </Row>
      <Grid columns={GRID_STATS} gap={6}>
        <PlanStickyKpi
          label={`路径达产 DSCR${caliberSfx}`}
          value={fmt(sum.steadyDscr)}
          tone={
            sum.steadyDscr == null
              ? undefined
              : sum.steadyDscr >= thresholds.observe
                ? "success"
                : "warning"
          }
        />
        <PlanStickyKpi
          label={`正式窗最低${caliberSfx}`}
          value={
            sum.minDscr != null
              ? `${fmt(sum.minDscr)}@M${sum.minMonth}`
              : "—"
          }
        />
        <PlanStickyKpi
          label={
            refMode === "plan_target"
              ? "目标/补仓/平仓"
              : "样例观察/补仓/平仓"
          }
          value={`${thresholds.observe.toFixed(2)}/${thresholds.margin.toFixed(2)}/${thresholds.liquidate.toFixed(2)}×`}
        />
        <PlanStickyKpi
          label="爬坡豁免"
          value={`M1–M${exemptN}`}
          tone="info"
        />
      </Grid>
      {sum.alertZh && sum.alertZh !== "正常" ? (
        <Text size="small" tone="secondary">
          {sum.alertZh}
        </Text>
      ) : null}
      {sum.steadyDscr == null ? (
        <Text size="small" tone="tertiary">
          DSCR 无读数：优先本息为 0。请在左侧开启「优先投资」。
        </Text>
      ) : null}
    </Stack>
  );
}

/** SKU 首年保费是否已计入 softCosts（期初上车），经营月 1–12 勿重复扣 */
function skuFirstYearInsurancePrepaid(sku: AssetSku): boolean {
  return (sku.softCosts || []).some(
    (c) => c.id === "insurance_y1" && (c.amountMxn || 0) > 0,
  );
}

type AssumptionPackId =
  | "dae-es-zhuanche"
  | "dae-t1-zhuanche"
  | "station-mid"
  | "lto-ut-kuaiche";

type AssumptionCheckRow = {
  packId: AssumptionPackId;
  packZh: string;
  sourceId: string;
  sheetZh: string;
  appliesZh: string;
  metricZh: string;
  nature: ConstNatureId;
  natureZh: string;
  excelZh: string;
  canvasZh: string;
  status: "对齐" | "偏离" | "待案例表";
};

function approxEqNum(a: number, b: number, tol = 0.005): boolean {
  if (!Number.isFinite(a) || !Number.isFinite(b)) return false;
  const scale = Math.max(1, Math.abs(b));
  return Math.abs(a - b) <= Math.max(tol, scale * tol);
}

function fmtAuditNum(n: number, digits = 4): string {
  if (!Number.isFinite(n)) return "—";
  if (Math.abs(n) >= 100 || Number.isInteger(n)) return String(Math.round(n * 1000) / 1000);
  return String(Math.round(n * 10 ** digits) / 10 ** digits);
}

/**
 * 对照已附 Excel「1.1假设」与画布现值。
 * DAE/充电桩：强制对齐；LTO：无同级表时标「待案例表」。
 */
function buildAssumptionAudit(args: {
  daeCard: VehicleCard;
  t1Card?: VehicleCard;
  ltoCard?: VehicleCard;
  stationSku?: AssetSku;
  daeProfile: OpsProfile;
  ltoProfile?: OpsProfile;
  scenario: CashflowScenario;
}): AssumptionCheckRow[] {
  const sc = args.scenario;
  const scZh = SCENARIO_LABEL_ZH[sc];
  const daeCard = applyScenarioToVehicleCard(args.daeCard, sc);
  const knobs = DAE_SCENARIO_KNOBS[sc];
  const stOps = applyScenarioToStationOps(
    resolveStationOps(
      args.stationSku ||
        DEFAULT_ASSET_SKUS.find((s) => s.id === "station-medium") ||
        DEFAULT_ASSET_SKUS.find((s) => s.kind === "station")!,
    ),
    sc,
    args.stationSku ? stationOpsScaleOf(args.stationSku) : 1,
  );
  const stKnob = STATION_SCENARIO_KNOBS[sc];
  const daeSku =
    DEFAULT_ASSET_SKUS.find((s) => s.id === "aion-es") || DEFAULT_ASSET_SKUS[0]!;
  const daysMo = opsDaysPerMonth(daeCard.daysWeek || 6);
  const chargeMoCanvas =
    daeKmDay(daeCard) *
    ((daeSku.kwhPer100 || 15) / 100) *
    knobs.elecMxn *
    daysMo;
  const chargeMoExpect =
    daeKmDay({ ...daeCard, util: knobs.util, daysWeek: 6 }) *
    (15 / 100) *
    knobs.elecMxn *
    opsDaysPerMonth(6);

  const srcSheet =
    sc === "base"
      ? "1.1假设-DAE-专车"
      : `情景常量·${scZh}（中性=案例表）`;
  const stSheet =
    sc === "base"
      ? "1.1假设-充电桩"
      : `情景常量·${scZh}（中性=案例表）`;

  const daePairs: { metricZh: string; excel: number; canvas: number; unit: string }[] =
    [
      { metricZh: "利用率", excel: knobs.util, canvas: daeCard.util ?? 0, unit: "" },
      { metricZh: "IPH(车队净)", excel: knobs.iphMxn, canvas: daeCard.iphMxn || 0, unit: "MXN/h" },
      {
        metricZh: "IPH(抽佣前)",
        excel: iphGrossFromNetMxn(knobs.iphMxn, DAE_DEFAULT_PLATFORM_TAKE_PCT),
        canvas: iphGrossFromNetMxn(
          daeCard.iphMxn || 0,
          DAE_DEFAULT_PLATFORM_TAKE_PCT,
        ),
        unit: "MXN/h",
      },
      {
        metricZh: "平台抽佣",
        excel: DAE_DEFAULT_PLATFORM_TAKE_PCT,
        canvas: DAE_DEFAULT_PLATFORM_TAKE_PCT,
        unit: "",
      },
      { metricZh: "滴滴补贴", excel: knobs.subsidyPct, canvas: daeCard.subsidyPct ?? 0, unit: "" },
      { metricZh: "司机薪酬(单人)", excel: knobs.driverMxn, canvas: daeCard.driverMxn || 0, unit: "MXN/月" },
      {
        metricZh: "司机成本(两班×利用)",
        excel: knobs.driverMxn * 2 * knobs.util,
        canvas: daeDriverMonthMxn({ ...daeCard, mode: "DAE", shiftsPerDay: 2 }),
        unit: "MXN/月",
      },
      { metricZh: "保险", excel: knobs.insuranceYrMxn, canvas: daeCard.insuranceYrMxn || 0, unit: "MXN/年" },
      { metricZh: "保养", excel: knobs.maintMxn, canvas: daeCard.maintMxn || 0, unit: "MXN/月" },
      { metricZh: "软件", excel: knobs.softMxn, canvas: daeCard.softMxn || 0, unit: "MXN/月" },
      { metricZh: "易损合计", excel: knobs.wearYrMxn, canvas: daeCard.wearYrMxn || 0, unit: "MXN/年" },
      { metricZh: "车位租金", excel: knobs.parkingMxn, canvas: daeCard.parkingMxn ?? 0, unit: "MXN/月" },
      { metricZh: "电价", excel: knobs.elecMxn, canvas: knobs.elecMxn, unit: "MXN/kWh" },
      { metricZh: "充电费(推算月)", excel: chargeMoExpect, canvas: chargeMoCanvas, unit: "MXN/月" },
      { metricZh: "残值率", excel: knobs.residualRate, canvas: daeCard.residualRate ?? 0, unit: "" },
    ];

  const rows: AssumptionCheckRow[] = daePairs.map((p) => {
    const nature = natureOfMetric(p.metricZh);
    return {
      packId: "dae-es-zhuanche",
      packZh: `DAE·专车·ES·${scZh}`,
      sourceId: "fenbang-dae-xlsx",
      sheetZh: srcSheet,
      appliesZh: `墨西哥 · 网约车·专车 · DAE · ES · ${scZh}`,
      metricZh: p.metricZh,
      nature,
      natureZh: CONST_NATURE_META[nature].labelZh,
      excelZh: `${fmtAuditNum(p.excel)}${p.unit ? ` ${p.unit}` : ""}`,
      canvasZh: `${fmtAuditNum(p.canvas)}${p.unit ? ` ${p.unit}` : ""}`,
      status: approxEqNum(p.canvas, p.excel, p.metricZh.includes("充电") ? 0.03 : 0.005)
        ? "对齐"
        : "偏离",
    };
  });

  /** 极狐 T1：经营假设与 ES 同表口径；购入价/电耗以《极狐1》1.1 为准 */
  const t1Sku = DEFAULT_ASSET_SKUS.find((s) => s.id === "arcfox-t1");
  const t1CardRaw =
    args.t1Card ||
    DEFAULT_VEHICLE_CARDS.find((c) => c.id === "arcfox-t1-dae");
  if (t1Sku && t1CardRaw) {
    const t1Card = applyScenarioToVehicleCard(t1CardRaw, sc);
    const t1DaysMo = opsDaysPerMonth(t1Card.daysWeek || 6);
    const t1ChargeCanvas =
      daeKmDay(t1Card) *
      ((t1Sku.kwhPer100 || 15) / 100) *
      knobs.elecMxn *
      t1DaysMo;
    const t1Pairs: {
      metricZh: string;
      excel: number;
      canvas: number;
      unit: string;
    }[] = [
      {
        metricZh: "集采价(含税)",
        excel: ARCFOX_T1_DAE_EXCEL_ANCHOR.unitPurchaseMxn,
        canvas: t1Sku.purchasePriceMxn,
        unit: "MXN",
      },
      {
        metricZh: "指导价",
        excel: ARCFOX_T1_DAE_EXCEL_ANCHOR.guidePriceMxn,
        canvas: t1Sku.guidePriceMxn || 0,
        unit: "MXN",
      },
      {
        metricZh: "电耗",
        excel: 15,
        canvas: t1Sku.kwhPer100 || t1Card.kwhPer100 || 0,
        unit: "kWh/100km",
      },
      { metricZh: "利用率", excel: knobs.util, canvas: t1Card.util ?? 0, unit: "" },
      {
        metricZh: "IPH(车队净)",
        excel: knobs.iphMxn,
        canvas: t1Card.iphMxn || 0,
        unit: "MXN/h",
      },
      {
        metricZh: "司机成本(两班×利用)",
        excel: knobs.driverMxn * 2 * knobs.util,
        canvas: daeDriverMonthMxn({ ...t1Card, mode: "DAE", shiftsPerDay: 2 }),
        unit: "MXN/月",
      },
      {
        metricZh: "保险",
        excel: knobs.insuranceYrMxn,
        canvas: t1Card.insuranceYrMxn || 0,
        unit: "MXN/年",
      },
      {
        metricZh: "易损合计",
        excel: knobs.wearYrMxn,
        canvas: t1Card.wearYrMxn || 0,
        unit: "MXN/年",
      },
      {
        metricZh: "充电费(推算月)",
        excel: chargeMoExpect,
        canvas: t1ChargeCanvas,
        unit: "MXN/月",
      },
      {
        metricZh: "残值率",
        excel: knobs.residualRate,
        canvas: t1Card.residualRate ?? 0,
        unit: "",
      },
      {
        metricZh: "组合IRR锚点",
        excel: ARCFOX_T1_DAE_EXCEL_ANCHOR.excelReportedIrr,
        canvas: ARCFOX_T1_DAE_EXCEL_ANCHOR.excelReportedIrr,
        unit: "",
      },
    ];
    for (const p of t1Pairs) {
      const nature = natureOfMetric(p.metricZh);
      rows.push({
        packId: "dae-t1-zhuanche",
        packZh: `DAE·专车·T1·${scZh}`,
        sourceId: "fenbang-dae-arcfox-xlsx",
        sheetZh:
          sc === "base"
            ? "1.1假设-DAE-专车·极狐"
            : `情景常量·${scZh}（中性=极狐案例表）`,
        appliesZh: `墨西哥 · 网约车·专车 · DAE · 极狐T1 · ${scZh}`,
        metricZh: p.metricZh,
        nature,
        natureZh: CONST_NATURE_META[nature].labelZh,
        excelZh: `${fmtAuditNum(p.excel)}${p.unit ? ` ${p.unit}` : ""}`,
        canvasZh: `${fmtAuditNum(p.canvas)}${p.unit ? ` ${p.unit}` : ""}`,
        status: approxEqNum(
          p.canvas,
          p.excel,
          p.metricZh.includes("充电") || p.metricZh.includes("IRR") ? 0.03 : 0.005,
        )
          ? "对齐"
          : "偏离",
      });
    }
  }

  const stPairs: { metricZh: string; excel: number; canvas: number; unit: string }[] =
    [
      { metricZh: "外部利用率", excel: stKnob.externalUtil, canvas: stOps.externalUtil, unit: "" },
      { metricZh: "内部利用率", excel: stKnob.internalUtil, canvas: stOps.internalUtil, unit: "" },
      { metricZh: "外部电价", excel: stKnob.externalPriceMxn, canvas: stOps.externalPriceMxn, unit: "MXN/kWh" },
      { metricZh: "内部电价", excel: stKnob.internalPriceMxn, canvas: stOps.internalPriceMxn, unit: "MXN/kWh" },
      { metricZh: "电成本", excel: stKnob.elecCostMxn, canvas: stOps.elecCostMxn, unit: "MXN/kWh" },
      {
        metricZh: "对外平台抽佣",
        excel: stKnob.xiaojufenPct,
        canvas: stOps.xiaojufenPct,
        unit: "",
      },
      {
        metricZh: "对内平台抽佣",
        excel: stKnob.xiaojufenInternalPct,
        canvas: stOps.xiaojufenInternalPct || 0,
        unit: "",
      },
      { metricZh: "场站租赁", excel: stKnob.rentMonthMxn, canvas: stOps.rentMonthMxn, unit: "MXN/月" },
      { metricZh: "运维包", excel: stKnob.opexMonthMxn, canvas: stOps.opexMonthMxn, unit: "MXN/月" },
    ];

  for (const p of stPairs) {
    const nature = natureOfMetric(p.metricZh);
    rows.push({
      packId: "station-mid",
      packZh: `充电桩·中型·${scZh}`,
      sourceId: "fenbang-station-xlsx",
      sheetZh: stSheet,
      appliesZh: `墨西哥 · 场站 · 中型 · ${scZh}`,
      metricZh: p.metricZh,
      nature,
      natureZh: CONST_NATURE_META[nature].labelZh,
      excelZh: `${fmtAuditNum(p.excel)}${p.unit ? ` ${p.unit}` : ""}`,
      canvasZh: `${fmtAuditNum(p.canvas)}${p.unit ? ` ${p.unit}` : ""}`,
      status: approxEqNum(p.canvas, p.excel, 0.01) ? "对齐" : "偏离",
    });
  }

  const ltoRaw = args.ltoCard;
  if (ltoRaw) {
    const lto = applyScenarioToVehicleCard(ltoRaw, sc);
    const lk = LTO_SCENARIO_KNOBS[sc];
    const pending = [
      { metricZh: "出租率", excel: lk.occupancy, canvas: lto.occupancy ?? 0, unit: "" },
      { metricZh: "月租金", excel: lk.rentMonthMxn, canvas: lto.rentMonthMxn ?? 0, unit: "MXN" },
      { metricZh: "押金", excel: lk.depositMxn, canvas: lto.depositMxn ?? 0, unit: "MXN" },
      { metricZh: "坏账率", excel: lk.badDebt, canvas: lto.badDebt ?? 0, unit: "" },
    ];
    for (const p of pending) {
      const nature = natureOfMetric(p.metricZh);
      rows.push({
        packId: "lto-ut-kuaiche",
        packZh: `LTO·快车·UT·${scZh}`,
        sourceId: "fenbang-lto-xlsx",
        sheetZh: `情景常量·${scZh}（待附 Excel）`,
        appliesZh: `墨西哥 · 网约车·快车 · LTO · UT · ${scZh}`,
        metricZh: p.metricZh,
        nature,
        natureZh: CONST_NATURE_META[nature].labelZh,
        excelZh: `${fmtAuditNum(p.excel)}${p.unit ? ` ${p.unit}` : ""}`,
        canvasZh: `${fmtAuditNum(p.canvas)}${p.unit ? ` ${p.unit}` : ""}`,
        status: "待案例表",
      });
    }
  }

  return rows;
}

/** 案例表日均营运天：周 6 天 × 52/12 */
function opsDaysPerMonth(daysWeek = 6): number {
  return Math.max(1, (daysWeek || 6) * (52 / 12));
}

/** 《DAE-200》案例表日工时；司机单人月薪 26000 对应该基准 */
const DAE_BASE_HOURS_DAY = 9.5;

/**
 * DAE 有效司机月薪：案例表单司机 26000（9.5h/班）× 班次 × 利用率 × (日工时/9.5)。
 * 两班×75%×9.5h → 39000；日工时加到 11h → ×11/9.5。
 */
function daeDriverMonthMxn(card: VehicleCard): number {
  if (card.mode !== "DAE" || !(card.driverMxn > 0)) return 0;
  const shifts = Math.max(1, card.shiftsPerDay || 1);
  const util = Math.max(0, Math.min(1, card.util ?? 0.75));
  const hours = Math.max(0.5, card.hoursDay || DAE_BASE_HOURS_DAY);
  const hoursMul = hours / DAE_BASE_HOURS_DAY;
  return card.driverMxn * shifts * util * hoursMul;
}

/**
 * DAE 日均里程：案例表标称 350km/天/台，充电按 ×利用率（不加班次；两班仍一台车）。
 */
function daeKmDay(card: VehicleCard): number {
  const daysMo = opsDaysPerMonth(card.daysWeek || 6);
  const util = Math.max(0, Math.min(1, card.util ?? 0.75));
  return (350 * (card.daysWeek || 6) * (52 / 12) * util) / daysMo;
}

type WaterfallSlice = {
  id: string;
  nameZh: string;
  layer: CfLayer | "passenger" | "residual";
  amountMxn: number;
  remainingAfterMxn: number;
  noteZh: string;
};

type DayTaxSummary = {
  vatRate: number;
  opsRevIncludesVat: boolean;
  ivaOutputDay: number;
  /** 进项示意：充电等应税成本内拆（成本按含税计） */
  ivaInputDay: number;
  ivaNetDay: number;
  incomeTaxDay: number;
};

type AssetDayCashflow = {
  country: string;
  vertical: string;
  mode: OpMode;
  passengerPayMxn: number;
  slices: WaterfallSlice[];
  spvInflowMxn: number;
  spvResidualMxn: number;
  chargeDayMxn: number;
  noteZh: string;
  /** 日/月/年税层摘要（与瀑布 slice 同源） */
  tax?: DayTaxSummary;
};

type AssetMonthBar = {
  label: string;
  /** 负向：购置落地 / 养护 / 充电 / 随机维保 */
  capexMxn: number;
  maintMxn: number;
  chargeMxn: number;
  randomMaintMxn: number;
  /** 正向：进入运营 SPV 的经营流入（抽佣后、顺位分配前）；不含融资保证金退还 */
  opsInMxn: number;
  /** 瀑布顺位+当日充电后的经营权益层剩余（可为 0）；不含融资保证金退还 */
  equityInMxn: number;
  /**
   * 融资锁定保证金退还（优先/夹层本息结清月）。
   * 与经营权益分列：保证金不一定由经营主体缴纳，勿并入 equityIn。
   */
  depositReturnMxn?: number;
  /** 当月应计优先+夹层本息（与日切分债服同时钟；用于由净额反推 CFADS） */
  debtServiceMxn?: number;
  /**
   * 扣本息前经营净（对齐包层 CFADS）：经营流入−opex/税 − 不含债服。
   * 投放回收右柱 / VTL 持续经营剩余 NPV 用此口径；勿用杠杆后 net（高杠杆时常≈0）。
   */
  cfadsMxn?: number;
  outflowMxn: number;
  /** 经营流入 − 本图支出项 + 保证金退还（现金口径；IRR 仍含退还） */
  netMxn: number;
};

/** 含税额中的税 = gross×r/(1+r)；未税基数则 gross×r */
function vatOnAmountMxn(
  grossMxn: number,
  vat: number,
  includesVat: boolean,
): number {
  const r = Math.max(0, vat);
  const g = Math.max(0, grossMxn);
  if (r <= 0 || g <= 0) return 0;
  return includesVat ? g * (r / (1 + r)) : g * r;
}

function cfOpsRevIncludesVat(cfg: AssetCashflowConfig): boolean {
  return cfg.opsRevIncludesVat !== false;
}

function cfOpsVatEnabled(cfg: AssetCashflowConfig): boolean {
  return cfg.opsVatEnabled === true;
}

function cfVatNetInCashflow(cfg: AssetCashflowConfig): boolean {
  return cfg.vatNetInCashflow === true;
}

/**
 * 实体级 IVA 月度轧差（完整申报示意）：
 * 先用贷方余额（购车进项等）冲销当月「销项−经营进项」；
 * 冲不完则付现；当月进项>销项则继续滚贷方（可跨年）。
 * 默认假设：本路径/本资产包 = 单一纳税实体，无其他业务。
 */
function settleEntityIvaMonth(args: {
  outputMxn: number;
  opsInputMxn: number;
  creditMxn: number;
}): { cashOutMxn: number; creditAfterMxn: number; netBeforeCreditMxn: number } {
  const output = Math.max(0, args.outputMxn);
  const input = Math.max(0, args.opsInputMxn);
  const net = output - input;
  let credit = Math.max(0, args.creditMxn);
  if (net <= 0) {
    return {
      cashOutMxn: 0,
      creditAfterMxn: credit + -net,
      netBeforeCreditMxn: net,
    };
  }
  const used = Math.min(credit, net);
  credit -= used;
  return {
    cashOutMxn: net - used,
    creditAfterMxn: credit,
    netBeforeCreditMxn: net,
  };
}

/** 购车（单位）可抵扣进项 IVA：税基剔押金；含税列载则反拆 */
function unitPurchaseIvaCreditMxn(
  sku: AssetSku,
  vat: number,
  configId?: string,
): number {
  return Math.max(0, modelUnitIvaMxn(sku, 1, vat, configId));
}

function cfIncomeTaxEnabled(cfg: AssetCashflowConfig): boolean {
  return !!cfg.incomeTaxEnabled;
}

function cfIncomeTaxRate(cfg: AssetCashflowConfig): number {
  const r = cfg.incomeTaxRate;
  return r != null && Number.isFinite(r) ? Math.max(0, Math.min(0.6, r)) : 0.3;
}

/** 税口径短标签（路径指标 / 瀑布旁） */
function cfTaxBasisLabelZh(cfg: AssetCashflowConfig): string {
  const inc = cfOpsRevIncludesVat(cfg);
  const vatNet = cfVatNetInCashflow(cfg);
  const vatOn = cfOpsVatEnabled(cfg);
  if (inc && vatNet) return "经营含税·IVA完整申报(购置进项滚存+月度轧差)";
  if (inc && !vatOn) return "经营含税·与表内现金同列（销项不扣池）";
  if (inc && vatOn) return "经营含税·日瀑布示意拆销项（不扣池）";
  if (!inc && vatOn) return "经营未税·瀑布扣销项IVA";
  return "经营未税录入";
}

