/** 按情景重算单位路径 KPI（融资/税开关沿用当前 cfg 模板） */
function buildUnitScenarioExportPack(args: {
  scenario: CashflowScenario;
  cardBase: VehicleCard;
  daeShift: "single" | "double";
  mode: OpMode;
  country: string;
  vertical: string;
  sku: AssetSku;
  cfgTemplate: AssetCashflowConfig;
  invAssume: Partial<{
    util: number;
    iphMxn: number;
    hoursDay: number;
    daysWeek: number;
    subsidyPct: number;
    driverMxn: number;
    occupancy: number;
    rentMonthMxn: number;
    badDebt: number;
    rampYears: number;
    rampStartLoad: number;
  }>;
  unitLandedMxn: number;
  vat: number;
  internalPriceMxn: number;
  goLiveStages: GoLiveStage[];
  fx: number;
  usdIdr: number;
  configId?: string;
  discountAnn: number;
  holdYears: number;
  includeResidual: boolean;
  residualMxn: number;
  mgmtCapability?: number;
}): UnitExportScenarioPack {
  const sc = args.scenario;
  const shifted = applyDaeShiftToCard(
    args.cardBase,
    args.mode === "DAE" ? args.daeShift : "single",
  );
  const a = args.invAssume || {};
  const card: VehicleCard = {
    ...applyScenarioToVehicleCard(shifted, sc),
    ...(a.util != null ? { util: a.util } : {}),
    ...(a.iphMxn != null ? { iphMxn: a.iphMxn } : {}),
    ...(a.hoursDay != null ? { hoursDay: a.hoursDay } : {}),
    ...(a.daysWeek != null ? { daysWeek: a.daysWeek } : {}),
    ...(a.subsidyPct != null ? { subsidyPct: a.subsidyPct } : {}),
    ...(a.driverMxn != null ? { driverMxn: a.driverMxn } : {}),
    ...(a.occupancy != null ? { occupancy: a.occupancy } : {}),
    ...(a.rentMonthMxn != null ? { rentMonthMxn: a.rentMonthMxn } : {}),
    ...(a.badDebt != null ? { badDebt: a.badDebt } : {}),
    ...(a.rampYears != null ? { rampYears: a.rampYears } : {}),
    ...(a.rampStartLoad != null ? { rampStartLoad: a.rampStartLoad } : {}),
  };
  const elec =
    args.mode === "DAE"
      ? DAE_SCENARIO_KNOBS[sc].elecMxn
      : args.internalPriceMxn;
  let cfg: AssetCashflowConfig = {
    ...args.cfgTemplate,
    horizonMonths: Math.max(
      12,
      args.cfgTemplate.horizonMonths || args.holdYears * 12,
    ),
  };
  if (args.mode === "DAE" && cfg.chargeSource !== "manual") {
    const kwhDay =
      (daeKmDay(card) / 100) * (args.sku.kwhPer100 || card.kwhPer100 || 15);
    const dayFromCard = Math.round(kwhDay * elec * 100) / 100;
    const dw = card.daysWeek || 6;
    const cyc: ChargePayCycle =
      cfg.chargeCycle === "week" ||
      cfg.chargeCycle === "month" ||
      cfg.chargeCycle === "year"
        ? cfg.chargeCycle
        : "day";
    cfg = {
      ...cfg,
      chargeCycle: cyc,
      chargeSource: "from_card",
      chargeDayMxn: dayFromCard,
      chargeAmountMxn: chargeAmountFromDay(dayFromCard, cyc, dw),
    };
  }
  cfg = syncCfTiersToCard(cfg, card, args.sku);
  const day = buildAssetDayCashflow({
    country: args.country,
    vertical: args.vertical,
    mode: args.mode,
    card,
    sku: args.sku,
    cfg,
    internalPriceMxn: elec,
    unitLandedMxn: args.unitLandedMxn,
    opsMonth: 1,
    vat: args.vat,
  });
  const bars = buildAssetMonthBars({
    sku: args.sku,
    card,
    cfg,
    day,
    qty: 1,
    discountRate: volumeDiscountRate(args.sku, 1),
    goLiveStages: args.goLiveStages,
    vat: args.vat,
    configId: args.configId,
    internalPriceMxn: elec,
    usdMxn: args.fx,
    usdIdr: args.usdIdr,
    unitLandedBook: args.unitLandedMxn,
    mgmtCapability: args.mgmtCapability ?? 0.7,
  });
  const withResidualOnLast = (nets: number[], resMxn: number) => {
    if (!(resMxn > 0) || nets.length === 0) return nets.slice();
    const out = nets.slice();
    out[out.length - 1] = (out[out.length - 1] || 0) + resMxn;
    return out;
  };
  const rawNets = bars.map((b) => b.netMxn || 0);
  const pathNets = args.includeResidual
    ? withResidualOnLast(rawNets, args.residualMxn)
    : rawNets;
  const pathIrrAnn = annualizeMonthIrr(irr(pathNets));
  const pathNpvMxn = npvAnnualOnMonths(pathNets, args.discountAnn);
  const pathStaticPb = staticPaybackPeriod(pathNets);
  const pathDynamicPb = dynamicPaybackPeriod(pathNets, args.discountAnn);
  const cumPathNet = rawNets.reduce((s, n) => s + n, 0);
  const initInv = bars
    .filter((b) => !b.label.startsWith("经营"))
    .reduce((s, b) => s + (b.outflowMxn || 0), 0);
  const initUse = initInv > 0 ? initInv : args.unitLandedMxn;
  const totalReturnMxn = args.includeResidual
    ? cumPathNet + args.residualMxn
    : cumPathNet;
  const returnMultiple =
    initUse > 0 ? (initUse + totalReturnMxn) / initUse : null;
  const firstOps = bars.find((b) => b.label.startsWith("经营"));
  const daysMo = opsDaysPerMonth(card.daysWeek || 6);
  const financeMo =
    ((day.slices || [])
      .filter((s) => s.id === "investor_pi" || s.id === "investor_mezz")
      .reduce((s, x) => s + (x.amountMxn || 0), 0) || 0) * daysMo;
  const pnl = steadyPnlFromFirstOpsBar({
    firstOpsBar: firstOps,
    financeMo,
  });
  const freeMo =
    firstOps != null ? pnl.freeMo : day.spvResidualMxn * daysMo;
  const monthNetSample = assignUnitCfYearIds(barsToUnitCfPath(bars))
    .filter((p) => p.kind === "ops")
    .slice(0, 12)
    .map((p) => ({
      label: p.shortZh || `M${p.opsMonth}`,
      net: p.net,
    }));
  const chargeDay =
    cfg.chargeDayMxn != null && Number.isFinite(cfg.chargeDayMxn)
      ? cfg.chargeDayMxn
      : undefined;
  return {
    scenario: sc,
    labelZh: SCENARIO_LABEL_ZH[sc],
    metrics: {
      pathIrrAnn,
      pathNpvMxn,
      pathPbMo: pathStaticPb.months,
      pathDynamicPb: { months: pathDynamicPb.months },
      cumPathNet,
      initInv: initUse,
      totalReturnMxn,
      returnMultiple,
    },
    residualMxn: args.residualMxn,
    freeMo,
    companyMo: pnl.companyMo,
    assumeHighlight: buildUnitExportOpsAssumeRows({
      mode: args.mode,
      card,
      elecMxn: elec,
      chargeDayMxn: chargeDay,
    }),
    monthNetSample,
  };
}

/** 经营假设全量列示（按模式；供当前情景块与三情景各自细节） */
function buildUnitExportOpsAssumeRows(args: {
  mode: OpMode;
  card: VehicleCard;
  elecMxn: number;
  chargeDayMxn?: number;
}): UnitExportKv[] {
  const { mode, card } = args;
  const moneyPlain = (n: number) => {
    const v = Math.round((n || 0) * 100) / 100;
    return Number.isInteger(v) ? String(v) : v.toFixed(2);
  };
  if (mode === "DAE") {
    return [
      { labelZh: "利用率", valueZh: pct(card.util ?? 0) },
      { labelZh: "IPH", valueZh: moneyPlain(card.iphMxn || 0) },
      { labelZh: "班次", valueZh: String(card.shiftsPerDay || 1) },
      { labelZh: "营运日/周", valueZh: String(card.daysWeek || 6) },
      { labelZh: "日工时", valueZh: String(card.hoursDay || 10) },
      { labelZh: "坏账", valueZh: pct(card.badDebt ?? 0, 1) },
      { labelZh: "补贴", valueZh: pct(card.subsidyPct ?? 0) },
      { labelZh: "残值率（卡片）", valueZh: pct(card.residualRate ?? 0) },
      { labelZh: "司机月薪（人）", valueZh: moneyPlain(card.driverMxn || 0) },
      {
        labelZh: "保险（年）",
        valueZh: moneyPlain(card.insuranceYrMxn || 0),
      },
      { labelZh: "保养（月）", valueZh: moneyPlain(card.maintMxn || 0) },
      { labelZh: "软件/GPS（月）", valueZh: moneyPlain(card.softMxn || 0) },
      { labelZh: "易损件（年）", valueZh: moneyPlain(card.wearYrMxn || 0) },
      { labelZh: "车位（月）", valueZh: moneyPlain(card.parkingMxn || 0) },
      { labelZh: "电价（情景）", valueZh: moneyPlain(args.elecMxn || 0) },
      ...(args.chargeDayMxn != null
        ? [
            {
              labelZh: "充电日额（推算）",
              valueZh: moneyPlain(args.chargeDayMxn),
            },
          ]
        : []),
    ];
  }
  return [
    { labelZh: "出租率", valueZh: pct(card.occupancy ?? 0) },
    { labelZh: "月租", valueZh: moneyPlain(card.rentMonthMxn || 0) },
    { labelZh: "押金", valueZh: moneyPlain(card.depositMxn || 0) },
    { labelZh: "坏账", valueZh: pct(card.badDebt ?? 0, 1) },
    { labelZh: "营运日/周", valueZh: String(card.daysWeek || 6) },
    { labelZh: "残值率（卡片）", valueZh: pct(card.residualRate ?? 0) },
  ];
}

/** 三情景经营假设对照：行=假设项，列=各情景 */
function cfExportScenarioAssumeCompareTable(
  packs: UnitExportScenarioPack[],
  esc: (s: string) => string,
): string {
  if (packs.length < 2) return "";
  const labels: string[] = [];
  const seen = new Set<string>();
  for (const pk of packs) {
    for (const r of pk.assumeHighlight || []) {
      if (!seen.has(r.labelZh)) {
        seen.add(r.labelZh);
        labels.push(r.labelZh);
      }
    }
  }
  if (!labels.length) return "";
  const head = ["假设项", ...packs.map((p) => p.labelZh)];
  const rows = labels.map((lab) => [
    lab,
    ...packs.map((pk) => {
      const hit = (pk.assumeHighlight || []).find((r) => r.labelZh === lab);
      return hit?.valueZh ?? "—";
    }),
  ]);
  return cfExportHtmlTable("三情景 · 经营假设对照（全项）", head, rows, esc);
}

function exportUnitTrialReport(
  ctx: UnitExportContext,
  format: CfExportFormat,
): string {
  const safeName = (ctx.assetNameZh || "asset").replace(/[\\/:*?"<>|]/g, "_");
  const scopeTag = ctx.scope === "unit" ? "单位" : "单元";
  const scTag =
    ctx.scenarioPacks && ctx.scenarioPacks.length > 1
      ? "-三情景"
      : `-${SCENARIO_LABEL_ZH[ctx.scenario] || ctx.scenario}`;
  const base = `${scopeTag}现金流-${safeName}${scTag}-${orderExportStamp()}`;
  const multi = !!(ctx.scenarioPacks && ctx.scenarioPacks.length > 1);
  if (format === "excel") {
    orderExportDownloadText(
      `${base}.xls`,
      "application/vnd.ms-excel",
      buildUnitExportExcelHtml(ctx),
    );
    return multi
      ? "已下载 Excel（.xls）·含保守/中性/激进对照"
      : "已下载 Excel（.xls），请用 Excel / WPS 打开";
  }
  if (format === "word") {
    orderExportDownloadText(
      `${base}.doc`,
      "application/msword",
      buildUnitExportDocHtml(ctx),
    );
    return multi
      ? "已下载 Word（.doc）·以图为主（表在附录）·含三情景"
      : "已下载 Word（.doc）·以图为主（表在附录）";
  }
  openOrderExportPdfPrint(buildUnitExportPdfLiteHtml(ctx), ctx.titleZh);
  return "已下载 PDF 摘要 HTML（轻量）·请用浏览器打开后打印 → 另存为 PDF；完整内容请用 Word/Excel";
}


