type OpsFunnelStep = {
  id: string;
  nameZh: string;
  days: number;
  passRate: number;
  /** 进入本节点台数 */
  enterQty: number;
  /** 离开本节点台数 */
  exitQty: number;
  dropQty: number;
  cumDays: number;
  noteZh: string;
};

/** 台数展示：整数，禁止浮点尾巴 */
function fmtFleetQty(n: number): string {
  if (!Number.isFinite(n)) return "—";
  return String(Math.round(n));
}

/** 字段底表说明：UI 不展示 Open API / 厂商接口路径 */
function fleetSchemaNoteUi(note: string): string {
  return note
    .replace(/滴滴侧/g, "平台侧")
    .replace(/滴滴/g, "平台")
    .replace(
      /\b(addCar|bindCar|bindDriver|unbindCar|unbindDriver|deleteDriver|addDocument|withholdRecord|driverOrderList|VEHICLE_STATUS_UPDATE|DRIVER_STATUS_UPDATE|strategy_type=\d+|customized_car_id|plate_no|plate_number|car_audit_status|car_reg_time)\b/gi,
      "",
    )
    .replace(/[a-z]+\/[a-zA-Z_/]+/g, "")
    .replace(/\s*[·；,，]\s*(?=[·；,，]|$)/g, "")
    .replace(/\s{2,}/g, " ")
    .replace(/^[·；\s]+|[·；\s]+$/g, "")
    .trim();
}

/** 资产投产漏斗：付款购置 → 各阶段 → 投产可经营 */
function buildOpsFunnel(args: {
  startQty: number;
  stages: GoLiveStage[];
  customsPass: number;
  pdiPass: number;
  matchPass: number;
}): OpsFunnelStep[] {
  const n0 = Math.max(0, Math.round(args.startQty));
  const passOf = (id: GoLiveStageId): number => {
    if (id === "ocean") return 1;
    if (id === "customs")
      return Math.max(0.5, Math.min(1, args.customsPass ?? 0.98));
    if (id === "pdi") return Math.max(0.5, Math.min(1, args.pdiPass ?? 0.97));
    return Math.max(0.4, Math.min(1, args.matchPass ?? 0.92));
  };
  const steps: OpsFunnelStep[] = [
    {
      id: "pay",
      nameZh: "付款购置",
      days: 0,
      passRate: 1,
      enterQty: n0,
      exitQty: n0,
      dropQty: 0,
      cumDays: 0,
      noteZh: "资金落地；资产尚未产生收入",
    },
  ];
  let qty = n0;
  let cum = 0;
  for (const s of args.stages) {
    const enter = qty;
    const pass = passOf(s.id);
    const exit = Math.round(enter * pass);
    const drop = Math.max(0, enter - exit);
    cum += s.days;
    steps.push({
      id: s.id,
      nameZh: s.nameZh,
      days: s.days,
      passRate: pass,
      enterQty: enter,
      exitQty: exit,
      dropQty: drop,
      cumDays: cum,
      noteZh: s.whyZh,
    });
    qty = exit;
  }
  steps.push({
    id: "live",
    nameZh: "投产出收入",
    days: 0,
    passRate: 1,
    enterQty: qty,
    exitQty: qty,
    dropQty: 0,
    cumDays: cum,
    noteZh: "开始计入经营流入；其后才是组合爬坡到达产",
  });
  return steps;
}

/** 达产负荷：资产卡固有爬坡 × 管理能力缩短 */
function rampLoadAtAge(
  age: number,
  rampYears: number,
  startLoad: number,
  mgmt: number,
) {
  if (age < 1) return 0;
  const m = Math.max(0, Math.min(1, mgmt));
  const effRamp = Math.max(1, rampYears * (1.35 - 0.5 * m));
  const start = Math.max(0.05, Math.min(1, startLoad));
  if (age >= effRamp) return 1;
  if (effRamp <= 1) return 1;
  return Math.min(1, start + ((1 - start) * (age - 1)) / (effRamp - 1));
}

/**
 * 单位月路径达产负荷（与年模型同公式，年→月）。
 * rampYears=0 → 零爬坡（运营第 1 月即满产）；
 * 默认 DAE rampYears=2 + mgmt0.7 → 有效约 24 运营月爬满（不是 2 个月）。
 */
function rampLoadAtOpsMonth(
  opsMonth: number,
  rampYears: number,
  startLoad: number,
  mgmt: number,
): number {
  if (opsMonth < 1) return 0;
  const ry = Number.isFinite(rampYears) ? rampYears : 2;
  if (ry <= 1e-9) return 1;
  const m = Math.max(0, Math.min(1, mgmt));
  const effRampY = Math.max(1 / 12, ry * (1.35 - 0.5 * m));
  const rampMo = Math.max(1, Math.round(effRampY * 12));
  /** 允许 0：起点空载；勿夹成 0.05 导致「填 0 仍有量」 */
  const start = Math.max(0, Math.min(1, startLoad));
  if (opsMonth >= rampMo) return 1;
  if (rampMo <= 1) return 1;
  return Math.min(
    1,
    start + ((1 - start) * (opsMonth - 1)) / (rampMo - 1),
  );
}

/** 单位月路径：按经营月把出租率/利用率乘上爬坡负荷（与计划切分同式） */
function vehicleCardAtOpsMonth(
  card: VehicleCard,
  mode: OpMode,
  opsMonth: number,
  mgmt: number,
): VehicleCard {
  const rampY = card.rampYears ?? 2;
  const rampStart = card.rampStartLoad ?? 0.55;
  const load = rampLoadAtOpsMonth(opsMonth, rampY, rampStart, mgmt);
  if (mode === "LTO" || mode === "RTO") {
    return {
      ...card,
      occupancy: (card.occupancy ?? 0.85) * load,
      driverMxn:
        card.driverMxn != null ? card.driverMxn * load : card.driverMxn,
    };
  }
  return {
    ...card,
    util: (card.util ?? 0.75) * load,
    driverMxn:
      card.driverMxn != null ? card.driverMxn * load : card.driverMxn,
  };
}

function effectiveRampMonths(
  rampYears: number,
  mgmt: number,
): number {
  const ry = Number.isFinite(rampYears) ? Math.max(0, rampYears) : 2;
  if (ry <= 1e-9) return 0;
  const m = Math.max(0, Math.min(1, mgmt));
  return Math.max(1, Math.round(ry * (1.35 - 0.5 * m) * 12));
}

/** 场站路径爬坡（无管理能力缩短；月数=年×12） */
function stationRampLoadAtOpsMonth(
  opsMonth: number,
  rampYears: number,
  startLoad: number,
): number {
  if (opsMonth < 1) return 0;
  const ry = Number.isFinite(rampYears) ? rampYears : 0.5;
  if (ry <= 1e-9) return 1;
  const rampMo = Math.max(1, Math.round(Math.max(0, ry) * 12) || 1);
  const start = Math.max(0.05, Math.min(1, startLoad));
  if (opsMonth >= rampMo) return 1;
  if (rampMo <= 1) return 1;
  return Math.min(
    1,
    start + ((1 - start) * (opsMonth - 1)) / (rampMo - 1),
  );
}

/**
 * 收入假设内嵌：达产爬坡曲线（相对稳态%）。
 * 改达产年数 / 起始负荷 / 管理能力即重绘。
 */
function RampLoadAssumeChart(props: {
  rampYears: number;
  rampStartLoad: number;
  /** 传入则用车辆公式（含管理能力缩短）；不传则场站公式 */
  mgmt?: number;
  height?: number;
  titleZh?: string;
}) {
  const vehicle = props.mgmt != null;
  const mgmt = props.mgmt ?? 0.7;
  const ry = Number.isFinite(props.rampYears) ? props.rampYears : vehicle ? 2 : 0.5;
  const start = Math.max(0.05, Math.min(1, props.rampStartLoad || (vehicle ? 0.55 : 0.5)));
  const effMo = vehicle
    ? effectiveRampMonths(ry, mgmt)
    : ry <= 1e-9
      ? 0
      : Math.max(1, Math.round(ry * 12));
  const horizon = Math.min(48, Math.max(effMo > 0 ? effMo + 6 : 12, 18));
  const categories: string[] = [];
  const loadPct: number[] = [];
  const flatFull: number[] = [];
  for (let m = 1; m <= horizon; m++) {
    categories.push(`M${m}`);
    const load = vehicle
      ? rampLoadAtOpsMonth(m, ry, start, mgmt)
      : stationRampLoadAtOpsMonth(m, ry, start);
    loadPct.push(Math.round(load * 1000) / 10);
    flatFull.push(100);
  }
  const startPct = Math.round(start * 1000) / 10;
  return (
    <Stack gap={4}>
      <Text size="small" weight="medium">
        {props.titleZh || "达产爬坡曲线（相对稳态负荷%）"}
      </Text>
      <LineChart
        height={props.height ?? 148}
        categories={categories}
        series={[
          {
            name: "爬坡负荷%",
            data: loadPct,
            tone: "info" as const,
          },
          {
            name: "满产100%",
            data: flatFull,
            tone: "neutral" as const,
          },
        ]}
        valueSuffix="%"
        beginAtZero
        yMax={100}
        referenceLines={
          effMo > 0
            ? [
                {
                  value: startPct,
                  label: `起点 M1 ${startPct}%`,
                  tone: "warning" as const,
                },
              ]
            : [
                {
                  value: 100,
                  label: "零爬坡·满产",
                  tone: "success" as const,
                },
              ]
        }
      />
      <Text size="small" tone="tertiary">
        {ry <= 1e-9
          ? "零爬坡：运营第 1 月即满产（曲线贴 100%）。"
          : `起点 ${pct(start)} → 约 M${effMo} 达满产` +
            (vehicle
              ? `（达产 ${ry} 年 × 管理能力 ${pct(mgmt, 0)} → 有效 ${effMo} 月；不是把「2年」当成2个月）。`
              : `（达产 ${ry} 年 = ${effMo} 月）。`) +
            " 改上方数字即重绘路径。"}
      </Text>
    </Stack>
  );
}

/** 情景系数：固有带宽 ×（资源越差振幅越大） */
function scenarioFactorOf(
  band: number,
  readiness: number,
  scenario: CashflowScenario,
) {
  const r = Math.max(0, Math.min(1, readiness));
  const amp = Math.max(0, band) * (1.25 - 0.5 * r);
  if (scenario === "down") return Math.max(0.4, 1 - amp);
  if (scenario === "up") return 1 + amp;
  return 1;
}


