/** 案例表稳态月：经营净额 / 毛收入（满产后 deploy=0 的月） */
function fenbangSteadyNetToGrossRatio(): number {
  const steady = FENBANG_DAE_COHORT.monthlyHead.filter((r) => r.deploy === 0);
  let inc = 0;
  let cf = 0;
  for (const r of steady) {
    inc += r.incomeKUsd;
    cf += r.cfKUsd;
  }
  if (!(inc > 0)) return 0.36;
  return Math.max(0.05, Math.min(0.95, cf / inc));
}

function fenbangFmtKUsd(v: number): string {
  const a = Math.abs(v);
  if (a >= 1000) return `${(v / 1000).toFixed(1)}M`;
  return `${Math.round(v)}`;
}

/** 订单投放图：绝对展示币（buildModel/toDisplay 口径，非 Excel 案例 kUSD） */
function deployRecoverFmtAbsolute(_unitSuffix: string): (v: number) => string {
  return (v: number) => {
    const a = Math.abs(v);
    const sign = v < 0 ? "-" : "";
    if (a >= 1_000_000) return `${sign}${(a / 1_000_000).toFixed(1)}M`;
    if (a >= 1_000) return `${sign}${(a / 1_000).toFixed(0)}k`;
    return `${sign}${Math.round(a)}`;
  };
}

function mergeDeployCapexStacks(
  stacks: DeployCapexStack[],
): DeployCapexStack[] {
  const acc = new Map<string, DeployCapexStack>();
  for (const s of stacks) {
    if (s.value <= 0) continue;
    const prev = acc.get(s.id);
    if (prev) prev.value += s.value;
    else acc.set(s.id, { ...s });
  }
  const list = [...acc.values()];
  list.sort((a, b) => {
    const ia = CAPEX_STACK_ORDER.indexOf(a.id);
    const ib = CAPEX_STACK_ORDER.indexOf(b.id);
    const ra = ia < 0 ? 99 : ia;
    const rb = ib < 0 ? 99 : ib;
    if (ra !== rb) return ra - rb;
    return a.labelZh.localeCompare(b.labelZh, "zh");
  });
  return list;
}

/** 投放柱内资产分层（ES / UT / 场站等） */
type DeployCapexStack = {
  id: string;
  labelZh: string;
  value: number;
};

type DeployRecoverBatch = {
  key: string;
  labelZh: string;
  /** 柱底第二行，如「10台 · 约Y2回本」 */
  noteZh: string;
  /** 含税采购全额（展示币） */
  capex: number;
  /** 左柱分资产堆叠；缺省则整柱为「投放」 */
  capexStacks?: DeployCapexStack[];
  /**
   * 劣后/权益出资（展示币）：优先取单元路径「期初」outflow（有债时已是权益现金）；
   * 无路径时按订单 payPlan 权益占比×含税采购。
   */
  capexEquity?: number;
  /** 权益口径左柱分色（与 capexStacks 同结构，按权益/全额比例缩放） */
  capexStacksEquity?: DeployCapexStack[];
  /** 右柱分年净CF（默认=扣本息前 CFADS）；year=经营年第几 */
  netStacks: { year: number; labelZh: string; value: number }[];
  /** 右柱分月净CF（默认=CFADS）；year 字段复用为 opsMonth */
  monthStacks?: { year: number; labelZh: string; value: number }[];
  /**
   * 剔优先本息后的回收（路径杠杆净≈CFADS−优先/夹层本息）。
   * 有月路径时必填；无则与 netStacks 同形回退。
   */
  netStacksAfterPi?: { year: number; labelZh: string; value: number }[];
  monthStacksAfterPi?: { year: number; labelZh: string; value: number }[];
  /** 月路径回本月（经营第 N 月）；有 monthStacks 时优先展示 */
  paybackMonth?: number | null;
};

/** 投放回收视角：资产全额·CFADS / 劣后权益出资·剔本息 */
type DeployRecoverNetMode = "cfads" | "after_senior";

function scaleDeployCapexStacks(
  stacks: DeployCapexStack[] | undefined,
  factor: number,
): DeployCapexStack[] | undefined {
  if (!stacks?.length) return undefined;
  const f = Math.max(0, factor);
  const out = stacks
    .map((s) => ({ ...s, value: s.value * f }))
    .filter((s) => s.value > 1e-12);
  return out.length ? out : undefined;
}

/** 单元路径期初 outflow 合计（有债时=权益现金出资，账面币） */
function equityOutlayBookFromPath(path: UnitCfPathPt[]): number {
  return assignUnitCfYearIds(path)
    .filter((p) => p.kind === "capex")
    .reduce((s, p) => s + Math.max(0, p.outflow), 0);
}

function deployBatchCapexLive(
  b: DeployRecoverBatch,
  mode: DeployRecoverNetMode,
): {
  capex: number;
  capexStacks?: DeployCapexStack[];
} {
  if (mode === "after_senior") {
    const capex =
      b.capexEquity != null && Number.isFinite(b.capexEquity)
        ? b.capexEquity
        : b.capex;
    const capexStacks =
      b.capexStacksEquity?.length
        ? b.capexStacksEquity
        : b.capexStacks
          ? scaleDeployCapexStacks(
              b.capexStacks,
              b.capex > 1e-12 ? capex / b.capex : 1,
            )
          : [{ id: "equity", labelZh: "劣后", value: capex }];
    return { capex, capexStacks };
  }
  return { capex: b.capex, capexStacks: b.capexStacks };
}

function unitPathRecoverNet(
  p: UnitCfPathPt,
  mode: DeployRecoverNetMode = "cfads",
): number {
  if (mode === "after_senior") {
    return Number.isFinite(p.net) ? p.net : 0;
  }
  return typeof p.cfads === "number" && Number.isFinite(p.cfads)
    ? p.cfads
    : p.net;
}

function deployRecoverBatchStacks(
  b: DeployRecoverBatch,
  mode: DeployRecoverNetMode,
): {
  netStacks: { year: number; labelZh: string; value: number }[];
  monthStacks?: { year: number; labelZh: string; value: number }[];
} {
  if (mode === "after_senior") {
    return {
      netStacks: b.netStacksAfterPi?.length
        ? b.netStacksAfterPi
        : b.netStacks,
      monthStacks: b.monthStacksAfterPi?.length
        ? b.monthStacksAfterPi
        : b.monthStacks,
    };
  }
  return { netStacks: b.netStacks, monthStacks: b.monthStacks };
}

/** 订单行 → 投放柱资产类（ES / UT / 场站…） */
function orderLineCapexKind(line: PurchaseOrderLine): {
  id: string;
  labelZh: string;
} {
  if (line.modeLabel === "场站" || line.skuId.includes("station")) {
    return { id: "station", labelZh: "场站" };
  }
  const sku = DEFAULT_ASSET_SKUS.find((x) => x.id === line.skuId);
  if (sku?.kind === "station") return { id: "station", labelZh: "场站" };
  if (sku?.kind === "two_wheel") return { id: "two_wheel", labelZh: "两轮" };
  const hay =
    `${line.skuId} ${line.nameZh} ${sku?.id || ""} ${sku?.model || ""} ${sku?.nameZh || ""}`.toLowerCase();
  if (
    hay.includes("aion-es") ||
    /\bes\b/.test(hay) ||
    hay.includes("埃安es") ||
    hay.includes("埃安 es")
  ) {
    return { id: "es", labelZh: "ES" };
  }
  if (
    hay.includes("aion-ut") ||
    /\but\b/.test(hay) ||
    hay.includes("埃安ut") ||
    hay.includes("埃安 ut")
  ) {
    return { id: "ut", labelZh: "UT" };
  }
  if (
    hay.includes("arcfox") ||
    hay.includes("t1") ||
    hay.includes("极狐")
  ) {
    return { id: "t1", labelZh: "T1" };
  }
  const short = (line.nameZh || sku?.model || sku?.nameZh || "其他").slice(0, 8);
  return { id: `other:${line.skuId || short}`, labelZh: short };
}

const CAPEX_STACK_ORDER = ["station", "es", "ut", "t1", "two_wheel"];

/** 节奏轨：车台数（不含场站枪） */
function orderVehicleQtyTotal(lines: PurchaseOrderLine[]): number {
  return lines
    .filter((l) => orderLineAsset(l) !== "station")
    .reduce((s, l) => s + Math.max(0, l.qty), 0);
}

/** 节奏轨：场站枪数合计 */
function orderStationGunTotal(lines: PurchaseOrderLine[]): number {
  return lines
    .filter((l) => orderLineAsset(l) === "station")
    .reduce((s, l) => s + Math.max(0, l.qty), 0);
}

/** 场站座数：订单行按枪计价，用 SKU 每站枪数反推座数 */
function orderStationSeatTotal(
  lines: PurchaseOrderLine[],
  skus: AssetSku[],
): number {
  let seats = 0;
  for (const l of lines) {
    if (orderLineAsset(l) !== "station") continue;
    const guns = Math.max(0, l.qty);
    if (!(guns > 0)) continue;
    const sku = skus.find((s) => s.id === l.skuId);
    const per = Math.max(1, sku ? stationGunCount(sku) : 10);
    seats += Math.max(1, Math.round(guns / per));
  }
  return seats;
}

/** 按资产类汇总台数/枪数，供节奏柱分色堆叠 */
function orderRhythmMix(
  lines: PurchaseOrderLine[],
): { id: string; labelZh: string; qty: number; station: boolean }[] {
  const acc = new Map<
    string,
    { id: string; labelZh: string; qty: number; station: boolean }
  >();
  for (const l of lines) {
    if (!(l.qty > 0)) continue;
    const kind = orderLineCapexKind(l);
    const station = kind.id === "station";
    const prev = acc.get(kind.id);
    if (prev) prev.qty += Math.max(0, l.qty);
    else
      acc.set(kind.id, {
        id: kind.id,
        labelZh: kind.labelZh,
        qty: Math.max(0, l.qty),
        station,
      });
  }
  const list = [...acc.values()];
  list.sort((a, b) => {
    const ia = CAPEX_STACK_ORDER.indexOf(a.id);
    const ib = CAPEX_STACK_ORDER.indexOf(b.id);
    const ra = ia < 0 ? 99 : ia;
    const rb = ib < 0 ? 99 : ib;
    if (ra !== rb) return ra - rb;
    return a.labelZh.localeCompare(b.labelZh, "zh");
  });
  return list;
}

function orderRhythmMixTip(lines: PurchaseOrderLine[]): string {
  const mix = orderRhythmMix(lines);
  if (!mix.length) return "无资产行";
  return mix
    .map((m) =>
      m.station ? `${m.labelZh}${m.qty}枪` : `${m.labelZh}×${m.qty}`,
    )
    .join(" · ");
}

function orderCapexStacksDisplay(
  order: PurchaseOrder,
  vat: number,
  usdMxn: number,
  disp: (usd: number) => number,
): DeployCapexStack[] {
  const v = Math.max(0, vat);
  const acc = new Map<string, DeployCapexStack>();
  for (const l of order.lines) {
    const lineUsd = orderLineLandedUsd(l, usdMxn);
    const sku = DEFAULT_ASSET_SKUS.find((x) => x.id === l.skuId);
    const grossUsd =
      l.engineBookCcy === "USD"
        ? lineUsd
        : sku && skuPricesIncludeVat(sku)
          ? lineUsd
          : lineUsd * (1 + v);
    if (grossUsd <= 0) continue;
    const kind = orderLineCapexKind(l);
    const prev = acc.get(kind.id);
    if (prev) prev.value += disp(grossUsd);
    else acc.set(kind.id, { id: kind.id, labelZh: kind.labelZh, value: disp(grossUsd) });
  }
  const list = [...acc.values()].filter((s) => s.value > 0);
  list.sort((a, b) => {
    const ia = CAPEX_STACK_ORDER.indexOf(a.id);
    const ib = CAPEX_STACK_ORDER.indexOf(b.id);
    const ra = ia < 0 ? 99 : ia;
    const rb = ib < 0 ? 99 : ib;
    if (ra !== rb) return ra - rb;
    return a.labelZh.localeCompare(b.labelZh, "zh");
  });
  return list;
}

/** 订单月路径账面净额 → 与左柱同一套展示币（路径统一为 MXN 账，再折展示币） */
function orderBookNetToDisplay(
  _order: PurchaseOrder,
  netBookMxn: number,
  fx: number,
  ccy: Currency,
  usdIdr: number,
): number {
  /** 单元/订单月路径已统一 MXN 账（授信包场站 USD 列载在建路径时已×FX） */
  const usd = netBookMxn / Math.max(fx, 1e-9);
  return toDisplay(usd, fx, ccy, usdIdr);
}

/** 单元月路径 → 投放图右柱分月堆叠（仅经营月；默认最多 36 月） */
function orderMonthStacksFromPath(
  order: PurchaseOrder,
  monthPath: UnitCfPathPt[],
  fx: number,
  ccy: Currency,
  usdIdr: number,
  maxMonths = 60,
  mode: DeployRecoverNetMode = "cfads",
): { year: number; labelZh: string; value: number }[] {
  const ops = assignUnitCfYearIds(monthPath).filter(
    (p) => p.kind === "ops" && p.opsMonth > 0,
  );
  return ops.slice(0, maxMonths).map((p) => ({
    year: p.opsMonth,
    labelZh: `M${p.opsMonth}`,
    value: orderBookNetToDisplay(
      order,
      unitPathRecoverNet(p, mode),
      fx,
      ccy,
      usdIdr,
    ),
  }));
}

/** 月堆叠 → 按年汇总（与「按月」同源，避免 buildModel 年行与单元回本口径打架） */
function yearStacksFromMonthStacks(
  monthStacks: { year: number; labelZh: string; value: number }[],
  maxYears = 5,
): { year: number; labelZh: string; value: number }[] {
  const byY = new Map<number, number>();
  for (const ms of monthStacks) {
    const y = Math.floor((Math.max(1, ms.year) - 1) / 12) + 1;
    if (y < 1 || y > maxYears) continue;
    byY.set(y, (byY.get(y) || 0) + ms.value);
  }
  const out: { year: number; labelZh: string; value: number }[] = [];
  for (let y = 1; y <= maxYears; y++) {
    out.push({
      year: y,
      labelZh: `第${y}年`,
      value: byY.get(y) || 0,
    });
  }
  return out;
}

/** 通用：左柱采购 / 右柱分年或分月净CF堆叠 / 虚线=采购回本对照；可全屏放大 */
function DeployRecoverBatchChart(props: {
  title: string;
  unitSuffix: string;
  batches: DeployRecoverBatch[];
  footnote: string;
  sourceNote?: string;
  fmtValue?: (v: number) => string;
  /** useCanvasState 键，避免计划/订单页全屏态互抢 */
  theaterKey?: string;
  /** 有 monthStacks 时默认露出按年/按月 */
  defaultGrain?: "year" | "month";
}) {
  const theme = useHostTheme();
  const { title, unitSuffix, batches, sourceNote } = props;
  const theaterKey = props.theaterKey || "deployRecoverTheater";
  const [theaterOpen, setTheaterOpen] = useCanvasState<boolean>(
    theaterKey,
    false,
  );
  const [netMode, setNetMode] = useCanvasState<DeployRecoverNetMode>(
    `${theaterKey}NetModeV1`,
    "cfads",
  );
  const modeLive: DeployRecoverNetMode =
    netMode === "after_senior" ? "after_senior" : "cfads";
  const batchesLive = batches.map((b) => {
    const st = deployRecoverBatchStacks(b, modeLive);
    const cap = deployBatchCapexLive(b, modeLive);
    return {
      ...b,
      capex: cap.capex,
      capexStacks: cap.capexStacks,
      netStacks: st.netStacks,
      monthStacks: st.monthStacks,
    };
  });
  const hasMonth = batchesLive.some(
    (b) => b.monthStacks != null && b.monthStacks.length > 0,
  );
  const [grain, setGrain] = useCanvasState<"year" | "month">(
    `${theaterKey}GrainV1`,
    props.defaultGrain || "year",
  );
  /** 按月下钻聚焦经营年：-1=全路径月；1..=仅该年 12 月 */
  const [yearFocus, setYearFocus] = useCanvasState<number>(
    `${theaterKey}YFocusV1`,
    -1,
  );
  /** 图例点灭：仅影响显示，不改台账/计划采购量 */
  const [hiddenCapex, setHiddenCapex] = useCanvasState<Record<string, boolean>>(
    `${theaterKey}HideCapexV1`,
    {},
  );
  const [hiddenBand, setHiddenBand] = useCanvasState<Record<string, boolean>>(
    `${theaterKey}HideBandV1`,
    {},
  );
  const grainLive: "year" | "month" =
    hasMonth && grain === "month" ? "month" : "year";
  const fmt = props.fmtValue || fenbangFmtKUsd;
  if (!batches.length) return null;

  const resolveStacks = (b: DeployRecoverBatch) => {
    if (
      grainLive === "month" &&
      b.monthStacks &&
      b.monthStacks.length > 0
    ) {
      if (yearFocus > 0) {
        return b.monthStacks
          .filter((s) => Math.floor((s.year - 1) / 12) + 1 === yearFocus)
          .map((s, i) => ({
            ...s,
            labelZh: `Y${yearFocus}·M${(s.year - 1) % 12 + 1}`,
            /** 图例色带仍按经营年 */
            year: yearFocus * 100 + i + 1,
            _opsMonth: s.year,
            _bandYear: yearFocus,
          }));
      }
      return b.monthStacks.map((s) => ({
        ...s,
        _opsMonth: s.year,
        _bandYear: Math.floor((s.year - 1) / 12) + 1,
      }));
    }
    return b.netStacks.map((s) => ({
      ...s,
      _opsMonth: s.year,
      _bandYear: s.year,
    }));
  };

  const withPb = batchesLive.map((b) => {
    const stacks = resolveStacks(b);
    const netTotal = stacks.reduce((s, x) => s + x.value, 0);
    const fullMonth = b.monthStacks || [];
    let cum = 0;
    let paybackPeriod: number | null = null;
    const pbSource =
      grainLive === "month" && fullMonth.length > 0 ? fullMonth : b.netStacks;
    for (const ys of pbSource) {
      cum += ys.value;
      if (paybackPeriod == null && cum >= b.capex) paybackPeriod = ys.year;
    }
    let paybackMonth: number | null = null;
    if (fullMonth.length > 0) {
      let mc = 0;
      for (const ms of fullMonth) {
        mc += ms.value;
        if (paybackMonth == null && mc >= b.capex) paybackMonth = ms.year;
      }
    }
    return {
      ...b,
      stacks,
      netTotal,
      paybackPeriod,
      paybackMonth,
    };
  });
  const footnoteLive =
    modeLive === "after_senior"
      ? `视角·劣后权益：左柱=权益/劣后现金出资（单元路径期初 outflow；无路径时按订单融资占比×含税采购）；右柱=剔优先本息后经营净（≈CFADS−优先/夹层本息）。虚线=权益出资额：累计越过≈权益方静态回本。${hasMonth ? "可切「按月」或点击右柱某年下钻。" : ""}`
      : props.footnote;
  const yearColors = [
    theme.category.blue,
    theme.category.cyan,
    theme.category.green,
    theme.category.yellow,
    theme.category.orange,
  ];
  /** 左柱资产色：与右柱分年色错开 */
  const capexColorById: Record<string, string> = {
    es: theme.text.primary,
    ut: theme.category.purple,
    t1: theme.category.pink,
    station: theme.category.gray,
    two_wheel: theme.fill.quaternary,
  };
  const capexFallbackColors = [
    theme.text.tertiary,
    theme.stroke.secondary,
    theme.fill.tertiary,
  ];
  const colorForCapex = (id: string, idx: number) =>
    capexColorById[id] ||
    capexFallbackColors[idx % capexFallbackColors.length]!;
  const bandMax = Math.max(
    1,
    ...withPb.flatMap((b) => b.stacks.map((s) => s._bandYear || 1)),
  );
  const bandIds = Array.from(
    { length: Math.min(5, bandMax) },
    (_, i) => i + 1,
  );
  const legendCapex = (() => {
    const seen = new Map<string, string>();
    for (const b of withPb) {
      const stacks =
        b.capexStacks && b.capexStacks.length > 0
          ? b.capexStacks
          : b.capex > 0
            ? [{ id: "capex", labelZh: "投放", value: b.capex }]
            : [];
      for (const s of stacks) {
        if (s.value > 0 && !seen.has(s.id)) seen.set(s.id, s.labelZh);
      }
    }
    const entries = [...seen.entries()];
    entries.sort((a, b) => {
      const ia = CAPEX_STACK_ORDER.indexOf(a[0]);
      const ib = CAPEX_STACK_ORDER.indexOf(b[0]);
      const ra = ia < 0 ? 99 : ia;
      const rb = ib < 0 ? 99 : ib;
      if (ra !== rb) return ra - rb;
      return a[1].localeCompare(b[1], "zh");
    });
    return entries.map(([id, labelZh], i) => ({
      id,
      labelZh,
      color: colorForCapex(id, i),
    }));
  })();
  const maxH = Math.max(
    1,
    ...withPb.map((v) => {
      const capShow =
        v.capexStacks && v.capexStacks.length > 0
          ? v.capexStacks
              .filter((s) => s.value > 0 && !hiddenCapex[s.id])
              .reduce((a, s) => a + s.value, 0)
          : hiddenCapex.capex
            ? 0
            : v.capex;
      const netShow = v.stacks
        .filter((s) => !hiddenBand[String(s._bandYear || s.year)])
        .reduce((a, s) => a + Math.max(0, s.value), 0);
      return Math.max(capShow, netShow, v.capex * 0.15);
    }),
  );
  const n = withPb.length;
  const isSingle = n === 1;
  /** 绘图区紧凑；少批时勿 width:100% 等比拉成超高柱 */
  const plotH = theaterOpen
    ? isSingle
      ? 320
      : 280
    : isSingle
      ? 160
      : Math.max(140, Math.min(200, 120 + n * 8));
  const barW = theaterOpen
    ? grainLive === "month"
      ? isSingle
        ? 44
        : 36
      : isSingle
        ? 40
        : 30
    : grainLive === "month"
      ? isSingle
        ? 36
        : 28
      : isSingle
        ? 34
        : 24;
  const gap = theaterOpen ? (isSingle ? 28 : 16) : isSingle ? 22 : 14;
  const pairGap = theaterOpen ? 52 : 44;
  const labelH = theaterOpen ? 64 : isSingle ? 44 : 42;
  const padTop = theaterOpen ? 22 : 12;
  const axisW = 44;
  const padLeft = axisW + 8;
  const padRight = 12;
  const pairW = barW * 2 + gap;
  const width = padLeft + padRight + n * pairW + (n - 1) * pairGap;
  const height = padTop + plotH + labelH;
  /** 非全屏：按内容比例缩放，高度封顶，避免单批被拉成半屏高 */
  const chartMaxH = theaterOpen ? undefined : isSingle ? 200 : Math.min(240, height);
  const yScale = (v: number) => (Math.max(0, v) / maxH) * plotH;
  /** 非零年段至少这么高，避免 Y1/Y2 糊成一条；超高则整体压回 plotH */
  const MIN_NET_SEG_PX = theaterOpen ? 10 : 7;

  const kpiCapex = withPb.reduce((s, v) => {
    const parts =
      v.capexStacks && v.capexStacks.length > 0
        ? v.capexStacks.filter((x) => x.value > 0 && !hiddenCapex[x.id])
        : v.capex > 0 && !hiddenCapex.capex
          ? [{ value: v.capex }]
          : [];
    return s + parts.reduce((a, x) => a + x.value, 0);
  }, 0);
  const kpiRecover = withPb.reduce((s, v) => {
    return (
      s +
      v.stacks
        .filter((x) => !hiddenBand[String(x._bandYear || x.year)])
        .reduce((a, x) => a + Math.max(0, x.value), 0)
    );
  }, 0);
  const kpiRatio = kpiCapex > 1e-9 ? kpiRecover / kpiCapex : null;
  const kpiPb =
    withPb.length === 1
      ? grainLive === "month"
        ? withPb[0]!.paybackMonth != null
          ? `M${withPb[0]!.paybackMonth}`
          : withPb[0]!.paybackPeriod != null
            ? `M${withPb[0]!.paybackPeriod}`
            : "期内未回本"
        : withPb[0]!.paybackPeriod != null
          ? `Y${withPb[0]!.paybackPeriod}`
          : "期内未回本"
      : null;

  const openYearMonth = (y: number) => {
    if (!hasMonth) return;
    setGrain("month");
    setYearFocus(Math.max(1, Math.round(y)));
  };
  const goYearAll = () => {
    setGrain("year");
    setYearFocus(-1);
  };
  const goMonthAll = () => {
    setGrain("month");
    setYearFocus(-1);
  };

  const yTicks = [0, 0.25, 0.5, 0.75, 1].map((t) => ({
    t,
    y: padTop + plotH - t * plotH,
    label: t === 0 ? "0" : fmt(maxH * t),
  }));

  const chartBody = (
    <Stack gap={theaterOpen ? 10 : 6} style={{ minWidth: 0, width: "100%" }}>
      <Row gap={10} align="center" wrap>
        <Text size="small" weight={theaterOpen ? "semibold" : undefined}>
          {title} · {unitSuffix}
        </Text>
        {hasMonth ? (
          <>
            <Pill size="sm" active={grainLive === "year"} onClick={goYearAll}>
              按年
            </Pill>
            <Pill
              size="sm"
              active={grainLive === "month" && yearFocus < 0}
              onClick={goMonthAll}
            >
              按月
            </Pill>
            {yearFocus > 0 ? (
              <Pill size="sm" active onClick={goMonthAll}>
                Y{yearFocus}·月 · 看全路径
              </Pill>
            ) : null}
          </>
        ) : null}
        <Text size="small" tone="tertiary">
          视角
        </Text>
        <Pill
          size="sm"
          active={modeLive === "cfads"}
          onClick={() => setNetMode("cfads")}
          title="左=含税购置全额 · 右=扣本息前 CFADS（资产侧静态回本）"
        >
          资产全额
        </Pill>
        <Pill
          size="sm"
          active={modeLive === "after_senior"}
          onClick={() => setNetMode("after_senior")}
          title="左=劣后/权益出资 · 右=剔优先本息后路径净（权益方投入回报周期）"
        >
          劣后权益
        </Pill>
        <Spacer />
        <Button
          variant={theaterOpen ? "secondary" : "ghost"}
          onClick={() => setTheaterOpen(!theaterOpen)}
        >
          {theaterOpen ? "退出全屏" : "全屏"}
        </Button>
      </Row>

      {/* KPI 一眼读：投放 / 回收 / 倍数 / 回本 */}
      <Row gap={20} align="center" wrap>
        <Stat
          value={fmt(kpiCapex)}
          label={modeLive === "after_senior" ? "权益投放" : "投放"}
        />
        <Stat
          value={fmt(kpiRecover)}
          label={
            modeLive === "after_senior"
              ? grainLive === "month"
                ? "剔本息·月累计"
                : "剔本息·年累计"
              : grainLive === "month"
                ? "CFADS·月累计"
                : "CFADS·年累计"
          }
          tone={
            kpiRatio != null && kpiRatio >= 1
              ? "success"
              : kpiRatio != null && kpiRatio < 0.6
                ? "warning"
                : undefined
          }
        />
        {kpiRatio != null ? (
          <Stat
            value={`${kpiRatio >= 10 ? kpiRatio.toFixed(1) : kpiRatio.toFixed(2)}×`}
            label={
              modeLive === "after_senior" ? "回收÷权益" : "回收÷投放"
            }
            tone={kpiRatio >= 1 ? "success" : "warning"}
          />
        ) : null}
        {kpiPb ? (
          <Stat
            value={kpiPb}
            label="静态回本"
            tone={kpiPb === "期内未回本" ? "warning" : "info"}
          />
        ) : null}
      </Row>

      <Row gap={10} align="center" wrap>
        <Text size="small" tone="tertiary" weight="medium">
          {modeLive === "after_senior" ? "左·权益出资" : "左·投放"}
        </Text>
        {legendCapex.map((c) => {
          const off = !!hiddenCapex[c.id];
          return (
            <span
              key={c.id}
              title={
                off
                  ? "点击显示（仅图例显隐，不改计划采购）"
                  : "点击隐藏（仅图例显隐，不改计划采购）"
              }
              onClick={() =>
                setHiddenCapex((prev) => ({ ...prev, [c.id]: !prev[c.id] }))
              }
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 4,
                cursor: "pointer",
                opacity: off ? 0.45 : 1,
                textDecoration: off ? "line-through" : undefined,
              }}
            >
              <span
                style={{
                  width: 10,
                  height: 10,
                  borderRadius: 2,
                  background: c.color,
                }}
              />
              <Text size="small" tone="tertiary">
                {c.labelZh}
              </Text>
            </span>
          );
        })}
        <span
          style={{
            width: 1,
            height: 12,
            background: theme.stroke.secondary,
            margin: "0 2px",
          }}
        />
        <Text size="small" tone="tertiary" weight="medium">
          右·回收
        </Text>
        {bandIds.map((y) => {
          const off = !!hiddenBand[String(y)];
          return (
            <span
              key={y}
              title={
                off
                  ? "点击显示该年净CF"
                  : "点击隐藏该年净CF（仅显示；点右柱可下钻月）"
              }
              onClick={() =>
                setHiddenBand((prev) => ({
                  ...prev,
                  [String(y)]: !prev[String(y)],
                }))
              }
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 4,
                cursor: "pointer",
                opacity: off ? 0.45 : 1,
                textDecoration: off ? "line-through" : undefined,
              }}
            >
              <span
                style={{
                  width: 10,
                  height: 10,
                  borderRadius: 2,
                  background: yearColors[(y - 1) % yearColors.length],
                }}
              />
              <Text size="small" tone="tertiary">
                {grainLive === "month" ? `Y${y}` : `Y${y}`}
              </Text>
            </span>
          );
        })}
        <span
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 4,
          }}
        >
          <span
            style={{
              width: 14,
              height: 0,
              borderTop: `2px dashed ${theme.category.red}`,
            }}
          />
          <Text size="small" tone="tertiary">
            回本线
          </Text>
        </span>
        {(Object.values(hiddenCapex).some(Boolean) ||
          Object.values(hiddenBand).some(Boolean)) && (
          <Pill
            size="sm"
            onClick={() => {
              setHiddenCapex({});
              setHiddenBand({});
            }}
          >
            显示全部
          </Pill>
        )}
      </Row>

      <div
        style={{
          width: "100%",
          overflowX: theaterOpen ? "auto" : "visible",
          overflowY: "hidden",
          WebkitOverflowScrolling: "touch",
          borderTop: `1px solid ${theme.stroke.tertiary}`,
          borderBottom: `1px solid ${theme.stroke.tertiary}`,
          paddingTop: 4,
          paddingBottom: 2,
          lineHeight: 0,
        }}
      >
        <svg
          viewBox={`0 0 ${width} ${height}`}
          preserveAspectRatio="xMinYMin meet"
          style={{
            display: "block",
            ...(theaterOpen
              ? {
                  width: Math.max(width, 960),
                  height: "auto",
                  minWidth: width,
                }
              : {
                  height: chartMaxH,
                  width: "auto",
                  maxWidth: "100%",
                }),
          }}
          role="img"
          aria-label="投放与分年净现金流对照"
        >
          {/* 水平刻度网格 */}
          {yTicks.map((tk) => (
            <g key={`yt-${tk.t}`}>
              <line
                x1={padLeft - 4}
                x2={width - padRight}
                y1={tk.y}
                y2={tk.y}
                stroke={
                  tk.t === 0 ? theme.stroke.primary : theme.stroke.tertiary
                }
                strokeWidth={tk.t === 0 ? 1.25 : 0.75}
                strokeDasharray={tk.t === 0 ? undefined : "3 4"}
              />
              <text
                x={padLeft - 8}
                y={tk.y + 3}
                textAnchor="end"
                fill={theme.text.tertiary}
                fontSize={theaterOpen ? 10 : 9}
              >
                {tk.label}
              </text>
            </g>
          ))}
          {/* 柱顶分组小标（单批时更醒目） */}
          {isSingle ? (
            <>
              <text
                x={padLeft + barW / 2}
                y={padTop - 10}
                textAnchor="middle"
                fill={theme.text.secondary}
                fontSize={11}
                fontWeight={600}
              >
                投放
              </text>
              <text
                x={padLeft + barW + gap + barW / 2}
                y={padTop - 10}
                textAnchor="middle"
                fill={theme.text.secondary}
                fontSize={11}
                fontWeight={600}
              >
                回收
              </text>
            </>
          ) : null}
          {withPb.map((v, i) => {
            const x0 = padLeft + i * (pairW + pairGap);
            const baseY = padTop + plotH;
            const rx = x0 + barW + gap;
            const capexParts =
              v.capexStacks && v.capexStacks.length > 0
                ? v.capexStacks.filter(
                    (s) => s.value > 0 && !hiddenCapex[s.id],
                  )
                : v.capex > 0 && !hiddenCapex.capex
                  ? [{ id: "capex", labelZh: "投放", value: v.capex }]
                  : [];
            const capShow = capexParts.reduce((a, s) => a + s.value, 0);
            const capH = yScale(capShow);
            const netParts = v.stacks.filter(
              (s) =>
                Math.max(0, s.value) > 0 &&
                !hiddenBand[String(s._bandYear || s.year)],
            );
            const netShow = netParts.reduce(
              (a, s) => a + Math.max(0, s.value),
              0,
            );
            let segHs = netParts.map((ys) => {
              const raw = yScale(Math.max(0, ys.value));
              return raw > 0 && raw < MIN_NET_SEG_PX ? MIN_NET_SEG_PX : raw;
            });
            const segSum = segHs.reduce((a, h) => a + h, 0);
            if (segSum > plotH && segSum > 0) {
              const k = plotH / segSum;
              segHs = segHs.map((h) => h * k);
            }
            const netHDraw = segHs.reduce((a, h) => a + h, 0);
            let capCursor = baseY;
            let yCursor = baseY;
            /** 累计 CF 越过采购额的那一段（回本年/月） */
            let cumPb = 0;
            let pbSegIdx = -1;
            for (let si = 0; si < netParts.length; si++) {
              cumPb += Math.max(0, netParts[si]!.value);
              if (pbSegIdx < 0 && cumPb >= v.capex) {
                pbSegIdx = si;
                break;
              }
            }
            const pbText =
              grainLive === "month"
                ? v.paybackMonth != null
                  ? `约M${v.paybackMonth}回本`
                  : v.paybackPeriod != null
                    ? `约M${v.paybackPeriod}回本`
                    : "期内未回本"
                : v.paybackPeriod != null
                  ? `约Y${v.paybackPeriod}回本`
                  : "期内未回本";
            const note = v.noteZh ? `${v.noteZh} · ${pbText}` : pbText;
            const recovered = capShow > 1e-9 && netShow >= capShow;
            return (
              <g key={v.key}>
                {/* 轻底带：区分投放/回收两柱 */}
                <rect
                  x={x0 - 4}
                  y={padTop}
                  width={barW + 8}
                  height={plotH}
                  fill={theme.fill.tertiary}
                  opacity={0.35}
                  rx={3}
                />
                <rect
                  x={rx - 4}
                  y={padTop}
                  width={barW + 8}
                  height={plotH}
                  fill={theme.fill.tertiary}
                  opacity={0.2}
                  rx={3}
                />
                {capexParts.map((seg, si) => {
                  const h = yScale(Math.max(0, seg.value));
                  capCursor -= h;
                  const isTop = si === capexParts.length - 1;
                  return (
                    <rect
                      key={seg.id}
                      x={x0}
                      y={capCursor}
                      width={barW}
                      height={Math.max(0, h - (isTop ? 0 : 1))}
                      fill={colorForCapex(seg.id, si)}
                      rx={isTop ? 3 : 0}
                      ry={isTop ? 3 : 0}
                    >
                      <title>{`${seg.labelZh} ${fmt(seg.value)}`}</title>
                    </rect>
                  );
                })}
                <text
                  x={x0 + barW / 2}
                  y={baseY - capH - 6}
                  textAnchor="middle"
                  fill={theme.text.secondary}
                  fontSize={theaterOpen ? 12 : isSingle ? 11 : 9}
                  fontWeight={600}
                >
                  {fmt(capShow)}
                </text>
                {netParts.map((ys, si) => {
                  const h = segHs[si] || 0;
                  yCursor -= h;
                  const band = ys._bandYear || ys.year;
                  const canDrill =
                    grainLive === "year" && hasMonth && !!v.monthStacks?.length;
                  const isPb = si === pbSegIdx;
                  const isTop = si === netParts.length - 1;
                  return (
                    <g key={`${ys.labelZh}-${ys.year}`}>
                      <rect
                        x={rx}
                        y={yCursor}
                        width={barW}
                        height={Math.max(0, h - (isTop || isPb ? 0 : 1))}
                        fill={yearColors[(band - 1) % yearColors.length]}
                        stroke={isPb ? theme.category.red : "none"}
                        strokeWidth={isPb ? 2 : 0}
                        rx={isTop ? 3 : 0}
                        ry={isTop ? 3 : 0}
                        style={canDrill ? { cursor: "pointer" } : undefined}
                        onClick={
                          canDrill ? () => openYearMonth(band) : undefined
                        }
                      >
                        <title>
                          {grainLive === "month"
                            ? `${ys.labelZh} ${fmt(ys.value)}${isPb ? " · 回本越过" : ""}`
                            : `第${band}年 ${fmt(ys.value)}${isPb ? " · 回本年" : ""}${canDrill ? " · 点击下钻月" : ""}`}
                        </title>
                      </rect>
                      {h >= (theaterOpen ? 14 : 12) ? (
                        <text
                          x={rx + barW / 2}
                          y={yCursor + h / 2 + 3}
                          textAnchor="middle"
                          fill={theme.bg.editor}
                          fontSize={theaterOpen ? 10 : 8}
                          fontWeight={isPb ? 700 : 500}
                          style={{ pointerEvents: "none" }}
                        >
                          {grainLive === "month"
                            ? `M${ys._opsMonth || ys.year}`
                            : `Y${band}`}
                        </text>
                      ) : null}
                      {isPb ? (
                        <text
                          x={rx + barW + 6}
                          y={yCursor + Math.min(h, 14)}
                          textAnchor="start"
                          fill={theme.category.red}
                          fontSize={theaterOpen ? 11 : 9}
                          fontWeight={700}
                        >
                          回本
                        </text>
                      ) : null}
                    </g>
                  );
                })}
                {/* 回本门槛虚线：跨左右两柱，更易对照 */}
                <line
                  x1={x0 - 2}
                  x2={rx + barW + 2}
                  y1={baseY - capH}
                  y2={baseY - capH}
                  stroke={theme.category.red}
                  strokeWidth={1.5}
                  strokeDasharray="5 3"
                  opacity={0.9}
                >
                  <title>
                    {modeLive === "after_senior"
                      ? "静态回本门槛（=左柱权益出资）"
                      : "静态回本门槛（=左柱含税采购）"}
                  </title>
                </line>
                <text
                  x={rx + barW / 2}
                  y={baseY - netHDraw - 6}
                  textAnchor="middle"
                  fill={
                    recovered ? theme.category.green : theme.text.secondary
                  }
                  fontSize={theaterOpen ? 12 : isSingle ? 11 : 9}
                  fontWeight={600}
                >
                  {fmt(netShow)}
                </text>
                <text
                  x={x0 + pairW / 2}
                  y={baseY + 14}
                  textAnchor="middle"
                  fill={theme.text.primary}
                  fontSize={theaterOpen ? 13 : isSingle ? 12 : 10}
                  fontWeight={600}
                >
                  {v.labelZh}
                </text>
                <text
                  x={x0 + pairW / 2}
                  y={baseY + 28}
                  textAnchor="middle"
                  fill={
                    pbSegIdx >= 0 ? theme.category.red : theme.text.tertiary
                  }
                  fontSize={theaterOpen ? 11 : 9}
                  fontWeight={pbSegIdx >= 0 ? 600 : 400}
                >
                  {note}
                </text>
                {!isSingle ? (
                  <>
                    <text
                      x={x0 + barW / 2}
                      y={baseY + 42}
                      textAnchor="middle"
                      fill={theme.text.tertiary}
                      fontSize={8}
                    >
                      投
                    </text>
                    <text
                      x={rx + barW / 2}
                      y={baseY + 42}
                      textAnchor="middle"
                      fill={theme.text.tertiary}
                      fontSize={8}
                    >
                      收
                    </text>
                  </>
                ) : null}
              </g>
            );
          })}
        </svg>
      </div>
      <Text size="small" tone="tertiary">
        {grainLive === "month"
          ? modeLive === "after_senior"
            ? "视角·劣后权益：右柱=剔本息后经营净月堆叠；虚线=权益出资额，累计越过≈权益方静态回本。点「按年」回到分年；点右柱年段可下钻月。"
            : "视角·资产全额：右柱=CFADS 月堆叠；虚线=含税采购额，累计越过≈资产侧静态回本（未扣本息）。点「按年」回到分年；点右柱年段可下钻月。"
          : footnoteLive}
      </Text>
      {sourceNote ? (
        <Text size="small" tone="tertiary">
          {sourceNote}
          {" · "}
          {modeLive === "after_senior" ? "剔本息回收" : "CFADS回收"}约{" "}
          {fmt(kpiRecover)}
          {modeLive === "after_senior"
            ? " · 视角：劣后权益（出资÷剔本息）"
            : " · 视角：资产全额（购置÷CFADS）"}
        </Text>
      ) : null}
    </Stack>
  );

  if (!theaterOpen) return chartBody;

  return (
    <>
      <div style={{ minHeight: 120 }} aria-hidden />
      <div
        role="dialog"
        aria-label={`${title} 全屏`}
        style={{
          position: "fixed",
          inset: 0,
          zIndex: 9995,
          boxSizing: "border-box",
          padding: "12px 16px 20px",
          background: theme.bg.editor,
          overflow: "auto",
          display: "flex",
          flexDirection: "column",
        }}
      >
        {chartBody}
      </div>
    </>
  );
}

/**
 * 案例表投放批次：
 * 左柱=期初采购；右柱=投产后第1–5年净现金流堆叠（毛收入×稳态净/毛比）。
 */
function FenbangDeployRecoverChart() {
  const data = FENBANG_DAE_COHORT;
  const vintages = data.vintages;
  if (!vintages.length) return null;
  const netRatio = fenbangSteadyNetToGrossRatio();
  const batches: DeployRecoverBatch[] = vintages.map((v) => {
    const netStacks = v.yearStacks.map((ys) => ({
      year: ys.year,
      labelZh: ys.labelZh,
      value: ys.kUsd * netRatio,
    }));
    let cum = 0;
    let paybackYear: number | null = null;
    for (const ys of netStacks) {
      cum += ys.value;
      if (paybackYear == null && cum >= v.capexKUsd) paybackYear = ys.year;
    }
    return {
      key: v.ym,
      labelZh: v.labelZh,
      noteZh: `${v.units}台 · ${
        paybackYear != null ? `约Y${paybackYear}回本` : "5年内未回本"
      }`,
      capex: v.capexKUsd,
      /** 案例表为 DAE·ES 车队 */
      capexStacks: [
        { id: "es", labelZh: "ES", value: v.capexKUsd },
      ],
      netStacks,
    };
  });
  return (
    <DeployRecoverBatchChart
      title="月度投放 & 净现金流回收（Excel 案例批次）"
      unitSuffix="kUSD"
      batches={batches}
      theaterKey="fenbangDeployRecoverTheater"
      footnote={`左柱=该月采购投放（按资产类型分色）；右柱=该批次投产后第1–5年净现金流堆叠（案例分年毛收入 × 稳态净/毛比 ${pct(netRatio, 0)}）。虚线=采购额：右柱累计越过虚线≈该批静态回本。`}
      sourceNote={`信源：${data.sourceZh} · 投放 ${data.deployTotalUnits} 台 · 采购合计 ${data.deployCapexTotalKUsd.toFixed(0)} kUSD · 5 年批净合计约 ${fenbangFmtKUsd(batches.reduce((s, b) => s + b.netStacks.reduce((t, x) => t + x.value, 0), 0))}`}
    />
  );
}

/** 订单批次 → 投放/分年经营净CF（buildModel 年行；购置年加回 capex 以免双计） */
function orderDeployRecoverBatches(
  orders: PurchaseOrder[],
  trials: { orderId: string; rows: YearRow[] }[],
  vat: number,
  fx: number,
  ccy: Currency,
  usdIdr: number = DEFAULT_USD_IDR,
  monthPathByOrderId?: Map<string, UnitCfPathPt[]>,
): DeployRecoverBatch[] {
  const open = [...orders]
    .filter((o) => o.status !== "cancelled")
    /** 与节奏轨一致：无车又无站的空壳不进柱 */
    .filter(
      (o) =>
        orderVehicleQtyTotal(o.lines) > 0 || orderStationGunTotal(o.lines) > 0,
    )
    .sort((a, b) => String(a.payDate).localeCompare(String(b.payDate)));
  /** trials 保留入参兼容调用方；回收柱仅认月路径，不再吃年行 */
  void trials;
  const disp = (usd: number) => toDisplay(usd, fx, ccy, usdIdr);
  return open.map((o) => {
    const capexUsd = orderTotalGrossUsd(o, vat, fx);
    const monthPath = monthPathByOrderId?.get(o.id);
    const monthStacks =
      monthPath && monthPath.length > 0
        ? orderMonthStacksFromPath(o, monthPath, fx, ccy, usdIdr, 60, "cfads")
        : undefined;
    const monthStacksAfterPi =
      monthPath && monthPath.length > 0
        ? orderMonthStacksFromPath(
            o,
            monthPath,
            fx,
            ccy,
            usdIdr,
            60,
            "after_senior",
          )
        : undefined;
    /** 优先用单元月路径汇总年柱，与回本/按月下钻同源；无月路径时年柱留空（勿静默回退 buildModel） */
    const netStacks =
      monthStacks && monthStacks.length > 0
        ? yearStacksFromMonthStacks(monthStacks, 5)
        : [];
    const netStacksAfterPi =
      monthStacksAfterPi && monthStacksAfterPi.length > 0
        ? yearStacksFromMonthStacks(monthStacksAfterPi, 5)
        : [];
    const capex = disp(capexUsd);
    const capexStacks = orderCapexStacksDisplay(o, vat, fx, disp);
    /** 权益出资：优先路径期初 outflow；否则订单融资占比 */
    const pathEqBook =
      monthPath && monthPath.length > 0
        ? equityOutlayBookFromPath(monthPath)
        : 0;
    const capexEquity =
      pathEqBook > 1e-9
        ? orderBookNetToDisplay(o, pathEqBook, fx, ccy, usdIdr)
        : disp(orderEquityMxn(o, vat, fx));
    const eqRatio = capex > 1e-12 ? Math.min(1, capexEquity / capex) : 1;
    const capexStacksEquity =
      scaleDeployCapexStacks(capexStacks, eqRatio) ||
      (capexEquity > 0
        ? [{ id: "equity", labelZh: "劣后", value: capexEquity }]
        : undefined);
    let cum = 0;
    let paybackYear: number | null = null;
    for (const ys of netStacks) {
      cum += ys.value;
      if (paybackYear == null && cum >= capex) paybackYear = ys.year;
    }
    let paybackMonth: number | null = null;
    if (monthStacks && monthStacks.length > 0) {
      let mc = 0;
      for (const ms of monthStacks) {
        mc += ms.value;
        if (paybackMonth == null && mc >= capex) paybackMonth = ms.year;
      }
    }
    const units = o.lines.reduce((s, l) => s + Math.max(0, l.qty), 0);
    const carQty = o.lines
      .filter((l) => orderLineAsset(l) !== "station")
      .reduce((s, l) => s + Math.max(0, l.qty), 0);
    const gunQty = o.lines
      .filter((l) => orderLineAsset(l) === "station")
      .reduce((s, l) => s + Math.max(0, l.qty), 0);
    const scaleZh =
      carQty > 0 && gunQty > 0
        ? `${carQty}台+${gunQty}枪`
        : gunQty > 0
          ? `${gunQty}枪`
          : `${carQty || units}台`;
    const payShort = String(o.payDate || "").slice(2, 7);
    /**
     * 第 N 次与左栏节奏轨同源：按付款日在同授信包内重排，
     * 勿死用持久化 creditDrawdownSeq（拖月后易与节奏「第2次」错位）。
     */
    const seq = creditDrawdownRankByPayDate(open, o.id);
    const trancheN = o.creditDrawdownPlanId
      ? open.filter(
          (x) =>
            x.creditDrawdownPlanId === o.creditDrawdownPlanId &&
            x.status !== "cancelled",
        ).length
      : 0;
    const labelZh = seq
      ? `第${seq}${trancheN ? `/${trancheN}` : ""}次·${payShort || o.unitCode}`
      : payShort || o.unitCode || o.label;
    const pbZh =
      paybackMonth != null
        ? `约M${paybackMonth}回本`
        : paybackYear != null
          ? `约Y${paybackYear}回本`
          : "期内未回本";
    return {
      key: o.id,
      labelZh,
      /** 规模；回本由图表按年/月 grain 重算 */
      noteZh: scaleZh,
      capex,
      capexStacks,
      capexEquity,
      capexStacksEquity,
      netStacks,
      monthStacks,
      netStacksAfterPi,
      monthStacksAfterPi,
      paybackMonth,
    };
  });
}

function OrderDeployRecoverChart(props: {
  batches: DeployRecoverBatch[];
  unitSuffix: string;
  /** 可选范围说明，如管理人名 */
  scopeLabel?: string;
  theaterKey?: string;
}) {
  const { batches, unitSuffix, scopeLabel, theaterKey } = props;
  if (!batches.length) return null;
  const capexSum = batches.reduce((s, b) => s + b.capex, 0);
  const scopePrefix = scopeLabel ? `${scopeLabel} · ` : "";
  const hasMonth = batches.some((b) => (b.monthStacks?.length || 0) > 0);
  const fmtAbs = deployRecoverFmtAbsolute(unitSuffix);
  return (
    <DeployRecoverBatchChart
      title="订单投放 & 净现金流回收（按付款批次）"
      unitSuffix={unitSuffix}
      batches={batches}
      theaterKey={theaterKey || "orderDeployRecoverTheater"}
      fmtValue={fmtAbs}
      footnote={`视角·资产全额：左柱=含税采购；右柱=CFADS。切「劣后权益」后左柱改权益出资、右柱剔优先/夹层本息，虚线对权益回本。${hasMonth ? "可切「按月」或点击右柱某年下钻。" : ""}`}
      sourceNote={`${scopePrefix}付款批次 ${batches.length} 笔 · 采购合计约 ${fmtAbs(capexSum)}（${unitSuffix}${hasMonth ? "·月路径" : ""}）`}
    />
  );
}

/** YYYY-MM-DD → YYYY-MM */
function payDateToYm(payDate: string): string {
  const s = String(payDate || "").slice(0, 7);
  return /^\d{4}-\d{2}$/.test(s) ? s : "";
}

/** 日历加减月，保留日（溢出则落到月末） */
function addCalendarMonthsIso(isoDate: string, deltaMo: number): string {
  const raw = String(isoDate || "").slice(0, 10);
  const d = new Date(`${raw}T12:00:00`);
  if (Number.isNaN(d.getTime())) return raw || isoDate;
  const day = d.getDate();
  d.setDate(1);
  d.setMonth(d.getMonth() + deltaMo);
  const last = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
  d.setDate(Math.min(day, last));
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${dd}`;
}

/** 把付款日改到目标年月，尽量保留原日 */
function payDateMovedToYm(payDate: string, ym: string): string {
  if (!/^\d{4}-\d{2}$/.test(ym)) return payDate;
  const dayRaw = String(payDate || "").slice(8, 10);
  const dayN = Math.max(1, Math.min(28, parseInt(dayRaw || "1", 10) || 1));
  const [ys, ms] = ym.split("-");
  const y = parseInt(ys!, 10);
  const mo = parseInt(ms!, 10);
  const last = new Date(y, mo, 0).getDate();
  const dd = String(Math.min(dayN, last)).padStart(2, "0");
  return `${ym}-${dd}`;
}

function listYmSpan(fromYm: string, toYm: string): string[] {
  if (!fromYm || !toYm) return [];
  const out: string[] = [];
  let cur = fromYm;
  for (let i = 0; i < 96; i++) {
    out.push(cur);
    if (cur >= toYm) break;
    cur = payDateToYm(addCalendarMonthsIso(`${cur}-01`, 1));
  }
  return out;
}

/**
 * 计划投放节奏轨：横拖改付款月、顶边竖拖改台数、拖到已有月合并、点空月拆半批。
 * 测算场景：已付款默认可拖且不改 status；点「解锁」才批量改 pending_pay。
 * 按付款月重排 creditDrawdownSeq；拆批不复制场站。
 */
function orderLineQtyTotal(lines: PurchaseOrderLine[]): number {
  return lines.reduce((s, l) => s + Math.max(0, l.qty), 0);
}

/** 按付款月在同批授信里的名次（1-based）；无 plan 则在当前列表内排 */
function creditDrawdownRankByPayDate(
  orders: PurchaseOrder[],
  orderId: string,
): number {
  const self = orders.find((o) => o.id === orderId);
  if (!self || self.status === "cancelled") return 0;
  const planId = self.creditDrawdownPlanId;
  const peers = orders
    .filter(
      (o) =>
        o.status !== "cancelled" &&
        (planId
          ? o.creditDrawdownPlanId === planId
          : o.id === orderId || !o.creditDrawdownPlanId),
    )
    .sort((a, b) => {
      const d = String(a.payDate).localeCompare(String(b.payDate));
      if (d !== 0) return d;
      return (a.creditDrawdownSeq || 0) - (b.creditDrawdownSeq || 0);
    });
  const i = peers.findIndex((o) => o.id === orderId);
  return i >= 0 ? i + 1 : 0;
}

/**
 * 节奏轨展示范围：优先同授信 plan；
 * 勿写死案例台数上限（上限应来自用户 envelope / 计划元数据，缺省不告警）。
 */
function resolveDeployRhythmScope(args: {
  orders: PurchaseOrder[];
  focusOrderId?: string | null;
}): { orders: PurchaseOrder[]; unitsCap: number | null; scopeZh: string } {
  const open = args.orders.filter((o) => o.status !== "cancelled");
  const focus =
    (args.focusOrderId &&
      open.find((o) => o.id === args.focusOrderId)) ||
    null;
  const yohoPeers = open.filter(
    (o) => o.creditDrawdownPlanId === YOHO_CREDIT_DRAWDOWN_PLAN_ID,
  );
  const planId =
    focus?.creditDrawdownPlanId ||
    (yohoPeers.length > 0 ? YOHO_CREDIT_DRAWDOWN_PLAN_ID : null);
  if (planId) {
    const peers = open.filter((o) => o.creditDrawdownPlanId === planId);
    if (peers.length > 0) {
      return {
        orders: peers,
        unitsCap: null,
        scopeZh: displayCreditPlanScopeZh(
          planId,
          planId === YOHO_CREDIT_DRAWDOWN_PLAN_ID
            ? YOHO_CREDIT_DRAWDOWN_PLAN_LABEL
            : peers[0]!.creditDrawdownPlanLabelZh,
        ),
      };
    }
  }
  /** 无 YOHO/焦点时：台账若恰好一个授信 plan，收窄到该包（避免多包名却混算） */
  const uniquePlans = [
    ...new Set(
      open
        .map((o) => o.creditDrawdownPlanId)
        .filter((id): id is string => !!id),
    ),
  ];
  if (uniquePlans.length === 1) {
    const onlyId = uniquePlans[0]!;
    const peers = open.filter((o) => o.creditDrawdownPlanId === onlyId);
    if (peers.length > 0) {
      return {
        orders: peers,
        unitsCap: null,
        scopeZh: displayCreditPlanScopeZh(
          onlyId,
          peers[0]!.creditDrawdownPlanLabelZh,
        ),
      };
    }
  }
  if (focus) {
    return { orders: [focus], unitsCap: null, scopeZh: focus.unitCode || "本批" };
  }
  return { orders: open, unitsCap: null, scopeZh: "当前列表" };
}

/**
 * 整包左右同屏统一订单范围。
 * - package：与节奏轨同授信子集（须能唯一落到一个 plan）
 * - all：管理人过滤后的全部未取消台账
 * 瀑布 / DSCR / VTL / 节奏 / 投放图必须共用本结果。
 */
function resolvePlanLiveOrderScope(args: {
  orders: PurchaseOrder[];
  focusOrderId?: string | null;
  mode: "package" | "all";
  managerLabelZh: string;
}): {
  orders: PurchaseOrder[];
  unitsCap: number | null;
  scopeZh: string;
  packageAvailable: boolean;
  packageOrderCount: number;
  allOrderCount: number;
} {
  const open = args.orders.filter((o) => o.status !== "cancelled");
  const pkg = resolveDeployRhythmScope({
    orders: open,
    focusOrderId: args.focusOrderId,
  });
  const pkgPlanIds = new Set(
    pkg.orders
      .map((o) => o.creditDrawdownPlanId)
      .filter((id): id is string => !!id),
  );
  /**
   * 仅当 pkg 结果落在「单一授信 plan」时才可点「当前授信包」。
   * 多 plan 无焦点时 resolve 会回落整表 → packageAvailable=false，避免假亮。
   */
  const packageAvailable =
    pkg.orders.length > 0 &&
    pkgPlanIds.size === 1 &&
    (pkg.orders.length < open.length ||
      open.every((o) => o.creditDrawdownPlanId === [...pkgPlanIds][0]));
  const allScopeZh =
    !args.managerLabelZh || args.managerLabelZh === "全部"
      ? "全部台账"
      : `管理人 ${args.managerLabelZh}`;
  if (args.mode === "all" || !packageAvailable) {
    return {
      orders: open,
      unitsCap: null,
      scopeZh: allScopeZh,
      packageAvailable,
      packageOrderCount: pkgPlanIds.size === 1 ? pkg.orders.length : 0,
      allOrderCount: open.length,
    };
  }
  return {
    orders: pkg.orders,
    unitsCap: pkg.unitsCap,
    scopeZh: pkg.scopeZh,
    packageAvailable,
    packageOrderCount: pkg.orders.length,
    allOrderCount: open.length,
  };
}

/** 同授信 plan 内按 payDate 重写第 N 次；不改 paid/pending（解锁只走「解锁·按未付款测算」） */
function resequenceOrdersForRhythmScenario(
  orders: PurchaseOrder[],
  _touchIds?: Set<string>,
): PurchaseOrder[] {
  const planIds = new Set<string>();
  for (const o of orders) {
    if (o.status === "cancelled") continue;
    if (o.creditDrawdownPlanId) planIds.add(o.creditDrawdownPlanId);
  }
  const seqById = new Map<string, number>();
  for (const planId of planIds) {
    const peers = orders
      .filter(
        (o) =>
          o.status !== "cancelled" && o.creditDrawdownPlanId === planId,
      )
      .sort((a, b) => {
        const d = String(a.payDate).localeCompare(String(b.payDate));
        if (d !== 0) return d;
        return String(a.id).localeCompare(String(b.id));
      });
    peers.forEach((o, i) => seqById.set(o.id, i + 1));
  }
  const next = orders.map((o) => {
    if (o.status === "cancelled") return o;
    const nextSeq = seqById.get(o.id);
    if (nextSeq == null) return o;
    if (o.creditDrawdownSeq === nextSeq) return o;
    return {
      ...o,
      creditDrawdownSeq: nextSeq,
    };
  });
  return dedupeCreditPlanStations(next);
}

/** 只改车辆台数，场站枪行原样保留 */
function scaleOrderVehicleQty(
  lines: PurchaseOrderLine[],
  targetVehicles: number,
): PurchaseOrderLine[] {
  const veh = lines.filter((l) => orderLineAsset(l) !== "station");
  const st = lines
    .filter((l) => orderLineAsset(l) === "station")
    .map((l) => ({ ...l }));
  if (!veh.length) return [...st];
  return [...scaleOrderLinesToTotalQty(veh, targetVehicles), ...st];
}

/** 拆出的新批：只带车，不复制场站（包内场站应仍挂在原批，避免多座 $500k） */
function scaleOrderVehicleQtyNoStation(
  lines: PurchaseOrderLine[],
  targetVehicles: number,
): PurchaseOrderLine[] {
  const veh = lines.filter((l) => orderLineAsset(l) !== "station");
  if (!veh.length) return [];
  return scaleOrderLinesToTotalQty(veh, targetVehicles);
}

/**
 * 同授信 plan：场站只保留在付款日最早的一笔（其余剥掉）。
 * 防止拆批/误合并后出现「多柱都标站」= 多座 $500k 假象。
 */
function dedupeCreditPlanStations(orders: PurchaseOrder[]): PurchaseOrder[] {
  const byPlan = new Map<string, PurchaseOrder[]>();
  for (const o of orders) {
    if (o.status === "cancelled" || !o.creditDrawdownPlanId) continue;
    if (orderStationGunTotal(o.lines) <= 0) continue;
    const g = byPlan.get(o.creditDrawdownPlanId) || [];
    g.push(o);
    byPlan.set(o.creditDrawdownPlanId, g);
  }
  const keepStationId = new Set<string>();
  for (const group of byPlan.values()) {
    group.sort((a, b) => {
      const d = String(a.payDate).localeCompare(String(b.payDate));
      if (d !== 0) return d;
      return (a.creditDrawdownSeq || 0) - (b.creditDrawdownSeq || 0);
    });
    keepStationId.add(group[0]!.id);
  }
  if (!keepStationId.size) return orders;
  return orders.map((o) => {
    if (o.status === "cancelled" || !o.creditDrawdownPlanId) return o;
    if (orderStationGunTotal(o.lines) <= 0) return o;
    if (keepStationId.has(o.id)) return o;
    return {
      ...o,
      lines: o.lines.filter((l) => orderLineAsset(l) !== "station"),
    };
  });
}

function scaleOrderLinesToTotalQty(
  lines: PurchaseOrderLine[],
  target: number,
): PurchaseOrderLine[] {
  const t = Math.max(1, Math.round(target));
  const next = lines.map((l) => ({ ...l }));
  const sum = orderLineQtyTotal(next);
  if (sum <= 0) {
    if (next[0]) next[0] = { ...next[0], qty: t };
    return next;
  }
  let alloc = 0;
  for (let i = 0; i < next.length; i++) {
    if (i === next.length - 1) {
      next[i] = { ...next[i]!, qty: Math.max(0, t - alloc) };
    } else {
      const q = Math.max(
        0,
        Math.round((Math.max(0, next[i]!.qty) / sum) * t),
      );
      next[i] = { ...next[i]!, qty: q };
      alloc += q;
    }
  }
  if (orderLineQtyTotal(next) <= 0 && next[0]) {
    next[0] = { ...next[0], qty: t };
  }
  return next;
}

function mergeOrderLines(
  into: PurchaseOrderLine[],
  from: PurchaseOrderLine[],
): PurchaseOrderLine[] {
  const map = new Map<string, PurchaseOrderLine>();
  for (const l of into) {
    map.set(`${l.skuId}|${l.cardId}|${l.modeLabel}`, { ...l });
  }
  for (const l of from) {
    const k = `${l.skuId}|${l.cardId}|${l.modeLabel}`;
    const prev = map.get(k);
    if (prev) {
      /** 场站同行合并：取较大枪数，勿 10+10=20 当成两座 */
      if (orderLineAsset(prev) === "station") {
        map.set(k, {
          ...prev,
          qty: Math.max(prev.qty, Math.max(0, l.qty)),
          unitLandedMxn: prev.unitLandedMxn,
          engineBookCcy: prev.engineBookCcy || l.engineBookCcy,
        });
      } else {
        map.set(k, { ...prev, qty: prev.qty + Math.max(0, l.qty) });
      }
    } else {
      map.set(k, {
        ...l,
        id: `${l.id}-m${Date.now().toString(36).slice(-4)}`,
      });
    }
  }
  return [...map.values()];
}

/** 节奏轨加购：SKU → 默认经营模式 */
function rhythmDefaultModeForSku(sku: AssetSku): string {
  if (sku.kind === "station") return "场站";
  if (sku.kind === "two_wheel" || sku.id === "id-escooter-sample") return "LTO";
  if (sku.id === "aion-ut") return "LTO";
  return "DAE";
}

/** 场站默认枪数（无规格时 10） */
function rhythmStationGuns(sku: AssetSku): number {
  const spec = sku.stationSpec;
  if (!spec) return 10;
  return Math.max(1, (spec.fastGuns || 0) + (spec.slowGuns || 0));
}

/** 节奏轨加购选项：skuId::configId */
function rhythmAddOptionValue(skuId: string, configId: string): string {
  return `${skuId}::${configId}`;
}

function parseRhythmAddOption(
  raw: string,
): { skuId: string; configId: string } | null {
  const s = String(raw || "");
  const i = s.indexOf("::");
  if (i <= 0) return null;
  const skuId = s.slice(0, i);
  const configId = s.slice(i + 2);
  if (!skuId || !configId) return null;
  return { skuId, configId };
}

/** 展开货架 → 下拉项（车/两轮/场站 × 配置档；已有标「再加」） */
function buildRhythmAddOptions(
  skus: AssetSku[],
  order: PurchaseOrder,
): { value: string; label: string }[] {
  const presentSku = new Set(order.lines.map((l) => l.skuId));
  const presentName = new Set(order.lines.map((l) => l.nameZh));
  const out: { value: string; label: string }[] = [];
  for (const sku of skus) {
    if (
      sku.kind !== "vehicle" &&
      sku.kind !== "two_wheel" &&
      sku.kind !== "station"
    ) {
      continue;
    }
    const variants =
      sku.configVariants && sku.configVariants.length > 0
        ? sku.configVariants
        : [
            {
              id: sku.defaultConfigId || `${sku.id}-std`,
              nameZh: sku.model || sku.nameZh,
              rangeZh: "",
              batteryKwh: 0,
              tireSpecZh: "",
              isDefault: true,
            } as SkuConfigVariant,
          ];
    for (const v of variants) {
      const value = rhythmAddOptionValue(sku.id, v.id);
      const lineName =
        sku.kind === "station"
          ? sku.nameZh
          : `${sku.nameZh} · ${v.nameZh}`;
      const already =
        presentName.has(lineName) ||
        (presentSku.has(sku.id) &&
          variants.length === 1);
      const kindTag =
        sku.kind === "station"
          ? "场站"
          : sku.kind === "two_wheel"
            ? "两轮"
            : "车";
      const label = [
        `[${kindTag}]`,
        sku.nameZh,
        v.nameZh && v.nameZh !== sku.nameZh ? v.nameZh : null,
        already ? "已有·再加" : null,
      ]
        .filter(Boolean)
        .join(" · ");
      out.push({ value, label });
    }
  }
  return out;
}

/** 节奏轨：从货架 SKU(+配置档) 生成一行 */
function buildRhythmOrderLineFromSku(
  sku: AssetSku,
  qty: number,
  configId?: string,
): PurchaseOrderLine {
  const modeLabel = rhythmDefaultModeForSku(sku);
  const variant = resolveConfigVariant(sku, configId);
  const cfgId =
    variant?.id ||
    sku.defaultConfigId ||
    sku.configVariants?.[0]?.id;
  const isStation = sku.kind === "station";
  const q = isStation
    ? Math.max(1, Math.round(qty || rhythmStationGuns(sku)))
    : Math.max(1, Math.round(qty));
  const disc = volumeDiscountRate(sku, isStation ? 1 : q);
  let unitLandedMxn = modelUnitLandedEngineBook(
    sku,
    isStation ? 1 : q,
    17.522,
    DEFAULT_USD_IDR,
    cfgId,
  );
  if (isStation) {
    /** 场站货架价按「座」；订单行按枪计价 → 单价÷枪数 */
    const guns = rhythmStationGuns(sku);
    unitLandedMxn = unitLandedMxn / Math.max(guns, 1);
  }
  const modeKey = modeLabel === "场站" ? "st" : modeLabel.toLowerCase();
  const nameZh =
    isStation || !variant
      ? sku.nameZh
      : `${sku.nameZh} · ${variant.nameZh}`;
  return {
    id: `rhythm-${sku.id}-${cfgId || modeKey}-${Date.now().toString(36).slice(-5)}`,
    skuId: sku.id,
    cardId: isStation ? "station" : `${sku.id}-${modeKey}`,
    nameZh,
    modeLabel,
    qty: q,
    unitLabel: isStation ? "枪" : sku.unitLabel || "台",
    unitLandedMxn,
    engineBookCcy: skuEngineBookCcy(sku),
    discountRate: disc,
  };
}

function DeployRhythmTrack(props: {
  orders: PurchaseOrder[];
  /** 货架 SKU（含配置档）；缺省用内置默认 */
  skus?: AssetSku[];
  /** 台数上限示意（如授信 65）；不强制截断，仅角标告警 */
  unitsCap?: number | null;
  /** 范围角标（通用名，如「当前授信包」；勿贴案例报告版本号） */
  scopeZh?: string | null;
  canUndo?: boolean;
  undoCount?: number;
  onUndo?: () => void;
  /** 每次改动前调用（父级压入订单快照） */
  onBeforeEdit?: () => void;
  onMutateOrders: (
    fn: (prev: PurchaseOrder[]) => PurchaseOrder[],
  ) => void;
}) {
  const theme = useHostTheme();
  /** V2：默认少留空白；旧 V1=6 会把轴顶到首批前半年空月 */
  const [padBefore, setPadBefore] = useCanvasState<number>(
    "deployRhythmPadBeforeV2",
    1,
  );
  const [padAfter, setPadAfter] = useCanvasState<number>(
    "deployRhythmPadAfterV2",
    6,
  );
  /** 拖拽态用本地 state，避免 useCanvasState 持久化导致 pointer 丢失后灰柱卡死 */
  const [dragId, setDragId] = useState<string>("");
  const [dragMode, setDragMode] = useState<"move" | "resize" | "">("");
  const [hoverYm, setHoverYm] = useState<string>("");
  const [previewUnits, setPreviewUnits] = useState<number>(0);
  /** 点选批次 → 下方数字改台数（多品类不必竖拖） */
  const [editOrderId, setEditOrderId] = useState<string>("");
  /** 台数输入草稿：清空不立刻写 0 */
  const [qtyDraftByKey, setQtyDraftByKey] = useState<Record<string, string>>(
    {},
  );
  /** 本批加车型：下拉选中的货架 skuId */
  const [addSkuId, setAddSkuId] = useState<string>("");
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const userScrolledRef = useRef(false);
  const lastAutoScrollKey = useRef("");

  const open = [...props.orders]
    .filter((o) => o.status !== "cancelled")
    /** 无车又无站的空壳批不画，避免「0 台第N次」占月 */
    .filter(
      (o) =>
        orderVehicleQtyTotal(o.lines) > 0 || orderStationGunTotal(o.lines) > 0,
    )
    .sort((a, b) => String(a.payDate).localeCompare(String(b.payDate)));

  const unitsOf = (o: PurchaseOrder) => orderVehicleQtyTotal(o.lines);
  const orderHasStation = (o: PurchaseOrder) =>
    orderStationGunTotal(o.lines) > 0;
  const totalUnits = open.reduce((s, o) => s + unitsOf(o), 0);
  const totalStations = open.filter(orderHasStation).length;
  const unitsCap =
    props.unitsCap != null && props.unitsCap > 0 ? props.unitsCap : null;
  const overCap = unitsCap != null && totalUnits > unitsCap + 1e-9;
  const yms = open.map((o) => payDateToYm(o.payDate)).filter(Boolean);
  const minYm = yms.length
    ? yms.reduce((a, b) => (a <= b ? a : b), yms[0]!)
    : "";
  const maxYm = yms.length
    ? yms.reduce((a, b) => (a >= b ? a : b), yms[0]!)
    : "";
  const baseYm = minYm;
  const lagMonthsHint = (() => {
    if (open.length < 2) return "单批 · 无错期";
    const lags = open.map((o) =>
      monthsBetweenPayDates(`${baseYm}-01`, o.payDate),
    );
    const maxLag = Math.max(...lags);
    const minLag = Math.min(...lags);
    if (maxLag <= 0) return "相对最早付款月 · 同月投放";
    return `相对最早 ${baseYm} · 错期 ${minLag === 0 ? 0 : minLag}–${maxLag} 月`;
  })();
  /** 在已有付款月两侧多留空月，可横滚/拖到更远年月 */
  const spanStart = minYm
    ? payDateToYm(
        addCalendarMonthsIso(`${minYm}-01`, -Math.max(0, padBefore)),
      ) || minYm
    : "";
  const spanEnd = maxYm
    ? payDateToYm(
        addCalendarMonthsIso(`${maxYm}-01`, Math.max(2, padAfter)),
      ) || maxYm
    : "";
  const months =
    spanStart && spanEnd ? listYmSpan(spanStart, spanEnd) : ([] as string[]);
  const nMo = Math.max(1, months.length);
  const maxU = Math.max(1, ...open.map(unitsOf), unitsCap || 0);

  const plotH = 110;
  const labelH = 28;
  const padL = 8;
  const padR = 8;
  /** 固定列宽，月数增多则加宽画布 → 外层横滚，不被压扁 */
  const colW = 48;
  const width = padL + padR + nMo * colW;
  const height = 22 + plotH + labelH;
  const baseY = 20 + plotH;

  /** 仅 scope/首批变化时滚到首批；用户横滚后不再抢焦点 */
  useEffect(() => {
    const el = scrollRef.current;
    if (!el || !minYm || !months.length) return;
    const key = `${minYm}|${props.scopeZh || ""}|${open.length}`;
    if (key !== lastAutoScrollKey.current) {
      userScrolledRef.current = false;
      lastAutoScrollKey.current = key;
    }
    if (userScrolledRef.current) return;
    const firstIdx = Math.max(0, months.indexOf(minYm));
    const target = Math.max(0, firstIdx - (padBefore > 0 ? 1 : 0)) * colW;
    const run = () => {
      el.scrollLeft = target;
    };
    run();
    const t = setTimeout(run, 50);
    return () => clearTimeout(t);
  }, [minYm, open.length, props.scopeZh, nMo, colW, padBefore, months]);

  /** 草稿停顿后提交；空串不提交（避免 ""→0） */
  useEffect(() => {
    const entries = Object.entries(qtyDraftByKey);
    if (!entries.length || !open.length) return;
    const t = setTimeout(() => {
      for (const [k, v] of entries) {
        const sep = k.indexOf("::");
        if (sep < 0) continue;
        const oid = k.slice(0, sep);
        const lid = k.slice(sep + 2);
        const trimmed = String(v).trim();
        if (trimmed === "" || !/^\d+$/.test(trimmed)) continue;
        const n = Math.round(Number(trimmed));
        if (!Number.isFinite(n)) continue;
        const o = open.find((x) => x.id === oid);
        if (!o) continue;
        const line = o.lines.find((l) => l.id === lid);
        if (!line || line.qty === n) continue;
        const nextQty = Math.max(0, Math.min(999, n));
        props.onBeforeEdit?.();
        props.onMutateOrders((prev) =>
          resequenceOrdersForRhythmScenario(
            prev.map((row) =>
              row.id === oid
                ? {
                    ...row,
                    lines: row.lines.map((l) =>
                      l.id === lid ? { ...l, qty: nextQty } : l,
                    ),
                  }
                : row,
            ),
            new Set([oid]),
          ),
        );
      }
    }, 500);
    return () => clearTimeout(t);
  }, [qtyDraftByKey]); // open/props 在超时回调内读最新闭包；勿把 open 数组放进 deps

  if (!open.length) return null;

  const ymAtClientX = (clientX: number, svgEl: SVGSVGElement) => {
    const rect = svgEl.getBoundingClientRect();
    /** 横滚后仍按 viewBox 坐标取月：用 client 相对 SVG 内容宽度 */
    const scaleX = width / Math.max(1, rect.width);
    const x = (clientX - rect.left) * scaleX;
    const idx = Math.max(
      0,
      Math.min(nMo - 1, Math.floor((x - padL) / colW)),
    );
    return months[idx] || "";
  };

  const unitsAtClientY = (clientY: number, svgEl: SVGSVGElement) => {
    const rect = svgEl.getBoundingClientRect();
    const y = ((clientY - rect.top) / Math.max(1, rect.height)) * height;
    const fromBottom = baseY - y;
    const u = Math.round((fromBottom / Math.max(1, plotH - 8)) * maxU);
    return Math.max(1, Math.min(999, u));
  };

  const commitMoveOrMerge = (orderId: string, ym: string) => {
    const o = open.find((x) => x.id === orderId);
    if (!o || !ym) return;
    const curYm = payDateToYm(o.payDate);
    const peers = open.filter(
      (x) => x.id !== orderId && payDateToYm(x.payDate) === ym,
    );
    if (peers.length > 0) {
      const into = peers[0]!;
      const fromCode = String(o.unitCode || o.label || orderId).slice(0, 24);
      const intoCode = String(into.unitCode || into.label || into.id).slice(
        0,
        24,
      );
      const ok =
        typeof window !== "undefined"
          ? window.confirm(
              `将「${fromCode}」合并进同月「${intoCode}」（${ym}）？\n被拖批次会取消；台数/车型并入目标批。可随后用「撤销」恢复。`,
            )
          : true;
      if (!ok) return;
      const touched = new Set([into.id, orderId]);
      props.onBeforeEdit?.();
      props.onMutateOrders((prev) =>
        resequenceOrdersForRhythmScenario(
          prev.map((row) => {
            if (row.id === into.id) {
              return {
                ...row,
                /** 保留原 status（含 paid）；不因合并偷偷改成待付款 */
                lines: mergeOrderLines(row.lines, o.lines),
                payDate: payDateMovedToYm(row.payDate, ym),
              };
            }
            if (row.id === orderId) {
              return { ...row, status: "cancelled" as const };
            }
            return row;
          }),
          touched,
        ),
      );
      return;
    }
    if (curYm === ym) return;
    const nextPay = payDateMovedToYm(o.payDate, ym);
    const delta = monthsBetweenPayDates(o.payDate, nextPay);
    const nextGo =
      o.goLiveDate && delta !== 0
        ? addCalendarMonthsIso(o.goLiveDate, delta)
        : undefined;
    props.onBeforeEdit?.();
    props.onMutateOrders((prev) =>
      resequenceOrdersForRhythmScenario(
        prev.map((row) =>
          row.id === orderId
            ? {
                ...row,
                payDate: nextPay,
                ...(nextGo ? { goLiveDate: nextGo } : {}),
              }
            : row,
        ),
        new Set([orderId]),
      ),
    );
  };

  const commitResize = (orderId: string, units: number) => {
    const o = open.find((x) => x.id === orderId);
    if (!o) return;
    const u = Math.max(1, Math.round(units));
    if (u === unitsOf(o)) return;
    props.onBeforeEdit?.();
    props.onMutateOrders((prev) =>
      resequenceOrdersForRhythmScenario(
        prev.map((row) =>
          row.id === orderId
            ? {
                ...row,
                lines: scaleOrderVehicleQty(row.lines, u),
              }
            : row,
        ),
        new Set([orderId]),
      ),
    );
  };

  /** 按行改台数/枪数；写 0 = 删该行；本批空了则取消订单 */
  const commitLineQty = (orderId: string, lineId: string, raw: string) => {
    const trimmed = String(raw).trim();
    if (trimmed === "") return;
    const n = Math.round(Number(String(raw).replace(/[^\d.-]/g, "")));
    if (!Number.isFinite(n)) return;
    const o = open.find((x) => x.id === orderId);
    if (!o) return;
    const line = o.lines.find((l) => l.id === lineId);
    if (!line) return;
    const nextQty = Math.max(0, Math.min(999, n));
    /** 已是 0 再点移除：仍要删行（兼容旧数据残留 0 台行） */
    if (nextQty === line.qty && nextQty > 0) return;
    const key = `${orderId}::${lineId}`;
    setQtyDraftByKey((prev) => {
      if (!(key in prev)) return prev;
      const next = { ...prev };
      delete next[key];
      return next;
    });
    props.onBeforeEdit?.();
    let cancelled = false;
    props.onMutateOrders((prev) =>
      resequenceOrdersForRhythmScenario(
        prev.map((row) => {
          if (row.id !== orderId) return row;
          const lines =
            nextQty <= 0
              ? row.lines.filter((l) => l.id !== lineId)
              : row.lines.map((l) =>
                  l.id === lineId ? { ...l, qty: nextQty } : l,
                );
          const empty =
            orderVehicleQtyTotal(lines) <= 0 &&
            orderStationGunTotal(lines) <= 0;
          if (empty) {
            cancelled = true;
            return { ...row, lines, status: "cancelled" as const };
          }
          return { ...row, lines };
        }),
        new Set([orderId]),
      ),
    );
    if (cancelled) setEditOrderId("");
  };

  /** 本批加采购项（车/两轮/场站 × 配置档；同名行则 +1） */
  const addVehicleSkuToOrder = (orderId: string, optionValue: string) => {
    const parsed = parseRhythmAddOption(optionValue);
    if (!parsed) return;
    const shelf = props.skus?.length ? props.skus : DEFAULT_ASSET_SKUS;
    const sku = shelf.find((s) => s.id === parsed.skuId);
    if (!sku) return;
    const o = open.find((x) => x.id === orderId);
    if (!o) return;
    const draft = buildRhythmOrderLineFromSku(sku, sku.kind === "station" ? rhythmStationGuns(sku) : skuMinQty(sku), parsed.configId);
    const hit = o.lines.find(
      (l) =>
        l.skuId === draft.skuId &&
        l.modeLabel === draft.modeLabel &&
        l.nameZh === draft.nameZh,
    );
    if (hit) {
      const bump =
        sku.kind === "station" ? rhythmStationGuns(sku) : 1;
      commitLineQty(orderId, hit.id, String(hit.qty + bump));
      return;
    }
    props.onBeforeEdit?.();
    props.onMutateOrders((prev) =>
      resequenceOrdersForRhythmScenario(
        prev.map((row) =>
          row.id === orderId
            ? { ...row, lines: [...row.lines, draft] }
            : row,
        ),
        new Set([orderId]),
      ),
    );
  };

  const unlockAllForScenario = () => {
    const paidIds = new Set(
      open.filter((o) => o.status === "paid").map((o) => o.id),
    );
    props.onBeforeEdit?.();
    props.onMutateOrders((prev) =>
      resequenceOrdersForRhythmScenario(
        prev.map((row) =>
          paidIds.has(row.id)
            ? { ...row, status: "pending_pay" as const }
            : row,
        ),
        paidIds.size ? paidIds : undefined,
      ),
    );
  };

  const splitIntoYm = (ym: string) => {
    const donors = open
      .filter((o) => unitsOf(o) >= 2)
      .sort((a, b) => unitsOf(b) - unitsOf(a));
    const src = donors[0];
    if (!src) return;
    if (payDateToYm(src.payDate) === ym) return;
    const total = unitsOf(src);
    const take = Math.max(1, Math.floor(total / 2));
    const remain = total - take;
    if (remain < 1) return;
    const nextPay = payDateMovedToYm(src.payDate, ym);
    const delta = monthsBetweenPayDates(src.payDate, nextPay);
    const nextGo = src.goLiveDate
      ? addCalendarMonthsIso(src.goLiveDate, delta)
      : nextPay;
    const newId = `po-split-${ym}-${Date.now().toString(36)}`;
    const maxSeq = open.reduce(
      (m, o) => Math.max(m, o.creditDrawdownSeq || 0),
      0,
    );
    props.onBeforeEdit?.();
    props.onMutateOrders((prev) => {
      const peers = prev;
      const cloned = normalizePurchaseOrder(
        {
          ...src,
          id: newId,
          label: `${src.label}·拆分`,
          payDate: nextPay,
          goLiveDate: nextGo,
          status: "pending_pay",
          lines: scaleOrderVehicleQtyNoStation(src.lines, take),
          creditDrawdownSeq: src.creditDrawdownPlanId
            ? maxSeq + 1
            : undefined,
          noteZh: `${src.noteZh || ""} · 自 ${src.unitCode} 拆至 ${ym}`.trim(),
        },
        peers,
      );
      return resequenceOrdersForRhythmScenario(
        [
          ...prev.map((row) =>
            row.id === src.id
              ? {
                  ...row,
                  lines: scaleOrderVehicleQty(row.lines, remain),
                }
              : row,
          ),
          cloned,
        ],
        new Set([src.id, newId]),
      );
    });
  };

  const clearDrag = () => {
    setDragId("");
    setDragMode("");
    setHoverYm("");
    setPreviewUnits(0);
  };

  const paidN = open.filter((o) => o.status === "paid").length;

  return (
    <Stack gap={6} style={{ minWidth: 0, width: "100%" }}>
      <Row gap={8} align="center" wrap>
        <Text size="small" weight="medium">
          投放节奏
        </Text>
        <HelpQ
          id="deploy-rhythm-track"
          label="节奏轨"
          tip="柱高=车辆台数，分色=T1/ES/UT/场站。点柱或下方胶囊选批后按品类填台数；横拖改月；右侧竖条粗调。拖到同月会先确认再合并。默认轴贴首批付款月（少露空月）。"
        />
        {props.scopeZh ? (
          <Text size="small" tone="secondary">
            {props.scopeZh}
          </Text>
        ) : null}
        <Text size="small" tone="tertiary">
          合计 {totalUnits} 台
          {totalStations > 0 ? ` · ${totalStations} 批含站` : ""}
          {unitsCap != null ? ` / 上限 ${unitsCap}` : ""} · {open.length} 批 ·{" "}
          {spanStart}→{spanEnd}
        </Text>
        <Text size="small" tone="tertiary">
          {lagMonthsHint}
        </Text>
        {overCap ? (
          <Text size="small" tone="secondary">
            已超上限
          </Text>
        ) : null}
        {paidN > 0 ? (
          <Pill
            size="sm"
            active={false}
            onClick={() => unlockAllForScenario()}
            title="将已付款批改为待付款，并按付款月重排第N次"
          >
            解锁·按未付款测算 ({paidN})
          </Pill>
        ) : (
          <Text size="small" tone="tertiary">
            均为未付款
          </Text>
        )}
        <Pill
          size="sm"
          active={false}
          onClick={() =>
            setPadBefore((n) => {
              /** 只改时间轴留白，不改付款日；到上限再点缩回 */
              if (n >= 24) return 1;
              return Math.min(24, n + 3);
            })
          }
          title={`时间轴向前多留空月（当前 −${padBefore} 月）；到上限再点缩回。不改投放时点。`}
        >
          ← 轴更早
        </Pill>
        <Pill
          size="sm"
          active={false}
          onClick={() =>
            setPadAfter((n) => {
              if (n >= 36) return 6;
              return Math.min(36, n + 3);
            })
          }
          title={`时间轴向后多留空月（当前 +${padAfter} 月）；到上限再点缩回。不改投放时点。`}
        >
          轴更晚 →
        </Pill>
        {padBefore > 1 || padAfter > 6 ? (
          <Pill
            size="sm"
            active={false}
            onClick={() => {
              setPadBefore(1);
              setPadAfter(6);
            }}
            title="时间轴留白恢复默认（不改付款日）"
          >
            轴复位
          </Pill>
        ) : null}
        <Text size="small" tone="tertiary">
          {spanStart}→{spanEnd} · 横滚可拖到空月（改时点请拖柱）
        </Text>
        {props.canUndo && props.onUndo ? (
          <Pill
            size="sm"
            active={false}
            onClick={() => props.onUndo?.()}
            title="撤销上一次节奏轨改动"
          >
            撤销{props.undoCount != null && props.undoCount > 0
              ? ` (${props.undoCount})`
              : ""}
          </Pill>
        ) : null}
        {dragMode === "move" && dragId ? (
          <Text size="small" tone="secondary">
            拖至 {hoverYm || "…"}
            {hoverYm &&
            open.some(
              (x) =>
                x.id !== dragId && payDateToYm(x.payDate) === hoverYm,
            )
              ? "（将合并）"
              : ""}
          </Text>
        ) : null}
        {dragMode === "resize" && dragId ? (
          <Text size="small" tone="secondary">
            台数 → {previewUnits || "…"}
          </Text>
        ) : null}
      </Row>
      <div
        ref={scrollRef}
        onScroll={() => {
          userScrolledRef.current = true;
        }}
        style={{
          width: "100%",
          overflowX: "auto",
          WebkitOverflowScrolling: "touch",
          borderTop: `1px solid ${theme.stroke.tertiary}`,
          borderBottom: `1px solid ${theme.stroke.tertiary}`,
          paddingTop: 6,
          paddingBottom: 4,
        }}
      >
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          style={{ display: "block", minWidth: width }}
          role="img"
          aria-label="投放节奏时间轴：横滚到更远年月；拖月、拖台数、点空月拆批"
          onPointerMove={(e) => {
            if (!dragId || !dragMode) return;
            const svg = e.currentTarget;
            if (dragMode === "move") {
              const ym = ymAtClientX(e.clientX, svg);
              if (ym && ym !== hoverYm) setHoverYm(ym);
            } else if (dragMode === "resize") {
              const u = unitsAtClientY(e.clientY, svg);
              if (u !== previewUnits) setPreviewUnits(u);
            }
          }}
          onPointerUp={(e) => {
            if (!dragId || !dragMode) return;
            const svg = e.currentTarget;
            const id = dragId;
            const mode = dragMode;
            const ym = hoverYm || ymAtClientX(e.clientX, svg);
            const u = previewUnits || unitsAtClientY(e.clientY, svg);
            clearDrag();
            try {
              svg.releasePointerCapture(e.pointerId);
            } catch {
              /* ignore */
            }
            if (mode === "move" && ym) commitMoveOrMerge(id, ym);
            if (mode === "resize") commitResize(id, u);
          }}
          onPointerCancel={() => {
            clearDrag();
          }}
          onLostPointerCapture={() => {
            clearDrag();
          }}
        >
          {months.map((ym, i) => {
            const x = padL + i * colW;
            const occupied = open.some((o) => payDateToYm(o.payDate) === ym);
            const isHover = hoverYm === ym && dragMode === "move";
            return (
              <g key={ym}>
                <rect
                  x={x}
                  y={20}
                  width={colW}
                  height={plotH}
                  fill={
                    isHover ? theme.fill.secondary : theme.fill.tertiary
                  }
                  opacity={isHover ? 0.55 : occupied ? 0.2 : 0.12}
                  style={{
                    cursor: occupied || dragId ? "default" : "copy",
                  }}
                  onClick={() => {
                    if (dragId) return;
                    if (occupied) return;
                    splitIntoYm(ym);
                  }}
                >
                  <title>
                    {occupied
                      ? ym
                      : `${ym} · 点击：从台数最大批拆一半入本月`}
                  </title>
                </rect>
                {!occupied ? (
                  <text
                    x={x + colW / 2}
                    y={20 + plotH / 2}
                    textAnchor="middle"
                    fill={theme.text.quaternary}
                    fontSize={9}
                    style={{ pointerEvents: "none" }}
                  >
                    +
                  </text>
                ) : null}
                <text
                  x={x + colW / 2}
                  y={height - 8}
                  textAnchor="middle"
                  fill={theme.text.tertiary}
                  fontSize={9}
                >
                  {ym.slice(2)}
                </text>
              </g>
            );
          })}
          {open.map((o) => {
            const ym = payDateToYm(o.payDate);
            const mi = months.indexOf(ym);
            if (mi < 0) return null;
            const uReal = unitsOf(o);
            const u =
              dragId === o.id && dragMode === "resize" && previewUnits > 0
                ? previewUnits
                : uReal;
            const mixRaw = orderRhythmMix(o.lines);
            const vehSegs = mixRaw.filter((m) => !m.station);
            const stSegs = mixRaw.filter((m) => m.station);
            const vehBase = Math.max(
              1,
              vehSegs.reduce((s, m) => s + m.qty, 0),
            );
            const vehScale = u / vehBase;
            const colorForRhythm = (id: string) => {
              const map: Record<string, string> = {
                es: theme.text.primary,
                ut: theme.category.purple,
                t1: theme.category.pink,
                station: theme.category.gray,
                two_wheel: theme.fill.quaternary,
              };
              return map[id] || theme.category.blue;
            };
            /** 车段按台数堆叠；场站固定顶带（不把枪数混进台高） */
            const vehHeights = vehSegs.map((m) =>
              Math.max(3, ((m.qty * vehScale) / maxU) * (plotH - 18)),
            );
            const stBand = stSegs.length > 0 ? 11 : 0;
            const h = Math.max(
              14,
              vehHeights.reduce((s, x) => s + x, 0) + stBand,
            );
            const sameYm = open.filter((x) => payDateToYm(x.payDate) === ym);
            const slot = sameYm.findIndex((x) => x.id === o.id);
            const slotN = Math.max(1, sameYm.length);
            const barW = Math.min(
              colW - 10,
              Math.max(14, Math.floor((colW - 8 - (slotN - 1) * 2) / slotN)),
            );
            const gap = 2;
            const totalBarsW = slotN * barW + (slotN - 1) * gap;
            const x0 =
              padL +
              mi * colW +
              (colW - totalBarsW) / 2 +
              slot * (barW + gap);
            const y = baseY - h;
            const wasPaid = o.status === "paid";
            const dragging = dragId === o.id;
            const withSt = stSegs.length > 0;
            const mixTip = orderRhythmMixTip(o.lines);
            const seq = creditDrawdownRankByPayDate(open, o.id);
            const label = seq > 0 ? `第${seq}次` : String(o.unitCode || "").slice(-4);
            const qtyInside = h >= 28;
            /** 台数在柱内或柱顶；「第N次」一律贴顶栏，避免高柱把标签压矮 */
            const qtyY = qtyInside
              ? y + h / 2 + 3
              : Math.min(baseY - 4, Math.max(22, y - 6));
            const labelY = slotN > 1 ? 11 + slot * 9 : 12;
            const selected = editOrderId === o.id;
            const startMove = (e: {
              preventDefault: () => void;
              stopPropagation: () => void;
              pointerId: number;
              currentTarget: SVGElement;
            }) => {
              e.preventDefault();
              e.stopPropagation();
              const svg = e.currentTarget.ownerSVGElement;
              if (svg) {
                try {
                  svg.setPointerCapture(e.pointerId);
                } catch {
                  /* ignore */
                }
              }
              setEditOrderId(o.id);
              setDragId(o.id);
              setDragMode("move");
              setHoverYm(ym);
              setPreviewUnits(0);
            };
            let stackY = baseY;
            const stackRects: {
              key: string;
              y: number;
              h: number;
              fill: string;
              tip: string;
            }[] = [];
            for (let si = 0; si < vehSegs.length; si++) {
              const seg = vehSegs[si]!;
              const segH = vehHeights[si]!;
              stackY -= segH;
              stackRects.push({
                key: `${o.id}-${seg.id}`,
                y: stackY,
                h: segH,
                fill:
                  dragging && dragMode === "move"
                    ? theme.category.orange
                    : colorForRhythm(seg.id),
                tip: `${seg.labelZh}×${Math.round(seg.qty * vehScale)}`,
              });
            }
            if (withSt) {
              stackY -= stBand;
              const guns = stSegs.reduce((s, m) => s + m.qty, 0);
              stackRects.push({
                key: `${o.id}-station`,
                y: stackY,
                h: stBand,
                fill:
                  dragging && dragMode === "move"
                    ? theme.category.orange
                    : theme.category.gray,
                tip: `场站 ${guns}枪`,
              });
            }
            return (
              <g
                key={o.id}
                style={{
                  opacity: dragging ? 0.9 : wasPaid ? 0.92 : 1,
                }}
              >
                <rect
                  x={x0}
                  y={20}
                  width={Math.max(8, barW - 8)}
                  height={plotH}
                  fill="transparent"
                  style={{ cursor: "grab" }}
                  onPointerDown={startMove}
                  onClick={(e) => {
                    e.stopPropagation();
                    setEditOrderId(o.id);
                  }}
                >
                  <title>
                    {`${o.unitCode || o.label} · ${ym} · ${u}台 · ${mixTip}${
                      wasPaid ? " · 已付款·可拖（点「解锁」才改状态）" : ""
                    } · 点选下方改台数；拖改月；右侧竖条粗调`}
                  </title>
                </rect>
                {selected ? (
                  <rect
                    x={x0 - 2}
                    y={Math.min(y, 20) - 2}
                    width={barW + 4}
                    height={Math.max(h, plotH) + 4}
                    fill="none"
                    stroke={theme.category.cyan}
                    strokeWidth={1.5}
                    rx={2}
                    style={{ pointerEvents: "none" }}
                  />
                ) : null}
                {stackRects.map((r) => (
                  <rect
                    key={r.key}
                    x={x0}
                    y={r.y}
                    width={barW}
                    height={Math.max(1, r.h)}
                    fill={r.fill}
                    stroke={theme.stroke.primary}
                    strokeWidth={0.5}
                    style={{ pointerEvents: "none" }}
                  >
                    <title>{r.tip}</title>
                  </rect>
                ))}
                {withSt ? (
                  <text
                    x={x0 + barW / 2}
                    y={y + 8}
                    textAnchor="middle"
                    fill={theme.bg.editor}
                    fontSize={8}
                    fontWeight={700}
                    style={{ pointerEvents: "none" }}
                  >
                    站
                  </text>
                ) : null}
                {/* 右侧竖条改台数，避免占满柱顶抢横拖 */}
                <rect
                  x={x0 + barW - 7}
                  y={20}
                  width={7}
                  height={plotH}
                  rx={2}
                  fill={
                    dragging && dragMode === "resize"
                      ? theme.category.cyan
                      : theme.fill.primary
                  }
                  opacity={dragging && dragMode === "resize" ? 0.95 : 0.35}
                  style={{ cursor: "ns-resize" }}
                  onPointerDown={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    const svg = e.currentTarget.ownerSVGElement;
                    if (svg) {
                      try {
                        svg.setPointerCapture(e.pointerId);
                      } catch {
                        /* ignore */
                      }
                    }
                    setDragId(o.id);
                    setDragMode("resize");
                    setPreviewUnits(uReal);
                    setHoverYm("");
                  }}
                >
                  <title>竖拖改车辆台数（场站不变）</title>
                </rect>
                <text
                  x={x0 + barW / 2}
                  y={qtyY}
                  textAnchor="middle"
                  fill={
                    qtyInside ? theme.bg.editor : theme.text.primary
                  }
                  fontSize={qtyInside ? 9 : 10}
                  fontWeight={600}
                  style={{ pointerEvents: "none" }}
                >
                  {u}
                </text>
                <text
                  x={x0 + barW / 2}
                  y={labelY}
                  textAnchor="middle"
                  fill={selected ? theme.category.cyan : theme.text.secondary}
                  fontSize={8}
                  style={{ pointerEvents: "none" }}
                >
                  {label}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
      <Row gap={8} align="center" wrap>
        {(
          [
            ["t1", "T1", theme.category.pink],
            ["es", "ES", theme.text.primary],
            ["ut", "UT", theme.category.purple],
            ["station", "场站", theme.category.gray],
            ["two_wheel", "两轮", theme.fill.quaternary],
          ] as const
        ).map(([id, zh, fill]) =>
          open.some((o) =>
            orderRhythmMix(o.lines).some((m) => m.id === id),
          ) ? (
            <span
              key={id}
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 4,
              }}
            >
              <span
                style={{
                  width: 8,
                  height: 8,
                  background: fill,
                  border: `1px solid ${theme.stroke.secondary}`,
                  flexShrink: 0,
                }}
              />
              <Text size="small" tone="tertiary">
                {zh}
              </Text>
            </span>
          ) : null,
        )}
      </Row>
      {(() => {
        const editId =
          editOrderId && open.some((o) => o.id === editOrderId)
            ? editOrderId
            : open[0]?.id || "";
        const editO = open.find((o) => o.id === editId);
        if (!editO) return null;
        const seq = creditDrawdownRankByPayDate(open, editO.id);
        const seqZh = seq > 0 ? `第${seq}次` : editO.unitCode || "本批";
        const vehLines = editO.lines.filter(
          (l) => orderLineAsset(l) !== "station",
        );
        const stLines = editO.lines.filter(
          (l) => orderLineAsset(l) === "station",
        );
        return (
          <Stack gap={6}>
            <Row gap={8} align="center" wrap>
              <Text size="small" weight="medium">
                改台数 · {seqZh}
              </Text>
              <Text size="small" tone="tertiary">
                {payDateToYm(editO.payDate)} · 点柱选批 · 框内改数即写入（0=移除）
              </Text>
              <Spacer />
              <Text size="small" tone="secondary">
                车合计 {unitsOf(editO)} 台
                {orderHasStation(editO) ? " · 含站" : ""}
              </Text>
            </Row>
            <Row gap={8} align="center" wrap>
              {open.map((o) => {
                const s = creditDrawdownRankByPayDate(open, o.id);
                const lab = s > 0 ? `第${s}次` : String(o.unitCode || "").slice(-6);
                return (
                  <Pill
                    key={o.id}
                    size="sm"
                    active={o.id === editId}
                    onClick={() => setEditOrderId(o.id)}
                  >
                    {lab} · {unitsOf(o)}
                  </Pill>
                );
              })}
            </Row>
            <Stack gap={4}>
              {vehLines.map((l) => {
                const dk = `${editO.id}::${l.id}`;
                const draft = qtyDraftByKey[dk];
                const applyRaw = (raw: string) =>
                  commitLineQty(editO.id, l.id, raw);
                return (
                <Row key={l.id} gap={8} align="center" wrap>
                  <Text
                    size="small"
                    tone="secondary"
                    style={{ flex: "0 0 120px", minWidth: 96 }}
                  >
                    {l.nameZh}
                  </Text>
                  <div style={{ width: 88 }}>
                    <TextInput
                      type="number"
                      value={draft ?? String(l.qty)}
                      onChange={(v) => {
                        setQtyDraftByKey((prev) => ({ ...prev, [dk]: v }));
                        /** 数字框上下箭头 / 键入完整数字：即时写入；清空不立刻清 0 */
                        if (String(v).trim() === "") return;
                        applyRaw(v);
                      }}
                      onBlur={() =>
                        applyRaw(draft ?? String(l.qty))
                      }
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          applyRaw(draft ?? String(l.qty));
                        }
                      }}
                    />
                  </div>
                  <Text size="small" tone="tertiary">
                    {l.unitLabel || "台"}
                  </Text>
                  <Button
                    variant="ghost"
                    title="从本批移除该采购项"
                    onClick={() => commitLineQty(editO.id, l.id, "0")}
                  >
                    移除
                  </Button>
                </Row>
                );
              })}
              {stLines.map((l) => {
                const dk = `${editO.id}::${l.id}`;
                const draft = qtyDraftByKey[dk];
                const applyRaw = (raw: string) =>
                  commitLineQty(editO.id, l.id, raw);
                return (
                <Row key={l.id} gap={8} align="center" wrap>
                  <Text
                    size="small"
                    tone="secondary"
                    style={{ flex: "0 0 120px", minWidth: 96 }}
                  >
                    {l.nameZh || "场站"}
                  </Text>
                  <div style={{ width: 88 }}>
                    <TextInput
                      type="number"
                      value={draft ?? String(l.qty)}
                      onChange={(v) => {
                        setQtyDraftByKey((prev) => ({ ...prev, [dk]: v }));
                        if (String(v).trim() === "") return;
                        applyRaw(v);
                      }}
                      onBlur={() =>
                        applyRaw(draft ?? String(l.qty))
                      }
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          applyRaw(draft ?? String(l.qty));
                        }
                      }}
                    />
                  </div>
                  <Text size="small" tone="tertiary">
                    枪
                  </Text>
                  <Button
                    variant="ghost"
                    title="从本批移除场站"
                    onClick={() => commitLineQty(editO.id, l.id, "0")}
                  >
                    移除
                  </Button>
                </Row>
                );
              })}
              {(() => {
                const shelf = props.skus?.length
                  ? props.skus
                  : DEFAULT_ASSET_SKUS;
                const addOpts = buildRhythmAddOptions(shelf, editO);
                if (addOpts.length === 0) return null;
                const pick =
                  addSkuId && addOpts.some((o) => o.value === addSkuId)
                    ? addSkuId
                    : addOpts[0]!.value;
                return (
                  <Row gap={8} align="center" wrap>
                    <Text
                      size="small"
                      tone="tertiary"
                      style={{ flex: "0 0 120px", minWidth: 96 }}
                    >
                      加采购项到本批
                    </Text>
                    <div style={{ minWidth: 220, flex: "1 1 240px" }}>
                      <Select
                        value={pick}
                        options={addOpts}
                        onChange={(v) => setAddSkuId(v)}
                      />
                    </div>
                    <Button
                      variant="ghost"
                      title="写入本批一行（车默认1台；场站按该档枪数）"
                      onClick={() => {
                        addVehicleSkuToOrder(editO.id, pick);
                        setAddSkuId("");
                      }}
                    >
                      加入
                    </Button>
                  </Row>
                );
              })()}
              {vehLines.length > 1 ? (
                <Row gap={8} align="center" wrap>
                  <Text
                    size="small"
                    tone="tertiary"
                    style={{ flex: "0 0 120px", minWidth: 96 }}
                  >
                    整批按比例缩放到
                  </Text>
                  <div style={{ width: 88 }}>
                    <TextInput
                      type="number"
                      value={String(unitsOf(editO))}
                      onChange={(v) => {
                        const n = Math.round(
                          Number(String(v).replace(/[^\d.-]/g, "")),
                        );
                        if (!Number.isFinite(n) || n < 1) return;
                        commitResize(editO.id, n);
                      }}
                    />
                  </div>
                  <Text size="small" tone="tertiary">
                    台（各车型同比）
                  </Text>
                </Row>
              ) : null}
            </Stack>
          </Stack>
        );
      })()}
      <Text size="small" tone="tertiary">
        柱高=车辆台数 · 分色=车型 · 顶灰「站」=该批挂场站 · 点柱或下方胶囊选批后填台数 ·
        填 0 /「移除」删采购项 ·「加采购项到本批」可选货架全部车型配置档与场站 ·
        横拖改月 · 右侧竖条粗调 · 已付款不自动改状态（需点解锁）。
      </Text>
    </Stack>
  );
}

/** 各订单单元月路径（供投放图按月下钻；与订单测算同源） */
function buildOrderMonthPathById(args: {
  orders: PurchaseOrder[];
  p: Premise;
  cards: VehicleCard[];
  cfBySku: Record<string, AssetCashflowConfig>;
  normalizedSkus: AssetSku[];
  cfgConfigBySku: Record<string, string>;
  invAssume: OrderInvAssumePatch;
  orderCfOverrideById?: Record<string, OrderCfOverride>;
  planInvAssume?: OrderInvAssumePatch;
  planDebt?: Pick<PlanOverride, "seniorDebt" | "mezzDebt">;
  planScenarioForce?: boolean;
  invResidualInPath: boolean;
  invResidualMode: "market" | "book";
  daeShift: DaeShift;
  goLiveStages: GoLiveStage[];
  discountAnn?: number;
}): Map<string, UnitCfPathPt[]> {
  const out = new Map<string, UnitCfPathPt[]>();
  for (const order of args.orders) {
    if (order.status === "cancelled") continue;
    const orderOverride = args.orderCfOverrideById?.[order.id];
    const agg = buildOrderAggregatedUnitCf({
      ...args,
      order,
      invAssume: {},
      orderOverride,
      planInvAssume: args.planInvAssume,
      planDebt: args.planDebt,
      planScenarioForce: args.planScenarioForce,
    });
    if (agg?.monthPath?.length) out.set(order.id, agg.monthPath);
  }
  return out;
}

/** 各订单残值（供计划叠加末月） */
function buildOrderResidualById(
  args: Parameters<typeof buildOrderMonthPathById>[0],
): Map<string, number> {
  const out = new Map<string, number>();
  for (const order of args.orders) {
    if (order.status === "cancelled") continue;
    const orderOverride = args.orderCfOverrideById?.[order.id];
    const agg = buildOrderAggregatedUnitCf({
      ...args,
      order,
      invAssume: {},
      orderOverride,
      planInvAssume: args.planInvAssume,
      planDebt: args.planDebt,
      planScenarioForce: args.planScenarioForce,
    });
    if (agg) out.set(order.id, agg.residualMxn || 0);
  }
  return out;
}


function irr(cashflows: number[]): number | null {
  if (cashflows.length < 2) return null;
  /** 去掉首尾近 0，避免空窗把牛顿法卡死 */
  let lo = 0;
  let hi = cashflows.length - 1;
  while (lo < cashflows.length && Math.abs(cashflows[lo]!) < 1e-9) lo += 1;
  while (hi > lo && Math.abs(cashflows[hi]!) < 1e-9) hi -= 1;
  const cf = cashflows.slice(lo, hi + 1);
  if (cf.length < 2) return null;
  let hasPos = false;
  let hasNeg = false;
  for (const c of cf) {
    if (c > 1e-9) hasPos = true;
    if (c < -1e-9) hasNeg = true;
  }
  if (!hasPos || !hasNeg) return null;

  const npvAt = (r: number): number => {
    if (!(r > -0.999999)) return NaN;
    let s = 0;
    let disc = 1;
    for (let t = 0; t < cf.length; t++) {
      s += cf[t]! * disc;
      disc /= 1 + r;
      if (!Number.isFinite(disc) || disc === 0) {
        /** 后续折现归零，剩余项可忽略 */
        break;
      }
    }
    return s;
  };

  /** 牛顿：多起点；导数用递推折现，避免长路径 pow 溢出 */
  const starts = [0.01, 0.05, 0.1, 0.2, 0.5, 1, -0.2, -0.5];
  for (const r0 of starts) {
    let r = r0;
    let ok = false;
    for (let i = 0; i < 60; i++) {
      let npv = 0;
      let d = 0;
      let disc = 1;
      for (let t = 0; t < cf.length; t++) {
        const c = cf[t]!;
        npv += c * disc;
        if (t > 0) d -= (t * c * disc) / (1 + r);
        disc /= 1 + r;
        if (!Number.isFinite(disc)) break;
      }
      if (!Number.isFinite(npv) || !Number.isFinite(d)) break;
      if (Math.abs(d) < 1e-14) break;
      const next = r - npv / d;
      if (!Number.isFinite(next)) break;
      if (next <= -0.999999) {
        r = -0.999;
        break;
      }
      if (next > 5) {
        r = 5;
        ok = true;
        break;
      }
      if (Math.abs(next - r) < 1e-9) {
        r = next;
        ok = true;
        break;
      }
      r = next;
    }
    if (ok && Number.isFinite(r) && r > -0.99 && r <= 5) {
      const n = npvAt(r);
      const scale = Math.max(1, ...cf.map((c) => Math.abs(c)));
      if (Number.isFinite(n) && Math.abs(n) < scale * 1e-3) return r;
      if (r >= 5 - 1e-9) return 5;
    }
  }

  /** 二分兜底：在 (-0.99, 5] 找变号 */
  const grid = [
    -0.99, -0.5, -0.2, -0.05, 0, 0.01, 0.05, 0.1, 0.2, 0.5, 1, 2, 3, 5,
  ];
  let a = grid[0]!;
  let fa = npvAt(a);
  for (let i = 1; i < grid.length; i++) {
    const b = grid[i]!;
    const fb = npvAt(b);
    if (!Number.isFinite(fa) || !Number.isFinite(fb)) {
      a = b;
      fa = fb;
      continue;
    }
    if (fa === 0) return a;
    if (fb === 0) return b;
    if (fa * fb < 0) {
      let loR = a;
      let hiR = b;
      let fLo = fa;
      for (let k = 0; k < 80; k++) {
        const mid = (loR + hiR) / 2;
        const fMid = npvAt(mid);
        if (!Number.isFinite(fMid)) break;
        if (Math.abs(fMid) < 1e-7 || (hiR - loR) / 2 < 1e-10) return mid;
        if (fLo * fMid <= 0) {
          hiR = mid;
        } else {
          loR = mid;
          fLo = fMid;
        }
      }
      return (loR + hiR) / 2;
    }
    a = b;
    fa = fb;
  }
  return null;
}

/** 月 IRR → 年化；极端杠杆权益封顶 ±100（10000%）供表/卡展示 */
function annualizeMonthIrr(rMo: number | null): number | null {
  if (rMo == null || !Number.isFinite(rMo) || rMo <= -0.99) return null;
  if (rMo > 5) return 100;
  const ann = Math.pow(1 + rMo, 12) - 1;
  if (!Number.isFinite(ann)) return 100;
  if (Math.abs(ann) > 100) return ann > 0 ? 100 : -100;
  return ann;
}

/** 月度现金流折现率：年化 → 月率 */
function monthDiscountRate(annualRate: number) {
  const a = Math.max(0, annualRate);
  return Math.pow(1 + a, 1 / 12) - 1;
}

/** 路径 NPV（月度序列，按年化折现） */
function npvAnnualOnMonths(cashflows: number[], annualRate: number): number {
  const rMo = monthDiscountRate(annualRate);
  let s = 0;
  for (let t = 0; t < cashflows.length; t++) {
    s += cashflows[t]! / Math.pow(1 + rMo, t);
  }
  return s;
}

/**
 * 静态回收期（月）：累计净现金流首次 ≥0 的期序（1-based）；
 * 含期初负投入与空窗，与路径条一致。
 */
function staticPaybackPeriod(cashflows: number[]): {
  months: number | null;
  index: number;
} {
  let cum = 0;
  for (let i = 0; i < cashflows.length; i++) {
    cum += cashflows[i]!;
    if (cum >= 0) return { months: i + 1, index: i };
  }
  return { months: null, index: -1 };
}

/**
 * 动态回收期（月）：折现后累计首次 ≥0 的期序（1-based）。
 */
function dynamicPaybackPeriod(
  cashflows: number[],
  annualRate: number,
): { months: number | null; index: number } {
  const rMo = monthDiscountRate(annualRate);
  let cum = 0;
  for (let i = 0; i < cashflows.length; i++) {
    cum += cashflows[i]! / Math.pow(1 + rMo, i);
    if (cum >= 0) return { months: i + 1, index: i };
  }
  return { months: null, index: -1 };
}

/** 单位路径回报基准折现默认（年化）；可被 useCanvasState unitCfDiscountAnn 覆盖 */
const UNIT_CF_DISCOUNT_ANN = 0.08;

function clampUnitCfDiscountAnn(r: number): number {
  if (!Number.isFinite(r)) return UNIT_CF_DISCOUNT_ANN;
  /** 夹到 0–50%，并量化到 0.1pp，避免 float 垃圾 */
  const clamped = Math.max(0, Math.min(0.5, r));
  return Math.round(clamped * 1000) / 1000;
}

/**
 * 测算币种示意国债 / 政府债年化收益率（非实时抓取）。
 * 键对齐展示币种 Currency（MXN/USD/IDR/CNY/HKD）。
 */
const TREASURY_YIELD_ANN: Record<string, number> = {
  USD: 0.042,
  MXN: 0.09,
  IDR: 0.068,
  CNY: 0.017,
  HKD: 0.038,
};
const TREASURY_YIELD_ASOF = "2026-08 · 示意";

function treasuryYieldAnnForCcy(ccy: string): number {
  const key = String(ccy || "USD").toUpperCase();
  return clampUnitCfDiscountAnn(
    TREASURY_YIELD_ANN[key] ?? TREASURY_YIELD_ANN.USD!,
  );
}

/** 折现率百分点展示（最多 1 位小数） */
function formatDiscountAnnPct(r: number): string {
  const pctPts = Math.round(clampUnitCfDiscountAnn(r) * 1000) / 10;
  return Number.isInteger(pctPts) ? String(pctPts) : pctPts.toFixed(1);
}

function pathYearsFromMonths(pathMonths: number): number {
  return Math.max(1, Math.round(Math.max(1, pathMonths) / 12));
}

function unitNpvTipZh(opts: {
  annualRate: number;
  pathMonths: number;
  opsYears: number;
  npvWindowMonths?: number;
}) {
  const rAnn = Math.round(opts.annualRate * 1000) / 10;
  const rMo =
    Math.round((Math.pow(1 + opts.annualRate, 1 / 12) - 1) * 1e6) / 1e6;
  const winMo = opts.npvWindowMonths ?? opts.pathMonths;
  return [
    `NPV（年化折现 ${rAnn}%）= Σ_{t=0…T} CF_t / (1+r_月)^t`,
    `r_月 = (1+${rAnn}%)^(1/12)−1 ≈ ${rMo}`,
    `CF_t：单车第 t 期净现金流（t=0 起含期初购置/保证金/空窗）`,
    `NPV 窗口 ${winMo} 期（约 ${pathYearsFromMonths(winMo)} 年；路径共 ${opts.pathMonths} 期·经营约 ${opts.opsYears} 年；超出则截断、不足用已有路径）`,
    `末月残值入参（若并入路径）：落地价 × min(物理残值率, 维保残值率, 市场残值率)`,
  ].join("\n");
}

/**
 * NPV 旁小号：年化折现 %（NPV 窗口已撤；序列跟随持有期路径）。
 * 国债一键始终跟投资计价货币 investCcy。
 */
function UnitNpvParamsInline(props: {
  discountAnn: number;
  onDiscountAnn: (r: number) => void;
  investCcy?: Currency;
}) {
  const pctShown =
    Math.round(clampUnitCfDiscountAnn(props.discountAnn) * 1000) / 10;
  const miniIn = {
    width: 40,
    fontSize: 11,
    padding: "1px 3px",
    minHeight: 18,
    lineHeight: 1.15,
  };
  return (
    <Stack gap={2} style={{ paddingTop: 2, minWidth: 0 }}>
      <Row gap={2} align="center">
        <Text
          size="small"
          tone="tertiary"
          title="年化折现率：用于 NPV 与动态回收期"
          style={{ whiteSpace: "nowrap" }}
        >
          年化折现
        </Text>
        <TextInput
          type="number"
          value={String(pctShown)}
          onChange={(v) => {
            const n = Number(v);
            if (!Number.isFinite(n)) return;
            props.onDiscountAnn(clampUnitCfDiscountAnn(n / 100));
          }}
          style={miniIn}
        />
        <Text size="small" tone="tertiary">
          %
        </Text>
        {props.investCcy ? (
          <Button
            variant="ghost"
            title={`示意国债/政府债 · ${props.investCcy} · ${TREASURY_YIELD_ASOF}`}
            onClick={() =>
              props.onDiscountAnn(treasuryYieldAnnForCcy(props.investCcy!))
            }
          >
            国债·{props.investCcy}
          </Button>
        ) : null}
      </Row>
    </Stack>
  );
}

/**
 * NPV Stat + 年化折现：固定占网格一格；值在上、控件在下。
 */
function UnitNpvStatWithParams(props: {
  tip?: string;
  value: string;
  label: string;
  tone?: "success" | "danger" | "warning" | "info";
  discountAnn: number;
  onDiscountAnn: (r: number) => void;
  investCcy?: Currency;
}) {
  return (
    <Stack gap={4} style={{ width: "100%", minWidth: 0 }}>
      <div
        title={props.tip}
        style={{
          cursor: props.tip ? "help" : undefined,
          minWidth: 0,
          overflow: "hidden",
        }}
      >
        <Stat value={props.value} label={props.label} tone={props.tone} />
      </div>
      <UnitNpvParamsInline
        discountAnn={props.discountAnn}
        onDiscountAnn={props.onDiscountAnn}
        investCcy={props.investCcy}
      />
    </Stack>
  );
}

function buildModel(
  p: Premise,
  nodes: InvestmentNode[],
  cards: VehicleCard[] = DEFAULT_VEHICLE_CARDS,
): {
  rows: YearRow[];
  assets: {
    id: string;
    name: string;
    spv: string;
    units: number;
    unitCostUsd: number;
    totalCostUsd: number;
    bodyShare: number;
    batteryShare: number;
    acctLife: number;
    physLife: number;
    maintLife: number;
    activeLife: number;
    residualRate: number;
    residualUsd: number;
    model: string;
    fields: { k: string; v: string }[];
  }[];
  relatedAnnual: number;
  equityOutlay: number;
  totals: {
    revenue: number;
    varCost: number;
    fixedCost: number;
    contribution: number;
    afterSiteFixed: number;
    netIncome: number;
    cashFlow: number;
    ebitda: number;
    depreciation: number;
    hqAlloc: number;
    endBook: number;
    endResidual: number;
    totalCapex: number;
  };
  cashIrr: number | null;
  /** 全自有资金假设下的无杠杆 IRR（资本层关闭或对照） */
  unleveredIrr: number | null;
  accountingRoi: number;
  capitalPlan: {
    includeDebt: boolean;
    lines: {
      key: InvestAsset;
      nameZh: string;
      units: number;
      unitCapex: number;
      totalCapex: number;
      financePct: number;
      financeRate: number;
      financeYears: number;
      debt: number;
      equity: number;
    }[];
    totalDebt: number;
    totalEquity: number;
    totalCapex: number;
  };
  schedule: {
    year: number;
    stationGuns: number;
    daeUnits: number;
    ltoUnits: number;
    rtoUnits: number;
    labels: string[];
  }[];
} {
  const fx = p.usdMxn;
  const yrs = Math.max(3, Math.min(12, Math.round(p.years)));
  const catalog = (cards.length ? cards : DEFAULT_VEHICLE_CARDS).map(
    normalizeCard,
  );
  const findCard = (node: InvestmentNode) => {
    const id = node.cardId || defaultCardId(node.asset);
    const mapped =
      id === "dae-aion-es"
        ? "aion-es-dae"
        : id === "lto-aion-ut"
          ? "aion-ut-lto"
          : id;
    return (
      catalog.find((c) => c.id === mapped || c.id === id) ||
      catalog.find((c) => modeToAsset(c.mode) === node.asset) ||
      catalog[0]
    );
  };
  const daeCardRaw =
    catalog.find((c) => c.mode === "DAE") || DEFAULT_VEHICLE_CARDS[0]!;
  const ltoCardRaw =
    catalog.find((c) => c.mode === "LTO") || DEFAULT_VEHICLE_CARDS[1]!;
  const rtoCardRaw =
    catalog.find((c) => c.mode === "RTO") || DEFAULT_VEHICLE_CARDS[2]!;
  const scenario = (p.cashflowScenario ?? "base") as CashflowScenario;
  const daeCard = applyScenarioToVehicleCard(daeCardRaw, scenario);
  const ltoCard = applyScenarioToVehicleCard(ltoCardRaw, scenario);
  const rtoCard = applyScenarioToVehicleCard(rtoCardRaw, scenario);
  const stScKnob = STATION_SCENARIO_KNOBS[scenario];

  const activeNodes = nodes.filter((n) => n.enabled && n.quantity > 0);

  const totalGuns = activeNodes
    .filter((n) => n.asset === "station")
    .reduce((s, n) => s + n.quantity, 0);
  const totalDae = activeNodes
    .filter((n) => n.asset === "dae")
    .reduce((s, n) => s + n.quantity, 0);
  const totalLto = activeNodes
    .filter((n) => n.asset === "lto")
    .reduce((s, n) => s + n.quantity, 0);
  const totalRto = activeNodes
    .filter((n) => n.asset === "rto")
    .reduce((s, n) => s + n.quantity, 0);

  const daeRef = Math.max(totalDae, 1);
  const ltoRef = Math.max(totalLto + totalRto, 1);

  const vehicleUnitUsd = (node: InvestmentNode) => {
    const card = findCard(node);
    return cardAmtToUsd(
      vehicleUnitMxn(card, node.discountRate ?? 0),
      card,
      fx,
    );
  };

  // —— 单位成本（车辆：标价×(1−折扣)+落地皮费；场站仍按枪）——
  const stationTotalCapex = mxnToUsd(
    p.chargerCapexMxn + p.stationFitoutMxn,
    fx,
  );
  const stationDeposit = mxnToUsd(p.stationDepositMxn, fx);
  const costPerGun = stationTotalCapex / Math.max(p.chargerGuns, 1);

  let daeFleet = 0;
  let ltoFleet = 0;
  let rtoFleet = 0;
  for (const n of activeNodes) {
    if (n.asset === "dae") daeFleet += vehicleUnitUsd(n) * n.quantity;
    if (n.asset === "lto") ltoFleet += vehicleUnitUsd(n) * n.quantity;
    if (n.asset === "rto") rtoFleet += vehicleUnitUsd(n) * n.quantity;
  }
  const daeUnitCost =
    totalDae > 0
      ? daeFleet / totalDae
      : cardAmtToUsd(vehicleUnitMxn(daeCard, 0), daeCard, fx);
  const ltoUnitCost =
    totalLto > 0
      ? ltoFleet / totalLto
      : cardAmtToUsd(vehicleUnitMxn(ltoCard, 0), ltoCard, fx);
  const rtoUnitCost =
    totalRto > 0
      ? rtoFleet / totalRto
      : cardAmtToUsd(vehicleUnitMxn(rtoCard, 0), rtoCard, fx);
  const chargerCost = costPerGun * totalGuns;

  const cardLife = (card: VehicleCard) => {
    if (p.residualMode === "physical") return card.physYears;
    if (p.residualMode === "maintenance") return card.maintYears;
    return card.acctYears;
  };
  const cardResR = (card: VehicleCard) => {
    if (p.residualMode === "physical")
      return Math.max(0, Math.min(1, card.physResidualRate ?? 0));
    if (p.residualMode === "maintenance")
      return Math.max(0, Math.min(1, card.maintResidualRate ?? 0));
    return Math.max(0, Math.min(1, card.residualRate ?? 0));
  };

  const cLife = lifeYears(p, "charger");
  const dLife = cardLife(daeCard);
  const lLife = cardLife(ltoCard);
  const cResR = residualRate(p, "charger");
  const dResR = cardResR(daeCard);
  const lResR = cardResR(ltoCard);

  const daeSoftMxn = softCostSumMxn(daeCard);
  const ltoSoftMxn = softCostSumMxn(ltoCard);

  const assets = [
    {
      id: "charger-station-1",
      name: "场站充电单元",
      spv: "场站项目公司",
      units: totalGuns,
      unitCostUsd: costPerGun,
      totalCostUsd: chargerCost,
      bodyShare: 1,
      batteryShare: 0,
      acctLife: p.chargerAcctYears,
      physLife: p.chargerPhysYears,
      maintLife: p.chargerMaintYears,
      activeLife: cLife,
      residualRate: cResR,
      residualUsd: chargerCost * cResR,
      model: `${p.powerKw}kW×枪 · 由投资节点汇总`,
      fields: [
        { k: "资产类型", v: "充电桩+装修一次性购置" },
        { k: "计划枪数", v: `${totalGuns}枪` },
        {
          k: "单枪建设成本",
          v: `${(costPerGun * fx).toFixed(2)} / ${costPerGun.toFixed(2)}`,
        },
        {
          k: "会计/物理/维保年限",
          v: `${p.chargerAcctYears}/${p.chargerPhysYears}/${p.chargerMaintYears}`,
        },
      ],
    },
    {
      id: daeCard.id,
      name: `${daeCard.nameZh}·DAE车队`,
      spv: "车辆项目公司",
      units: totalDae,
      unitCostUsd: daeUnitCost,
      totalCostUsd: daeFleet,
      bodyShare: daeCard.bodyShare,
      batteryShare: daeCard.batteryShare,
      acctLife: daeCard.acctYears,
      physLife: daeCard.physYears,
      maintLife: daeCard.maintYears,
      activeLife: dLife,
      residualRate: dResR,
      residualUsd: daeFleet * dResR,
      model: daeCard.model,
      fields: [
        { k: "资产卡", v: vehicleCardTitleZh(daeCard) },
        { k: "模式", v: OP_MODE_LABEL[daeCard.mode] },
        { k: "计划台数", v: `${totalDae}台（投资节点合计）` },
        {
          k: "标价（折扣前）",
          v: `${daeCard.listPriceMxn.toLocaleString()} MXN`,
        },
        {
          k: "落地皮费合计",
          v: `${daeSoftMxn.toLocaleString()} MXN`,
        },
        {
          k: "平均单车落地成本",
          v: `${(daeUnitCost * fx).toFixed(0)} MXN / ${daeUnitCost.toFixed(0)} USD`,
        },
        { k: "IPH", v: `${daeCard.iphMxn} MXN/h` },
      ],
    },
    {
      id: ltoCard.id,
      name: `${ltoCard.nameZh}·LTO车队`,
      spv: "车辆项目公司",
      units: totalLto,
      unitCostUsd: ltoUnitCost,
      totalCostUsd: ltoFleet,
      bodyShare: ltoCard.bodyShare,
      batteryShare: ltoCard.batteryShare,
      acctLife: ltoCard.acctYears,
      physLife: ltoCard.physYears,
      maintLife: ltoCard.maintYears,
      activeLife: lLife,
      residualRate: lResR,
      residualUsd: ltoFleet * lResR,
      model: ltoCard.model,
      fields: [
        { k: "资产卡", v: vehicleCardTitleZh(ltoCard) },
        { k: "模式", v: OP_MODE_LABEL[ltoCard.mode] },
        { k: "计划台数", v: `${totalLto}台（投资节点合计）` },
        {
          k: "标价（折扣前）",
          v: `${ltoCard.listPriceMxn.toLocaleString()} MXN`,
        },
        {
          k: "落地皮费合计",
          v: `${ltoSoftMxn.toLocaleString()} MXN`,
        },
        {
          k: "平均单车落地成本",
          v: `${(ltoUnitCost * fx).toFixed(0)} MXN / ${ltoUnitCost.toFixed(0)} USD`,
        },
        {
          k: "月租金·出租率",
          v: `${ltoCard.rentMonthMxn} MXN · ${Math.round(ltoCard.occupancy * 100)}%`,
        },
      ],
    },
    {
      id: rtoCard.id,
      name: `${rtoCard.nameZh}·RTO车队`,
      spv: "车辆项目公司",
      units: totalRto,
      unitCostUsd: rtoUnitCost,
      totalCostUsd: rtoFleet,
      bodyShare: rtoCard.bodyShare,
      batteryShare: rtoCard.batteryShare,
      acctLife: rtoCard.acctYears,
      physLife: rtoCard.physYears,
      maintLife: rtoCard.maintYears,
      activeLife: cardLife(rtoCard),
      residualRate: cardResR(rtoCard),
      residualUsd: rtoFleet * cardResR(rtoCard),
      model: rtoCard.model,
      fields: [
        { k: "资产卡", v: vehicleCardTitleZh(rtoCard) },
        { k: "模式", v: OP_MODE_LABEL[rtoCard.mode] },
        { k: "计划台数", v: `${totalRto}台（资产单元合计）` },
        {
          k: "标价（折扣前）",
          v: `${rtoCard.listPriceMxn.toLocaleString()} MXN`,
        },
        {
          k: "月租金·出租率",
          v: `${rtoCard.rentMonthMxn} MXN · ${Math.round(rtoCard.occupancy * 100)}%`,
        },
      ],
    },
  ];

  // 按年汇总投资节点
  const schedule = Array.from({ length: yrs }, (_, i) => {
    const year = i + 1;
    const yearNodes = activeNodes.filter((n) => n.year === year);
    return {
      year,
      stationGuns: yearNodes
        .filter((n) => n.asset === "station")
        .reduce((s, n) => s + n.quantity, 0),
      daeUnits: yearNodes
        .filter((n) => n.asset === "dae")
        .reduce((s, n) => s + n.quantity, 0),
      ltoUnits: yearNodes
        .filter((n) => n.asset === "lto")
        .reduce((s, n) => s + n.quantity, 0),
      rtoUnits: yearNodes
        .filter((n) => n.asset === "rto")
        .reduce((s, n) => s + n.quantity, 0),
      labels: yearNodes.map((n) => n.label),
    };
  });

  // 单位经济（单枪/单车/月，MXN）——场站率用来自情景常量包
  const gunKwhFull = p.powerKw * 24 * 30;
  const extKwh = gunKwhFull * stScKnob.externalUtil;
  const intKwh = gunKwhFull * stScKnob.internalUtil;
  const extRevGun = extKwh * stScKnob.externalPriceMxn;
  const intRevGun = intKwh * stScKnob.internalPriceMxn;
  const elecGun = (extKwh + intKwh) * p.lossFactor * stScKnob.elecCostMxn;
  const xiaojufen =
    extRevGun * stScKnob.xiaojufenPct +
    intRevGun * (stScKnob.xiaojufenInternalPct || 0);
  const payFee = extRevGun * p.payFeePct * (1 + p.vat);
  const varPerGun = elecGun + xiaojufen + payFee;

  const daeMonthGross =
    daeCard.iphMxn *
    daeCard.hoursDay *
    daeCard.daysWeek *
    (52 / 12) *
    daeCard.util *
    Math.max(1, daeCard.shiftsPerDay || 1);
  const daeMonthSubsidy = daeMonthGross * daeCard.subsidyPct;
  const daeMonthKm = 350 * daeCard.daysWeek * (52 / 12) * daeCard.util;
  const daeMonthKwh = (daeMonthKm / 100) * daeCard.kwhPer100;
  const daeChargeInternalShare = p.relatedEnabled ? p.priorityChargePct : 0;
  const daeElecMxn = DAE_SCENARIO_KNOBS[scenario].elecMxn;
  const daeChargeCost =
    daeMonthKwh *
    (daeChargeInternalShare * stScKnob.internalPriceMxn +
      (1 - daeChargeInternalShare) * daeElecMxn);
  const daeMonthOpexOne =
    daeCard.insuranceYrMxn / 12 +
    daeCard.maintMxn +
    daeCard.softMxn +
    daeCard.wearYrMxn / 12 +
    daeChargeCost +
    daeDriverMonthMxn(daeCard) +
    (daeCard.parkingMxn ?? 0) +
    (p.relatedEnabled ? p.relatedParkingMxn : 0);

  const ltoMonthRent =
    ltoCard.rentMonthMxn * ltoCard.occupancy * (1 - ltoCard.badDebt);
  const ltoMonthKm = 175 * 6 * (52 / 12) * ltoCard.occupancy;
  const ltoMonthKwh = (ltoMonthKm / 100) * ltoCard.kwhPer100;
  const ltoInternalKwh = p.relatedEnabled
    ? ltoMonthKwh * p.priorityChargePct
    : 0;
  const ltoMonthOpexOne =
    ltoCard.insuranceYrMxn / 12 + ltoCard.softMxn;

  const rtoMonthRent =
    rtoCard.rentMonthMxn * rtoCard.occupancy * (1 - rtoCard.badDebt);
  const rtoMonthKm = 175 * 6 * (52 / 12) * rtoCard.occupancy;
  const rtoMonthKwh = (rtoMonthKm / 100) * rtoCard.kwhPer100;
  const rtoInternalKwh = p.relatedEnabled
    ? rtoMonthKwh * p.priorityChargePct
    : 0;
  const rtoMonthOpexOne =
    rtoCard.insuranceYrMxn / 12 + rtoCard.softMxn;

  const hqFullAnnualUsd = mxnToUsd((p.hqMonthMxn ?? 640_891) * 12, fx);
  // 对齐原表：投放初期全额计入管理报表；稳定期按 hqSteadyPct（默认25%）
  const hqCostForYear = (y: number) => {
    if (!p.includeHq) return 0;
    const share = y <= 1 ? 1 : (p.hqSteadyPct ?? 0.25);
    return hqFullAnnualUsd * share;
  };

  // —— 资本配置（对应资产：充电桩 / DAE / LTO）——
  const useDebt = p.includeDebt !== false;
  const stFinPct = useDebt ? (p.stationFinancePct ?? 0.85) : 0;
  const stFinRate = p.stationFinanceRate ?? 0.14;
  const stFinYears = Math.max(1, Math.round(p.stationFinanceYears ?? 3));
  const daeFinPct = useDebt ? p.daeFinancePct : 0;
  const daeFinRate = p.daeFinanceRate;
  const daeFinYears = Math.max(1, Math.round(p.daeFinanceYears));
  const ltoFinPct = useDebt ? p.ltoFinancePct : 0;
  const ltoFinRate = p.ltoFinanceRate;
  const ltoFinYears = Math.max(1, Math.round(p.ltoFinanceYears));

  // 权益投入：各投资节点权益部分（1−融资比例）+ 场站押金
  let equityOutlay = stationDeposit;
  let totalAssetCapex = 0;
  for (const n of activeNodes) {
    if (n.asset === "station") {
      const c = costPerGun * n.quantity;
      totalAssetCapex += c;
      equityOutlay += c * (1 - stFinPct);
    } else if (n.asset === "dae") {
      const c = vehicleUnitUsd(n) * n.quantity;
      totalAssetCapex += c;
      equityOutlay += c * (1 - daeFinPct);
    } else if (n.asset === "rto") {
      const c = vehicleUnitUsd(n) * n.quantity;
      totalAssetCapex += c;
      equityOutlay += c * (1 - ltoFinPct); // RTO 暂共用 LTO 资本条款，可在资本配置拆分
    } else {
      const c = vehicleUnitUsd(n) * n.quantity;
      totalAssetCapex += c;
      equityOutlay += c * (1 - ltoFinPct);
    }
  }
  const fullEquityOutlay = stationDeposit + totalAssetCapex;

  const capitalPlan = {
    includeDebt: useDebt,
    lines: [
      {
        key: "station" as InvestAsset,
        nameZh: "充电桩",
        units: totalGuns,
        unitCapex: costPerGun,
        totalCapex: costPerGun * totalGuns,
        financePct: stFinPct,
        financeRate: stFinRate,
        financeYears: stFinYears,
        debt: costPerGun * totalGuns * stFinPct,
        equity: costPerGun * totalGuns * (1 - stFinPct),
      },
      {
        key: "dae" as InvestAsset,
        nameZh: daeCard.nameZh,
        units: totalDae,
        unitCapex: daeUnitCost,
        totalCapex: daeFleet,
        financePct: daeFinPct,
        financeRate: daeFinRate,
        financeYears: daeFinYears,
        debt: daeFleet * daeFinPct,
        equity: daeFleet * (1 - daeFinPct),
      },
      {
        key: "lto" as InvestAsset,
        nameZh: ltoCard.nameZh,
        units: totalLto,
        unitCapex: ltoUnitCost,
        totalCapex: ltoFleet,
        financePct: ltoFinPct,
        financeRate: ltoFinRate,
        financeYears: ltoFinYears,
        debt: ltoFleet * ltoFinPct,
        equity: ltoFleet * (1 - ltoFinPct),
      },
      {
        key: "rto" as InvestAsset,
        nameZh: `${rtoCard.nameZh}·RTO`,
        units: totalRto,
        unitCapex: rtoUnitCost,
        totalCapex: rtoFleet,
        financePct: ltoFinPct,
        financeRate: ltoFinRate,
        financeYears: ltoFinYears,
        debt: rtoFleet * ltoFinPct,
        equity: rtoFleet * (1 - ltoFinPct),
      },
    ].filter((l) => l.units > 0),
    totalDebt:
      costPerGun * totalGuns * stFinPct +
      daeFleet * daeFinPct +
      ltoFleet * ltoFinPct +
      rtoFleet * ltoFinPct,
    totalEquity: equityOutlay,
    totalCapex: totalAssetCapex + stationDeposit,
  };

  // 分年折旧基数：按投放节点实际落地成本入账
  type Vintage = { year: number; cost: number; life: number; resR: number };
  const vintages: Vintage[] = [];
  for (const n of activeNodes) {
    if (n.asset === "station") {
      vintages.push({
        year: n.year,
        cost: costPerGun * n.quantity,
        life: cLife,
        resR: cResR,
      });
    } else if (n.asset === "dae") {
      vintages.push({
        year: n.year,
        cost: vehicleUnitUsd(n) * n.quantity,
        life: dLife,
        resR: dResR,
      });
    } else if (n.asset === "rto") {
      vintages.push({
        year: n.year,
        cost: vehicleUnitUsd(n) * n.quantity,
        life: cardLife(rtoCard),
        resR: cardResR(rtoCard),
      });
    } else {
      vintages.push({
        year: n.year,
        cost: vehicleUnitUsd(n) * n.quantity,
        life: lLife,
        resR: lResR,
      });
    }
  }

  const rows: YearRow[] = [];
  let gunsOnline = 0;
  let daeOnline = 0;
  let ltoOnline = 0;
  let rtoOnline = 0;
  let bookValue = 0;
  let loanSt = 0;
  let loanDae = 0;
  let loanLto = 0;
  let loanRto = 0;
  let cumNi = 0;
  let cumulativeCF = 0;
  let cash = equityOutlay; // 期初注入权益
  let stationBuilt = false;

  const relatedAnnualMxn =
    (daeMonthKwh * daeChargeInternalShare * daeRef +
      (ltoInternalKwh * Math.max(totalLto, 1) +
        rtoInternalKwh * Math.max(totalRto, 1)) /
        Math.max(totalLto + totalRto, 1) *
        ltoRef) *
    p.internalPriceMxn *
    12;

  for (let y = 1; y <= yrs; y++) {
    const sch = schedule[y - 1];
    const openingCash = cash;

    // —— 本年投资（Capex 与资本层借款分开；车辆按节点折扣+皮费）——
    let stationCapex = 0;
    let vehicleCapex = 0;
    let financingInStation = 0;
    let financingInDae = 0;
    let financingInLto = 0;
    let stationBookAdd = 0;
    const yearNodes = activeNodes.filter((n) => n.year === y);
    for (const n of yearNodes) {
      if (n.asset === "station") {
        const gunCost = costPerGun * n.quantity;
        stationCapex += gunCost;
        stationBookAdd += gunCost;
        if (!stationBuilt) {
          stationCapex += stationDeposit;
          stationBuilt = true;
        }
        financingInStation += gunCost * stFinPct;
      } else if (n.asset === "dae") {
        const c = vehicleUnitUsd(n) * n.quantity;
        vehicleCapex += c;
        financingInDae += c * daeFinPct;
      } else {
        const c = vehicleUnitUsd(n) * n.quantity;
        vehicleCapex += c;
        financingInLto += c * ltoFinPct;
      }
    }
    const financingIn =
      financingInStation + financingInDae + financingInLto;
    const capex = stationCapex + vehicleCapex;
    loanSt += financingInStation;
    loanDae += financingInDae;
    loanLto += financingInLto;

    gunsOnline += sch.stationGuns;
    daeOnline += sch.daeUnits;
    ltoOnline += sch.ltoUnits;
    rtoOnline += sch.rtoUnits ?? 0;
    bookValue += stationBookAdd + vehicleCapex;

    // —— 运营（稳态规模 × 达产负荷；情景已写入单位常量）——
    const mgmt = p.mgmtCapability ?? 0.7;

    const blendLoad = (asset: InvestAsset, cardRampY: number, start: number) => {
      let w = 0;
      let q = 0;
      for (const n of activeNodes) {
        if (n.asset !== asset || n.year > y) continue;
        const age = y - n.year + 1;
        const load = rampLoadAtAge(age, cardRampY, start, mgmt);
        w += load * n.quantity;
        q += n.quantity;
      }
      return q > 0 ? w / q : 1;
    };

    const daeRamp = blendLoad(
      "dae",
      daeCard.rampYears ?? 2,
      daeCard.rampStartLoad ?? 0.55,
    );
    const ltoRamp = blendLoad(
      "lto",
      ltoCard.rampYears ?? 2,
      ltoCard.rampStartLoad ?? 0.6,
    );
    const rtoRamp = blendLoad(
      "rto",
      rtoCard.rampYears ?? 2,
      rtoCard.rampStartLoad ?? 0.5,
    );
    const stRamp = blendLoad(
      "station",
      p.stationRampYears ?? 2,
      p.stationRampStartLoad ?? 0.5,
    );

    const daeFactor = daeRamp;
    const ltoFactor = ltoRamp;
    const rtoFactor = rtoRamp;
    const stFactor = stRamp;

    const fleetQ = daeOnline + ltoOnline + rtoOnline + gunsOnline;
    const rampLoad =
      fleetQ > 0
        ? (daeRamp * daeOnline +
            ltoRamp * ltoOnline +
            rtoRamp * rtoOnline +
            stRamp * gunsOnline) /
          fleetQ
        : 1;
    /** 情景已写入单位常量（applyScenario*），此处不再二次乘倍率 */
    const scenarioFactor = scenarioCashMul(scenario);

    const daeRevSteady = cardAmtToUsd(
      (daeMonthGross + daeMonthSubsidy) * 12 * daeOnline,
      daeCard,
      fx,
    );
    const ltoRevSteady = cardAmtToUsd(
      ltoMonthRent * 12 * ltoOnline,
      ltoCard,
      fx,
    );
    const rtoRevSteady = cardAmtToUsd(
      rtoMonthRent * 12 * rtoOnline,
      rtoCard,
      fx,
    );

    const stationExtSteady = mxnToUsd(gunsOnline * extRevGun * 12, fx);
    const stationIntUtilSteady = mxnToUsd(gunsOnline * intRevGun * 12, fx);
    const relatedChargeFromVehicles = mxnToUsd(
      (daeMonthKwh * daeChargeInternalShare * daeOnline +
        ltoInternalKwh * ltoOnline +
        rtoInternalKwh * rtoOnline) *
        p.internalPriceMxn *
        12,
      fx,
    );
    const stationIntSteady = p.relatedEnabled
      ? Math.max(stationIntUtilSteady, relatedChargeFromVehicles)
      : stationIntUtilSteady;
    const stationPark = mxnToUsd(
      (p.parkingRentMxn * (gunsOnline > 0 ? 1 : 0) +
        (p.relatedEnabled ? p.relatedParkingMxn * daeOnline : 0)) *
        12,
      fx,
    );
    /** Excel：投资后满 6 个月才有衍生 → 首年约半年、次年起满年 */
    const stationAnc = mxnToUsd(
      p.ancillaryMxn *
        12 *
        (gunsOnline > 0 ? (y >= 2 ? 1 : y === 1 ? 0.5 : 0) : 0),
      fx,
    );

    const daeRev = daeRevSteady * daeFactor;
    const ltoRev = ltoRevSteady * ltoFactor;
    const rtoRev = rtoRevSteady * rtoFactor;
    let stationRev =
      (stationExtSteady + stationIntSteady) * stFactor +
      stationPark +
      stationAnc;
    let relatedCharge = stationIntSteady * stFactor;
    let eliminated = 0;

    // 可变成本：随达产部分爬坡；保险等半固定
    const daeOpexSteady = cardAmtToUsd(
      daeMonthOpexOne * 12 * daeOnline,
      daeCard,
      fx,
    );
    const ltoOpexSteady = cardAmtToUsd(
      ltoMonthOpexOne * 12 * ltoOnline,
      ltoCard,
      fx,
    );
    const rtoOpexSteady = cardAmtToUsd(
      rtoMonthOpexOne * 12 * rtoOnline,
      rtoCard,
      fx,
    );
    const stationVarSteady = mxnToUsd(gunsOnline * varPerGun * 12, fx);
    const daeOpex = daeOpexSteady * (0.35 + 0.65 * daeFactor);
    const ltoOpex = ltoOpexSteady * (0.45 + 0.55 * ltoFactor);
    const rtoOpex = rtoOpexSteady * (0.45 + 0.55 * rtoFactor);
    const stationVar = stationVarSteady * (0.4 + 0.6 * stFactor);
    const stationFixed = mxnToUsd(
      (gunsOnline > 0 ? p.stationRentMxn + p.opexStationMxn : 0) * 12,
      fx,
    );

    if (p.eliminateInternal && p.relatedEnabled) {
      const vehicleInternalCharge = relatedChargeFromVehicles * Math.min(daeFactor, ltoFactor || daeFactor);
      const elim = Math.min(relatedCharge, vehicleInternalCharge);
      stationRev -= elim;
      eliminated = elim;
    }

    const vehicleRev = daeRev + ltoRev + rtoRev;
    const steadyRevenue =
      daeRevSteady +
      ltoRevSteady +
      rtoRevSteady +
      stationExtSteady +
      stationIntSteady +
      stationPark +
      stationAnc;
    const revenue = stationRev + vehicleRev;

    // 折旧：各 vintage 自投放年起直线
    let dep = 0;
    for (const v of vintages) {
      const age = y - v.year + 1;
      if (age >= 1 && age <= v.life) {
        dep += (v.cost * (1 - v.resR)) / Math.max(v.life, 1);
      }
    }

    // —— 资本层：按资产配置计息与到期还本 ——
    const interestStation = loanSt * stFinRate;
    const interestDae = loanDae * daeFinRate;
    const interestLto = loanLto * ltoFinRate;
    const interest = interestStation + interestDae + interestLto;

    let financingOutStation = 0;
    let financingOutDae = 0;
    let financingOutLto = 0;
    for (const n of activeNodes) {
      if (n.asset === "station" && y === n.year + stFinYears - 1) {
        financingOutStation += costPerGun * n.quantity * stFinPct;
      }
      if (n.asset === "dae" && y === n.year + daeFinYears - 1) {
        financingOutDae += vehicleUnitUsd(n) * n.quantity * daeFinPct;
      }
      if (n.asset === "lto" && y === n.year + ltoFinYears - 1) {
        financingOutLto += vehicleUnitUsd(n) * n.quantity * ltoFinPct;
      }
      if (n.asset === "rto" && y === n.year + ltoFinYears - 1) {
        financingOutLto += vehicleUnitUsd(n) * n.quantity * ltoFinPct;
      }
    }
    financingOutStation = Math.min(financingOutStation, loanSt);
    financingOutDae = Math.min(financingOutDae, loanDae);
    financingOutLto = Math.min(financingOutLto, loanLto);
    loanSt -= financingOutStation;
    loanDae -= financingOutDae;
    loanLto -= financingOutLto;
    const financingOut =
      financingOutStation + financingOutDae + financingOutLto;

    // —— 成本分层 ——
    // 可变：随枪/车规模（电费佣金、司机、充电、维保保险等）
    let varCost = stationVar + daeOpex + ltoOpex + rtoOpex;
    // 固定：场站租金+运维（开站即发生，不随单车边际）
    const fixedCost = stationFixed;
    const hqAlloc =
      gunsOnline + daeOnline + ltoOnline + rtoOnline > 0
        ? hqCostForYear(y)
        : 0;

    if (p.eliminateInternal && p.relatedEnabled) {
      varCost -= eliminated; // 内部充电在合并口径从可变成本抵消
    }

    const contribution = revenue - varCost;
    const afterSiteFixed = contribution - fixedCost;
    let opex = varCost + fixedCost + hqAlloc;

    const ebitda = revenue - opex; // = afterSiteFixed - hqAlloc
    const ebit = ebitda - dep;
    // 残值：vintage 到期年回收
    let residualIn = 0;
    for (const v of vintages) {
      if (y === v.year + v.life - 1) {
        residualIn += v.cost * v.resR;
      }
    }

    const interestIncome = Math.max(0, cash) * p.depositRate;
    const unleveredPretax = ebit + interestIncome;
    const unleveredTax =
      unleveredPretax > 0 ? unleveredPretax * p.cit : 0;
    const unleveredNi = unleveredPretax - unleveredTax;
    const pretax = ebit - interest + interestIncome;
    const tax = pretax > 0 ? pretax * p.cit : 0;
    const netIncome = pretax - tax;
    cumNi += netIncome;

    const hqOnRevenue = revenue > 0 ? hqAlloc / revenue : 0;
    const hqOnContribution = contribution > 0 ? hqAlloc / contribution : 0;

    const operatingCF = netIncome + dep + interestIncome;
    const unleveredOpCf = unleveredNi + dep + interestIncome;
    const cashFlow =
      operatingCF - capex + financingIn - financingOut + residualIn;
    cumulativeCF += cashFlow;
    cash = openingCash + cashFlow;

    bookValue = Math.max(0, bookValue - dep);
    // 残值回收时减少账面
    bookValue = Math.max(0, bookValue - residualIn);

    const rLife = cardLife(rtoCard);
    const rResR = cardResR(rtoCard);
    const marketResidual =
      gunsOnline * costPerGun * Math.max(cResR, 1 - ((1 - cResR) * Math.min(y, cLife)) / cLife) +
      daeOnline * daeUnitCost * Math.max(dResR, 1 - ((1 - dResR) * Math.min(y, dLife)) / dLife) +
      ltoOnline * ltoUnitCost * Math.max(lResR, 1 - ((1 - lResR) * Math.min(y, lLife)) / lLife) +
      rtoOnline * rtoUnitCost * Math.max(rResR, 1 - ((1 - rResR) * Math.min(y, rLife)) / rLife);

    rows.push({
      year: y,
      label: `${PLAN_BASE_YEAR + y - 1}年`,
      gunsOnline,
      daeOnline,
      ltoOnline,
      bookValue,
      marketResidual,
      revenue,
      varCost,
      fixedCost,
      contribution,
      afterSiteFixed,
      rampLoad,
      scenarioFactor,
      steadyRevenue,
      opex,
      hqAlloc,
      hqOnRevenue,
      hqOnContribution,
      depreciation: dep,
      interest,
      interestIncome,
      ebitda,
      ebit,
      pretax,
      tax,
      netIncome,
      unleveredNi,
      financingInStation,
      financingInDae,
      financingInLto,
      financingOutStation,
      financingOutDae,
      financingOutLto,
      interestStation,
      interestDae,
      interestLto,
      loanBalStation: loanSt,
      loanBalDae: loanDae,
      loanBalLto: loanLto,
      openingCash,
      operatingCF,
      unleveredOpCf,
      stationCapex,
      vehicleCapex,
      capex,
      financingIn,
      financingOut,
      residualIn,
      cashFlow,
      cumulativeCF,
      closingCash: cash,
      stationRev,
      vehicleRev,
      relatedCharge,
      eliminated,
      nodeLabels: sch.labels,
    });
  }

  const cfSeries = [-equityOutlay, ...rows.map((r) => r.cashFlow)];
  const cashIrr = irr(cfSeries);
  const unleveredCfSeries = [
    -fullEquityOutlay,
    ...rows.map((r) => r.unleveredOpCf - r.capex + r.residualIn),
  ];
  const unleveredIrr = irr(unleveredCfSeries);
  const totals = {
    revenue: rows.reduce((s, r) => s + r.revenue, 0),
    varCost: rows.reduce((s, r) => s + r.varCost, 0),
    fixedCost: rows.reduce((s, r) => s + r.fixedCost, 0),
    contribution: rows.reduce((s, r) => s + r.contribution, 0),
    afterSiteFixed: rows.reduce((s, r) => s + r.afterSiteFixed, 0),
    netIncome: rows.reduce((s, r) => s + r.netIncome, 0),
    cashFlow: rows.reduce((s, r) => s + r.cashFlow, 0),
    ebitda: rows.reduce((s, r) => s + r.ebitda, 0),
    depreciation: rows.reduce((s, r) => s + r.depreciation, 0),
    hqAlloc: rows.reduce((s, r) => s + r.hqAlloc, 0),
    endBook: rows[rows.length - 1]?.bookValue ?? 0,
    endResidual: rows[rows.length - 1]?.marketResidual ?? 0,
    totalCapex: rows.reduce((s, r) => s + r.capex, 0),
  };
  const accountingRoi = equityOutlay > 0 ? totals.netIncome / equityOutlay : 0;

  return {
    rows,
    assets,
    relatedAnnual: mxnToUsd(relatedAnnualMxn, fx),
    equityOutlay,
    totals,
    cashIrr,
    unleveredIrr,
    accountingRoi,
    capitalPlan,
    schedule,
  };
}

function fmt(n: number, digits = 0) {
  if (!Number.isFinite(n)) return "—";
  return n.toLocaleString("zh-CN", {
    maximumFractionDigits: digits,
    minimumFractionDigits: digits,
  });
}

function pct(n: number | null, digits = 1) {
  if (n == null || !Number.isFinite(n)) return "—";
  /** 比率异常（如 IRR 溢出）勿输出科学计数 */
  if (Math.abs(n) > 20) return "—";
  return `${(n * 100).toFixed(digits)}%`;
}

/**
 * 年化 IRR 展示：高杠杆权益常 >2000%，勿走 pct 的「>20 藏成 —」。
 * 与 annualizeMonthIrr 封顶 ±100（10000%）对齐。
 */
function irrPctZh(n: number | null, digits = 1) {
  if (n == null || !Number.isFinite(n)) return "—";
  if (n >= 99.5) return "≥10000%（封顶）";
  if (n <= -99.5) return "≤-10000%（封顶）";
  if (Math.abs(n) > 20) return `${(n * 100).toFixed(0)}%`;
  return `${(n * 100).toFixed(digits)}%`;
}

type Currency = "MXN" | "USD" | "IDR" | "CNY" | "HKD";

function skuPriceCcyOf(sku: AssetSku): PriceCcy {
  return sku.priceCcy === "IDR" ? "IDR" : "MXN";
}

/** 价位本地币对应的引擎账面：IDR→USD 本位；MXN 保持本地账 */
function skuEngineBookCcy(sku: AssetSku): EngineBookCcy {
  return skuPriceCcyOf(sku) === "IDR" ? "USD" : "MXN";
}

/** 价位币种面值 → 投资本位 USD */
function localToUsd(
  local: number,
  priceCcy: PriceCcy,
  usdMxn: number,
  usdIdr: number,
): number {
  if (!Number.isFinite(local)) return NaN;
  if (priceCcy === "IDR") return local / Math.max(usdIdr, 1e-9);
  return local / Math.max(usdMxn, 1e-9);
}

/** SKU 价位面值 → 投资本位 USD（入引擎主路径） */
function skuLocalToUsd(
  local: number,
  sku: AssetSku,
  usdMxn: number,
  usdIdr: number,
): number {
  return localToUsd(local, skuPriceCcyOf(sku), usdMxn, usdIdr);
}

/**
 * SKU 价位面值 → 引擎账面金额。
 * MXN 价位：仍记 MXN；IDR 价位：折 USD 后记入（字段名可仍为 *Mxn，语义见 engineBookCcy）。
 */
function skuLocalToEngineBook(
  local: number,
  sku: AssetSku,
  usdMxn: number,
  usdIdr: number,
): number {
  if (skuPriceCcyOf(sku) === "MXN") return local;
  return skuLocalToUsd(local, sku, usdMxn, usdIdr);
}

/** 引擎账面 → 投资本位 USD */
function bookToUsd(
  amount: number,
  book: EngineBookCcy,
  usdMxn: number,
): number {
  if (!Number.isFinite(amount)) return NaN;
  if (book === "USD") return amount;
  return amount / Math.max(usdMxn, 1e-9);
}

/** 1 单位币种折合多少 USD */
function usdPerCcy(
  c: Currency,
  usdMxn: number,
  usdIdr: number,
  cnyMxn: number,
  usdHkd: number,
): number {
  if (c === "USD") return 1;
  if (c === "MXN") return 1 / Math.max(usdMxn, 1e-9);
  if (c === "IDR") return 1 / Math.max(usdIdr, 1e-9);
  if (c === "CNY") return Math.max(cnyMxn, 1e-9) / Math.max(usdMxn, 1e-9);
  return 1 / Math.max(usdHkd, 1e-9);
}

/** 投资本位 USD → 展示币种数值 */
function toDisplay(
  usd: number,
  usdMxn: number,
  ccy: Currency,
  usdIdr: number = DEFAULT_USD_IDR,
  cnyMxn: number = 2.5826,
  usdHkd: number = DEFAULT_USD_HKD,
): number {
  if (!Number.isFinite(usd)) return NaN;
  if (ccy === "USD") return usd;
  if (ccy === "IDR") return usd * usdIdr;
  if (ccy === "CNY")
    return usd * (usdMxn / Math.max(cnyMxn, 1e-9));
  if (ccy === "HKD") return usd * usdHkd;
  return usd * usdMxn;
}

function money(
  usd: number,
  usdMxn: number,
  ccy: Currency,
  digits = 0,
  usdIdr: number = DEFAULT_USD_IDR,
  cnyMxn: number = 2.5826,
  usdHkd: number = DEFAULT_USD_HKD,
): string {
  const v = toDisplay(usd, usdMxn, ccy, usdIdr, cnyMxn, usdHkd);
  if (!Number.isFinite(v)) return "—";
  const d =
    digits > 0
      ? digits
      : Math.abs(v) >= 1000
        ? 0
        : Math.abs(v) >= 1
          ? 2
          : 4;
  return fmt(v, d);
}

/**
 * 引擎账面金额 → 展示（默认账面为 MXN）。
 * IDR 价位入账后账面为 USD 时传 bookCcy: "USD"。
 */
function moneyMxn(
  mxn: number,
  usdMxn: number,
  ccy: Currency,
  digits = 0,
  withUnit = false,
  usdIdr: number = DEFAULT_USD_IDR,
  bookCcy: EngineBookCcy = "MXN",
  cnyMxn: number = 2.5826,
  usdHkd: number = DEFAULT_USD_HKD,
): string {
  if (!Number.isFinite(mxn)) return "—";
  const usd = bookToUsd(mxn, bookCcy, usdMxn);
  if (ccy === "MXN" && bookCcy === "MXN") {
    const s = fmt(mxn, digits);
    return withUnit ? `${s} MXN` : s;
  }
  const s = money(usd, usdMxn, ccy, digits, usdIdr, cnyMxn, usdHkd);
  return withUnit ? `${s} ${ccy}` : s;
}

/**
 * 路径回报公式条（紧凑两行）：
 * 总回报 = 累计净现金流 + 残值
 * 倍数 = (期初 + 总回报) ÷ 期初（含本金；期初=权益出资+保证金+投产前空窗等投入）
 */
function UnitReturnFormulaStrip(props: {
  initInv: number;
  pathCum: number;
  residualMxn: number;
  totalReturnMxn: number;
  returnMultiple: number | null;
  fx: number;
  ccy: Currency;
  /** 默认「累计净现金流」；场站对照可覆盖同名或短标签 */
  pathLabel?: string;
  /** 与回本 Tab「含残值」开关一致；关时公式条不叠加残值 */
  includeResidual?: boolean;
  /** 残值≈0 时的口径说明 */
  residualHintZh?: string | null;
  trailing?: any;
}) {
  const includeRes = props.includeResidual !== false;
  const pathLab = props.pathLabel ?? "累计净现金流";
  const a = moneyMxn(props.pathCum, props.fx, props.ccy, 0);
  const b = moneyMxn(props.residualMxn, props.fx, props.ccy, 0);
  const c = moneyMxn(props.totalReturnMxn, props.fx, props.ccy, 0);
  const init = moneyMxn(props.initInv, props.fx, props.ccy, 0);
  const mult =
    props.returnMultiple != null ? fmt(props.returnMultiple, 2) : null;
  return (
    <Stack gap={2}>
      <Text size="small" weight="semibold">
        {includeRes
          ? `${pathLab} ${a} + 残值 ${b} = 总回报 ${c}`
          : `${pathLab} ${a} = 总回报 ${c}`}
      </Text>
      {includeRes &&
      props.residualHintZh &&
      !(props.residualMxn > 1e-6) ? (
        <Text size="small" tone="tertiary">
          {props.residualHintZh}
        </Text>
      ) : null}
      <Row gap={10} wrap align="center">
        <Text size="small">
          倍数 = (期初 {init} + 总回报) ÷ 期初
          {mult != null ? ` = ${mult}x` : ""}
        </Text>
        {props.trailing}
      </Row>
    </Stack>
  );
}

/** SKU 货架价：价位面值 → 当前展示币（经 USD 本位） */
function moneyPriceLocal(
  local: number,
  priceCcy: PriceCcy,
  usdMxn: number,
  usdIdr: number,
  displayCcy: Currency,
  digits = 0,
  withUnit = false,
  cnyMxn: number = 2.5826,
  usdHkd: number = DEFAULT_USD_HKD,
): string {
  const usd = localToUsd(local, priceCcy, usdMxn, usdIdr);
  const s = money(
    usd,
    usdMxn,
    displayCcy,
    digits,
    usdIdr,
    cnyMxn,
    usdHkd,
  );
  return withUnit ? `${s} ${displayCcy}` : s;
}

function ccyUnit(ccy: Currency): string {
  if (ccy === "USD") return "USD";
  if (ccy === "IDR") return "IDR";
  if (ccy === "CNY") return "CNY";
  if (ccy === "HKD") return "HKD";
  return "MXN";
}

function ccyLabel(ccy: Currency): string {
  return ccyUnit(ccy);
}

/** 投资计价可选：不含 IDR（印尼仅作现金流/价位） */
const INVEST_CURRENCIES: Currency[] = ["MXN", "USD", "CNY", "HKD"];
/** 现金流可选：含展业国本币 IDR */
const CASH_CURRENCIES: Currency[] = ["MXN", "USD", "IDR", "CNY", "HKD"];

function isCurrency(v: unknown): v is Currency {
  return (
    v === "MXN" ||
    v === "USD" ||
    v === "IDR" ||
    v === "CNY" ||
    v === "HKD"
  );
}

function isInvestCurrency(v: unknown): v is Currency {
  return (
    v === "MXN" ||
    v === "USD" ||
    v === "CNY" ||
    v === "HKD"
  );
}

function countryCashCcy(country: string): Currency {
  return countryPriceCcy(country) === "IDR" ? "IDR" : "MXN";
}

function defaultCurrencyPair(country: string): {
  invest: Currency;
  cash: Currency;
} {
  return { invest: "USD", cash: countryCashCcy(country) };
}

function migrateLegacyCurrencyPair(
  legacy: unknown,
  country: string,
): { invest: Currency; cash: Currency } {
  const d = defaultCurrencyPair(country);
  if (!isCurrency(legacy)) return d;
  if (legacy === "USD") return { invest: "USD", cash: d.cash };
  return { invest: "USD", cash: legacy };
}

function pairFxKey(
  cash: Currency,
  invest: Currency,
): "usdMxn" | "usdIdr" | "cnyMxn" | "usdHkd" | null {
  if (cash === invest) return null;
  const pair = new Set<Currency>([cash, invest]);
  if (pair.has("IDR")) return "usdIdr";
  if (pair.has("MXN")) return "usdMxn";
  if (pair.has("CNY")) return "cnyMxn";
  if (pair.has("HKD")) return "usdHkd";
  return "usdMxn";
}

/** 1 单位投资计价 ≈ 多少现金流货币（经 USD 枢纽） */
function fxCashPerInvest(
  cash: Currency,
  invest: Currency,
  usdMxn: number,
  usdIdr: number,
  cnyMxn: number,
  usdHkd: number,
): number | null {
  if (cash === invest) return null;
  const uInv = usdPerCcy(invest, usdMxn, usdIdr, cnyMxn, usdHkd);
  const uCash = usdPerCcy(cash, usdMxn, usdIdr, cnyMxn, usdHkd);
  if (uCash <= 0) return null;
  return uInv / uCash;
}

type PairFxKey = "usdMxn" | "usdIdr" | "cnyMxn" | "usdHkd";

/** 顶栏 FX 输入：1 invest = n cash */
function applyInvestCashFxInput(
  invest: Currency,
  cash: Currency,
  n: number,
  fx: {
    usdMxn: number;
    usdIdr: number;
    cnyMxn: number;
    usdHkd: number;
  },
  onFxRate: (key: PairFxKey, rate: number) => void,
): void {
  if (!Number.isFinite(n) || n <= 0) return;
  const { usdMxn, usdIdr, cnyMxn, usdHkd } = fx;
  if (invest === "USD" && cash === "MXN") onFxRate("usdMxn", n);
  else if (invest === "MXN" && cash === "USD") onFxRate("usdMxn", 1 / n);
  else if (invest === "USD" && cash === "IDR") onFxRate("usdIdr", n);
  else if (invest === "IDR" && cash === "USD") onFxRate("usdIdr", 1 / n);
  else if (invest === "USD" && cash === "CNY")
    onFxRate("cnyMxn", usdMxn / n);
  else if (invest === "CNY" && cash === "USD")
    onFxRate("cnyMxn", usdMxn / n);
  else if (invest === "CNY" && cash === "MXN") onFxRate("cnyMxn", n);
  else if (invest === "MXN" && cash === "CNY") onFxRate("cnyMxn", 1 / n);
  else if (invest === "USD" && cash === "HKD") onFxRate("usdHkd", n);
  else if (invest === "HKD" && cash === "USD") onFxRate("usdHkd", 1 / n);
  else if (invest === "MXN" && cash === "IDR")
    onFxRate("usdIdr", n * Math.max(usdMxn, 1e-9));
  else if (invest === "IDR" && cash === "MXN")
    onFxRate("usdMxn", n * Math.max(usdIdr, 1e-9));
  else if (invest === "CNY" && cash === "IDR")
    onFxRate(
      "usdIdr",
      (n * Math.max(usdMxn, 1e-9)) / Math.max(cnyMxn, 1e-9),
    );
  else if (invest === "IDR" && cash === "CNY")
    onFxRate(
      "usdIdr",
      Math.max(usdMxn, 1e-9) / (n * Math.max(cnyMxn, 1e-9)),
    );
  else if (invest === "MXN" && cash === "HKD")
    onFxRate("usdHkd", n * Math.max(usdMxn, 1e-9));
  else if (invest === "HKD" && cash === "MXN")
    onFxRate("usdMxn", n * Math.max(usdHkd, 1e-9));
  else if (invest === "CNY" && cash === "HKD")
    onFxRate(
      "usdHkd",
      (n * Math.max(usdMxn, 1e-9)) / Math.max(cnyMxn, 1e-9),
    );
  else if (invest === "HKD" && cash === "CNY")
    onFxRate(
      "cnyMxn",
      (Math.max(usdMxn, 1e-9) * Math.max(usdHkd, 1e-9)) /
        (n * Math.max(usdHkd, 1e-9)),
    );
  else if (invest === "IDR" && cash === "HKD")
    onFxRate("usdHkd", n * Math.max(usdIdr, 1e-9));
  else if (invest === "HKD" && cash === "IDR")
    onFxRate(
      "usdIdr",
      Math.max(usdHkd, 1e-9) / Math.max(n, 1e-9),
    );
  else {
    const key = pairFxKey(cash, invest);
    if (key) onFxRate(key, n);
  }
}

/**
 * 顶栏货币对胶囊：A/B 翻面展示 + 点选配置投资/现金流货币。
 * - A 面：全盘按 investCcy 折算
 * - B 面：全盘按 cashCcy 展示
 * - 点未激活面 → 切面；再点已激活面或右侧「货币对」→ 展开配置
 * - invest≠cash 时展示 FX（1 投资计价 = N 现金流）+ [更新]
 */
function CurrencyPairCapsule(props: {
  investCcy: Currency;
  cashCcy: Currency;
  face: "A" | "B";
  onFace: (f: "A" | "B") => void;
  onInvest: (c: Currency) => void;
  onCash: (c: Currency) => void;
  configOpen: boolean;
  onToggleConfig: () => void;
  usdMxn: number;
  usdIdr: number;
  cnyMxn: number;
  usdHkd: number;
  onFxRate: (key: PairFxKey, rate: number) => void;
  onFxRefresh: () => void;
  /** 顶栏紧凑：FX 不收在胶囊旁，展开「货币对」时编辑 */
  compactHeader?: boolean;
}) {
  const theme = useHostTheme();
  const {
    investCcy,
    cashCcy,
    face,
    onFace,
    onInvest,
    onCash,
    configOpen,
    onToggleConfig,
    usdMxn,
    usdIdr,
    cnyMxn,
    usdHkd,
    onFxRate,
    onFxRefresh,
    compactHeader,
  } = props;
  const fxKey = pairFxKey(cashCcy, investCcy);
  const fxQuote = fxCashPerInvest(
    cashCcy,
    investCcy,
    usdMxn,
    usdIdr,
    cnyMxn,
    usdHkd,
  );
  const showFx =
    investCcy !== cashCcy && fxQuote != null && Number.isFinite(fxQuote);
  const faceChip = (f: "A" | "B", roleZh: string, code: Currency) => {
    const active = face === f;
    return (
      <button
        type="button"
        onClick={() => {
          if (active) onToggleConfig();
          else {
            onFace(f);
            if (configOpen) onToggleConfig();
          }
        }}
        title={
          active
            ? `当前 ${f} 面（${roleZh} ${code}）· 再点配置货币对`
            : `切到 ${f} 面：全盘按${roleZh}货币展示`
        }
        style={{
          margin: 0,
          border: "none",
          cursor: "pointer",
          padding: "5px 11px",
          fontSize: 12,
          lineHeight: 1.2,
          fontWeight: active ? 600 : 400,
          color: active ? theme.text.primary : theme.text.tertiary,
          background: active ? theme.bg.chrome : "transparent",
          whiteSpace: "nowrap" as const,
        }}
      >
        {f} · {roleZh} {code}
      </button>
    );
  };
  const applyPairFxInput = (raw: string) => {
    const n = Number(raw);
    if (!Number.isFinite(n) || n <= 0 || !fxKey) return;
    applyInvestCashFxInput(
      investCcy,
      cashCcy,
      n,
      { usdMxn, usdIdr, cnyMxn, usdHkd },
      onFxRate,
    );
  };
  return (
    <Stack gap={4} style={{ flex: "0 0 auto", minWidth: 0 }}>
      <Row gap={6} align="center" wrap>
        <Row
          gap={0}
          align="center"
          style={{
            border: `1px solid ${theme.stroke.secondary}`,
            borderRadius: 999,
            overflow: "hidden",
            background: theme.bg.elevated,
            flex: "0 0 auto",
          }}
        >
          {faceChip("A", "投资", investCcy)}
          <div
            style={{
              width: 1,
              alignSelf: "stretch",
              background: theme.stroke.tertiary,
              flex: "0 0 auto",
            }}
          />
          {faceChip("B", "现金流", cashCcy)}
          <button
            type="button"
            onClick={onToggleConfig}
            title="点选配置投资计价 / 现金流货币对"
            style={{
              margin: 0,
              border: "none",
              borderLeft: `1px solid ${theme.stroke.tertiary}`,
              cursor: "pointer",
              padding: "5px 10px",
              fontSize: 11,
              lineHeight: 1.2,
              color: configOpen ? theme.text.primary : theme.text.tertiary,
              background: configOpen ? theme.bg.chrome : "transparent",
              fontWeight: configOpen ? 600 : 400,
              whiteSpace: "nowrap" as const,
            }}
          >
            {configOpen ? "收起" : "货币对"}
          </button>
        </Row>
        {showFx && !compactHeader ? (
          <Row gap={4} align="center" style={{ flex: "0 0 auto" }}>
            <Text size="small" tone="tertiary" style={{ whiteSpace: "nowrap" }}>
              FX 1 {investCcy}=
            </Text>
            <TextInput
              type="number"
              value={String(Math.round(fxQuote! * 1000) / 1000)}
              onChange={applyPairFxInput}
              style={{ width: 72, fontSize: 12, padding: "2px 6px", minHeight: 22 }}
            />
            <Text size="small" tone="tertiary" style={{ whiteSpace: "nowrap" }}>
              {cashCcy}
            </Text>
            <Button variant="ghost" onClick={onFxRefresh}>
              更新
            </Button>
          </Row>
        ) : null}
      </Row>
      {configOpen ? (
        <Stack
          gap={6}
          style={mergeStyle({
            padding: "8px 10px",
            border: `1px solid ${theme.stroke.secondary}`,
            background: theme.bg.elevated,
            borderRadius: 8,
            minWidth: 240,
          })}
        >
          <Row gap={8} align="center" wrap>
            <Text size="small" tone="secondary" style={{ minWidth: 64 }}>
              投资计价
            </Text>
            <Row gap={4}>
              {INVEST_CURRENCIES.map((c) => (
                <Pill
                  key={`inv-${c}`}
                  size="sm"
                  active={investCcy === c}
                  onClick={() => onInvest(c)}
                >
                  {c}
                </Pill>
              ))}
            </Row>
          </Row>
          <Row gap={8} align="center" wrap>
            <Text size="small" tone="secondary" style={{ minWidth: 64 }}>
              现金流
            </Text>
            <Row gap={4}>
              {CASH_CURRENCIES.map((c) => (
                <Pill
                  key={`cash-${c}`}
                  size="sm"
                  active={cashCcy === c}
                  onClick={() => onCash(c)}
                >
                  {c}
                </Pill>
              ))}
            </Row>
          </Row>
          {compactHeader && showFx ? (
            <Row gap={4} align="center" wrap>
              <Text size="small" tone="tertiary" style={{ whiteSpace: "nowrap" }}>
                FX 1 {investCcy}=
              </Text>
              <TextInput
                type="number"
                value={String(Math.round(fxQuote! * 1000) / 1000)}
                onChange={applyPairFxInput}
                style={{ width: 72, fontSize: 12, padding: "2px 6px", minHeight: 22 }}
              />
              <Text size="small" tone="tertiary">{cashCcy}</Text>
              <Button variant="ghost" onClick={onFxRefresh}>更新</Button>
            </Row>
          ) : null}
          {!compactHeader ? (
            <Text size="small" tone="tertiary">
              A=全折投资计价 · B=全折现金流 · 路径 CF 按现金流货币 · IRR/NPV/国债跟投资计价
            </Text>
          ) : null}
        </Stack>
      ) : null}
    </Stack>
  );
}


function skuKindZh(kind: SkuKind): string {
  if (kind === "station") return "场站";
  if (kind === "two_wheel") return "两轮";
  return "车辆";
}

/** 车辆或两轮：走滚动资产单位/单元现金流 */
function isRollingAssetSku(sku: AssetSku): boolean {
  return sku.kind === "vehicle" || sku.kind === "two_wheel";
}

/** 含税落地（价位面值）→ 引擎账面（MXN 或 USD） */
function modelUnitGrossEngineBook(
  model: AssetSku,
  qty: number,
  vat: number,
  usdMxn: number,
  usdIdr: number,
  configId?: string,
): number {
  return skuLocalToEngineBook(
    modelUnitGrossMxn(model, qty, vat, configId),
    model,
    usdMxn,
    usdIdr,
  );
}

/** 落地现金（价位面值）→ 引擎账面（MXN 或 USD） */
function modelUnitLandedEngineBook(
  model: AssetSku,
  qty: number,
  usdMxn: number,
  usdIdr: number,
  configId?: string,
): number {
  return skuLocalToEngineBook(
    modelUnitLandedMxn(model, qty, configId),
    model,
    usdMxn,
    usdIdr,
  );
}

/** 图表统一中性色（黑白灰）；多系列靠图例区分 */
const CHART_BW = "neutral" as const;

/** 中文优先字体栈：避免侧栏窄屏缺字形/挤叠；勿对汉字用负字距 */
const FONT_UI =
  '"PingFang SC", "Hiragino Sans GB", "Noto Sans SC", "Microsoft YaHei", "Segoe UI", system-ui, -apple-system, sans-serif';

type OpsDayKind = "run" | "idle" | "maint" | "claim" | "offline";
const OPS_DAY_KIND_ZH: Record<OpsDayKind, string> = {
  run: "运营",
  idle: "空闲",
  maint: "维保",
  claim: "出险",
  offline: "下线",
};
function seedOpsDayStatus(unitIdx: number, dayIdx: number, seed: number): OpsDayKind {
  const x = (unitIdx * 17 + dayIdx * 31 + seed * 13) % 100;
  if (x < 62) return "run";
  if (x < 78) return "idle";
  if (x < 90) return "maint";
  if (x < 96) return "claim";
  return "offline";
}
function OpsMetricsHeatmapPanel(props: {
  unitCount: number;
  days?: number;
  seed?: number;
}) {
  const theme = useHostTheme();
  const days = Math.max(14, Math.min(31, props.days ?? 28));
  const nUnits = Math.max(1, Math.min(24, Math.round(props.unitCount || 8)));
  const seed = props.seed ?? 202608;
  const kinds: OpsDayKind[] = ["run", "idle", "maint", "claim", "offline"];
  const toneFill: Record<OpsDayKind, string> = {
    run: theme.fill.primary,
    idle: theme.fill.tertiary,
    maint: theme.fill.secondary,
    claim: theme.fill.primary,
    offline: theme.stroke.tertiary,
  };
  const opacity: Record<OpsDayKind, number> = {
    run: 0.85, idle: 0.35, maint: 0.55, claim: 0.7, offline: 0.25,
  };
  const fleetHeat = Array.from({ length: days }, (_, d) => {
    let run = 0;
    for (let u = 0; u < nUnits; u++) {
      if (seedOpsDayStatus(u, d, seed) === "run") run += 1;
    }
    return run / nUnits;
  });
  const cell = 10;
  const gap = 2;
  const labelW = 36;
  const gridW = labelW + days * (cell + gap);
  const gridH = nUnits * (cell + gap) + 8;
  return (
    <Stack gap={12}>
      <Row gap={10} wrap align="center">
        {kinds.map((k) => (
          <Row key={k} gap={4} align="center">
            <span
              style={{
                width: 10,
                height: 10,
                borderRadius: 2,
                background: toneFill[k],
                opacity: opacity[k],
                border: `1px solid ${theme.stroke.tertiary}`,
              }}
            />
            <Text size="small" tone="tertiary">
              {OPS_DAY_KIND_ZH[k]}
            </Text>
          </Row>
        ))}
        <Text size="small" tone="tertiary">
          {nUnits} 台 · 近 {days} 日
        </Text>
      </Row>
      <Stack gap={6}>
        <Text size="small" weight="medium">
          单车日状态日历
        </Text>
        <div style={{ overflowX: "auto", maxWidth: "100%" }}>
          <svg width={gridW} height={gridH + 18} style={{ display: "block" }}>
            {Array.from({ length: days }, (_, d) => (
              <text
                key={`d-${d}`}
                x={labelW + d * (cell + gap) + cell / 2}
                y={10}
                textAnchor="middle"
                fill={theme.text.tertiary}
                style={{ fontFamily: FONT_UI, fontSize: 12 }}
              >
                {d + 1}
              </text>
            ))}
            {Array.from({ length: nUnits }, (_, u) => (
              <g key={`u-${u}`}>
                <text
                  x={0}
                  y={18 + u * (cell + gap) + cell - 1}
                  fill={theme.text.tertiary}
                  style={{ fontFamily: FONT_UI, fontSize: 12 }}
                >
                  {`U${u + 1}`}
                </text>
                {Array.from({ length: days }, (_, d) => {
                  const k = seedOpsDayStatus(u, d, seed);
                  return (
                    <rect
                      key={`c-${u}-${d}`}
                      x={labelW + d * (cell + gap)}
                      y={14 + u * (cell + gap)}
                      width={cell}
                      height={cell}
                      rx={1}
                      fill={toneFill[k]}
                      opacity={opacity[k]}
                    >
                      <title>{`U${u + 1} · D${d + 1} · ${OPS_DAY_KIND_ZH[k]}`}</title>
                    </rect>
                  );
                })}
              </g>
            ))}
          </svg>
        </div>
      </Stack>
      <Stack gap={6}>
        <Text size="small" weight="medium">
          车队叠加热力（日运营占比）
        </Text>
        <div style={{ overflowX: "auto", maxWidth: "100%" }}>
          <svg
            width={Math.max(gridW, days * 14)}
            height={56}
            style={{ display: "block" }}
          >
            {fleetHeat.map((h, d) => {
              const barH = Math.max(2, Math.round(h * 36));
              return (
                <g key={`fh-${d}`}>
                  <rect
                    x={d * 14}
                    y={40 - barH}
                    width={12}
                    height={barH}
                    rx={1}
                    fill={theme.fill.primary}
                    opacity={0.35 + h * 0.55}
                  >
                    <title>{`D${d + 1} · 运营 ${Math.round(h * 100)}%`}</title>
                  </rect>
                  <text
                    x={d * 14 + 6}
                    y={52}
                    textAnchor="middle"
                    fill={theme.text.tertiary}
                    style={{ fontFamily: FONT_UI, fontSize: 12 }}
                  >
                    {d + 1}
                  </text>
                </g>
              );
            })}
          </svg>
        </div>
        <Text size="small" tone="tertiary">
          Source: 示意种子 seed={seed} · 非实盘遥测
        </Text>
      </Stack>
    </Stack>
  );
}


