/** Cursor 式页面标题：仅短标题 */
function PageIntro({ title }: { title: string; description?: string }) {
  return <H2 style={TYPE.h2}>{title}</H2>;
}

/** 投资链：已并入顶栏 */
function InvestJourneyBar(_props: {
  step: "unit" | "pack" | "book";
  onGo: (tab: TabId) => void;
}) {
  return null;
}

/** 经营假设定性语气：ok=健康绿 / edge=边缘黄 / warn=极端红 / muted=中性灰 */
type OpsJudgeTone = "ok" | "edge" | "warn" | "muted";
type OpsJudge = { text: string; tone: OpsJudgeTone };

function opsJudgeColor(
  theme: ReturnType<typeof useHostTheme>,
  tone: OpsJudgeTone,
): string {
  if (tone === "ok") return theme.category.green;
  if (tone === "edge") return theme.category.yellow;
  if (tone === "warn") return theme.category.red;
  return theme.text.tertiary;
}

/**
 * 经营假设短判（2–4 字）。阈值对齐墨西哥网约车 DAE 车队常识 +《DAE-200》锚点：
 * - IPH：每小时车队里程收入 MXN/h（案例默认 210；库内常见 185–230）
 *   <150 偏低 · 150–180 一般 · 180–240 偏稳 · 240–300 偏高 · >300 激进
 * - 利用率%：<50 偏低 · 50–70 一般 · 70–85 偏稳 · >85 偏满
 * - 日工时 h：<6 偏少 · 6–9 适中 · 9–11 偏满 · >11 过载
 * - 周营运天：≤5 偏松 · 6 常规 · 7 满负荷
 * - 补贴%：0 无补贴 · ≤5 轻补 · ≤15 中补 · >15 高补依赖
 */
function clampPlatformTakePct(p: number): number {
  return Math.max(0, Math.min(0.6, p));
}

/** 抽佣前 IPH（乘客侧里程单价示意）= 车队净 IPH ÷ (1−平台%) */
function iphGrossFromNetMxn(netMxn: number, platformTakePct: number): number {
  const keep = 1 - clampPlatformTakePct(platformTakePct);
  if (!(netMxn > 0)) return 0;
  if (keep <= 0.05) return netMxn;
  return netMxn / keep;
}

/** 车队净 IPH = 抽佣前 × (1−平台%) */
function iphNetFromGrossMxn(grossMxn: number, platformTakePct: number): number {
  const keep = 1 - clampPlatformTakePct(platformTakePct);
  return Math.max(0, grossMxn * keep);
}

function judgeIphMxn(iph: number): OpsJudge {
  if (!(iph > 0)) return { text: "未填", tone: "muted" };
  if (iph < 150) return { text: "偏低", tone: "warn" };
  if (iph < 180) return { text: "一般", tone: "edge" };
  if (iph <= 240) return { text: "偏稳", tone: "ok" };
  if (iph <= 300) return { text: "偏高", tone: "edge" };
  return { text: "激进", tone: "warn" };
}

function judgeIphGrossMxn(gross: number, net: number): OpsJudge {
  if (!(gross > 0)) return { text: "未填", tone: "muted" };
  if (!(net > 0)) return { text: "—", tone: "muted" };
  const uplift = gross / net - 1;
  if (uplift < 0.15) return { text: "低抽成", tone: "ok" };
  if (uplift <= 0.35) return { text: "常规", tone: "ok" };
  return { text: "高抽成", tone: "edge" };
}

function judgeUtilPct(pct: number): OpsJudge {
  if (!(pct > 0)) return { text: "未填", tone: "muted" };
  if (pct < 50) return { text: "偏低", tone: "warn" };
  if (pct < 70) return { text: "一般", tone: "edge" };
  if (pct <= 85) return { text: "偏稳", tone: "ok" };
  return { text: "偏满", tone: "edge" };
}

function judgeHoursDay(h: number): OpsJudge {
  if (!(h > 0)) return { text: "未填", tone: "muted" };
  if (h < 6) return { text: "偏少", tone: "edge" };
  if (h < 9) return { text: "适中", tone: "ok" };
  if (h <= 11) return { text: "偏满", tone: "edge" };
  return { text: "过载", tone: "warn" };
}

function judgeDaysWeek(d: number): OpsJudge {
  const n = Math.round(d);
  if (!(n > 0)) return { text: "未填", tone: "muted" };
  if (n <= 5) return { text: "偏松", tone: "edge" };
  if (n === 6) return { text: "常规", tone: "ok" };
  return { text: "满负荷", tone: "edge" };
}

function judgeSubsidyPct(pct: number): OpsJudge {
  if (!(pct > 0)) return { text: "无补贴", tone: "ok" };
  if (pct <= 5) return { text: "轻补", tone: "ok" };
  if (pct <= 15) return { text: "中补", tone: "edge" };
  return { text: "高补依赖", tone: "warn" };
}

/**
 * 单车电耗 kWh/100km 短判。
 * 四轮对齐《DAE-200》ES 锚点 15：<11 偏省 · 11–14 适中 · 14–16 贴案 · 16–20 偏高 · >20 费电。
 * 两轮：<3 偏省 · ≤6 常规 · ≤9 偏高 · >9 费电。
 */
function judgeKwhPer100(kwh: number, kind?: SkuKind): OpsJudge {
  if (!(kwh > 0)) return { text: "未填", tone: "muted" };
  if (kind === "station") return { text: "—", tone: "muted" };
  if (kind === "two_wheel") {
    if (kwh < 3) return { text: "偏省", tone: "ok" };
    if (kwh <= 6) return { text: "常规", tone: "ok" };
    if (kwh <= 9) return { text: "偏高", tone: "edge" };
    return { text: "费电", tone: "warn" };
  }
  if (kwh < 11) return { text: "偏省", tone: "ok" };
  if (kwh < 14) return { text: "适中", tone: "ok" };
  if (kwh <= 16) return { text: "常用档", tone: "ok" };
  if (kwh <= 20) return { text: "偏高", tone: "edge" };
  return { text: "费电", tone: "warn" };
}

/**
 * 车辆购置 vs SKU 指导价/MSRP（或缺省案例购入锚）偏离短判。
 * 偏离 d=(购入−参照)/参照：
 *   ≤−25% 显著偏低（核验成色）· −25%～−8% 偏廉 · −8%～+8% 贴市 ·
 *   +8%～+20% 偏贵 · >+20% 显著偏高
 */
function judgePurchaseVsRef(priceMxn: number, refMxn: number): OpsJudge {
  if (!(priceMxn > 0)) return { text: "未填", tone: "muted" };
  if (!(refMxn > 0)) return { text: "无参照", tone: "muted" };
  const d = (priceMxn - refMxn) / refMxn;
  if (d <= -0.25) return { text: "显著偏低", tone: "warn" };
  if (d < -0.08) return { text: "偏廉", tone: "edge" };
  if (d <= 0.08) return { text: "贴市", tone: "ok" };
  if (d <= 0.2) return { text: "偏贵", tone: "edge" };
  return { text: "显著偏高", tone: "warn" };
}

/** 购置参照：优先配置档/SKU 指导价；否则回落案例默认购入锚 */
function resolvePurchasePriceRef(
  sku: AssetSku,
  configId?: string,
): { refMxn: number; labelZh: string; sourceZh: string } | null {
  const guide = skuGuidePriceMxn(sku, configId);
  if (guide > 0) {
    return {
      refMxn: guide,
      labelZh: "指导价",
      sourceZh: skuPricesIncludeVat(sku)
        ? "SKU 含税指导/MSRP"
        : "SKU 未税指导/MSRP",
    };
  }
  const catalog = DEFAULT_ASSET_SKUS.find((s) => s.id === sku.id);
  const caseAnchor = catalog
    ? skuPurchasePriceMxn(catalog, configId)
    : 0;
  if (caseAnchor > 0) {
    return {
      refMxn: caseAnchor,
      labelZh: "案例购入锚",
      sourceZh: "货架默认·案例",
    };
  }
  return null;
}

function NumField({
  label,
  value,
  onChange,
  hint,
  tip,
  tipId,
  /** 底层按 MXN 存储；有 displayCcy 时输入框直接显示/编辑当前币种 */
  mxnFx,
  displayCcy,
  /** 瀑布配置卡内：矮录入、不铺满宽脚注 */
  compact,
  /** 标签旁短判（如「偏稳」），随 value 实时更新 */
  judge,
}: {
  label: string;
  value: number;
  onChange: (n: number) => void;
  hint?: string;
  /** 悬停/点击查看的口径说明 */
  tip?: string;
  tipId?: string;
  mxnFx?: number;
  displayCcy?: Currency;
  compact?: boolean;
  judge?: OpsJudge;
}) {
  const theme = useHostTheme();
  const showUsd =
    mxnFx != null && displayCcy === "USD" && Number.isFinite(mxnFx) && mxnFx > 0;
  const displayValue = showUsd ? value / mxnFx! : value;
  const displayDigits = showUsd
    ? value >= 10_000
      ? 1
      : 2
    : undefined;
  const shown = Number.isFinite(displayValue)
    ? displayDigits != null
      ? String(
          Number(
            displayValue.toFixed(
              displayValue >= 1000 ? Math.min(displayDigits, 1) : displayDigits,
            ),
          ),
        )
      : String(value)
    : "";

  let foot: string | null = null;
  if (!compact && mxnFx != null && Number.isFinite(value) && displayCcy) {
    foot = showUsd
      ? `底层 ${fmt(value, 0)} MXN · FX ${mxnFx}`
      : `当前 MXN · ≈ ${fmt(value / mxnFx, value >= 1000 ? 1 : 2)} USD`;
  }

  /** compact：旁注并入悬停，避免占行；有短判时仍在下方露出一行参照旁注 */
  const tipMerged =
    tip && compact && hint ? `${tip}\n旁注：${hint}` : tip || undefined;
  const showHintBelow = Boolean(hint) && (!(compact && tip) || Boolean(judge));

  const labelRow = (
    <Row gap={4} align="center" wrap style={{ minWidth: 0 }}>
      {tipMerged ? (
        <TipLabel
          id={tipId || `nf-${label}`}
          label={label}
          tip={tipMerged}
        />
      ) : (
        <Text tone="secondary" style={TYPE.label}>
          {label}
        </Text>
      )}
      {judge ? (
        <Text
          size="small"
          weight="medium"
          style={mergeStyle(TYPE.label, {
            color: opsJudgeColor(theme, judge.tone),
            flex: "0 0 auto",
          })}
        >
          {judge.text}
        </Text>
      ) : null}
    </Row>
  );

  return (
    <Stack gap={compact ? 2 : 4} style={{ minWidth: 0 }}>
      {labelRow}
      <TextInput
        type="number"
        value={shown}
        onChange={(v) => {
          const n = Number(v);
          if (!Number.isFinite(n)) return;
          if (showUsd) onChange(n * mxnFx!);
          else onChange(n);
        }}
      />
      {(foot || showHintBelow) && (
        <Text style={mergeStyle(TYPE.caption, { color: theme.text.tertiary })}>
          {[foot, showHintBelow ? hint : null].filter(Boolean).join(" · ")}
        </Text>
      )}
    </Stack>
  );
}

/** 表单字段标签：统一小号字重，避免与 Stat/正文抢层级 */
function FieldLabel({ children }: { children: string }) {
  return (
    <Text tone="secondary" style={TYPE.label}>
      {children}
    </Text>
  );
}

/** 点击展开的因子说明：居中浮层，避免 Canvas 分栏 overflow 裁切侧边说明 */
function TipLabel(props: {
  id: string;
  label: string;
  tip: string;
}) {
  const theme = useHostTheme();
  const [openTipId, setOpenTipId] = useCanvasState<string>(
    "cf-factor-tip-ui",
    "",
  );
  const open = openTipId === props.id;
  const toggle = () => setOpenTipId(open ? "" : props.id);
  return (
    <>
      <span
        title={props.tip.replace(/\n+/g, " · ")}
        role="button"
        onClick={toggle}
        style={{
          cursor: "help",
          borderBottom: `1px dotted ${theme.stroke.primary}`,
        }}
      >
        <Text tone="secondary" style={TYPE.label}>
          {props.label}
        </Text>
      </span>
      {open ? (
        <div
          role="presentation"
          style={{
            position: "fixed",
            inset: 0,
            zIndex: 10000,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            padding: 16,
            background: theme.fill.primary,
          }}
          onClick={() => setOpenTipId("")}
        >
          <div
            role="dialog"
            aria-label={props.label}
            style={{
              width: "min(360px, calc(100% - 32px))",
              maxHeight: "min(70vh, 420px)",
              overflow: "auto",
              padding: "12px 14px",
              background: theme.bg.elevated,
              border: `1px solid ${theme.stroke.primary}`,
              borderRadius: 8,
              boxSizing: "border-box",
            }}
            onClick={(e: { stopPropagation: () => void }) => e.stopPropagation()}
          >
            <Text size="small" weight="semibold" style={{ marginBottom: 6 }}>
              {props.label}
            </Text>
            <Text size="small" style={{ whiteSpace: "pre-wrap" }}>
              {props.tip}
            </Text>
            <Text size="small" tone="tertiary" style={{ marginTop: 8 }}>
              点遮罩或再点字段名收起
            </Text>
          </div>
        </div>
      ) : null}
    </>
  );
}

/**
 * 问号口径：悬停看摘要，点击居中浮层看全文。
 * 计划对照区把长注释收进这里，把版面留给 VTL / 瀑布 / 堆叠。
 */
function HelpQ(props: { id: string; tip: string; label?: string }) {
  const theme = useHostTheme();
  const [openTipId, setOpenTipId] = useCanvasState<string>(
    "cf-factor-tip-ui",
    "",
  );
  const open = openTipId === props.id;
  const title = props.label || "口径说明";
  const tipOneLine = props.tip.replace(/\n+/g, " · ");
  return (
    <>
      <span
        title={tipOneLine}
        role="button"
        aria-label={title}
        onClick={() => setOpenTipId(open ? "" : props.id)}
        style={{
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          width: 16,
          height: 16,
          borderRadius: 999,
          border: `1px solid ${theme.stroke.secondary}`,
          color: theme.text.tertiary,
          fontSize: 11,
          lineHeight: 1,
          cursor: "help",
          flexShrink: 0,
          userSelect: "none",
        }}
      >
        ?
      </span>
      {open ? (
        <div
          role="presentation"
          style={{
            position: "fixed",
            inset: 0,
            zIndex: 10000,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            padding: 16,
            background: theme.fill.primary,
          }}
          onClick={() => setOpenTipId("")}
        >
          <div
            role="dialog"
            aria-label={title}
            style={{
              width: "min(420px, calc(100% - 32px))",
              maxHeight: "min(70vh, 480px)",
              overflow: "auto",
              padding: "12px 14px",
              background: theme.bg.elevated,
              border: `1px solid ${theme.stroke.primary}`,
              borderRadius: 8,
              boxSizing: "border-box",
            }}
            onClick={(e: { stopPropagation: () => void }) => e.stopPropagation()}
          >
            <Text size="small" weight="semibold" style={{ marginBottom: 6 }}>
              {title}
            </Text>
            <Text size="small" style={{ whiteSpace: "pre-wrap" }}>
              {props.tip}
            </Text>
            <Text size="small" tone="tertiary" style={{ marginTop: 8 }}>
              点遮罩或再点 ? 收起
            </Text>
          </div>
        </div>
      ) : null}
    </>
  );
}

/** 顶栏 ··· 菜单：fixed 浮层，避免被导航行遮挡或 overflow 裁切 */
function HeaderMoreMenu(props: {
  open: boolean;
  anchor: { top: number; left: number } | null;
  onClose: () => void;
  items: { key: string; label: string; onClick: () => void }[];
}) {
  const theme = useHostTheme();
  if (!props.open || !props.anchor) return null;
  return (
    <div
      role="presentation"
      style={{ position: "fixed", inset: 0, zIndex: 10000 }}
      onClick={props.onClose}
    >
      <div
        role="menu"
        aria-label="更多"
        style={{
          position: "fixed",
          top: props.anchor.top,
          left: props.anchor.left,
          zIndex: 10001,
          width: 180,
          padding: 6,
          boxSizing: "border-box",
          border: `1px solid ${theme.stroke.secondary}`,
          borderRadius: 8,
          background: theme.bg.elevated,
          boxShadow: "0 8px 24px rgba(0,0,0,0.28)",
        }}
        onClick={(e: { stopPropagation: () => void }) => e.stopPropagation()}
      >
        {props.items.map((item) => (
          <button
            key={item.key}
            type="button"
            onClick={item.onClick}
            style={{
              display: "block",
              width: "100%",
              margin: 0,
              padding: "8px 10px",
              border: "none",
              borderRadius: 6,
              background: "transparent",
              color: theme.text.primary,
              fontSize: 13,
              lineHeight: 1.3,
              textAlign: "left",
              whiteSpace: "nowrap",
              cursor: "pointer",
            }}
          >
            {item.label}
          </button>
        ))}
      </div>
    </div>
  );
}

