type CoreStatTone = "success" | "danger" | "warning" | "info" | undefined;

/**
 * 回本周期：静态/动态回收 · 杠杆后/无债对照权益 IRR · NPV+折现 · 累计净现金流公式。
 * funding 有对照时用双 IRR 替换单 IRR，避免同序列重复；月供/劣后在「瀑布过程」Tab。
 * embedded：嵌在结果文件夹 Tab 内时不重复标题。
 */
function InvCoreOutputsBlock(props: {
  theme: ReturnType<typeof useHostTheme>;
  hint?: string;
  embedded?: boolean;
  staticPb: { value: string; label: string };
  dynamicPb: { value: string; label: string };
  irr: { value: string; label: string; tone?: CoreStatTone };
  npv: {
    value: string;
    label: string;
    tone?: CoreStatTone;
    tip?: string;
    discountAnn: number;
    onDiscountAnn: (r: number) => void;
    investCcy?: Currency;
  };
  formula: {
    initInv: number;
    pathCum: number;
    residualMxn: number;
    totalReturnMxn: number;
    returnMultiple: number | null;
    fx: number;
    ccy: Currency;
    residualHintZh?: string | null;
    trailing?: any;
  };
  /** 杠杆后 vs 无债对照权益 IRR；与顶栏单 IRR 同序列时只展示本对照 */
  funding?: {
    equityIrr: string;
    equityIrrNoPi: string;
    holdYears: number;
  };
  /** 末月是否叠加残值（静态/动态回本、IRR、NPV、公式条） */
  includeResidual: boolean;
  onIncludeResidual: (v: boolean) => void;
  /** 投委会权威对照（避免把杠杆劣后切片 IRR 当成对外主读数） */
  authorityHint?: {
    titleZh: string;
    bodyZh: string;
    stats?: { label: string; value: string; tone?: CoreStatTone }[];
  };
}) {
  const { npv, formula, funding, includeResidual, onIncludeResidual } = props;
  const dualIrr = !!(funding && (funding.equityIrr || funding.equityIrrNoPi));
  const irrYears = funding?.holdYears ?? 0;
  return (
    <Stack gap={props.embedded ? 10 : 14}>
      <InvColTitle title="回本周期" hint={props.hint} />
      {props.authorityHint ? (
        <Callout tone="warning" title={props.authorityHint.titleZh}>
          <Stack gap={4}>
            <Text size="small">{props.authorityHint.bodyZh}</Text>
            {props.authorityHint.stats?.length ? (
              <Grid columns={GRID_STATS} gap={8}>
                {props.authorityHint.stats.map((s) => (
                  <Stat
                    key={s.label}
                    label={s.label}
                    value={s.value}
                    tone={s.tone}
                  />
                ))}
              </Grid>
            ) : null}
          </Stack>
        </Callout>
      ) : null}
      <CollapsibleSection
        title="口径对照（回本/IRR/NPV）"
        defaultOpen={false}
      >
        <PaybackMetricsScopeTable />
      </CollapsibleSection>
      <Row gap={8} align="center" wrap>
        <Toggle
          checked={includeResidual}
          onChange={onIncludeResidual}
        />
        <Text size="small">含残值（末月处置计入回本/IRR/NPV）</Text>
      </Row>
      <div className="inv-core-4">
        <Grid columns={GRID_CORE_4} gap={12}>
          <Stat value={props.staticPb.value} label={props.staticPb.label} />
          <Stat value={props.dynamicPb.value} label={props.dynamicPb.label} />
          {dualIrr ? (
            <Stat
              label={IRR_LABEL.leveredEquity(irrYears, includeResidual)}
              value={funding!.equityIrr}
              tone="info"
            />
          ) : (
            <Stat
              value={props.irr.value}
              label={props.irr.label}
              tone={props.irr.tone}
            />
          )}
          {dualIrr ? (
            <Stat
              label={IRR_LABEL.unleveredEquity(irrYears, includeResidual)}
              value={funding!.equityIrrNoPi}
              tone="success"
            />
          ) : (
            <UnitNpvStatWithParams
              tip={npv.tip}
              value={npv.value}
              label={npv.label}
              tone={npv.tone}
              discountAnn={npv.discountAnn}
              onDiscountAnn={npv.onDiscountAnn}
              investCcy={npv.investCcy}
            />
          )}
        </Grid>
      </div>
      {dualIrr ? (
        <div className="inv-core-4">
          <Grid columns={GRID_CORE_4} gap={12}>
            <UnitNpvStatWithParams
              tip={npv.tip}
              value={npv.value}
              label={npv.label}
              tone={npv.tone}
              discountAnn={npv.discountAnn}
              onDiscountAnn={npv.onDiscountAnn}
              investCcy={npv.investCcy}
            />
          </Grid>
        </div>
      ) : null}
      <UnitReturnFormulaStrip
        initInv={formula.initInv}
        pathCum={formula.pathCum}
        residualMxn={formula.residualMxn}
        totalReturnMxn={formula.totalReturnMxn}
        returnMultiple={formula.returnMultiple}
        fx={formula.fx}
        ccy={formula.ccy}
        includeResidual={includeResidual}
        residualHintZh={formula.residualHintZh}
        trailing={formula.trailing}
      />
          {dualIrr && irrYears > 0 ? (
        <Text size="small" tone="tertiary">
          {IRR_LABEL.dualFootnote(irrYears, includeResidual)}
          {funding!.equityIrr &&
          funding!.equityIrr !== "—" &&
          parseFloat(String(funding!.equityIrr).replace("%", "")) > 150
            ? " · 杠杆后 IRR>150% 多为劣后本金过小的切片效应，对外请用无债对照或投委会权威口径。"
            : ""}
        </Text>
      ) : null}
    </Stack>
  );
}

