function buildYohoPkgWfSteps(
  row: YohoPkgMonthRow,
  deltaOrder: string[],
  rampMode: YohoPkgRampMode,
  curveOverride?: Partial<YohoPkgRampCurve> | null,
  opts?: { includeStationExt?: boolean },
): WfBridgeStep[] {
  const order = normalizeYohoSteadyWfOrder(deltaOrder);
  const catalog = buildYohoPkgWfDeltaCatalog(
    row,
    rampMode,
    curveOverride,
    opts,
  );
  const mezzStep: WfBridgeStep | null =
    row.mezzPi > 1e-6
      ? {
          id: "investor_mezz",
          label: "夹层",
          kind: "delta",
          mxn: -row.mezzPi,
          module: "finance",
        }
      : null;
  /** 与堆叠一致：接近 0 的分项不占桥位（图例也不应误导「有成本却看不见」） */
  const mid = order
    .map((id) => catalog[id])
    .filter((s) => Math.abs(s.mxn) > 0.5);
  const withMezz =
    mezzStep == null
      ? mid
      : (() => {
          const piIdx = mid.findIndex((s) => s.id === "investor_pi");
          if (piIdx < 0) return [...mid, mezzStep];
          return [
            ...mid.slice(0, piIdx + 1),
            mezzStep,
            ...mid.slice(piIdx + 1),
          ];
        })();
  /**
   * 中间段按切分展示；终柱仍用月路径权益（与 CFADS/DSCR 同源）。
   * 切分合计若有缝：不画「未拆出/未拆入」柱（易与「其他」一样误导），
   * 仅由 auditYohoPkgMonthRows 的切分≠路径检查告警。
   */
  let bridgeEq = row.mile;
  for (const s of withMezz) bridgeEq += s.mxn;
  const pathEq = row.equity;
  void bridgeEq;
  return [
    {
      id: "passenger",
      label: "里程流水",
      kind: "total",
      mxn: row.mile,
      module: "income",
    },
    ...withMezz,
    {
      id: "equity_residual",
      label: "经营权益",
      kind: "total",
      mxn: pathEq,
      module: "equity",
    },
  ];
}

/**
 * 运营周期时间轴：横向拖拽节点切换月份；value=0 表示达产稳态锚点。
 */
function OpsMonthTimeline(props: {
  maxMonth: number;
  steadyMonth: number;
  value: number;
  onChange: (monthOrZero: number) => void;
  compact?: boolean;
}) {
  const theme = useHostTheme();
  const maxM = Math.max(1, props.maxMonth);
  const steadyM = Math.min(maxM, Math.max(1, props.steadyMonth));
  const value =
    props.value <= 0 ? 0 : Math.min(maxM, Math.max(1, Math.round(props.value)));
  const displayMo = value <= 0 ? steadyM : value;
  const pctOf = (m: number) => ((m - 1) / Math.max(1, maxM - 1)) * 100;
  const thumbPct = value <= 0 ? pctOf(steadyM) : pctOf(value);

  const setFromClientX = (el: HTMLElement, clientX: number) => {
    const rect = el.getBoundingClientRect();
    const x = Math.min(rect.width, Math.max(0, clientX - rect.left));
    const t = rect.width <= 1 ? 0 : x / rect.width;
    const mo = Math.round(1 + t * (maxM - 1));
    props.onChange(Math.min(maxM, Math.max(1, mo)));
  };

  const marks = Array.from(
    new Set(
      [1, 3, 6, 12, 18, 24, steadyM, maxM].filter((m) => m >= 1 && m <= maxM),
    ),
  ).sort((a, b) => a - b);

  return (
    <Stack gap={4}>
      <Row gap={8} align="center" wrap>
        <Text size="small" weight="medium">
          时间节点
        </Text>
        <Pill
          size="sm"
          active={value <= 0}
          onClick={() => props.onChange(0)}
        >
          达产稳态·M{steadyM}
        </Pill>
        <Pill
          size="sm"
          active={value === 1}
          onClick={() => props.onChange(1)}
        >
          M1
        </Pill>
        <Pill
          size="sm"
          active={value > 0 && value === displayMo}
          onClick={() => props.onChange(displayMo)}
        >
          {value <= 0 ? `查看 M${steadyM}` : `当前 M${displayMo}`}
        </Pill>
        <IconButton
          size="sm"
          title="上一月"
          disabled={displayMo <= 1}
          onClick={() => props.onChange(displayMo - 1)}
        >
          ‹
        </IconButton>
        <IconButton
          size="sm"
          title="下一月"
          disabled={displayMo >= maxM}
          onClick={() => props.onChange(displayMo + 1)}
        >
          ›
        </IconButton>
        <Text size="small" tone="tertiary">
          预设路径 M1–M{maxM} · 拖拽滑块
        </Text>
      </Row>
      <div
        role="slider"
        aria-valuemin={1}
        aria-valuemax={maxM}
        aria-valuenow={displayMo}
        aria-label="运营月时间轴"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === "ArrowLeft" || e.key === "ArrowDown") {
            e.preventDefault();
            props.onChange(Math.max(1, displayMo - 1));
          } else if (e.key === "ArrowRight" || e.key === "ArrowUp") {
            e.preventDefault();
            props.onChange(Math.min(maxM, displayMo + 1));
          } else if (e.key === "Home") {
            e.preventDefault();
            props.onChange(1);
          } else if (e.key === "End") {
            e.preventDefault();
            props.onChange(maxM);
          }
        }}
        onPointerDown={(e) => {
          const el = e.currentTarget;
          el.setPointerCapture(e.pointerId);
          setFromClientX(el, e.clientX);
        }}
        onPointerMove={(e) => {
          if (!e.currentTarget.hasPointerCapture(e.pointerId)) return;
          setFromClientX(e.currentTarget, e.clientX);
        }}
        onPointerUp={(e) => {
          if (e.currentTarget.hasPointerCapture(e.pointerId)) {
            e.currentTarget.releasePointerCapture(e.pointerId);
          }
        }}
        style={{
          position: "relative",
          height: props.compact ? 36 : 44,
          cursor: "ew-resize",
          userSelect: "none",
          touchAction: "none",
          border: `1px solid ${theme.stroke.tertiary}`,
          background: theme.bg.elevated,
          padding: "0 10px",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 10,
            right: 10,
            top: "50%",
            height: 2,
            marginTop: -1,
            background: theme.stroke.secondary,
          }}
        />
        {marks.map((m) => (
          <div
            key={`mk-${m}`}
            style={{
              position: "absolute",
              left: `calc(10px + (100% - 20px) * ${pctOf(m) / 100})`,
              top: "50%",
              width: 1,
              height: m === steadyM ? 14 : 8,
              marginTop: m === steadyM ? -7 : -4,
              marginLeft: -0.5,
              background:
                m === steadyM ? theme.accent.primary : theme.stroke.primary,
            }}
            title={m === steadyM ? `稳态锚点 M${m}` : `M${m}`}
          />
        ))}
        <div
          style={{
            position: "absolute",
            left: `calc(10px + (100% - 20px) * ${thumbPct / 100})`,
            top: "50%",
            width: 16,
            height: 16,
            marginTop: -8,
            marginLeft: -8,
            borderRadius: 8,
            background: theme.accent.primary,
            border: `2px solid ${theme.bg.editor}`,
            boxSizing: "border-box",
            pointerEvents: "none",
          }}
        />
        <Text
          size="small"
          tone="secondary"
          style={{
            position: "absolute",
            left: `calc(10px + (100% - 20px) * ${thumbPct / 100})`,
            top: 2,
            transform: "translateX(-50%)",
            whiteSpace: "nowrap",
            pointerEvents: "none",
            fontSize: 12,
          }}
        >
          {value <= 0 ? `稳态 M${steadyM}` : `M${displayMo}`}
        </Text>
      </div>
    </Stack>
  );
}

/** 瀑布中间段顺序：拖拽或 ↑↓；起点收入 / 终点权益固定 */
function WfDeltaOrderEditor(props: {
  order: string[];
  labels: Record<string, string>;
  modules: Record<string, WfModule>;
  onReorder: (next: string[]) => void;
  onReset?: () => void;
  compact?: boolean;
}) {
  const theme = useHostTheme();
  const order = props.order;
  const move = (fromId: string, toId: string) => {
    if (fromId === toId) return;
    const next = [...order];
    const fi = next.indexOf(fromId);
    const ti = next.indexOf(toId);
    if (fi < 0 || ti < 0) return;
    next.splice(fi, 1);
    next.splice(ti, 0, fromId);
    props.onReorder(next);
  };
  const nudge = (id: string, dir: -1 | 1) => {
    const i = order.indexOf(id);
    if (i < 0) return;
    const j = i + dir;
    if (j < 0 || j >= order.length) return;
    const next = [...order];
    const tmp = next[i]!;
    next[i] = next[j]!;
    next[j] = tmp;
    props.onReorder(next);
  };

  return (
    <Stack gap={4}>
      <Row gap={6} align="center" wrap>
        <Text tone="secondary" style={{ ...TYPE.caption, fontSize: 11 }}>
          分配顺序（拖或 ↑↓ · 收入起/权益终固定）
        </Text>
        {props.onReset ? (
          <Pill size="sm" onClick={props.onReset}>
            恢复默认
          </Pill>
        ) : null}
      </Row>
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          flexWrap: "wrap",
          gap: 4,
          alignItems: "center",
        }}
      >
        {order.map((id, idx) => {
          const mod = props.modules[id] || "variable";
          const label = props.labels[id] || id;
          return (
            <div
              key={id}
              draggable
              onDragStart={(e) => {
                e.dataTransfer.setData("text/plain", id);
                e.dataTransfer.effectAllowed = "move";
              }}
              onDragOver={(e) => {
                e.preventDefault();
                e.dataTransfer.dropEffect = "move";
                e.currentTarget.style.outline = `1px solid ${theme.accent.primary}`;
              }}
              onDragLeave={(e) => {
                e.currentTarget.style.outline = "none";
              }}
              onDrop={(e) => {
                e.preventDefault();
                e.currentTarget.style.outline = "none";
                const from = e.dataTransfer.getData("text/plain");
                if (from) move(from, id);
              }}
              title="拖到目标位置以调整分配顺序"
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 3,
                padding: "1px 4px 1px 5px",
                border: `1px solid ${theme.stroke.tertiary}`,
                background: theme.bg.elevated,
                cursor: "grab",
                userSelect: "none",
                lineHeight: 1.15,
                borderRadius: 2,
              }}
            >
              <span
                style={{
                  width: 7,
                  height: 7,
                  background: wfModuleFill(theme, mod),
                  border: `1px solid ${theme.stroke.secondary}`,
                  flexShrink: 0,
                }}
              />
              <Text
                style={{
                  ...TYPE.caption,
                  fontSize: 11,
                  lineHeight: 1.2,
                  whiteSpace: "nowrap",
                }}
              >
                {idx + 1}.{label}
              </Text>
              <span
                style={{
                  display: "inline-flex",
                  flexDirection: "column",
                  gap: 0,
                  marginLeft: 1,
                }}
              >
                <button
                  type="button"
                  title="上移"
                  disabled={idx === 0}
                  onClick={() => nudge(id, -1)}
                  style={{
                    margin: 0,
                    padding: "0 2px",
                    border: "none",
                    background: "transparent",
                    cursor: idx === 0 ? "default" : "pointer",
                    color:
                      idx === 0
                        ? theme.text.quaternary
                        : theme.text.secondary,
                    fontSize: 9,
                    lineHeight: 1,
                    height: 10,
                  }}
                >
                  ▲
                </button>
                <button
                  type="button"
                  title="下移"
                  disabled={idx === order.length - 1}
                  onClick={() => nudge(id, 1)}
                  style={{
                    margin: 0,
                    padding: "0 2px",
                    border: "none",
                    background: "transparent",
                    cursor:
                      idx === order.length - 1 ? "default" : "pointer",
                    color:
                      idx === order.length - 1
                        ? theme.text.quaternary
                        : theme.text.secondary,
                    fontSize: 9,
                    lineHeight: 1,
                    height: 10,
                  }}
                >
                  ▼
                </button>
              </span>
            </div>
          );
        })}
      </div>
    </Stack>
  );
}

/**
 * 计划 Tab · 非 YOHO 授信包（LAFA / WuWei 等）实时对照：
 * 用计划订立的优先/夹层/爬坡压入焦点订单月路径，出 DSCR 示意、瀑布/堆叠、VTL。
 */
function PlanOrderLivePreview(props: {
  order: PurchaseOrder;
  p: Premise;
  cards: VehicleCard[];
  cfBySku: Record<string, AssetCashflowConfig>;
  normalizedSkus: AssetSku[];
  cfgConfigBySku: Record<string, string>;
  orderOverride?: OrderCfOverride;
  planInvAssume?: OrderInvAssumePatch;
  planDebt?: Pick<PlanOverride, "seniorDebt" | "mezzDebt">;
  planScenarioForce?: boolean;
  invResidualMode: "market" | "book";
  daeShift: DaeShift;
  goLiveStages: GoLiveStage[];
  discountAnn: number;
  fx: number;
  ccy: string;
  usdIdr: number;
  focus?: "waterfall" | "stack" | "vtl" | "pkg";
  vtlIncludeNpv: boolean;
  onVtlIncludeNpv: (v: boolean) => void;
  vtlFxBufferPct: number;
  vtlIncludeCnyDeposit: boolean;
  onVtlIncludeCnyDeposit: (v: boolean) => void;
  vtlIncludeStationNpvHaircut: boolean;
  onVtlIncludeStationNpvHaircut: (v: boolean) => void;
  vtlRefLineMode: "formula" | "report_p90";
  onVtlRefLineMode: (v: "formula" | "report_p90") => void;
  compact?: boolean;
}) {
  const [invWfGrain, setInvWfGrain] = useCanvasState<"day" | "month" | "year">(
    "planLiveOrderWfGrain",
    "month",
  );
  const orderUnitCf = buildOrderAggregatedUnitCf({
    order: props.order,
    p: props.p,
    cards: props.cards,
    cfBySku: props.cfBySku,
    normalizedSkus: props.normalizedSkus,
    cfgConfigBySku: props.cfgConfigBySku,
    invAssume: {},
    orderOverride: props.orderOverride,
    planInvAssume: props.planInvAssume,
    planDebt: props.planDebt,
    planScenarioForce: props.planScenarioForce,
    invResidualInPath: INV_RESIDUAL_IN_PATH,
    invResidualMode: props.invResidualMode,
    daeShift: props.daeShift,
    goLiveStages: props.goLiveStages,
    discountAnn: props.discountAnn,
  });
  if (!orderUnitCf) {
    return (
      <Text size="small" tone="tertiary">
        本单暂无可对照的月路径（请确认订单行与场景已就绪）。
      </Text>
    );
  }
  const {
    primaryCtx,
    primaryLine,
    holdYears,
    residualMxn,
    bars: orderBars,
    monthPath,
  } = orderUnitCf;
  const mgrName = pickOperatorMeta(props.order.managerId).nameZh;
  const daysMoOrder = primaryCtx
    ? opsDaysPerMonth(primaryCtx.cfCardLive.daysWeek || 6)
    : 26;
  const editQty = Math.max(1, Math.round(primaryLine?.qty || 1));
  let portfolioFinanceMo = 0;
  let seniorFinanceMo = 0;
  let mezzFinanceMo = 0;
  for (const line of props.order.lines) {
    const ctx = buildOrderLineCfContext({
      order: props.order,
      line,
      p: props.p,
      cards: props.cards,
      cfBySku: props.cfBySku,
      normalizedSkus: props.normalizedSkus,
      cfgConfigBySku: props.cfgConfigBySku,
      invAssume: {},
      orderOverride: props.orderOverride,
      planInvAssume: props.planInvAssume,
      planDebt: props.planDebt,
      planScenarioForce: props.planScenarioForce,
      daeShift: props.daeShift,
      goLiveStages: props.goLiveStages,
    });
    if (!ctx) continue;
    const dMo = opsDaysPerMonth(ctx.cfCardLive.daysWeek || 6);
    const q = Math.max(1, Math.round(line.qty || 1));
    const senDay =
      ctx.cfDay.slices?.find((s) => s.id === "investor_pi")?.amountMxn || 0;
    const mezDay =
      ctx.cfDay.slices?.find((s) => s.id === "investor_mezz")?.amountMxn || 0;
    portfolioFinanceMo += (senDay + mezDay) * dMo * q;
    if (primaryLine && line.id === primaryLine.id) {
      seniorFinanceMo = senDay * dMo * q;
      mezzFinanceMo = mezDay * dMo * q;
    }
  }
  const firstOpsBar = orderBars.find((b) => b.label.startsWith("经营第"));
  const { grossMo } = steadyPnlFromFirstOpsBar({
    firstOpsBar,
    financeMo: portfolioFinanceMo,
  });
  /** 计划层 DSCR 分母=优先；无优先时回退总本息 */
  const dscrDenom =
    seniorFinanceMo > 1e-6 ? seniorFinanceMo : portfolioFinanceMo;
  const dscr =
    dscrDenom > 1e-6 ? (grossMo + portfolioFinanceMo) / dscrDenom : null;
  const seniorOn = !!(
    primaryCtx?.cfCfgLive.spvTiers.find((t) => t.id === "investor_pi")?.enabled
  );
  const mezzOn = !!(
    primaryCtx?.cfCfgLive.spvTiers.find((t) => t.id === "investor_mezz")
      ?.enabled
  );
  const orderToDisp = (mxn: number) => {
    const book: EngineBookCcy =
      primaryCtx?.sku != null ? skuEngineBookCcy(primaryCtx.sku) : "MXN";
    return Math.round(
      toDisplay(bookToUsd(mxn, book, props.fx), props.fx, props.ccy, props.usdIdr),
    );
  };
  const marketResOverride =
    props.orderOverride?.invAssume?.marketResRate ??
    props.orderOverride?.invAssume?.residualRate ??
    null;

  return (
    <Stack gap={props.compact ? 6 : 8}>
      <Text size="small" tone="tertiary">
        {mgrName} · {props.order.unitCode} · 计划订立已压入本单路径（不写回订单台账）
      </Text>
      <Grid columns={GRID_STATS} gap={8}>
        <Stat
          label={PNL_STAT.dscr}
          value={dscr != null ? `${fmt(dscr, 2)}×` : "—"}
          tone={
            dscr == null
              ? undefined
              : dscr >= 1.25
                ? "success"
                : dscr >= 1
                  ? "warning"
                  : "danger"
          }
        />
        <Stat
          label={PNL_STAT.seniorPay(props.ccy)}
          value={seniorOn ? moneyMxn(seniorFinanceMo, props.fx, props.ccy, 0) : "关"}
        />
        <Stat
          label={PNL_STAT.mezzPay(props.ccy)}
          value={mezzOn ? moneyMxn(mezzFinanceMo, props.fx, props.ccy, 0) : "关"}
        />
        <Stat
          label={`毛利示意（${props.ccy}/月）`}
          value={moneyMxn(grossMo, props.fx, props.ccy, 0)}
        />
      </Grid>

      {/* 测算图同屏：瀑布 → 堆叠 → VTL */}
      <Stack gap={10}>
        {primaryCtx ? (
          <>
            <div id="plan-live-waterfall">
              <Stack gap={6}>
                <Row gap={6} wrap align="center">
                  <Text size="small" weight="medium">
                    桥段瀑布
                  </Text>
                  {(
                    [
                      { id: "day" as const, label: "按日" },
                      { id: "month" as const, label: "按月" },
                      { id: "year" as const, label: "按年" },
                    ] as const
                  ).map((g) => (
                    <Pill
                      key={g.id}
                      size="sm"
                      active={invWfGrain === g.id}
                      onClick={() => setInvWfGrain(g.id)}
                    >
                      {g.label}
                    </Pill>
                  ))}
                </Row>
                {(() => {
                  const scale =
                    (invWfGrain === "day"
                      ? 1
                      : invWfGrain === "month"
                        ? daysMoOrder
                        : daysMoOrder * 12) * editQty;
                  const grainLabel =
                    invWfGrain === "day"
                      ? `日×${editQty}`
                      : invWfGrain === "month"
                        ? `月（×${fmt(daysMoOrder, 1)} 营运日×${editQty}）`
                        : `年（×${fmt(daysMoOrder * 12, 0)} 日×${editQty}）`;
                  const steps = daySlicesToBridgeSteps(
                    primaryCtx.cfDay.slices || [],
                  ).map((s) => ({
                    ...s,
                    mxn: s.mxn * scale,
                  }));
                  return (
                    <CashflowWaterfallBridge
                      compact
                      steps={steps}
                      toDisp={orderToDisp}
                      ccy={props.ccy}
                      grainLabel={grainLabel}
                    />
                  );
                })()}
              </Stack>
            </div>
            <div id="plan-live-stack">
              <CashflowWaterfallYearStack
                compact
                statePrefix="planLiveOrderWf"
                titleZh="订单月度堆叠（计划订立）"
                footnoteZh="柱高≈收入切分；改左栏优先/夹层即时刷新。DSCR 分母=优先本息。"
                buildArgs={{
                  country: props.order.country,
                  vertical: props.order.vertical,
                  mode: primaryCtx.mode,
                  card: primaryCtx.cfCardLive,
                  sku: primaryCtx.sku,
                  cfg: primaryCtx.cfCfgLive,
                  internalPriceMxn: primaryCtx.cfElecMxn,
                  unitLandedMxn: primaryCtx.unitLanded1,
                  goLiveStages: props.goLiveStages,
                  vat: props.p.vat,
                  holdYears,
                  qty: editQty,
                }}
                toDisp={orderToDisp}
                ccy={props.ccy}
              />
            </div>
          </>
        ) : (
          <Text size="small" tone="tertiary">
            无主编辑行，无法展开瀑布（场站-only 订单请看组合路径）。
          </Text>
        )}
        <div id="plan-live-vtl">
        {(() => {
          const vtlNpvDrivers = primaryCtx
            ? buildVtlNpvOpsDrivers({
                mode: primaryCtx.mode,
                card: primaryCtx.cfCardLive,
                cfg: primaryCtx.cfCfgLive,
                residualInPath: INV_RESIDUAL_IN_PATH,
                terminalResidualMxn: residualMxn,
              })
            : null;
          const vtl = buildVtlSeries({
            path: monthPath,
            bars: orderBars,
            collaterals: (props.order.lines || []).flatMap((ln) => {
              const ctx = buildOrderLineCfContext({
                order: props.order,
                line: ln,
                p: props.p,
                cards: props.cards,
                cfBySku: props.cfBySku,
                normalizedSkus: props.normalizedSkus,
                cfgConfigBySku: props.cfgConfigBySku,
                invAssume: {},
                orderOverride: props.orderOverride,
                planInvAssume: props.planInvAssume,
                planDebt: props.planDebt,
                planScenarioForce: props.planScenarioForce,
                daeShift: props.daeShift,
                goLiveStages: props.goLiveStages,
              });
              if (ctx) {
                const landed =
                  (ln.unitLandedMxn || 0) * Math.max(1, ln.qty || 1);
                return [
                  {
                    sku: ctx.sku,
                    unitLanded: landed,
                    spvTiers: ctx.cfCfgLive.spvTiers,
                  },
                ];
              }
              const sku =
                props.normalizedSkus.find((s) => s.id === ln.skuId) ||
                DEFAULT_ASSET_SKUS.find((s) => s.id === ln.skuId);
              if (!sku) return [];
              const landed =
                (ln.unitLandedMxn || 0) * Math.max(1, ln.qty || 1);
              const mode = defaultModeForSku(sku);
              const card =
                props.cards.map(normalizeCard).find((c) => c.mode === mode) ||
                DEFAULT_VEHICLE_CARDS[0];
              const resolved = resolveOrderAssumptions(
                props.orderOverride,
                sku.id,
                ln.id,
              );
              let cfg = mergeCfConfigPatch(
                props.cfBySku[sku.id],
                resolved.cfPatch,
                mode,
                card,
                sku,
              );
              cfg = applyPayPlanToInvestorPi(
                cfg,
                props.order.payPlan,
                mode,
                0,
              );
              cfg = applyPlanDebtToCfConfig(
                cfg,
                props.planDebt,
                mode,
                0,
              );
              return [{ sku, unitLanded: landed, spvTiers: cfg.spvTiers }];
            }),
            residualMode: props.invResidualMode,
            marketResOverride,
            holdYears,
            residualInPath: INV_RESIDUAL_IN_PATH,
            terminalResidualMxn: residualMxn,
            discountAnn: props.discountAnn,
            fxBufferPct: props.vtlFxBufferPct,
            includeNpv: props.vtlIncludeNpv,
            includeDeposit: props.vtlIncludeCnyDeposit,
            npvOpsDrivers: vtlNpvDrivers,
            remainingNpvByIndex: applyStationNpvHaircutToRemaining(
              remainingNpvByIndexFromNets(
                monthPath.map((p) => unitPathRecoverNet(p)),
                props.discountAnn,
                INV_RESIDUAL_IN_PATH,
                residualMxn,
              ),
              orderStationRemainingNpvByPathIndex({
                order: props.order,
                path: monthPath,
                normalizedSkus: props.normalizedSkus,
                discountAnn: props.discountAnn,
              }),
              !!props.vtlIncludeStationNpvHaircut,
            ),
            ...(() => {
              const x = yohoVtlExtraCoverParts({
                includeDeposit: props.vtlIncludeCnyDeposit,
                usdMxn: props.p.usdMxn,
              });
              return {
                extraCoverMxn: x.sharedMxn,
                extraCoverLiqMxn: x.liqMxn,
                extraCoverGcMxn: x.gcMxn,
              };
            })(),
          });
          return (
            <VtlCoveragePanel
              compact
              points={vtl.points}
              assumeSnapshot={vtl.assumeSnapshot}
              npvContext={vtl.npvContext}
              loanMaturityMo={vtl.loanMaturityMo}
              seniorPrincipalPct={vtl.seniorPrincipalPct}
              toDisp={orderToDisp}
              ccy={props.ccy}
              includeNpv={props.vtlIncludeNpv}
              onIncludeNpv={props.onVtlIncludeNpv}
              fxBufferPct={props.vtlFxBufferPct}
              includeCnyDeposit={props.vtlIncludeCnyDeposit}
              onIncludeCnyDeposit={props.onVtlIncludeCnyDeposit}
              includeStationNpvHaircut={props.vtlIncludeStationNpvHaircut}
              onIncludeStationNpvHaircut={props.onVtlIncludeStationNpvHaircut}
              refLineMode={props.vtlRefLineMode}
              onRefLineMode={props.onVtlRefLineMode}
            />
          );
        })()}
        </div>
      </Stack>
    </Stack>
  );
}

/** 计划 Tab · 订单路径月度现金流（瀑布 → 堆叠+DSCR） */
function YohoCreditPackageMonthlyCfPanel(props: {
  compact?: boolean;
  /**
   * 台账订单叠加行（与左栏同引擎）。提供时主视图对表。
   */
  orderRows?: YohoPkgMonthRow[] | null;
  /** 中性计划路径：经营目标三线；缺省则用 orderRows / 报告行自锚 */
  targetRows?: YohoPkgMonthRow[] | null;
  /** IVA 进项贷方累计（实体轧差）；有则在堆叠下展示可开关采购窗口 */
  ivaPath?: YohoPkgIvaMonthPt[] | null;
  orderMeta?: { orderCount: number; unitSum: number } | null;
  /** 与计划 FX buffer 同键；缺省读 planOverride / VTL */
  fxBufferPct?: number | null;
  /** 增值税税率；剔税 DSCR 折算用，默认 16% */
  vatRate?: number | null;
  /** YOHO 报告场站外部净示意；非 YOHO 管理人关 */
  includeStationExt?: boolean;
  /** 面板标题前缀 */
  titlePrefixZh?: string;
}) {
  const fromOrders = !!(props.orderRows && props.orderRows.length > 0);
  /** 订单路径禁止叠报告场站外部净；报告快算默认允许 */
  const includeStationExt = fromOrders
    ? false
    : props.includeStationExt !== false;
  const [planOverride, setPlanOverride] = useCanvasState<PlanOverride>(
    "planOverrideV1",
    {},
  );
  const [vtlFxBufferPct] = useCanvasState<number>("vtlFxBufferPct", 0.1);
  const [pkgDscrVatMode] = useCanvasState<PkgDscrVatMode>(
    "pkgDscrVatModeV1",
    "as_is",
  );
  const [pkgDscrFxMode] = useCanvasState<PkgDscrFxMode>(
    "pkgDscrFxModeV1",
    "with_fx",
  );
  const vatRate = Math.max(
    0,
    Math.min(0.5, props.vatRate != null ? props.vatRate : 0.16),
  );
  const fxBufPlan =
    props.fxBufferPct != null && Number.isFinite(props.fxBufferPct)
      ? Math.max(0, Math.min(0.5, props.fxBufferPct))
      : planOverride.fxBufferPct != null
        ? Math.max(0, Math.min(0.5, planOverride.fxBufferPct))
        : Math.max(0, Math.min(0.5, vtlFxBufferPct));
  const fxBuf = pkgDscrEffectiveFxBuf(fxBufPlan, pkgDscrFxMode);
  const fxFac = fxBufferDscrFactor(fxBuf);
  const rampMode: YohoPkgRampMode = planOverride.yohoPkgRampMode ?? "base24";
  const rampCurve = planOverrideToYohoPkgRampCurve(planOverride);
  const rampCurveResolved = resolveYohoPkgRampCurve(rampMode, rampCurve);
  const setRampMode = (mode: YohoPkgRampMode) => {
    const mapped = yohoPkgRampModeToInvAssume(mode);
    setPlanOverride((prev) => ({
      ...prev,
      yohoPkgRampMode: mode,
      rampYears: mapped.rampYears,
      rampStartLoad: mapped.rampStartLoad,
    }));
  };
  const [gapHorizon, setGapHorizon] = useCanvasState<"h6" | "h18">(
    "yohoPkgGapHorizon",
    "h6",
  );
  const [steadyWfOrderRaw, setSteadyWfOrderRaw] = useCanvasState<string[]>(
    "yohoSteadyWfDeltaOrder",
    [...YOHO_STEADY_WF_DELTA_DEFAULT],
  );
  /** 0=达产稳态锚点；≥1=预设路径经营月 */
  const [wfFocusMo, setWfFocusMo] = useCanvasState<number>(
    "yohoPkgWfFocusMo",
    0,
  );
  /** 解析后的经营月（稳态时也写具体 Mn），供 IVA/VTL 兄弟图跟蓝点 */
  const [, setWfFocusMoLive] = useCanvasState<number>(
    "yohoPkgWfFocusMoLive",
    1,
  );
  const [dscrRefModeRaw] = useCanvasState<PkgDscrRefLineMode>(
    "pkgDscrRefLineMode",
    "plan_target",
  );
  const dscrRefMode = normalizePkgDscrRefMode(dscrRefModeRaw);
  /** DSCR 虚线显隐：经营目标|样例观察 / 补仓 / 平仓 */
  const [hiddenDscrRefs, setHiddenDscrRefs] = useCanvasState<
    Record<string, boolean>
  >("pkgDscrRefLinesHidden", {});
  const toggleDscrRefLine = (id: string, allIds: string[]) => {
    setHiddenDscrRefs((prev) => {
      const next = { ...prev, [id]: !prev[id] };
      const visible = allIds.filter((rid) => !next[rid]).length;
      if (visible === 0) return prev;
      return next;
    });
  };
  const steadyWfOrder = normalizeYohoSteadyWfOrder(steadyWfOrderRaw).filter(
    (id) => !(fromOrders && id === "st_ext"),
  );
  const reportRows = buildCalendarAlignedPackageMonths({
    planId: "yoho-credit-65p1-v238",
    rampMode,
    rampCurve,
    planDebt: {
      seniorDebt: planOverride.seniorDebt,
      mezzDebt: planOverride.mezzDebt,
    },
    scenario: "base",
  });
  const rows = fromOrders ? props.orderRows! : reportRows;
  const pkgAuditIssues = fromOrders
    ? [
        ...auditYohoPkgMonthRows(rows),
        ...runYohoPkgExtremeChartSelfCheck().map((s) => `自检·${s}`),
      ]
    : runYohoPkgExtremeChartSelfCheck().map((s) => `自检·${s}`);
  const targetRows =
    props.targetRows && props.targetRows.length > 0
      ? props.targetRows
      : fromOrders
        ? rows
        : reportRows;
  const pkgDebtTerms = resolveYohoPkgDebtFromPlan(
    {
      seniorDebt: planOverride.seniorDebt,
      mezzDebt: planOverride.mezzDebt,
    },
    { fallback: fromOrders ? "off" : "report" },
  );
  const debtSource = resolveYohoPkgSeniorDebtSource(
    {
      seniorDebt: planOverride.seniorDebt,
      mezzDebt: planOverride.mezzDebt,
    },
    { path: fromOrders ? "orders" : "report_sample" },
  );
  const steady = yohoPkgSteadyMonth(rows);
  const lastDeployMo = yohoPkgLastDeployMonth();
  const omitIvaOnCharts = pkgDscrVatMode === "ex_vat";
  const wfDisplayRows = yohoPkgRowsForWfDisplay(rows, omitIvaOnCharts);
  const steadyDisp =
    wfDisplayRows.find((r) => r.month === steady.month) || steady;
  const prebuilt = yohoPkgMonthsToWfPrebuilt(wfDisplayRows);
  const dscrSeries = buildPkgDscrSeries(
    rows,
    rampMode,
    rampCurve,
    fxBuf,
    pkgDscrVatMode,
    vatRate,
  );
  const dscrTargetSeries = buildPkgDscrSeries(
    targetRows,
    rampMode,
    rampCurve,
    fxBuf,
    pkgDscrVatMode,
    vatRate,
  );
  const dscrThresholds = resolvePkgDscrThresholds(
    dscrSeries,
    dscrRefMode,
    dscrTargetSeries,
  );
  const dscrRefSpecs: Array<{
    id: string;
    label: string;
    value: number;
    tone: "info" | "warning" | "danger";
  }> = [
    {
      id: "observe",
      label: dscrRefMode === "plan_target" ? "经营目标" : "样例观察",
      value: dscrThresholds.observe,
      tone: "info",
    },
    {
      id: "margin",
      label: "补仓",
      value: dscrThresholds.margin,
      tone: "warning",
    },
    {
      id: "liquidate",
      label: "平仓",
      value: dscrThresholds.liquidate,
      tone: "danger",
    },
  ];
  const dscrRefIds = dscrRefSpecs.map((s) => s.id);
  const dscrOverlay: WfStackOverlayLine = {
    name: "DSCR",
    data: dscrSeries.map((p) =>
      p.dscr != null && Number.isFinite(p.dscr) ? p.dscr : null,
    ),
    valueSuffix: "×",
    /** 次轴跟已出图点；允许只还息爬坡高倍数（勿再死封 3.5× 把中段顶穿后看似断线） */
    yMax: (() => {
      const drawn = dscrSeries
        .map((p) => p.dscr)
        .filter((v): v is number => v != null && Number.isFinite(v) && v > 0);
      const rawMax = Math.max(
        2,
        dscrThresholds.observe,
        ...(drawn.length ? drawn : [2]),
      );
      return Math.min(12, Math.max(3.5, rawMax * 1.08));
    })(),
    referenceLines: dscrRefSpecs
      .filter((s) => !hiddenDscrRefs[s.id])
      .map((s) => ({
        value: s.value,
        label: s.label,
        tone: s.tone,
      })),
    /** 虚线可隐藏；触线橙/红仍按完整三线 */
    alertLevels: dscrRefSpecs.map((s) => ({
      value: s.value,
      tone: s.tone,
    })),
  };
  const gapN = gapHorizon === "h6" ? 6 : 18;
  const gapRows = rows.slice(0, gapN);
  const cumGap = gapRows.reduce((s, r) => s + r.gap, 0);
  const negGap = gapRows.filter((r) => r.gap < 0).reduce((s, r) => s + r.gap, 0);
  const firstCover = rows.find((r) => r.gap >= 0 && r.month >= 2);
  const firstEq10k = rows.find((r) => r.equity >= 10_000);
  const usd = (n: number) =>
    Math.round(n).toLocaleString("en-US", { maximumFractionDigits: 0 });
  const maxMo = rows.length > 0 ? rows[rows.length - 1]!.month : 1;
  const focusIsSteady = wfFocusMo <= 0;
  const focusMo = focusIsSteady
    ? steady.month
    : Math.min(maxMo, Math.max(1, Math.round(wfFocusMo)));
  const focusRow =
    wfDisplayRows.find((r) => r.month === focusMo) ||
    (focusIsSteady ? steadyDisp : wfDisplayRows[0]!) ||
    steadyDisp;
  const wfRow = focusIsSteady ? steadyDisp : focusRow;
  const wfDeltaCatalog = buildYohoPkgWfDeltaCatalog(
    wfRow,
    rampMode,
    rampCurve,
    { includeStationExt },
  );
  const wfDeltaLabels = Object.fromEntries(
    Object.entries(wfDeltaCatalog).map(([id, s]) => [id, s.label]),
  );
  const wfDeltaModules = Object.fromEntries(
    Object.entries(wfDeltaCatalog).map(([id, s]) => [id, s.module]),
  );
  /** 焦点 DSCR 仍用路径真值行（含/剔由 vatMode 决定），勿用已改写的展示行 */
  const focusRowRaw =
    rows.find((r) => r.month === focusMo) ||
    (focusIsSteady ? steady : rows[0]!) ||
    steady;
  const focusCfadsAdj = pkgCfadsForDscr(
    focusRowRaw,
    pkgDscrVatMode,
    vatRate,
  );
  const focusDscr =
    focusRowRaw.pi > 1e-9 && Number.isFinite(focusCfadsAdj)
      ? (focusCfadsAdj * fxFac) / focusRowRaw.pi
      : null;

  useEffect(() => {
    setWfFocusMoLive(focusMo);
  }, [focusMo, setWfFocusMoLive]);

  return (
    <Stack gap={props.compact ? 6 : 8}>
      <Row gap={6} align="center" wrap>
        <Text size="small" weight="medium">
          {fromOrders
            ? `${props.titlePrefixZh || "测算图"} · 瀑布 → 堆叠+DSCR → VTL`
            : "授信包快算 · 瀑布 → 堆叠"}
        </Text>
        <HelpQ
          id="yoho-pkg-live-caliber"
          label={fromOrders ? "订单路径口径" : "授信包路径口径"}
          tip={[
            fromOrders
              ? `台账 ${props.orderMeta?.orderCount ?? "—"} 笔 / ${props.orderMeta?.unitSum ?? "—"} 台按付款日叠加；爬坡·债服·情景与左栏同一 PlanOverride。瀑布分项来自订单日切片。路径达产≈峰值 M${steady.month}。`
              : `单批负荷 ${Math.round(rampCurveResolved.startLoad * 100)}%→${rampCurveResolved.rampMonths} 月；投放错期写死报告批次。与左栏订单路径叠加不是同一引擎。`,
            `DSCR=${pkgDscrVatMode === "ex_vat" ? "剔IVA后经营净" : "CFADS"}${
              pkgDscrFxMode === "ex_fx"
                ? "（剔FX）"
                : `×(1−FX ${Math.round(fxBufPlan * 1000) / 10}%)`
            }/优先；堆叠柱为未乘 FX 的收入切分。`,
            PKG_OPS_ENGINE.decisionZh,
            debtSource.kind === "off"
              ? "优先已关：DSCR / 瀑布优先本息为 0。开启左侧「优先投资」订立条款。"
              : debtSource.kind === "order"
                ? "债服·订单条款：未订立时本息跟各单 payPlan/spv；参考样例只进附录，不写进主路径。"
                : `债服：${debtSource.labelZh}`,
          ].join("\n")}
        />
        <Pill size="sm" tone={fromOrders ? "success" : "warning"} active>
          {fromOrders ? "对表·台账" : "报告快算"}
        </Pill>
        <Pill
          size="sm"
          tone={
            debtSource.kind === "off"
              ? "deleted"
              : debtSource.kind === "plan"
                ? "success"
                : debtSource.kind === "order"
                  ? "success"
                  : "info"
          }
          active
        >
          {debtSource.labelZh}
        </Pill>
        {!fromOrders ? (
          <>
            <Pill
              size="sm"
              active={rampMode === "base24"}
              onClick={() => setRampMode("base24")}
            >
              锁口径·24月
            </Pill>
            <Pill
              size="sm"
              active={rampMode === "fast3"}
              onClick={() => setRampMode("fast3")}
            >
              短爬坡·3月
            </Pill>
          </>
        ) : (
          <Text size="small" tone="tertiary">
            爬坡/情景/债服请改左栏整包假设
          </Text>
        )}
      </Row>
      {pkgAuditIssues.length > 0 ? (
        <Callout tone="warning" title="包层对账自检">
          {pkgAuditIssues.join(" · ")}
        </Callout>
      ) : null}

      <div id="plan-live-waterfall">
      {/* ① 瀑布（截面） */}
      <Stack gap={6}>
        <Row gap={6} align="center" wrap>
          <Text size="small" weight="medium">
            {focusIsSteady
              ? `瀑布 · 达产稳态 M${steady.month}`
              : `瀑布 · 经营月 M${wfRow.month}`}
          </Text>
          <HelpQ
            id="yoho-pkg-waterfall"
            label="瀑布桥段"
            tip={`时间轴拖到任意经营月看当月桥段；「达产稳态」回到路径峰值锚点。瀑布/堆叠刻画经营现金流（里程→成本→优先→经营权益）。${omitIvaOnCharts ? "当前为剔IVA：桥段不扣 IVA付现，权益已加回。" : "含IVA时桥段含 IVA付现。"}保证金退还属融资现金流，不进桥段；结清月见上方融资旁注。`}
          />
        </Row>
        <OpsMonthTimeline
          maxMonth={maxMo}
          steadyMonth={steady.month}
          value={wfFocusMo}
          onChange={setWfFocusMo}
          compact={props.compact}
        />
        <Grid columns={GRID_STATS} gap={6}>
          <PlanStickyKpi label="在营台数" value={`${wfRow.nUnits}`} />
          <PlanStickyKpi
            label="经营净"
            value={`$${usd(wfRow.cfads)}`}
            tone={wfRow.cfads >= 0 ? "success" : "danger"}
          />
          <PlanStickyKpi
            label="优先本息"
            value={`$${usd(wfRow.pi)}`}
            tone="warning"
          />
          <PlanStickyKpi
            label="经营权益"
            value={`$${usd(wfRow.equity)}`}
            tone={wfRow.equity >= 0 ? "success" : "danger"}
          />
          {wfRow.depReturn > 0.5 ? (
            <PlanStickyKpi
              label="融资·保证金退还"
              value={`$${usd(wfRow.depReturn)}`}
              tone="info"
            />
          ) : null}
          <PlanStickyKpi
            label={`DSCR${pkgDscrCaliberSuffix(pkgDscrVatMode, pkgDscrFxMode)}`}
            value={focusDscr != null ? `${focusDscr.toFixed(2)}×` : "—"}
            tone={
              focusDscr == null
                ? undefined
                : focusDscr >= dscrThresholds.observe
                  ? "success"
                  : focusDscr >= dscrThresholds.liquidate
                    ? "warning"
                    : "danger"
            }
          />
        </Grid>
        <WfDeltaOrderEditor
          order={steadyWfOrder}
          labels={wfDeltaLabels}
          modules={wfDeltaModules}
          onReorder={setSteadyWfOrderRaw}
          onReset={() => setSteadyWfOrderRaw([...YOHO_STEADY_WF_DELTA_DEFAULT])}
          compact={props.compact}
        />
        <CashflowWaterfallBridge
          steps={buildYohoPkgWfSteps(
            wfRow,
            steadyWfOrder,
            rampMode,
            rampCurve,
            { includeStationExt },
          )}
          toDisp={(usdAmt) => usdAmt}
          ccy="USD"
          grainLabel={
            focusIsSteady ? `达产稳态·M${steady.month}` : `经营月·M${wfRow.month}`
          }
          compact={props.compact}
        />
      </Stack>

      </div>

      <div id="plan-live-stack">
      {/* ② 堆叠 + DSCR（纵向） */}
      <CashflowWaterfallYearStack
        prebuilt={prebuilt}
        toDisp={(usdAmt) => usdAmt}
        ccy="USD"
        compact={props.compact}
        statePrefix={`yohoPkgWf_${rampMode}`}
        initialDrill="month"
        titleZh={
          omitIvaOnCharts ? "月度堆叠 + DSCR · 剔IVA" : "月度堆叠 + DSCR"
        }
        footnoteZh={
          omitIvaOnCharts
            ? "剔IVA视图：柱上不画 IVA付现，金额加回经营权益，与 DSCR 剔IVA 分子同口径。路径真值仍含 IVA；切回含IVA 可对照。蓝框=选中月。DSCR 触线变色规则同前。"
            : "柱为经营月科目金额。蓝框=上方时间轴选中月（柱顶为该月堆叠合计）。DSCR 线：安全段蓝色；触及/低于经营目标或补仓→橙；触及/低于平仓→红（提示须重调投放节奏或假设）。有在营+本息即连线；仅债末本息萎缩且虚高断线。保证金退还不进堆叠。IVA/VTL 折线图蓝点同步跟此月。"
        }
        overlayLine={dscrOverlay}
        highlightMonth={focusMo}
      />
      <Row gap={6} wrap align="center">
        <Text size="small" tone="secondary">
          DSCR 参考线
        </Text>
        <HelpQ
          id="yoho-pkg-dscr-overlay"
          label="堆叠图 DSCR"
          tip={`DSCR=${
            pkgDscrVatMode === "ex_vat" ? "(CFADS+IVA)" : "CFADS"
          }${
            pkgDscrFxMode === "ex_fx"
              ? "（剔FX）"
              : `×(1−FX ${Math.round(fxBufPlan * 1000) / 10}%)`
          }÷优先。虚线为经营目标三线（中性达产稳态切分）：${dscrThresholds.observe.toFixed(2)} / ${dscrThresholds.margin.toFixed(2)} / ${dscrThresholds.liquidate.toFixed(2)}×。折线触线变色：≤目标/补仓=橙，≤平仓=红。点胶囊显隐参考线；爬坡窗内低于目标属计划达产过程。堆叠柱本身不乘 FX；剔IVA 时柱不画税现金。切「结构占比」或非「全路径月」时藏线。`}
        />
        {dscrRefSpecs.map((s) => {
          const off = !!hiddenDscrRefs[s.id];
          return (
            <Pill
              key={s.id}
              size="sm"
              active={!off}
              tone={s.tone}
              onClick={() => toggleDscrRefLine(s.id, dscrRefIds)}
              title={
                off
                  ? `点击显示 · ${s.label} ${s.value.toFixed(2)}×`
                  : `点击隐藏 · ${s.label} ${s.value.toFixed(2)}×`
              }
              style={
                off
                  ? { textDecoration: "line-through", opacity: 0.55 }
                  : undefined
              }
            >
              {s.label} {s.value.toFixed(2)}×
            </Pill>
          );
        })}
      </Row>
      <PackageDscrStrip
        rows={rows}
        targetRows={targetRows}
        rampMode={rampMode}
        rampCurve={rampCurve}
        fxBufferPct={fxBuf}
        vatRate={vatRate}
        compact={props.compact}
      />

      </div>

      {fromOrders ? (
        <div id="plan-live-iva">
          <YohoPkgIvaCreditChartPanel
            path={(props.ivaPath || []).filter((p) => p.month <= 36)}
            compact={props.compact}
            focusMonth={focusMo}
            emptyHintZh={
              (props.ivaPath || []).length === 0
                ? "路径为空：请确认税率 vat>0，且台账有未取消订单。若刚刷新请再切一次「测算·整包」页。"
                : undefined
            }
          />
        </div>
      ) : null}

      {/* 次要 KPI / 附录 / 缺口 — 收拢，不抢图表首屏 */}
      <CollapsibleSection
        title="达产 KPI · 缺口"
        defaultOpen={false}
        trailing={`达产 M${steady.month}`}
      >
        <Stack gap={8} style={{ paddingTop: 6 }}>
          <Grid columns={GRID_STATS} gap={6}>
            <PlanStickyKpi
              label={`路径达产经营净 M${steady.month}`}
              value={`$${usd(steady.cfads)}`}
              tone="success"
            />
            <PlanStickyKpi
              label="达产优先本息"
              value={debtSource.kind === "off" ? "已关" : `$${usd(steady.pi)}`}
              tone={debtSource.kind === "off" ? undefined : "danger"}
            />
            <PlanStickyKpi
              label="达产经营权益"
              value={`$${usd(steady.equity)}`}
              tone="success"
            />
            <PlanStickyKpi
              label={gapHorizon === "h6" ? "半年累计缺口" : "M1–M18 累计缺口"}
              value={`${cumGap >= 0 ? "+" : ""}$${usd(cumGap)}`}
              tone={cumGap >= 0 ? "success" : "danger"}
            />
          </Grid>
          {(() => {
            const split = splitEquityResidualUsd(steady.equity);
            return (
              <Grid columns={GRID_FORM} gap={6}>
                <PlanStickyKpi
                  label="扩产留存 90%"
                  value={`$${usd(split.expansionUsd)}`}
                />
                <PlanStickyKpi
                  label="当期可动用 10%"
                  value={`$${usd(split.distributableUsd)}`}
                />
              </Grid>
            );
          })()}
          <Row gap={6} align="center" wrap>
            <Text size="small" weight="medium">
              覆盖缺口
            </Text>
            <HelpQ
              id="yoho-pkg-gap"
              label="覆盖缺口"
              tip={`90/10 为权益用途分拆，不进 IRR 分子。覆盖≥1× 约 M${firstCover?.month ?? "—"} · 权益≥1万 约 M${firstEq10k?.month ?? "—"} · 仅负月合计 $${usd(negGap)}。`}
            />
            <Pill
              size="sm"
              active={gapHorizon === "h6"}
              onClick={() => setGapHorizon("h6")}
            >
              半年
            </Pill>
            <Pill
              size="sm"
              active={gapHorizon === "h18"}
              onClick={() => setGapHorizon("h18")}
            >
              M1–M18
            </Pill>
          </Row>
          <BarChart
            categories={gapRows.map((r) => `M${r.month}`)}
            series={[
              {
                name: "经营净",
                data: gapRows.map((r) => Math.round(r.cfads)),
                tone: "success",
              },
              {
                name: "优先本息",
                data: gapRows.map((r) => Math.round(r.pi)),
                tone: "danger",
              },
            ]}
            height={160}
            beginAtZero
            showValues={gapN <= 6}
            valuePrefix="$"
          />
          <BarChart
            categories={gapRows.map((r) => `M${r.month}`)}
            series={[
              {
                name: "缺口(经营净−优先)",
                data: gapRows.map((r) => Math.round(r.gap)),
                tone: "warning",
              },
            ]}
            height={140}
            showValues={gapN <= 6}
            valuePrefix="$"
            referenceLines={[{ value: 0, label: "平衡", tone: "neutral" }]}
          />
        </Stack>
      </CollapsibleSection>
    </Stack>
  );
}


function CashflowWaterfallBridge(props: {
  steps: WfBridgeStep[];
  toDisp: (mxn: number) => number;
  ccy: string;
  grainLabel: string;
  compact?: boolean;
}) {
  const theme = useHostTheme();
  const { steps, toDisp, ccy, grainLabel, compact } = props;
  const clipId = `wf-plot-clip-${Math.abs(
    steps.reduce((s, x) => s + x.label.length + Math.round(x.mxn), 0),
  ) % 9973}`;
  if (steps.length === 0) {
    return (
      <Text size="small" tone="tertiary">
        暂无瀑布切片（检查成本开关与收入入口）
      </Text>
    );
  }

  type WfGeom = {
    id: string;
    label: string;
    module: WfModule;
    kind: "income" | "delta" | "result";
    value: number;
    start: number;
    end: number;
  };

  const geoms: WfGeom[] = [];
  let cum = 0;
  for (const step of steps) {
    const v = toDisp(step.mxn);
    if (
      step.kind === "total" &&
      (step.id === "passenger" || step.module === "income")
    ) {
      cum = v;
      geoms.push({
        id: step.id,
        label: step.label,
        module: step.module,
        kind: "income",
        value: v,
        start: 0,
        end: v,
      });
      continue;
    }
    if (step.kind === "total" || step.id === "equity_residual" || step.id === "deposit_return") {
      geoms.push({
        id: step.id,
        label: step.label,
        module: step.module,
        kind: "result",
        value: v,
        start: 0,
        end: v,
      });
      cum = v;
      continue;
    }
    const start = cum;
    const end = start + v;
    cum = end;
    geoms.push({
      id: step.id,
      label: step.label,
      module: step.module,
      kind: "delta",
      value: v,
      start,
      end,
    });
  }

  const domainMin = Math.min(
    0,
    ...geoms.map((g) => g.start),
    ...geoms.map((g) => g.end),
  );
  const domainMax = Math.max(
    1,
    ...geoms.map((g) => g.start),
    ...geoms.map((g) => g.end),
  );
  const domainSpan = Math.max(1e-9, domainMax - domainMin);
  const n = geoms.length;
  const slotW =
    compact && n > 7 ? 64 : n > 8 ? 60 : n > 6 ? 54 : n > 4 ? 50 : 46;
  const barW = Math.min(compact ? 24 : 22, slotW - 12);
  const padL = 12;
  const plotH = compact ? 148 : 140;
  const valueH = compact ? 16 : 14;
  const padT = valueH + 10;
  const labelRotate = compact ? n >= 3 : n >= 5;
  const padB = labelRotate ? (compact ? 62 : 54) : compact ? 30 : 26;
  const h = padT + plotH + padB;
  const minChartW = compact ? 480 : 520;
  const w = Math.max(minChartW, padL * 2 + n * slotW);
  const innerH = plotH - 6;
  const plotTop = padT;
  const plotBot = padT + plotH;
  /** 线性映射：支持负值；0 轴可落在 plot 中部 */
  const yAt = (val: number) =>
    plotTop + ((domainMax - val) / domainSpan) * innerH;
  const yZero = yAt(0);
  const slotCx = (i: number) => padL + i * slotW + slotW / 2;
  const barX = (i: number) => slotCx(i) - barW / 2;
  const axisLabelY = plotBot + (labelRotate ? 16 : 18);

  const axisShort = (g: WfGeom) => {
    const m: Record<string, string> = {
      passenger: labelRotate ? "里程" : "里程流水",
      equity_residual: labelRotate ? "权益" : "经营权益",
      deposit_return: labelRotate ? "保证" : "保证金退还",
      equity_convert_debt: "投资人",
      subsidy: "补贴",
      st_in: labelRotate ? "场站入" : "场站流入",
      st_ext: labelRotate ? "场站" : "场站外部",
      tolls: "过路",
      iva_output: labelRotate ? "IVA" : "IVA付现",
      contract_fixed: labelRotate ? "维保" : "保险维保",
      wear: "易损",
      fix_insurance: "保险",
      fix_maint: "保养",
      fix_soft: "GPS",
      fix_parking: "车位",
      fix_site_rent: labelRotate ? "场站" : "场站成本",
      other_veh: labelRotate ? "车残" : "车·残差",
      other_st: labelRotate ? "站残" : "场站·残差",
      other_ops: labelRotate ? "其他" : "其他运营",
      veh_ops: labelRotate ? "其他" : "其他运营",
      trip_bonus: "冲单",
      income_tax: labelRotate ? "所得税" : "所得税",
      driver_wage: "司机",
      charge: "充电",
      investor_pi: "优先",
      investor_mezz: "夹层",
      equity_bridge_adj: labelRotate
        ? g.label.includes("流入")
          ? "未拆入"
          : "未拆出"
        : g.label,
      st_var: "可变",
      st_fix: "固定",
    };
    if (m[g.id]) return m[g.id]!;
    if (!labelRotate && g.label.length <= 5) return g.label;
    return g.label.length <= 4 ? g.label : g.label.slice(0, 4);
  };

  const legendMods = (
    [
      "income",
      "platform",
      "labor",
      "energy",
      "variable",
      "fixed",
      "finance",
      "tax",
      "equity",
    ] as WfModule[]
  ).filter((m) => geoms.some((g) => g.module === m));

  /** 图例跟柱上科目名对齐；场站科目虚线框+斜线，车队实心 */
  const legendSubjects = geoms
    .filter(
      (g) =>
        Math.abs(g.value) > 0.5 ||
        g.id === "equity_residual" ||
        g.id === "investor_pi" ||
        g.id === "investor_mezz",
    )
    .map((g) => ({
      id: g.id,
      label: axisShort(g),
      module: g.module,
      kind: g.kind,
      station: wfIsStationSubject(g.id),
    }));
  const hasStationLeg = legendSubjects.some((s) => s.station);
  const hasVehLeg = legendSubjects.some((s) => !s.station && s.kind === "delta");

  return (
    <Stack gap={6}>
      <Row gap={8} align="center" wrap>
        <Text weight="medium" style={TYPE.body}>
          瀑布过程
        </Text>
        <Text tone="tertiary" style={TYPE.caption}>
          {grainLabel} · {ccy}
          {n > 6 ? " · 可横滑" : ""}
          {domainMin < 0 ? " · 含负水位" : ""}
        </Text>
      </Row>
      {legendSubjects.length > 0 ? (
        <Stack gap={4}>
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              flexWrap: "wrap",
              alignItems: "center",
              gap: 10,
              width: "100%",
            }}
          >
            {legendSubjects.map((s) => (
              <span
                key={`${s.id}-${s.label}`}
                title={
                  s.station
                    ? `${s.label} · 场站 · ${WF_MODULE_ZH[s.module]}`
                    : `${s.label} · 车队 · ${WF_MODULE_ZH[s.module]}`
                }
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: 5,
                  flex: "0 0 auto",
                }}
              >
                <span
                  style={{
                    width: 10,
                    height: 10,
                    background: s.station
                      ? `repeating-linear-gradient(-45deg, ${wfModuleFill(theme, s.module)}55 0 2px, transparent 2px 4px)`
                      : wfModuleFill(theme, s.module),
                    border: s.station
                      ? `1.5px dashed ${wfModuleFill(theme, s.module)}`
                      : `1px solid ${theme.stroke.secondary}`,
                    borderRadius: 1,
                    display: "inline-block",
                    flexShrink: 0,
                    boxSizing: "border-box",
                  }}
                />
                <Text tone="tertiary" style={TYPE.caption}>
                  {s.label}
                </Text>
              </span>
            ))}
          </div>
          {hasStationLeg || hasVehLeg ? (
            <Text size="small" tone="tertiary">
              样式：实心=车队科目
              {hasStationLeg ? " · 斜线虚框=场站科目" : ""}
              {" · "}
              「其他运营」=日切未点名运营项；经营净跟月路径 CFADS（与投放回收同源）
            </Text>
          ) : null}
        </Stack>
      ) : legendMods.length > 0 ? (
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            flexWrap: "wrap",
            alignItems: "center",
            gap: 10,
            width: "100%",
          }}
        >
          {legendMods.map((m) => (
            <span
              key={m}
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 5,
                flex: "0 0 auto",
              }}
            >
              <span
                style={{
                  width: 9,
                  height: 9,
                  background: wfModuleFill(theme, m),
                  border: `1px solid ${theme.stroke.secondary}`,
                  borderRadius: 1,
                  display: "inline-block",
                  flexShrink: 0,
                }}
              />
              <Text tone="tertiary" style={TYPE.caption}>
                {WF_MODULE_ZH[m]}
              </Text>
            </span>
          ))}
        </div>
      ) : null}
      <div
        style={{
          border: `1px solid ${theme.stroke.tertiary}`,
          background: theme.bg.elevated,
          padding: labelRotate ? "4px 6px 14px" : "4px 6px 10px",
          overflowX: "auto",
          overflowY: "visible",
        }}
      >
        <svg
          viewBox={`0 0 ${w} ${h}`}
          preserveAspectRatio="xMinYMin meet"
          style={{
            display: "block",
            width: w,
            height: h,
            flexShrink: 0,
          }}
        >
          <defs>
            <clipPath id={clipId}>
              <rect x={0} y={plotTop - 2} width={w} height={plotH + 4} />
            </clipPath>
            {(
              [
                "variable",
                "fixed",
                "platform",
                "energy",
                "labor",
                "finance",
                "tax",
                "income",
                "equity",
              ] as WfModule[]
            ).map((mod) => {
              const c = wfModuleFill(theme, mod);
              return (
                <pattern
                  key={`st-hatch-${mod}`}
                  id={`${clipId}-st-${mod}`}
                  width={6}
                  height={6}
                  patternUnits="userSpaceOnUse"
                  patternTransform="rotate(-45)"
                >
                  <rect width={6} height={6} fill={`${c}33`} />
                  <line
                    x1={0}
                    y1={0}
                    x2={0}
                    y2={6}
                    stroke={c}
                    strokeWidth={2}
                  />
                </pattern>
              );
            })}
          </defs>
          <line
            x1={0}
            y1={yZero}
            x2={w}
            y2={yZero}
            stroke={theme.stroke.tertiary}
            strokeWidth={1}
          />
          <g clipPath={`url(#${clipId})`}>
            {geoms.map((g, i) => {
              const x = barX(i);
              const yTop = yAt(Math.max(g.start, g.end));
              const yBot = yAt(Math.min(g.start, g.end));
              const rectY = yTop;
              const rectH = Math.max(2, yBot - yTop);
              const fill = wfModuleFill(theme, g.module);
              const isSt = wfIsStationSubject(g.id);
              const prevEnd = i > 0 ? geoms[i - 1]!.end : null;
              const connY =
                prevEnd != null && g.kind === "delta" ? yAt(prevEnd) : null;
              const connX0 = i > 0 ? slotCx(i - 1) + barW / 2 : slotCx(i);
              return (
                <g key={`${g.id}-${i}-bar`}>
                  {connY != null ? (
                    <line
                      x1={connX0}
                      y1={connY}
                      x2={x}
                      y2={yAt(g.start)}
                      stroke={theme.stroke.secondary}
                      strokeWidth={1}
                      strokeDasharray="2 2"
                    />
                  ) : null}
                  <rect
                    x={x}
                    y={rectY}
                    width={barW}
                    height={rectH}
                    fill={isSt ? `url(#${clipId}-st-${g.module})` : fill}
                    stroke={fill}
                    strokeWidth={isSt ? 1.25 : 0.75}
                    strokeDasharray={isSt ? "3 2" : undefined}
                    rx={1}
                  >
                    <title>{`${g.label} · ${isSt ? "场站" : "车队"} · ${WF_MODULE_ZH[g.module]} · ${fmtCfAxis(g.value)} ${ccy}`}</title>
                  </rect>
                </g>
              );
            })}
          </g>
          {geoms.map((g, i) => {
            const cx = slotCx(i);
            const yTop = yAt(Math.max(g.start, g.end));
            const yBot = yAt(Math.min(g.start, g.end));
            const rectH = Math.max(2, yBot - yTop);
            const valStr = fmtCfAxis(
              g.kind === "delta" ? g.value : g.value,
            );
            /** 负柱：数值标在柱底下方；正柱标在柱顶上方 */
            const mostlyBelow = Math.min(g.start, g.end) < 0 && g.end <= 0;
            const valY = mostlyBelow
              ? yBot + 13
              : g.kind === "delta" && g.value < 0 && rectH >= 12
                ? yBot + 13
                : yTop - 4;
            return (
              <g key={`${g.id}-${i}-lbl`}>
                <text
                  x={cx}
                  y={valY}
                  textAnchor="middle"
                  fill={theme.text.secondary}
                  style={SVG_PX.wfValue}
                >
                  {valStr}
                </text>
                <text
                  x={cx}
                  y={axisLabelY}
                  transform={
                    labelRotate
                      ? `rotate(-38, ${cx}, ${axisLabelY})`
                      : undefined
                  }
                  textAnchor={labelRotate ? "end" : "middle"}
                  fill={theme.text.tertiary}
                  style={SVG_PX.wfAxis}
                >
                  {axisShort(g)}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
      {(() => {
        const income = geoms.find((g) => g.kind === "income");
        const result = geoms.find((g) => g.kind === "result");
        if (!income || !result) return null;
        const taller =
          result.value > income.value + 1
            ? "经营权益终柱高于里程起柱：中间必有补贴/场站净等经营正项。瀑布只画经营现金流，不含保证金退还。"
            : "起柱=里程流水，终柱=经营权益（都从 0 画）；中间浮动段为经营增减。保证金退还属融资现金流，不进本桥。";
        return (
          <Text size="small" tone="tertiary">
            {taller}
          </Text>
        );
      })()}
    </Stack>
  );
}

/** 资产阶段横轴：付款 → 投产；可拖游标 */
function GoLiveTimelineAxis({
  stages,
  cursorDay,
  onCursorDay,
  showCursor = true,
}: {
  stages: GoLiveStage[];
  cursorDay: number;
  onCursorDay?: (d: number) => void;
  showCursor?: boolean;
}) {
  const theme = useHostTheme();
  const total = Math.max(1, goLiveTotalDays(stages));
  const day = Math.max(0, Math.min(total, Math.round(cursorDay)));
  const pos = goLiveAxisPosition(stages, day);
  const segColors = [
    theme.fill.secondary,
    theme.fill.tertiary,
    theme.fill.secondary,
    theme.fill.tertiary,
  ];

  return (
    <Stack gap={10}>
      <Row gap={8} align="center" wrap>
        <Text size="small" weight="medium">
          资产阶段横轴
        </Text>
        <Text size="small" tone="tertiary">
          付款 → 投产 · 共 {goLiveTotalDays(stages)} 天 · 段宽按有效天比例
        </Text>
      </Row>

      {/* 端点标签 */}
      <Row gap={8} style={{ justifyContent: "space-between" }}>
        <Text size="small" weight="medium" style={{ color: theme.text.primary }}>
          付款 · D0
        </Text>
        <Text size="small" weight="medium" style={{ color: theme.text.primary }}>
          投产 · D{goLiveTotalDays(stages)}
        </Text>
      </Row>

      {/* 比例条 */}
      <div style={{ position: "relative", width: "100%" }}>
        <div
          style={{
            display: "flex",
            width: "100%",
            height: 36,
            border: `1px solid ${theme.stroke.secondary}`,
            overflow: "hidden",
          }}
        >
          {stages.map((s, i) => {
            const w = (s.days / total) * 100;
            const active = pos.pointId === s.id;
            return (
              <div
                key={s.id}
                title={`${s.nameZh} · ${s.days}天`}
                style={{
                  width: `${w}%`,
                  minWidth: s.days > 0 ? 28 : 0,
                  background: active
                    ? theme.accent.control
                    : segColors[i % segColors.length],
                  borderRight:
                    i < stages.length - 1
                      ? `1px solid ${theme.stroke.primary}`
                      : undefined,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: "0 4px",
                  boxSizing: "border-box",
                }}
              >
                <Text
                  size="small"
                  style={{
                    color: active ? theme.text.onAccent : theme.text.secondary,
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  {s.nameZh}
                  <span style={{ opacity: 0.75 }}> {s.days}d</span>
                </Text>
              </div>
            );
          })}
        </div>

        {showCursor && (
          <div
            style={{
              position: "absolute",
              left: `${pos.pct}%`,
              top: -4,
              bottom: -4,
              width: 2,
              marginLeft: -1,
              background: theme.text.primary,
              pointerEvents: "none",
            }}
          />
        )}
      </div>

      <div style={{ position: "relative", width: "100%", height: 18 }}>
        <Text
          size="small"
          tone="tertiary"
          style={{ position: "absolute", left: 0 }}
        >
          D0
        </Text>
        {stages.map((s) => {
          let end = 0;
          for (const x of stages) {
            end += x.days;
            if (x.id === s.id) break;
          }
          const left = (end / total) * 100;
          return (
            <Text
              key={s.id}
              size="small"
              tone="tertiary"
              style={{
                position: "absolute",
                left: `${left}%`,
                transform: "translateX(-100%)",
              }}
            >
              D{end}
            </Text>
          );
        })}
      </div>

      {showCursor && (
        <Stack gap={6}>
          <Row gap={8} align="center" wrap>
            <Pill active size="sm">
              今日 · D{day} · {pos.nameZh}
            </Pill>
            <Text size="small" tone="secondary">
              进度 {pos.pct.toFixed(0)}%
            </Text>
          </Row>
          {onCursorDay && (
            <Stack gap={4}>
              <Text size="small" tone="secondary">
                日游标（模拟每日推进）
              </Text>
              <input
                type="range"
                min={0}
                max={total}
                step={1}
                value={day}
                onChange={(e) => onCursorDay(Number(e.target.value))}
                style={{ width: "100%" }}
              />
            </Stack>
          )}
          <Text size="small" tone="secondary">
            本阶段宜采集：{pos.collectZh.join(" · ")}
          </Text>
        </Stack>
      )}
    </Stack>
  );
}

/** 可拖动刻度：range + 档位点按 + 即时业务含义 */
function ScaleField({
  label,
  value,
  onChange,
  min,
  max,
  step,
  display,
  why,
  effect,
  ticks,
}: {
  label: string;
  value: number;
  onChange: (n: number) => void;
  min: number;
  max: number;
  step: number;
  display: string;
  why?: string;
  effect?: string;
  ticks?: { value: number; label: string }[];
}) {
  const theme = useHostTheme();
  const clamped = Math.max(min, Math.min(max, value));
  return (
    <Stack
      gap={6}
      style={mergeStyle({
        padding: 12,
        border: `1px solid ${theme.stroke.tertiary}`,
        background: theme.bg.elevated,
        minWidth: 0,
        overflowWrap: "anywhere",
      })}
    >
      <Row align="center" gap={8} wrap>
        <Text size="small" weight="medium" style={{ minWidth: 0 }}>
          {label}
        </Text>
        <Spacer />
        <Text
          size="small"
          weight="semibold"
          style={{ color: theme.text.primary, whiteSpace: "nowrap" }}
        >
          {display}
        </Text>
      </Row>
      {why ? (
        <Text size="small" tone="tertiary">
          {why}
        </Text>
      ) : null}
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={clamped}
        onChange={(e) => {
          const n = Number(e.target.value);
          if (Number.isFinite(n)) onChange(n);
        }}
        style={{
          width: "100%",
          margin: 0,
          accentColor: theme.text.secondary,
          cursor: "pointer",
        }}
      />
      {ticks && ticks.length > 0 ? (
        <Row gap={4} wrap align="center">
          {ticks.map((t) => {
            const active = Math.abs(clamped - t.value) <= step * 0.51;
            return (
              <Pill
                key={`${t.label}-${t.value}`}
                size="sm"
                active={active}
                onClick={() => onChange(t.value)}
              >
                {t.label}
              </Pill>
            );
          })}
        </Row>
      ) : null}
      {effect ? (
        <Text size="small" tone="secondary">
          {effect}
        </Text>
      ) : null}
    </Stack>
  );
}

function capabilityBand(v: number): string {
  if (v < 0.35) return "偏弱";
  if (v < 0.55) return "一般";
  if (v < 0.75) return "中上";
  if (v < 0.9) return "较强";
  return "很强";
}

function readinessBand(v: number): string {
  if (v < 0.4) return "配套不足";
  if (v < 0.6) return "部分到位";
  if (v < 0.8) return "基本齐备";
  return "充分到位";
}

