  const pushOrdersToHistory = (
    orders: PurchaseOrder[],
    kind: OrderArchiveKind,
    noteZh?: string,
  ) => {
    if (!orders.length) return;
    setOrderHistory((prev) => [
      ...snapshotOrdersToArchive(orders, kind, noteZh),
      ...prev,
    ].slice(0, 80));
  };

  const restoreOrdersFromHistory = (archiveIds: string[]) => {
    const picks = orderHistory.filter((a) => archiveIds.includes(a.archiveId));
    if (!picks.length) return;
    setPurchaseOrders((prev) => {
      const base =
        prev.length > 0 ? prev.map((o) => normalizePurchaseOrder(o)) : [];
      const existing = new Set(base.map((o) => o.id));
      const added: PurchaseOrder[] = [];
      for (const arc of picks) {
        let o = normalizePurchaseOrder(
          JSON.parse(JSON.stringify(arc.order)) as PurchaseOrder,
          [...base, ...added],
        );
        if (existing.has(o.id)) {
          const newId = `po-restored-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 5)}`;
          o = normalizePurchaseOrder(
            {
              ...o,
              id: newId,
              label: `${o.label}（恢复）`,
              noteZh: `${o.noteZh || ""} · 自历史恢复（原 id ${arc.order.id}）`.trim(),
              status: o.status === "cancelled" ? "pending_pay" : o.status,
            },
            [...base, ...added],
          );
        } else if (o.status === "cancelled") {
          o = { ...o, status: "pending_pay" };
        }
        existing.add(o.id);
        added.push(o);
      }
      const next = [...base, ...added];
      if (added[0]) setOrderFocusId(added[0].id);
      return next;
    });
    setOrderHistorySelected([]);
    setOrderHistoryOpen(false);
  };

